//! Bounded PDF parser for the independently loaded PDF pack.
//!
//! This module reads PDF syntax and content operators directly. It intentionally
//! does not wrap a browser PDF viewer or a third-party PDF engine.

use std::collections::{BTreeMap, BTreeSet};
#[cfg(feature = "pdf-formats")]
use std::io::{Cursor, Read};
use std::rc::Rc;
#[cfg(feature = "pdf-formats")]
use std::sync::OnceLock;
use std::sync::{Arc, Mutex};

#[cfg(feature = "pdf-formats")]
use hayro_cmap::{BfString, CMap, CMapName};
use hayro_jbig2::{Decoder as Jbig2Decoder, Image as Jbig2Image};
#[cfg(feature = "pdf-formats")]
use skrifa::{
    FontRef, MetadataProvider,
    instance::{LocationRef, Size},
    outline::{DrawSettings, OutlinePen},
};

use crate::deflate;
use crate::diagnostic::{Diagnostic, DiagnosticCode, Fidelity, Phase};
use crate::format::pdf_crypto::{
    aes_cbc_decrypt, aes_cbc_encrypt, md5, rc4, sha256, sha384, sha512,
};
use crate::limits::Limits;
use crate::model::{
    AffineTransform, BlendMode, Document, DocumentFormat, DocumentKind, EmbeddedFont, FillRule,
    FontStyle, Geometry, GradientStop, ImageCrop, LineCap, LineJoin, MappingQuality, Object,
    ObjectKind, OutlineItem, Paint, PathCommand, PptxAction, Rect, SheetAxis, SourceLocator,
    SourceRef, StrokeStyle, TextAlign, TextLayout, TextOrientation, TextRun, Unit, UnitKind,
    Visual, VisualBrushChild,
};

#[path = "pdf_cmyk_lut.rs"]
mod pdf_cmyk_lut;
#[path = "pdf_type1.rs"]
mod pdf_type1;
#[path = "pdf_xfa.rs"]
