const PDF_HEADER_SCAN_BYTES: usize = 1_024;
const PDF_POINT_TO_CSS: f32 = 96.0 / 72.0;
const PDF_CID_PUA_START: u32 = 0x000f_0000;
const PDF_CID_BMP_PUA_START: u32 = 0x0000_e000;
const PDF_SIMPLE_GLYPH_PUA_START: u32 = 0x0000_e000;
const MAX_VALUE_DEPTH: usize = 128;
const MAX_FORM_DEPTH: usize = 16;
const MAX_PATH_COMMANDS: usize = 65_536;
const MAX_CLIP_DEPTH: usize = 64;
const MAX_PDF_TEXT_BATCH_ITEMS: usize = 4_096;
const MAX_PDF_PAGE_POINTS: f32 = 1_000_000.0;
const PDF_RASTER_MAGIC: &[u8; 8] = b"OVPDFR01";

pub(crate) type ObjectId = (u32, u16);
type PdfDict = BTreeMap<String, PdfValue>;

#[derive(Clone, Debug)]
enum PdfValue {
    Null,
    Bool(bool),
    Number(f64),
    Name(String),
    String(Vec<u8>),
    Array(Vec<PdfValue>),
    Dict(PdfDict),
    Ref(ObjectId),
    Stream { dict: PdfDict, bytes: Vec<u8> },
}

#[derive(Clone, Debug)]
struct IndirectObject {
    value: PdfValue,
    offset: usize,
}

struct PdfParser<'a> {
    bytes: &'a [u8],
    position: usize,
    nodes: usize,
    recovered_dicts: usize,
    limits: Limits,
}

impl<'a> PdfParser<'a> {
    fn new(bytes: &'a [u8], position: usize, limits: Limits) -> Self {
        Self {
            bytes,
            position,
            nodes: 0,
            recovered_dicts: 0,
            limits,
        }
    }

    fn skip_space(&mut self) {
        loop {
            while self.position < self.bytes.len() && is_pdf_space(self.bytes[self.position]) {
                self.position += 1;
            }
            if self.bytes.get(self.position) != Some(&b'%') {
                break;
            }
            while self.position < self.bytes.len()
                && !matches!(self.bytes[self.position], b'\r' | b'\n')
            {
                self.position += 1;
            }
        }
    }

    fn parse_value(&mut self, depth: usize) -> Result<PdfValue, Diagnostic> {
        if depth > MAX_VALUE_DEPTH {
            return Err(pdf_error(
                self.position,
                "PDF value nesting exceeds the parser limit",
            ));
        }
        self.nodes = self.nodes.checked_add(1).ok_or_else(object_limit)?;
        if self.nodes > self.limits.max_xml_nodes {
            return Err(object_limit());
        }
        self.skip_space();
        let start = self.position;
        match self.bytes.get(self.position).copied() {
            Some(b'/') => self.parse_name().map(PdfValue::Name),
            Some(b'(') => self.parse_literal_string().map(PdfValue::String),
            Some(b'<') if self.bytes.get(self.position + 1) == Some(&b'<') => {
                self.parse_dict(depth + 1).map(PdfValue::Dict)
            }
            Some(b'<') => self.parse_hex_string().map(PdfValue::String),
            Some(b'[') => self.parse_array(depth + 1).map(PdfValue::Array),
            Some(b't') if self.consume_keyword(b"true") => Ok(PdfValue::Bool(true)),
            Some(b'f') if self.consume_keyword(b"false") => Ok(PdfValue::Bool(false)),
            Some(b'n') if self.consume_keyword(b"null") => Ok(PdfValue::Null),
            Some(b'+' | b'-' | b'.' | b'0'..=b'9') => {
                let number = self.parse_number()?;
                let after_number = self.position;
                if number.fract() == 0.0 && number >= 0.0 && number <= u32::MAX as f64 {
                    self.skip_space();
                    let second_start = self.position;
                    if matches!(self.bytes.get(self.position), Some(b'0'..=b'9'))
                        && let Ok(generation) = self.parse_unsigned()
                    {
                        self.skip_space();
                        if generation <= u16::MAX as u32 && self.consume_keyword(b"R") {
                            return Ok(PdfValue::Ref((number as u32, generation as u16)));
                        }
                    }
                    self.position = second_start.min(after_number);
                }
                self.position = after_number;
                Ok(PdfValue::Number(number))
            }
            _ => Err(pdf_error(start, "invalid PDF value")),
        }
    }

    fn parse_name(&mut self) -> Result<String, Diagnostic> {
        let start = self.position;
        if self.bytes.get(self.position) != Some(&b'/') {
            return Err(pdf_error(start, "expected PDF name"));
        }
        self.position += 1;
        let mut decoded = Vec::new();
        while let Some(&byte) = self.bytes.get(self.position) {
            if is_pdf_space(byte) || is_pdf_delimiter(byte) {
                break;
            }
            if byte == b'#'
                && let (Some(high), Some(low)) = (
                    self.bytes
                        .get(self.position + 1)
                        .and_then(|value| hex(*value)),
                    self.bytes
                        .get(self.position + 2)
                        .and_then(|value| hex(*value)),
                )
            {
                decoded.push((high << 4) | low);
                self.position += 3;
            } else {
                decoded.push(byte);
                self.position += 1;
            }
            if decoded.len() > self.limits.max_xml_name_bytes {
                return Err(pdf_error(
                    start,
                    "PDF name exceeds the configured byte limit",
                ));
            }
        }
        Ok(decoded.into_iter().map(char::from).collect())
    }

    fn parse_literal_string(&mut self) -> Result<Vec<u8>, Diagnostic> {
        let start = self.position;
        self.position += 1;
        let mut result = Vec::new();
        let mut depth = 1_usize;
        while self.position < self.bytes.len() {
            let byte = self.bytes[self.position];
            self.position += 1;
            match byte {
                b'(' => {
                    depth += 1;
                    result.push(byte);
                }
                b')' => {
                    depth -= 1;
                    if depth == 0 {
                        return Ok(result);
                    }
                    result.push(byte);
                }
                b'\\' => {
                    let Some(&escaped) = self.bytes.get(self.position) else {
                        return Err(pdf_error(start, "unterminated PDF string escape"));
                    };
                    self.position += 1;
                    match escaped {
                        b'n' => result.push(b'\n'),
                        b'r' => result.push(b'\r'),
                        b't' => result.push(b'\t'),
                        b'b' => result.push(0x08),
                        b'f' => result.push(0x0c),
                        b'(' | b')' | b'\\' => result.push(escaped),
                        b'\r' => {
                            if self.bytes.get(self.position) == Some(&b'\n') {
                                self.position += 1;
                            }
                        }
                        b'\n' => {}
                        b'0'..=b'7' => {
                            let mut value = u16::from(escaped - b'0');
                            for _ in 0..2 {
                                let Some(&digit @ b'0'..=b'7') = self.bytes.get(self.position)
                                else {
                                    break;
                                };
                                value = value * 8 + u16::from(digit - b'0');
                                self.position += 1;
                            }
                            result.push((value & 0xff) as u8);
                        }
                        _ => result.push(escaped),
                    }
                }
                _ => result.push(byte),
            }
            if result.len() > self.limits.max_entry_uncompressed_bytes {
                return Err(pdf_error(
                    start,
                    "PDF string exceeds the configured byte limit",
                ));
            }
        }
        Err(pdf_error(start, "unterminated PDF literal string"))
    }

    fn parse_hex_string(&mut self) -> Result<Vec<u8>, Diagnostic> {
        let start = self.position;
        self.position += 1;
        let mut result = Vec::new();
        let mut high = None;
        while let Some(&byte) = self.bytes.get(self.position) {
            self.position += 1;
            if byte == b'>' {
                if let Some(value) = high {
                    result.push(value << 4);
                }
                return Ok(result);
            }
            if is_pdf_space(byte) {
                continue;
            }
            let value =
                hex(byte).ok_or_else(|| pdf_error(self.position - 1, "invalid PDF hex string"))?;
            if let Some(prefix) = high.take() {
                result.push((prefix << 4) | value);
            } else {
                high = Some(value);
            }
            if result.len() > self.limits.max_entry_uncompressed_bytes {
                return Err(pdf_error(
                    start,
                    "PDF string exceeds the configured byte limit",
                ));
            }
        }
        Err(pdf_error(start, "unterminated PDF hex string"))
    }

    fn parse_array(&mut self, depth: usize) -> Result<Vec<PdfValue>, Diagnostic> {
        let start = self.position;
        self.position += 1;
        let mut values = Vec::new();
        loop {
            self.skip_space();
            if self.bytes.get(self.position) == Some(&b']') {
                self.position += 1;
                return Ok(values);
            }
            if self.position >= self.bytes.len() {
                return Err(pdf_error(start, "unterminated PDF array"));
            }
            if values.len() >= self.limits.max_document_objects {
                return Err(object_limit());
            }
            values.push(self.parse_value(depth)?);
        }
    }

    fn parse_dict(&mut self, depth: usize) -> Result<PdfDict, Diagnostic> {
        let start = self.position;
        self.position += 2;
        let mut dict = PdfDict::new();
        loop {
            self.skip_space();
            if self.bytes.get(self.position..self.position + 2) == Some(b">>") {
                self.position += 2;
                return Ok(dict);
            }
            if self.bytes.get(self.position..self.position + 6) == Some(b"endobj")
                || self.bytes.get(self.position..self.position + 6) == Some(b"stream")
            {
                self.recovered_dicts += 1;
                return Ok(dict);
            }
            if self.position >= self.bytes.len() {
                return Err(pdf_error(start, "unterminated PDF dictionary"));
            }
            if self.bytes[self.position] != b'/' {
                let unexpected = self.position;
                while self.position < self.bytes.len()
                    && self.bytes[self.position] != b'/'
                    && !self.bytes[self.position..].starts_with(b"endobj")
                    && !self.bytes[self.position..].starts_with(b"stream")
                {
                    self.position += 1;
                    if self.position - unexpected > 4_096 {
                        return Err(pdf_error(unexpected, "invalid PDF dictionary key"));
                    }
                }
                self.recovered_dicts += 1;
                continue;
            }
            // PDF resource dictionaries commonly contain hundreds or thousands
            // of named fonts and XObjects. Bound them as reference maps rather
            // than applying the unrelated per-element XML attribute limit.
            if dict.len() >= self.limits.max_relationship_edges {
                return Err(pdf_error(
                    start,
                    "PDF dictionary exceeds the configured entry limit",
                ));
            }
            let key = self.parse_name()?;
            let value = self.parse_value(depth)?;
            dict.insert(key, value);
        }
    }

    fn parse_number(&mut self) -> Result<f64, Diagnostic> {
        let start = self.position;
        if matches!(self.bytes.get(self.position), Some(b'+' | b'-')) {
            self.position += 1;
        }
        let mut digits = 0;
        let mut dots = 0;
        while let Some(&byte) = self.bytes.get(self.position) {
            match byte {
                b'0'..=b'9' => digits += 1,
                b'.' => dots += 1,
                _ => break,
            }
            self.position += 1;
        }
        if digits == 0 || dots > 1 || self.position - start > 64 {
            return Err(pdf_error(start, "invalid PDF number"));
        }
        let text = std::str::from_utf8(&self.bytes[start..self.position])
            .map_err(|_| pdf_error(start, "invalid PDF number"))?;
        let value = text
            .parse::<f64>()
            .map_err(|_| pdf_error(start, "invalid PDF number"))?;
        if !value.is_finite() {
            return Err(pdf_error(start, "non-finite PDF number"));
        }
        Ok(value)
    }

    fn parse_unsigned(&mut self) -> Result<u32, Diagnostic> {
        let start = self.position;
        while matches!(self.bytes.get(self.position), Some(b'0'..=b'9')) {
            self.position += 1;
        }
        if start == self.position || self.position - start > 10 {
            return Err(pdf_error(start, "invalid PDF object number"));
        }
        let text = std::str::from_utf8(&self.bytes[start..self.position])
            .map_err(|_| pdf_error(start, "invalid PDF object number"))?;
        text.parse()
            .map_err(|_| pdf_error(start, "invalid PDF object number"))
    }

    fn consume_keyword(&mut self, keyword: &[u8]) -> bool {
        if self.bytes.get(self.position..self.position + keyword.len()) != Some(keyword) {
            return false;
        }
        let end = self.position + keyword.len();
        if self
            .bytes
            .get(end)
            .is_some_and(|byte| !is_pdf_space(*byte) && !is_pdf_delimiter(*byte))
        {
            return false;
        }
        self.position = end;
        true
    }
}

struct ObjectStore {
    objects: BTreeMap<ObjectId, IndirectObject>,
    active_xref_offsets: Option<BTreeMap<ObjectId, usize>>,
    decoded_function_streams: Mutex<BTreeMap<ObjectId, Arc<Vec<u8>>>>,
    type4_programs: Mutex<BTreeMap<ObjectId, Arc<Vec<Vec<u8>>>>>,
    limits: Limits,
    diagnostics: Vec<Diagnostic>,
}

struct EncryptionMetadata {
    dictionary: EncryptionDictionary,
    file_id: Vec<u8>,
}

enum EncryptionDictionary {
    Indirect(ObjectId),
    Inline(PdfDict),
}

#[derive(Clone, Copy)]
enum CryptMethod {
    Identity,
    Rc4,
    Aes128,
    Aes256,
}

struct SecurityHandler {
    key: Vec<u8>,
    string_method: CryptMethod,
    stream_method: CryptMethod,
    encrypt_metadata: bool,
}

const PASSWORD_PADDING: [u8; 32] = [
    0x28, 0xbf, 0x4e, 0x5e, 0x4e, 0x75, 0x8a, 0x41, 0x64, 0x00, 0x4e, 0x56, 0xff, 0xfa, 0x01, 0x08,
    0x2e, 0x2e, 0x00, 0xb6, 0xd0, 0x68, 0x3e, 0x80, 0x2f, 0x0c, 0xa9, 0xfe, 0x64, 0x53, 0x69, 0x7a,
];

fn find_encryption_metadata(
    bytes: &[u8],
    store: &ObjectStore,
    limits: Limits,
) -> Result<Option<EncryptionMetadata>, Diagnostic> {
    let mut candidate = None;
    let mut position = 0;
    while let Some(found) = find_bytes(bytes, position, b"trailer") {
        let mut parser = PdfParser::new(bytes, found + b"trailer".len(), limits);
        parser.skip_space();
        if let Ok(PdfValue::Dict(dict)) = parser.parse_value(0)
            && let Some(metadata) = encryption_metadata_from_dict(&dict)
        {
            candidate = Some(metadata);
        }
        position = found + b"trailer".len();
    }
    for object in store.objects.values() {
        let dict = match &object.value {
            PdfValue::Dict(dict) | PdfValue::Stream { dict, .. } => dict,
            _ => continue,
        };
        if dict_name(dict, "Type") == Some("XRef")
            && let Some(metadata) = encryption_metadata_from_dict(dict)
        {
            candidate = Some(metadata);
        }
    }
    Ok(candidate)
}

fn encryption_metadata_from_dict(dict: &PdfDict) -> Option<EncryptionMetadata> {
    let dictionary = match dict.get("Encrypt")? {
        PdfValue::Ref(id) => EncryptionDictionary::Indirect(*id),
        PdfValue::Dict(dictionary) => EncryptionDictionary::Inline(dictionary.clone()),
        _ => return None,
    };
    let PdfValue::Array(ids) = dict.get("ID")? else {
        return None;
    };
    let PdfValue::String(file_id) = ids.first()? else {
        return None;
    };
    Some(EncryptionMetadata {
        dictionary,
        file_id: file_id.clone(),
    })
}

fn password_error(code: DiagnosticCode, offset: usize, message: &'static str) -> Diagnostic {
    Diagnostic::fatal(code, Phase::Security, Some(offset), message).in_part("document.pdf")
}

fn security_handler(
    dictionary: &PdfDict,
    file_id: &[u8],
    password: Option<&[u8]>,
    offset: usize,
) -> Result<SecurityHandler, Diagnostic> {
    if dict_name(dictionary, "Filter") != Some("Standard") {
        return Err(password_error(
            DiagnosticCode::UnsupportedFeature,
            offset,
            "PDF_ENCRYPTION_UNSUPPORTED: only the Standard Security Handler is supported",
        ));
    }
    let revision = dictionary.get("R").and_then(number_i32).ok_or_else(|| {
        password_error(
            DiagnosticCode::FormatInvalid,
            offset,
            "PDF encryption dictionary is missing a valid revision",
        )
    })?;
    if (dict_name(dictionary, "StrF") == Some("Identity")
        && dict_name(dictionary, "StmF") == Some("Identity"))
        || (selected_crypt_filter_uses_embedded_file_auth(dictionary, "StrF")
            && selected_crypt_filter_uses_embedded_file_auth(dictionary, "StmF"))
    {
        return Ok(SecurityHandler {
            key: Vec::new(),
            string_method: CryptMethod::Identity,
            stream_method: CryptMethod::Identity,
            encrypt_metadata: false,
        });
    }
    let password_missing = password.is_none();
    let password = match password {
        Some(password) => password,
        None if matches!(revision, 2..=5) => b"",
        None => {
            return Err(password_error(
                DiagnosticCode::PdfPasswordRequired,
                offset,
                "PDF_PASSWORD_REQUIRED: a password is required to open this PDF",
            ));
        }
    };
    let result = match revision {
        2..=4 => legacy_security_handler(dictionary, file_id, password, revision, offset),
        5 => revision_five_security_handler(dictionary, password, offset),
        6 => revision_six_security_handler(dictionary, password, offset),
        _ => Err(password_error(
            DiagnosticCode::UnsupportedFeature,
            offset,
            "PDF_ENCRYPTION_REVISION_UNSUPPORTED: unsupported PDF encryption revision",
        )),
    };
    match result {
        Err(error) if password_missing && error.code == DiagnosticCode::PdfPasswordIncorrect => {
            Err(password_error(
                DiagnosticCode::PdfPasswordRequired,
                offset,
                "PDF_PASSWORD_REQUIRED: a password is required to open this PDF",
            ))
        }
        result => result,
    }
}

fn legacy_security_handler(
    dictionary: &PdfDict,
    file_id: &[u8],
    password: &[u8],
    revision: i32,
    offset: usize,
) -> Result<SecurityHandler, Diagnostic> {
    let owner = dictionary.get("O").and_then(pdf_string).ok_or_else(|| {
        password_error(
            DiagnosticCode::FormatInvalid,
            offset,
            "PDF encryption dictionary is missing O",
        )
    })?;
    let user = dictionary.get("U").and_then(pdf_string).ok_or_else(|| {
        password_error(
            DiagnosticCode::FormatInvalid,
            offset,
            "PDF encryption dictionary is missing U",
        )
    })?;
    let permissions = dictionary.get("P").and_then(number_i32).ok_or_else(|| {
        password_error(
            DiagnosticCode::FormatInvalid,
            offset,
            "PDF encryption dictionary is missing P",
        )
    })?;
    if owner.len() < 32 || user.len() < 16 {
        return Err(password_error(
            DiagnosticCode::FormatInvalid,
            offset,
            "PDF encryption credentials have invalid lengths",
        ));
    }
    let key_length = if revision == 2 {
        5
    } else {
        dictionary
            .get("Length")
            .and_then(number_usize)
            .unwrap_or(40)
            .checked_div(8)
            .filter(|length| (5..=16).contains(length))
            .ok_or_else(|| {
                password_error(
                    DiagnosticCode::FormatInvalid,
                    offset,
                    "PDF encryption key length must be 40 through 128 bits",
                )
            })?
    };
    let encrypt_metadata = !matches!(
        dictionary.get("EncryptMetadata"),
        Some(PdfValue::Bool(false))
    );
    let user_key = legacy_file_key(
        password,
        owner,
        permissions,
        file_id,
        revision,
        key_length,
        encrypt_metadata,
    );
    let mut key = if verify_legacy_user_password(user, file_id, revision, &user_key) {
        user_key
    } else {
        let recovered = recover_legacy_user_password(password, owner, revision, key_length);
        let recovered_key = legacy_file_key(
            &recovered,
            owner,
            permissions,
            file_id,
            revision,
            key_length,
            encrypt_metadata,
        );
        if !verify_legacy_user_password(user, file_id, revision, &recovered_key) {
            return Err(password_error(
                DiagnosticCode::PdfPasswordIncorrect,
                offset,
                "PDF_PASSWORD_INCORRECT: the supplied PDF password is incorrect",
            ));
        }
        recovered_key
    };
    let version = dictionary.get("V").and_then(number_i32).unwrap_or(0);
    if version == 4 && key.len() < 16 {
        // Acrobat and pdf.js accept V=4 files whose authentication key is
        // shorter than 128 bits, then zero-extend that key before deriving
        // per-object RC4/AES keys. Keep authentication at the declared size.
        key.resize(16, 0);
    }
    let (string_method, stream_method) = if version >= 4 {
        (
            crypt_filter_method(dictionary, "StrF", offset)?,
            crypt_filter_method(dictionary, "StmF", offset)?,
        )
    } else {
        (CryptMethod::Rc4, CryptMethod::Rc4)
    };
    Ok(SecurityHandler {
        key,
        string_method,
        stream_method,
        encrypt_metadata,
    })
}

fn padded_password(password: &[u8]) -> [u8; 32] {
    let mut padded = [0_u8; 32];
    let copied = password.len().min(32);
    padded[..copied].copy_from_slice(&password[..copied]);
    padded[copied..].copy_from_slice(&PASSWORD_PADDING[..32 - copied]);
    padded
}

fn legacy_file_key(
    password: &[u8],
    owner: &[u8],
    permissions: i32,
    file_id: &[u8],
    revision: i32,
    key_length: usize,
    encrypt_metadata: bool,
) -> Vec<u8> {
    let mut input = padded_password(password).to_vec();
    input.extend_from_slice(&owner[..32]);
    input.extend_from_slice(&permissions.to_le_bytes());
    input.extend_from_slice(file_id);
    if revision >= 4 && !encrypt_metadata {
        input.extend_from_slice(&[0xff; 4]);
    }
    let mut digest = md5(&input);
    if revision >= 3 {
        for _ in 0..50 {
            digest = md5(&digest[..key_length]);
        }
    }
    digest[..key_length].to_vec()
}

fn verify_legacy_user_password(user: &[u8], file_id: &[u8], revision: i32, key: &[u8]) -> bool {
    if revision == 2 {
        return user.get(..32) == Some(rc4(key, &PASSWORD_PADDING).as_slice());
    }
    let mut input = PASSWORD_PADDING.to_vec();
    input.extend_from_slice(file_id);
    let mut candidate = rc4(key, &md5(&input));
    for round in 1_u8..=19 {
        let round_key: Vec<u8> = key.iter().map(|byte| byte ^ round).collect();
        candidate = rc4(&round_key, &candidate);
    }
    user.get(..16) == candidate.get(..16)
}

fn recover_legacy_user_password(
    owner_password: &[u8],
    owner: &[u8],
    revision: i32,
    key_length: usize,
) -> Vec<u8> {
    let mut digest = md5(&padded_password(owner_password));
    if revision >= 3 {
        for _ in 0..50 {
            digest = md5(&digest);
        }
    }
    let key = &digest[..key_length];
    let mut recovered = owner[..32].to_vec();
    if revision == 2 {
        return rc4(key, &recovered);
    }
    for round in (0_u8..=19).rev() {
        let round_key: Vec<u8> = key.iter().map(|byte| byte ^ round).collect();
        recovered = rc4(&round_key, &recovered);
    }
    recovered
}

fn revision_five_security_handler(
    dictionary: &PdfDict,
    password: &[u8],
    offset: usize,
) -> Result<SecurityHandler, Diagnostic> {
    let user = dictionary
        .get("U")
        .and_then(pdf_string)
        .filter(|value| value.len() >= 48);
    let owner = dictionary
        .get("O")
        .and_then(pdf_string)
        .filter(|value| value.len() >= 48);
    let user_encrypted = dictionary
        .get("UE")
        .and_then(pdf_string)
        .filter(|value| value.len() == 32);
    let owner_encrypted = dictionary
        .get("OE")
        .and_then(pdf_string)
        .filter(|value| value.len() == 32);
    let (user, owner, user_encrypted, owner_encrypted) =
        match (user, owner, user_encrypted, owner_encrypted) {
            (Some(user), Some(owner), Some(user_encrypted), Some(owner_encrypted)) => {
                (user, owner, user_encrypted, owner_encrypted)
            }
            _ => {
                return Err(password_error(
                    DiagnosticCode::FormatInvalid,
                    offset,
                    "PDF AES-256 encryption credentials have invalid lengths",
                ));
            }
        };
    let user = &user[..48];
    let owner = &owner[..48];
    let password = &password[..password.len().min(127)];
    let zero_iv = [0_u8; 16];
    let key = if sha256_many(&[password, &user[32..40]]).as_slice() == &user[..32] {
        let intermediate = sha256_many(&[password, &user[40..48]]);
        aes_cbc_decrypt(&intermediate, &zero_iv, user_encrypted, false)
    } else if sha256_many(&[password, &owner[32..40], user]).as_slice() == &owner[..32] {
        let intermediate = sha256_many(&[password, &owner[40..48], user]);
        aes_cbc_decrypt(&intermediate, &zero_iv, owner_encrypted, false)
    } else {
        None
    }
    .filter(|key| key.len() == 32)
    .ok_or_else(|| {
        password_error(
            DiagnosticCode::PdfPasswordIncorrect,
            offset,
            "PDF_PASSWORD_INCORRECT: the supplied PDF password is incorrect",
        )
    })?;
    let string_method = crypt_filter_method(dictionary, "StrF", offset)?;
    let stream_method = crypt_filter_method(dictionary, "StmF", offset)?;
    Ok(SecurityHandler {
        key,
        string_method,
        stream_method,
        encrypt_metadata: !matches!(
            dictionary.get("EncryptMetadata"),
            Some(PdfValue::Bool(false))
        ),
    })
}

fn revision_six_security_handler(
    dictionary: &PdfDict,
    password: &[u8],
    offset: usize,
) -> Result<SecurityHandler, Diagnostic> {
    let user = dictionary
        .get("U")
        .and_then(pdf_string)
        .filter(|value| value.len() >= 48);
    let owner = dictionary
        .get("O")
        .and_then(pdf_string)
        .filter(|value| value.len() >= 48);
    let user_encrypted = dictionary
        .get("UE")
        .and_then(pdf_string)
        .filter(|value| value.len() == 32);
    let owner_encrypted = dictionary
        .get("OE")
        .and_then(pdf_string)
        .filter(|value| value.len() == 32);
    let (user, owner, user_encrypted, owner_encrypted) =
        match (user, owner, user_encrypted, owner_encrypted) {
            (Some(user), Some(owner), Some(user_encrypted), Some(owner_encrypted)) => {
                (user, owner, user_encrypted, owner_encrypted)
            }
            _ => {
                return Err(password_error(
                    DiagnosticCode::FormatInvalid,
                    offset,
                    "PDF AES-256 encryption credentials have invalid lengths",
                ));
            }
        };
    let user = &user[..48];
    let owner = &owner[..48];
    let prepared_password = str::from_utf8(password)
        .ok()
        .and_then(|password| stringprep::saslprep(password).ok())
        .map(|password| password.as_bytes()[..password.len().min(127)].to_vec());
    let password = prepared_password
        .as_deref()
        .unwrap_or(&password[..password.len().min(127)]);
    let zero_iv = [0_u8; 16];
    let user_validation = [password, &user[32..40]].concat();
    let owner_validation = [password, &owner[32..40], user].concat();
    let key = if revision_six_hash(password, &user_validation, &[])
        .is_some_and(|hash| hash.as_slice() == &user[..32])
    {
        let input = [password, &user[40..48]].concat();
        revision_six_hash(password, &input, &[]).and_then(|intermediate| {
            aes_cbc_decrypt(&intermediate, &zero_iv, user_encrypted, false)
        })
    } else if revision_six_hash(password, &owner_validation, user)
        .is_some_and(|hash| hash.as_slice() == &owner[..32])
    {
        let input = [password, &owner[40..48], user].concat();
        revision_six_hash(password, &input, user).and_then(|intermediate| {
            aes_cbc_decrypt(&intermediate, &zero_iv, owner_encrypted, false)
        })
    } else {
        None
    }
    .filter(|key| key.len() == 32)
    .ok_or_else(|| {
        password_error(
            DiagnosticCode::PdfPasswordIncorrect,
            offset,
            "PDF_PASSWORD_INCORRECT: the supplied PDF password is incorrect",
        )
    })?;
    let string_method = crypt_filter_method(dictionary, "StrF", offset)?;
    let stream_method = crypt_filter_method(dictionary, "StmF", offset)?;
    Ok(SecurityHandler {
        key,
        string_method,
        stream_method,
        encrypt_metadata: !matches!(
            dictionary.get("EncryptMetadata"),
            Some(PdfValue::Bool(false))
        ),
    })
}

fn revision_six_hash(password: &[u8], input: &[u8], user: &[u8]) -> Option<[u8; 32]> {
    let mut key = sha256(input).to_vec();
    let mut encrypted = vec![0_u8];
    let mut round = 0_usize;
    while round < 64 || usize::from(*encrypted.last()?) > round.saturating_sub(32) {
        if round >= 288 {
            return None;
        }
        let mut combined = Vec::with_capacity(password.len() + key.len() + user.len());
        combined.extend_from_slice(password);
        combined.extend_from_slice(&key);
        combined.extend_from_slice(user);
        let mut repeated = Vec::with_capacity(combined.len().checked_mul(64)?);
        for _ in 0..64 {
            repeated.extend_from_slice(&combined);
        }
        let iv: [u8; 16] = key.get(16..32)?.try_into().ok()?;
        encrypted = aes_cbc_encrypt(key.get(..16)?, &iv, &repeated)?;
        key = match encrypted
            .iter()
            .take(16)
            .map(|byte| usize::from(*byte))
            .sum::<usize>()
            % 3
        {
            0 => sha256(&encrypted).to_vec(),
            1 => sha384(&encrypted).to_vec(),
            _ => sha512(&encrypted).to_vec(),
        };
        round += 1;
    }
    key.get(..32)?.try_into().ok()
}

fn sha256_many(parts: &[&[u8]]) -> [u8; 32] {
    let capacity = parts.iter().map(|part| part.len()).sum();
    let mut bytes = Vec::with_capacity(capacity);
    for part in parts {
        bytes.extend_from_slice(part);
    }
    sha256(&bytes)
}

fn crypt_filter_method(
    dictionary: &PdfDict,
    selected_key: &str,
    offset: usize,
) -> Result<CryptMethod, Diagnostic> {
    let selected = dict_name(dictionary, selected_key).unwrap_or("Identity");
    if selected == "Identity" {
        return Ok(CryptMethod::Identity);
    }
    let Some(PdfValue::Dict(filters)) = dictionary.get("CF") else {
        return Err(password_error(
            DiagnosticCode::FormatInvalid,
            offset,
            "PDF encryption dictionary is missing its crypt filters",
        ));
    };
    let Some(PdfValue::Dict(filter)) = filters.get(selected) else {
        return Err(password_error(
            DiagnosticCode::FormatInvalid,
            offset,
            "PDF encryption dictionary references an unknown crypt filter",
        ));
    };
    match dict_name(filter, "CFM") {
        Some("V2") => Ok(CryptMethod::Rc4),
        Some("AESV2") => Ok(CryptMethod::Aes128),
        Some("AESV3") => Ok(CryptMethod::Aes256),
        Some("None") => Ok(CryptMethod::Identity),
        _ => Err(password_error(
            DiagnosticCode::UnsupportedFeature,
            offset,
            "PDF_ENCRYPTION_FILTER_UNSUPPORTED: unsupported PDF crypt filter",
        )),
    }
}

fn selected_crypt_filter_uses_embedded_file_auth(dictionary: &PdfDict, key: &str) -> bool {
    let Some(selected) = dict_name(dictionary, key) else {
        return false;
    };
    let Some(PdfValue::Dict(filters)) = dictionary.get("CF") else {
        return false;
    };
    let Some(PdfValue::Dict(filter)) = filters.get(selected) else {
        return false;
    };
    dict_name(filter, "AuthEvent") == Some("EFOpen")
}

fn pdf_string(value: &PdfValue) -> Option<&[u8]> {
    match value {
        PdfValue::String(bytes) => Some(bytes),
        _ => None,
    }
}

fn decrypt_pdf_value(
    value: &mut PdfValue,
    object_id: ObjectId,
    handler: &SecurityHandler,
    depth: usize,
) -> Result<(), ()> {
    if depth > MAX_VALUE_DEPTH {
        return Err(());
    }
    match value {
        PdfValue::String(bytes) => {
            *bytes =
                decrypt_pdf_bytes(bytes, object_id, handler, handler.string_method).ok_or(())?;
        }
        PdfValue::Array(values) => {
            for value in values {
                decrypt_pdf_value(value, object_id, handler, depth + 1)?;
            }
        }
        PdfValue::Dict(dict) => {
            for value in dict.values_mut() {
                decrypt_pdf_value(value, object_id, handler, depth + 1)?;
            }
        }
        PdfValue::Stream { dict, bytes } => {
            let skip_stream = dict_name(dict, "Type") == Some("XRef")
                || !handler.encrypt_metadata && dict_name(dict, "Type") == Some("Metadata");
            for value in dict.values_mut() {
                decrypt_pdf_value(value, object_id, handler, depth + 1)?;
            }
            if !skip_stream {
                *bytes =
                    decrypt_pdf_bytes(bytes, object_id, handler, handler.stream_method).ok_or(())?;
            }
        }
        PdfValue::Null
        | PdfValue::Bool(_)
        | PdfValue::Number(_)
        | PdfValue::Name(_)
        | PdfValue::Ref(_) => {}
    }
    Ok(())
}

fn decrypt_pdf_bytes(
    bytes: &[u8],
    object_id: ObjectId,
    handler: &SecurityHandler,
    method: CryptMethod,
) -> Option<Vec<u8>> {
    if matches!(method, CryptMethod::Identity) {
        return Some(bytes.to_vec());
    }
    if matches!(method, CryptMethod::Aes256) {
        let iv: [u8; 16] = bytes.get(..16)?.try_into().ok()?;
        return aes_cbc_decrypt(&handler.key, &iv, bytes.get(16..)?, true);
    }
    let mut key_input = handler.key.clone();
    key_input.extend_from_slice(&object_id.0.to_le_bytes()[..3]);
    key_input.extend_from_slice(&object_id.1.to_le_bytes());
    if matches!(method, CryptMethod::Aes128) {
        key_input.extend_from_slice(b"sAlT");
    }
    let digest = md5(&key_input);
    let key_length = (handler.key.len() + 5).min(16);
    match method {
        CryptMethod::Rc4 => Some(rc4(&digest[..key_length], bytes)),
        CryptMethod::Aes128 => {
            let iv: [u8; 16] = bytes.get(..16)?.try_into().ok()?;
            aes_cbc_decrypt(&digest[..key_length], &iv, bytes.get(16..)?, true)
        }
        CryptMethod::Identity | CryptMethod::Aes256 => unreachable!(),
    }
}

fn parse_bare_object_dict(bytes: &[u8], start: usize, limits: Limits) -> Option<(PdfDict, usize)> {
    let mut parser = PdfParser::new(bytes, start, limits);
    let mut dict = PdfDict::new();
    loop {
        parser.skip_space();
        let key_start = parser.position;
        if parser.consume_keyword(b"stream") || parser.consume_keyword(b"endobj") {
            parser.position = key_start;
            break;
        }
        parser.position = key_start;
        let Ok(PdfValue::Name(key)) = parser.parse_value(0) else {
            parser.position = key_start.saturating_add(1);
            while parser.position < bytes.len()
                && bytes[parser.position] != b'/'
                && !bytes[parser.position..].starts_with(b"stream")
                && !bytes[parser.position..].starts_with(b"endobj")
            {
                parser.position += 1;
            }
            if parser.position >= bytes.len() {
                break;
            }
            continue;
        };
        let value = if key == "Resources" {
            parser.skip_space();
            if parser.bytes.get(parser.position) == Some(&b'/') {
                PdfValue::Dict(parse_bare_page_resources(&mut parser)?)
            } else {
                parser.parse_value(0).ok()?
            }
        } else {
            parser.parse_value(0).ok()?
        };
        dict.insert(key, value);
    }
    parser.skip_space();
    let end = parser.position;
    let terminated = parser.consume_keyword(b"stream") || parser.consume_keyword(b"endobj");
    (!dict.is_empty() && terminated).then_some((dict, end))
}

fn parse_bare_page_resources(parser: &mut PdfParser<'_>) -> Option<PdfDict> {
    const CATEGORIES: &[&str] = &[
        "ColorSpace",
        "ExtGState",
        "Font",
        "Pattern",
        "ProcSet",
        "Properties",
        "Shading",
        "XObject",
    ];
    const PAGE_KEYS: &[&str] = &[
        "Annots", "ArtBox", "BleedBox", "Contents", "CropBox", "Dur", "MediaBox", "Parent",
        "Rotate", "TrimBox", "Type", "UserUnit",
    ];
    let mut resources = PdfDict::new();
    loop {
        parser.skip_space();
        let category_start = parser.position;
        let PdfValue::Name(category) = parser.parse_value(0).ok()? else {
            parser.position = category_start;
            break;
        };
        if !CATEGORIES.contains(&category.as_str()) {
            parser.position = category_start;
            break;
        }
        if category == "ProcSet" {
            resources.insert(category, parser.parse_value(0).ok()?);
            continue;
        }
        let mut entries = PdfDict::new();
        loop {
            parser.skip_space();
            let entry_start = parser.position;
            let PdfValue::Name(name) = parser.parse_value(0).ok()? else {
                parser.position = entry_start;
                break;
            };
            if CATEGORIES.contains(&name.as_str()) || PAGE_KEYS.contains(&name.as_str()) {
                parser.position = entry_start;
                break;
            }
            let value = parser.parse_value(0).ok()?;
            entries.insert(name, value);
        }
        resources.insert(category, PdfValue::Dict(entries));
    }
    Some(resources)
}

fn normalize_recovered_page_dictionary(value: &mut PdfValue) {
    let PdfValue::Dict(page) = value else {
        return;
    };
    if dict_name(page, "Type") != Some("Page") {
        return;
    }
    if !matches!(page.get("Resources"), Some(PdfValue::Dict(_))) {
        return;
    }
    let Some(PdfValue::Dict(mut resources)) = page.remove("Resources") else {
        unreachable!("the resource value was checked above");
    };
    const PAGE_KEYS: [&str; 11] = [
        "Annots", "ArtBox", "BleedBox", "Contents", "CropBox", "Dur", "MediaBox", "Parent",
        "Rotate", "TrimBox", "UserUnit",
    ];
    for value in resources.values_mut() {
        let PdfValue::Dict(entries) = value else {
            continue;
        };
        for key in PAGE_KEYS {
            if !page.contains_key(key)
                && let Some(value) = entries.remove(key)
            {
                page.insert(key.to_owned(), value);
            }
        }
    }
    for key in PAGE_KEYS {
        if !page.contains_key(key)
            && let Some(value) = resources.remove(key)
        {
            page.insert(key.to_owned(), value);
        }
    }
    page.insert("Resources".to_owned(), PdfValue::Dict(resources));
}

impl ObjectStore {
    fn scan(bytes: &[u8], limits: Limits) -> Result<Self, Diagnostic> {
        let mut objects = BTreeMap::new();
        let active_xref_offsets = classic_xref_offsets(bytes, limits);
        let mut diagnostics = Vec::new();
        let mut recovered_stream_lengths = BTreeSet::new();
        let mut position = 0;
        while position < bytes.len() {
            if !bytes[position].is_ascii_digit()
                || position > 0 && !is_pdf_space(bytes[position - 1])
            {
                position += 1;
                continue;
            }
            let mut parser = PdfParser::new(bytes, position, limits);
            let Ok(number) = parser.parse_unsigned() else {
                position += 1;
                continue;
            };
            parser.skip_space();
            let generation_start = parser.position;
            let generation = match parser.parse_unsigned() {
                Ok(generation) if generation <= u16::MAX as u32 => generation as u16,
                Ok(_) | Err(_)
                    if parser.position > generation_start
                        && parser.position - generation_start <= 32 =>
                {
                    diagnostics.push(
                        Diagnostic::warning(
                            DiagnosticCode::FormatInvalid,
                            Phase::Parse,
                            Fidelity::Approximate,
                            "PDF_OBJECT_GENERATION_NORMALIZED: an invalid generation number was recovered as zero",
                        )
                        .in_part("document.pdf")
                        .with_detail("object", number.to_string()),
                    );
                    0
                }
                _ => {
                    position += 1;
                    continue;
                }
            };
            parser.skip_space();
            if !parser.consume_keyword(b"obj") {
                position += 1;
                continue;
            }
            parser.skip_space();
            let value_offset = parser.position;
            let mut bare_dictionary_recovered = false;
            let mut value = if let Some((dict, end)) = (bytes.get(value_offset) == Some(&b'/'))
                .then(|| parse_bare_object_dict(bytes, value_offset, limits))
                .flatten()
            {
                bare_dictionary_recovered = true;
                parser.position = end;
                PdfValue::Dict(dict)
            } else {
                let Ok(value) = parser.parse_value(0) else {
                    position += 1;
                    continue;
                };
                value
            };
            normalize_recovered_page_dictionary(&mut value);
            if parser.recovered_dicts > 0 || bare_dictionary_recovered {
                diagnostics.push(
                    Diagnostic::warning(
                        DiagnosticCode::FormatInvalid,
                        Phase::Parse,
                        Fidelity::Approximate,
                        "PDF_DICTIONARY_TERMINATOR_RECOVERED: a dictionary missing its closing delimiter was isolated at the object boundary",
                    )
                    .in_part("document.pdf")
                    .with_detail("object", number.to_string()),
                );
            }
            parser.skip_space();
            if let PdfValue::Dict(dict) = &value
                && parser.consume_keyword(b"stream")
            {
                let dict = dict.clone();
                if bytes.get(parser.position) == Some(&b'\r') {
                    parser.position += 1;
                    if bytes.get(parser.position) == Some(&b'\n') {
                        parser.position += 1;
                    }
                } else if bytes.get(parser.position) == Some(&b'\n') {
                    parser.position += 1;
                } else {
                    position += 1;
                    continue;
                }
                let stream_start = parser.position;
                let direct_length = dict.get("Length").and_then(number_usize);
                let direct_stream_end = direct_length
                    .and_then(|length| stream_start.checked_add(length))
                    .filter(|end| *end <= bytes.len())
                    .filter(|&end| {
                        let mut marker = end;
                        if bytes.get(marker) == Some(&b'\r') {
                            marker += 1;
                            if bytes.get(marker) == Some(&b'\n') {
                                marker += 1;
                            }
                        } else if bytes.get(marker) == Some(&b'\n') {
                            marker += 1;
                        }
                        bytes.get(marker..marker.saturating_add(b"endstream".len()))
                            == Some(b"endstream")
                    });
                let stream_end =
                    direct_stream_end.or_else(|| find_bytes(bytes, stream_start, b"endstream"));
                let Some(stream_end) = stream_end else {
                    diagnostics.push(
                        Diagnostic::warning(
                            DiagnosticCode::FormatInvalid,
                            Phase::Parse,
                            Fidelity::Omitted,
                            "PDF_UNTERMINATED_STREAM_OMITTED: an unterminated trailing stream and the ambiguous bytes after it were omitted",
                        )
                        .in_part("document.pdf")
                        .with_detail("object", number.to_string()),
                    );
                    break;
                };
                if stream_end.saturating_sub(stream_start) > limits.max_entry_uncompressed_bytes {
                    return Err(pdf_error(
                        stream_start,
                        "PDF stream exceeds the configured byte limit",
                    ));
                }
                value = PdfValue::Stream {
                    dict,
                    bytes: bytes[stream_start..stream_end].to_vec(),
                };
                if direct_length.is_some() && direct_stream_end.is_none() {
                    recovered_stream_lengths.insert((number, generation));
                }
                parser.position = stream_end;
                if let Some(endstream) = find_bytes(bytes, parser.position, b"endstream") {
                    parser.position = endstream + b"endstream".len();
                }
            }
            if objects.len() >= limits.max_document_objects {
                return Err(object_limit());
            }
            let id = (number, generation);
            let candidate = IndirectObject {
                value,
                offset: value_offset,
            };
            match active_xref_offsets
                .as_ref()
                .and_then(|offsets| offsets.get(&id))
            {
                Some(expected) if *expected == position => {
                    objects.insert(id, candidate);
                }
                Some(_) => {
                    objects.entry(id).or_insert(candidate);
                }
                None => {
                    objects.insert(id, candidate);
                }
            }
            let endobj = find_bytes(bytes, parser.position, b"endobj");
            let next_object = find_indirect_object_header(
                bytes,
                parser.position,
                endobj.unwrap_or(bytes.len()),
                limits,
            );
            if let Some(next_object) = next_object {
                diagnostics.push(
                    Diagnostic::warning(
                        DiagnosticCode::FormatInvalid,
                        Phase::Parse,
                        Fidelity::Approximate,
                        "PDF_ENDOBJ_RECOVERED: a missing endobj marker was recovered at the next indirect object",
                    )
                    .in_part("document.pdf")
                    .with_detail("object", number.to_string()),
                );
                position = next_object;
            } else {
                position = endobj.map_or(parser.position.max(position + 1), |end| {
                    end + b"endobj".len()
                });
            }
        }
        let stream_lengths: BTreeMap<_, _> = objects
            .iter()
            .filter_map(|(&id, object)| {
                let PdfValue::Stream { dict, .. } = &object.value else {
                    return None;
                };
                let length = match dict.get("Length")? {
                    value @ PdfValue::Number(_) => number_usize(value),
                    PdfValue::Ref(length_id) => objects
                        .get(length_id)
                        .and_then(|object| number_usize(&object.value)),
                    _ => None,
                };
                Some((id, length))
            })
            .collect();
        for (id, object) in &mut objects {
            let PdfValue::Stream { bytes, .. } = &mut object.value else {
                continue;
            };
            if recovered_stream_lengths.contains(id) {
                bytes.truncate(trim_stream_end(bytes, bytes.len()));
            } else if let Some(length) = stream_lengths.get(id).copied().flatten()
                && length <= bytes.len()
            {
                bytes.truncate(length);
            } else {
                bytes.truncate(trim_stream_end(bytes, bytes.len()));
            }
        }
        Ok(Self {
            objects,
            active_xref_offsets,
            decoded_function_streams: Mutex::new(BTreeMap::new()),
            type4_programs: Mutex::new(BTreeMap::new()),
            limits,
            diagnostics,
        })
    }

    fn get(&self, id: ObjectId) -> Option<&IndirectObject> {
        self.objects.get(&id).or_else(|| {
            self.objects
                .range((id.0, 0)..=(id.0, u16::MAX))
                .next_back()
                .map(|(_, object)| object)
        })
    }

    fn decrypt(
        &mut self,
        metadata: EncryptionMetadata,
        password: Option<&[u8]>,
        offset: usize,
    ) -> Result<(), Diagnostic> {
        let mut encryption_objects = BTreeSet::new();
        let dictionary = match metadata.dictionary {
            EncryptionDictionary::Indirect(id) => {
                let Some(dictionary) = self.get(id).and_then(|object| match &object.value {
                    PdfValue::Dict(dictionary) => Some(dictionary),
                    _ => None,
                }) else {
                    self.diagnostics.push(
                        Diagnostic::warning(
                            DiagnosticCode::FormatInvalid,
                            Phase::Security,
                            Fidelity::Omitted,
                            "PDF_INVALID_ENCRYPTION_DICTIONARY_IGNORED: the unusable encryption dictionary was isolated",
                        )
                        .in_part("document.pdf"),
                    );
                    return Ok(());
                };
                encryption_objects.insert(id);
                dictionary.clone()
            }
            EncryptionDictionary::Inline(dictionary) => dictionary,
        };
        let dictionary =
            resolve_encryption_dictionary(self, &dictionary, &mut encryption_objects, 0)?;
        let handler = security_handler(&dictionary, &metadata.file_id, password, offset)?;
        for (&object_id, object) in &mut self.objects {
            if encryption_objects.contains(&object_id) {
                continue;
            }
            if decrypt_pdf_value(&mut object.value, object_id, &handler, 0).is_err() {
                object.value = PdfValue::Null;
                self.diagnostics.push(
                    Diagnostic::warning(
                        DiagnosticCode::FormatInvalid,
                        Phase::Security,
                        Fidelity::Omitted,
                        "PDF_ENCRYPTED_OBJECT_OMITTED: one malformed encrypted object was isolated",
                    )
                    .in_part("document.pdf")
                    .with_detail("object", object_id.0.to_string()),
                );
            }
        }
        Ok(())
    }

    fn resolve<'a>(&'a self, value: &'a PdfValue) -> Option<&'a PdfValue> {
        let mut value = value;
        for _ in 0..MAX_VALUE_DEPTH {
            let PdfValue::Ref(id) = value else {
                return Some(value);
            };
            value = &self.get(*id)?.value;
        }
        None
    }

    fn dict<'a>(&'a self, value: &'a PdfValue) -> Option<&'a PdfDict> {
        match self.resolve(value)? {
            PdfValue::Dict(dict) | PdfValue::Stream { dict, .. } => Some(dict),
            _ => None,
        }
    }

    fn expand_object_streams(&mut self) -> Result<(), Diagnostic> {
        let streams: Vec<_> = self
            .objects
            .iter()
            .filter_map(|(&id, object)| {
                let PdfValue::Stream { dict, .. } = &object.value else {
                    return None;
                };
                (dict_name(dict, "Type") == Some("ObjStm")).then_some((id, object.clone()))
            })
            .collect();
        for (id, object) in streams {
            if let Err(error) = self.expand_object_stream(&object) {
                if is_pdf_resource_limit(&error) {
                    return Err(error);
                }
                self.diagnostics.push(
                    omitted_pdf_diagnostic(error, 0, "A malformed PDF object stream was isolated")
                        .with_detail("object", id.0.to_string()),
                );
            }
        }
        Ok(())
    }

    fn expand_object_stream(&mut self, object: &IndirectObject) -> Result<(), Diagnostic> {
        let PdfValue::Stream { dict, .. } = &object.value else {
            return Ok(());
        };
        let count = dict.get("N").and_then(number_usize).ok_or_else(|| {
            pdf_error(
                object.offset,
                "PDF object stream is missing a valid N entry",
            )
        })?;
        let first = dict.get("First").and_then(number_usize).ok_or_else(|| {
            pdf_error(
                object.offset,
                "PDF object stream is missing a valid First entry",
            )
        })?;
        if count > self.limits.max_document_objects {
            return Err(object_limit());
        }
        let decoded = decode_stream(&object.value, self, self.limits)?;
        if first > decoded.len() {
            return Err(pdf_error(
                object.offset,
                "PDF object stream First entry is out of range",
            ));
        }
        let mut header = PdfParser::new(&decoded[..first], 0, self.limits);
        let mut entries = Vec::with_capacity(count);
        for _ in 0..count {
            header.skip_space();
            let number = header.parse_unsigned()?;
            header.skip_space();
            let offset = header.parse_unsigned()? as usize;
            entries.push((number, offset));
        }
        for (index, &(number, relative)) in entries.iter().enumerate() {
            let start = first.checked_add(relative).ok_or_else(object_limit)?;
            let end = entries
                .get(index + 1)
                .and_then(|(_, next)| first.checked_add(*next))
                .unwrap_or(decoded.len());
            if start > end || end > decoded.len() {
                return Err(pdf_error(
                    object.offset,
                    "PDF object stream offset is out of range",
                ));
            }
            let mut parser = PdfParser::new(&decoded[start..end], 0, self.limits);
            let value = parser.parse_value(0)?;
            let candidate = IndirectObject {
                value,
                offset: object.offset,
            };
            if self
                .active_xref_offsets
                .as_ref()
                .is_some_and(|offsets| offsets.contains_key(&(number, 0)))
            {
                continue;
            }
            match self.objects.entry((number, 0)) {
                std::collections::btree_map::Entry::Vacant(entry) => {
                    entry.insert(candidate);
                }
                std::collections::btree_map::Entry::Occupied(mut entry)
                    if candidate.offset > entry.get().offset =>
                {
                    entry.insert(candidate);
                }
                std::collections::btree_map::Entry::Occupied(_) => {}
            }
        }
        Ok(())
    }
}

fn classic_xref_offsets(bytes: &[u8], limits: Limits) -> Option<BTreeMap<ObjectId, usize>> {
    let marker = bytes
        .windows(b"startxref".len())
        .rposition(|window| window == b"startxref")?;
    let mut start = PdfParser::new(bytes, marker + b"startxref".len(), limits);
    start.skip_space();
    let offset = usize::try_from(start.parse_unsigned().ok()?).ok()?;
    let mut parser = PdfParser::new(bytes, offset, limits);
    parser.skip_space();
    if !parser.consume_keyword(b"xref") {
        return None;
    }
    let mut offsets = BTreeMap::new();
    loop {
        parser.skip_space();
        if parser.consume_keyword(b"trailer") {
            break;
        }
        let first = parser.parse_unsigned().ok()?;
        parser.skip_space();
        let count = parser.parse_unsigned().ok()?;
        if usize::try_from(count).ok()? > limits.max_document_objects {
            return None;
        }
        for index in 0..count {
            parser.skip_space();
            let object_offset = usize::try_from(parser.parse_unsigned().ok()?).ok()?;
            parser.skip_space();
            let generation = parser.parse_unsigned().ok()?;
            parser.skip_space();
            let in_use = parser.consume_keyword(b"n");
            if !in_use && !parser.consume_keyword(b"f") {
                return None;
            }
            if in_use && generation <= u16::MAX as u32 {
                offsets.insert(
                    (first.checked_add(index)?, generation as u16),
                    object_offset,
                );
            }
        }
    }
    Some(offsets)
}

fn resolve_encryption_dictionary(
    store: &ObjectStore,
    dictionary: &PdfDict,
    referenced: &mut BTreeSet<ObjectId>,
    depth: usize,
) -> Result<PdfDict, Diagnostic> {
    if depth > MAX_VALUE_DEPTH {
        return Err(pdf_error(
            0,
            "PDF encryption dictionary reference depth exceeds the parser limit",
        ));
    }
    dictionary
        .iter()
        .map(|(key, value)| {
            resolve_encryption_value(store, value, referenced, depth + 1)
                .map(|value| (key.clone(), value))
        })
        .collect()
}

fn resolve_encryption_value(
    store: &ObjectStore,
    value: &PdfValue,
    referenced: &mut BTreeSet<ObjectId>,
    depth: usize,
) -> Result<PdfValue, Diagnostic> {
    if depth > MAX_VALUE_DEPTH {
        return Err(pdf_error(
            0,
            "PDF encryption value reference depth exceeds the parser limit",
        ));
    }
    match value {
        PdfValue::Ref(id) => {
            referenced.insert(*id);
            let value = store.get(*id).map(|object| &object.value).ok_or_else(|| {
                pdf_error(0, "PDF encryption dictionary references a missing object")
            })?;
            resolve_encryption_value(store, value, referenced, depth + 1)
        }
        PdfValue::Dict(dictionary) => Ok(PdfValue::Dict(resolve_encryption_dictionary(
            store,
            dictionary,
            referenced,
            depth + 1,
        )?)),
        PdfValue::Array(values) => values
            .iter()
            .map(|value| resolve_encryption_value(store, value, referenced, depth + 1))
            .collect::<Result<Vec<_>, _>>()
            .map(PdfValue::Array),
        value => Ok(value.clone()),
    }
}

#[derive(Clone, Copy, Debug)]
struct Matrix {
    a: f32,
    b: f32,
    c: f32,
    d: f32,
    e: f32,
    f: f32,
}

impl Matrix {
    const IDENTITY: Self = Self {
        a: 1.0,
        b: 0.0,
        c: 0.0,
        d: 1.0,
        e: 0.0,
        f: 0.0,
    };

    fn concat(self, next: Self) -> Self {
        Self {
            a: self.a * next.a + self.c * next.b,
            b: self.b * next.a + self.d * next.b,
            c: self.a * next.c + self.c * next.d,
            d: self.b * next.c + self.d * next.d,
            e: self.a * next.e + self.c * next.f + self.e,
            f: self.b * next.e + self.d * next.f + self.f,
        }
    }

    fn point(self, x: f32, y: f32) -> (f32, f32) {
        (
            self.a * x + self.c * y + self.e,
            self.b * x + self.d * y + self.f,
        )
    }

    fn scale(self) -> f32 {
        (self.a.hypot(self.b) + self.c.hypot(self.d)) * 0.5
    }

    fn inverse_point(self, x: f32, y: f32) -> Option<(f32, f32)> {
        let determinant = self.a * self.d - self.b * self.c;
        if !determinant.is_finite() || determinant.abs() <= f32::EPSILON {
            return None;
        }
        let x = x - self.e;
        let y = y - self.f;
        Some((
            (self.d * x - self.c * y) / determinant,
            (-self.b * x + self.a * y) / determinant,
        ))
    }
}

