struct PageContext<'a> {
    store: &'a ObjectStore,
    page_indices: &'a BTreeMap<ObjectId, u32>,
    named_destinations: &'a BTreeMap<String, PdfValue>,
    optional_content: &'a OptionalContentConfig,
    limits: Limits,
    unit_index: u32,
    page_bounds: Rect,
    objects: Vec<Object>,
    diagnostics: Vec<Diagnostic>,
    diagnostic_keys: BTreeSet<&'static str>,
    active_forms: BTreeSet<ObjectId>,
    form_cycle_count: usize,
    parent_numeric_id: Option<u32>,
    fonts: &'a mut BTreeMap<ObjectId, Rc<FontInfo>>,
    inline_fonts: &'a mut BTreeMap<ObjectId, PdfValue>,
    image_resources: &'a mut BTreeMap<ObjectId, String>,
    image_masks: &'a mut BTreeMap<ObjectId, (String, u32, u32)>,
    shading_stops: BTreeMap<(ObjectId, u32), Vec<GradientStop>>,
}

impl<'a> PageContext<'a> {
    fn warning(&mut self, key: &'static str, message: &'static str) {
        self.warning_at(key, message, None);
    }

    fn warning_at(&mut self, key: &'static str, message: &'static str, bounds: Option<Rect>) {
        if self.diagnostic_keys.insert(key) {
            let mut diagnostic = Diagnostic::warning(
                DiagnosticCode::UnsupportedFeature,
                Phase::Parse,
                Fidelity::Unsupported,
                message,
            )
            .in_part("document.pdf")
            .with_detail("unitIndex", self.unit_index.to_string());
            if let Some(bounds) = bounds {
                diagnostic = diagnostic
                    .with_detail("x", bounds.x.to_string())
                    .with_detail("y", bounds.y.to_string())
                    .with_detail("width", bounds.width.to_string())
                    .with_detail("height", bounds.height.to_string());
            }
            self.diagnostics.push(diagnostic);
        }
    }

    fn push_object(
        &mut self,
        kind: ObjectKind,
        bounds: Rect,
        text: Option<String>,
        visual: Visual,
        source: SourceRef,
    ) -> Result<(), Diagnostic> {
        let parent_numeric_id = self.parent_numeric_id;
        self.push_object_with_parent(kind, bounds, text, visual, source, parent_numeric_id)
            .map(|_| ())
    }

    fn push_object_with_parent(
        &mut self,
        kind: ObjectKind,
        bounds: Rect,
        text: Option<String>,
        visual: Visual,
        source: SourceRef,
        parent_numeric_id: Option<u32>,
    ) -> Result<u32, Diagnostic> {
        if self.objects.len() >= self.limits.max_document_objects || !bounds.is_valid() {
            return Err(object_limit());
        }
        let numeric_id = u32::try_from(self.objects.len()).map_err(|_| object_limit())?;
        self.objects.push(Object {
            numeric_id,
            parent_numeric_id,
            stable_id: format!("pdf:{}:{numeric_id}", self.unit_index),
            parent_stable_id: parent_numeric_id
                .map(|parent| format!("pdf:{}:{parent}", self.unit_index)),
            kind,
            unit_index: self.unit_index,
            bounds,
            z: numeric_id as i32,
            text,
            source,
            visual,
        });
        Ok(numeric_id)
    }
}

fn pdf_text_layout(visual: &Visual) -> Option<&TextLayout> {
    match visual {
        Visual::TextLayout { layout, .. } => Some(layout),
        Visual::Effect { visual, .. }
        | Visual::Layer { visual, .. }
        | Visual::TextEffects { visual, .. }
        | Visual::StrokeStyle { visual, .. }
        | Visual::AdvancedEffect { visual, .. } => pdf_text_layout(visual),
        _ => None,
    }
}

fn batchable_pdf_text(object: &Object) -> bool {
    object.kind == ObjectKind::TextBox
        && object.text.as_ref().is_some_and(|text| !text.is_empty())
        && matches!(
            object.source.locator,
            SourceLocator::Pdf {
                kind: "text",
                action: None,
                ..
            }
        )
        && match pdf_text_layout(&object.visual) {
            Some(layout) => {
                layout.orientation == TextOrientation::Horizontal
                    && layout.rotation_degrees.abs() <= f32::EPSILON
            }
            None => matches!(object.visual, Visual::None),
        }
}

fn continues_pdf_text_batch(left: &Object, right: &Object) -> bool {
    if !batchable_pdf_text(left)
        || !batchable_pdf_text(right)
        || left.parent_numeric_id != right.parent_numeric_id
        || left.z.checked_add(1) != Some(right.z)
    {
        return false;
    }
    let tolerance = (left.bounds.height.min(right.bounds.height) * 0.02).max(0.01);
    (left.bounds.y - right.bounds.y).abs() <= tolerance
        && (left.bounds.height - right.bounds.height).abs() <= tolerance
        && (right.bounds.x - left.bounds.x - left.bounds.width).abs() <= tolerance
}

/// Coalesces only the public/object boundary. Child visuals retain their original
/// bounds and paint state and are replayed by the renderer without re-layout.
fn compact_pdf_text_batches(objects: &mut Vec<Object>) {
    let original = std::mem::take(objects);
    let mut compacted = Vec::with_capacity(original.len());
    let mut remapped_ids = BTreeMap::new();
    let mut start = 0;
    while start < original.len() {
        let mut end = start + 1;
        while end < original.len()
            && end - start < MAX_PDF_TEXT_BATCH_ITEMS
            && continues_pdf_text_batch(&original[end - 1], &original[end])
        {
            end += 1;
        }
        let new_id = compacted.len() as u32;
        for object in &original[start..end] {
            remapped_ids.insert(object.numeric_id, new_id);
        }
        if end - start == 1 {
            compacted.push(original[start].clone());
        } else {
            let first = &original[start];
            let mut left = first.bounds.x;
            let mut top = first.bounds.y;
            let mut right = first.bounds.x + first.bounds.width;
            let mut bottom = first.bounds.y + first.bounds.height;
            let mut text = String::new();
            let mut children = Vec::with_capacity(end - start);
            for object in &original[start..end] {
                left = left.min(object.bounds.x);
                top = top.min(object.bounds.y);
                right = right.max(object.bounds.x + object.bounds.width);
                bottom = bottom.max(object.bounds.y + object.bounds.height);
                text.push_str(object.text.as_deref().unwrap_or_default());
                children.push(VisualBrushChild {
                    bounds: object.bounds,
                    visual: object.visual.clone(),
                });
            }
            let mut source = first.source.clone();
            source.mapping = MappingQuality::Derived;
            compacted.push(Object {
                numeric_id: new_id,
                parent_numeric_id: first.parent_numeric_id,
                stable_id: first.stable_id.clone(),
                parent_stable_id: first.parent_stable_id.clone(),
                kind: ObjectKind::TextBox,
                unit_index: first.unit_index,
                bounds: Rect {
                    x: left,
                    y: top,
                    width: right - left,
                    height: bottom - top,
                },
                z: first.z,
                text: Some(text),
                source,
                visual: Visual::Group { children },
            });
        }
        start = end;
    }
    for (index, object) in compacted.iter_mut().enumerate() {
        object.numeric_id = index as u32;
        object.parent_numeric_id = object
            .parent_numeric_id
            .and_then(|parent| remapped_ids.get(&parent).copied());
        object.stable_id = format!("pdf:{}:{}", object.unit_index, object.numeric_id);
        object.parent_stable_id = object
            .parent_numeric_id
            .map(|parent| format!("pdf:{}:{parent}", object.unit_index));
    }
    *objects = compacted;
}

#[derive(Default)]
struct PdfPath {
    commands: Vec<PathCommand>,
    points: Vec<(f32, f32)>,
}

impl PdfPath {
    fn clear(&mut self) {
        self.commands.clear();
        self.points.clear();
    }

    fn point(&mut self, command: PathCommand, points: &[(f32, f32)]) {
        self.commands.push(command);
        self.points.extend_from_slice(points);
    }

    fn painted(&self) -> Option<(Rect, Vec<PathCommand>)> {
        let &(mut min_x, mut min_y) = self.points.first()?;
        let (mut max_x, mut max_y) = (min_x, min_y);
        for &(x, y) in &self.points[1..] {
            min_x = min_x.min(x);
            min_y = min_y.min(y);
            max_x = max_x.max(x);
            max_y = max_y.max(y);
        }
        let bounds = Rect {
            x: min_x,
            y: min_y,
            width: (max_x - min_x).max(0.01),
            height: (max_y - min_y).max(0.01),
        };
        let commands = self
            .commands
            .iter()
            .map(|command| match *command {
                PathCommand::MoveTo { x, y } => PathCommand::MoveTo {
                    x: x - min_x,
                    y: y - min_y,
                },
                PathCommand::LineTo { x, y } => PathCommand::LineTo {
                    x: x - min_x,
                    y: y - min_y,
                },
                PathCommand::QuadraticCurveTo { cpx, cpy, x, y } => PathCommand::QuadraticCurveTo {
                    cpx: cpx - min_x,
                    cpy: cpy - min_y,
                    x: x - min_x,
                    y: y - min_y,
                },
                PathCommand::BezierCurveTo {
                    cp1x,
                    cp1y,
                    cp2x,
                    cp2y,
                    x,
                    y,
                } => PathCommand::BezierCurveTo {
                    cp1x: cp1x - min_x,
                    cp1y: cp1y - min_y,
                    cp2x: cp2x - min_x,
                    cp2y: cp2y - min_y,
                    x: x - min_x,
                    y: y - min_y,
                },
                PathCommand::ClosePath => PathCommand::ClosePath,
            })
            .collect();
        Some((bounds, commands))
    }
}

enum ContentToken<'a> {
    Value(PdfValue),
    Operator(&'a str, usize),
}

struct ContentParser<'a> {
    parser: PdfParser<'a>,
}

impl<'a> ContentParser<'a> {
    fn new(bytes: &'a [u8], limits: Limits) -> Self {
        Self {
            parser: PdfParser::new(bytes, 0, limits),
        }
    }

    fn next(&mut self) -> Result<Option<ContentToken<'a>>, Diagnostic> {
        self.parser.skip_space();
        if self.parser.position >= self.parser.bytes.len() {
            return Ok(None);
        }
        let start = self.parser.position;
        let byte = self.parser.bytes[start];
        if byte == b'[' {
            return self.recovered_array().map(ContentToken::Value).map(Some);
        }
        if matches!(byte, b'/' | b'(' | b'<') || matches!(byte, b'+' | b'-' | b'.' | b'0'..=b'9') {
            return self
                .parser
                .parse_value(0)
                .map(ContentToken::Value)
                .map(Some);
        }
        let end = self.parser.bytes[start..]
            .iter()
            .position(|byte| is_pdf_space(*byte) || is_pdf_delimiter(*byte))
            .map_or(self.parser.bytes.len(), |length| start + length);
        if end == start {
            return Err(pdf_error(start, "invalid PDF content token"));
        }
        self.parser.position = end;
        let word = std::str::from_utf8(&self.parser.bytes[start..end])
            .map_err(|_| pdf_error(start, "PDF content operator is not ASCII"))?;
        match word {
            "true" => Ok(Some(ContentToken::Value(PdfValue::Bool(true)))),
            "false" => Ok(Some(ContentToken::Value(PdfValue::Bool(false)))),
            "null" => Ok(Some(ContentToken::Value(PdfValue::Null))),
            _ => Ok(Some(ContentToken::Operator(word, start))),
        }
    }

    fn recovered_array(&mut self) -> Result<PdfValue, Diagnostic> {
        let start = self.parser.position;
        self.parser.position += 1;
        let mut values = Vec::new();
        loop {
            self.parser.skip_space();
            if self.parser.bytes.get(self.parser.position) == Some(&b']') {
                self.parser.position += 1;
                return Ok(PdfValue::Array(values));
            }
            if self.parser.position >= self.parser.bytes.len() {
                return Err(pdf_error(start, "unterminated PDF content array"));
            }
            if values.len() >= self.parser.limits.max_document_objects {
                return Err(object_limit());
            }
            let position = self.parser.position;
            if matches!(self.parser.bytes[position], b'+' | b'-')
                && self
                    .parser
                    .bytes
                    .get(position + 1)
                    .is_none_or(|byte| is_pdf_space(*byte) || is_pdf_delimiter(*byte))
            {
                self.parser.position += 1;
                values.push(PdfValue::Number(0.0));
                continue;
            }
            values.push(self.parser.parse_value(1)?);
        }
    }

    fn inline_image(&mut self) -> Result<Option<PdfValue>, Diagnostic> {
        let bytes = self.parser.bytes;
        let mut dict = BTreeMap::new();
        loop {
            self.parser.skip_space();
            if self
                .parser
                .bytes
                .get(self.parser.position..self.parser.position + 2)
                == Some(b"ID")
                && self
                    .parser
                    .bytes
                    .get(self.parser.position + 2)
                    .is_none_or(|byte| is_pdf_space(*byte))
            {
                self.parser.position += 2;
                break;
            }
            let PdfValue::Name(key) = self.parser.parse_value(0)? else {
                return Err(pdf_error(
                    self.parser.position,
                    "invalid PDF inline image dictionary key",
                ));
            };
            self.parser.skip_space();
            let value = self.parser.parse_value(0)?;
            let canonical = inline_image_key(&key);
            // ISO 32000 gives the abbreviated inline-image entries precedence
            // when a malformed dictionary contains both spellings. This is
            // independent of their source order (PDF Association issue 14256).
            if canonical != key || !dict.contains_key(canonical) {
                dict.insert(canonical.to_owned(), inline_image_value(value));
            }
        }
        if bytes.get(self.parser.position) == Some(&b'\r') {
            self.parser.position += 1;
            if bytes.get(self.parser.position) == Some(&b'\n') {
                self.parser.position += 1;
            }
        } else if bytes
            .get(self.parser.position)
            .is_some_and(|byte| is_pdf_space(*byte))
        {
            self.parser.position += 1;
        }
        let start = self.parser.position;
        let mut position = start;
        while position + 2 <= bytes.len() {
            if &bytes[position..position + 2] == b"EI"
                && position
                    .checked_sub(1)
                    .is_some_and(|index| is_pdf_space(bytes[index]))
                && bytes
                    .get(position + 2)
                    .is_none_or(|byte| is_pdf_space(*byte))
            {
                self.parser.position = position + 2;
                let mut end = position;
                if end > start && is_pdf_space(bytes[end - 1]) {
                    end -= 1;
                    if end > start && bytes[end - 1] == b'\r' && bytes[end] == b'\n' {
                        end -= 1;
                    }
                }
                return Ok(Some(PdfValue::Stream {
                    dict,
                    bytes: bytes[start..end].to_vec(),
                }));
            }
            position += 1;
        }
        self.parser.position = bytes.len();
        Ok(None)
    }
}

fn inline_image_key(name: &str) -> &str {
    match name {
        "BPC" => "BitsPerComponent",
        "CS" => "ColorSpace",
        "D" => "Decode",
        "DP" => "DecodeParms",
        "F" => "Filter",
        "H" => "Height",
        "IM" => "ImageMask",
        "I" => "Interpolate",
        "W" => "Width",
        _ => name,
    }
}

fn inline_image_value(value: PdfValue) -> PdfValue {
    match value {
        PdfValue::Name(name) => PdfValue::Name(
            match name.as_str() {
                "G" => "DeviceGray",
                "RGB" => "DeviceRGB",
                "CMYK" => "DeviceCMYK",
                "AHx" => "ASCIIHexDecode",
                "A85" => "ASCII85Decode",
                "LZW" => "LZWDecode",
                "Fl" => "FlateDecode",
                "RL" => "RunLengthDecode",
                "CCF" => "CCITTFaxDecode",
                "DCT" => "DCTDecode",
                _ => &name,
            }
            .to_owned(),
        ),
        PdfValue::Array(values) => {
            PdfValue::Array(values.into_iter().map(inline_image_value).collect())
        }
        value => value,
    }
}

pub fn detect_and_parse(bytes: &[u8], limits: Limits) -> Result<Option<Document>, Diagnostic> {
    let Some(prepared) = prepare(bytes, limits, None)? else {
        return Ok(None);
    };
    prepared
        .materialize(None, true, &BTreeSet::new(), 0)
        .map(|(document, _)| Some(document))
}

pub(crate) struct PreparedPdf {
    store: ObjectStore,
    pages: Vec<PageEntry>,
    xfa_packets: BTreeMap<String, Vec<u8>>,
    needs_xfa_rendering: bool,
    limits: Limits,
    has_active_content: bool,
    has_attachments: bool,
}

pub(crate) fn prepare(
    bytes: &[u8],
    limits: Limits,
    password: Option<&[u8]>,
) -> Result<Option<PreparedPdf>, Diagnostic> {
    let header = find_bytes(
        &bytes[..bytes.len().min(PDF_HEADER_SCAN_BYTES)],
        0,
        b"%PDF-",
    );
    let recovered_header = header.is_none()
        && bytes.starts_with(b"%\xe2\xe3\xcf\xd3")
        && find_bytes(bytes, 0, b" obj").is_some()
        && find_bytes(bytes, 0, b"trailer").is_some()
        && find_bytes(bytes, 0, b"/Root").is_some();
    let header = match header {
        Some(header) => {
            let version_end = (header + 8).min(bytes.len());
            if version_end <= header + 5
                || !bytes[header + 5..version_end]
                    .iter()
                    .all(|byte| byte.is_ascii_digit() || *byte == b'.' || is_pdf_space(*byte))
            {
                return Err(pdf_error(header, "invalid PDF header"));
            }
            header
        }
        None if recovered_header => 0,
        None => return Ok(None),
    };
    let has_active_content = contains_token(bytes, b"/JavaScript") || contains_token(bytes, b"/JS");
    let has_attachments =
        contains_token(bytes, b"/EmbeddedFiles") || contains_token(bytes, b"/FileAttachment");

    let mut store = ObjectStore::scan(bytes, limits)?;
    if recovered_header {
        store.diagnostics.push(
            Diagnostic::warning(
                DiagnosticCode::FormatInvalid,
                Phase::Identify,
                Fidelity::Approximate,
                "PDF_HEADER_RECOVERED: the missing PDF version header was recovered from the binary marker and document structure",
            )
            .in_part("document.pdf"),
        );
    }
    if let Some(encryption) = find_encryption_metadata(bytes, &store, limits)? {
        store.decrypt(encryption, password, header)?;
    }
    store.expand_object_streams()?;
    if store.objects.is_empty() {
        return Err(pdf_error(
            header,
            "PDF contains no readable indirect objects",
        ));
    }
    let pages = collect_pages(&mut store)?;
    if pages.is_empty() {
        return Err(pdf_error(header, "PDF page tree contains no pages"));
    }
    if pages.len() > limits.max_document_objects {
        return Err(object_limit());
    }
    let xfa_packets = pdf_xfa_packets(&store, limits);
    let needs_xfa_rendering = pdf_catalog_needs_rendering(&store);
    Ok(Some(PreparedPdf {
        store,
        pages,
        xfa_packets,
        needs_xfa_rendering,
        limits,
        has_active_content,
        has_attachments,
    }))
}

impl PreparedPdf {
    pub(crate) fn materialize(
        &self,
        selected_unit: Option<usize>,
        include_embedded_fonts: bool,
        emitted_font_ids: &BTreeSet<ObjectId>,
        emitted_font_bytes: usize,
    ) -> Result<(Document, BTreeSet<ObjectId>), Diagnostic> {
        let store = &self.store;
        let pages = &self.pages;
        let limits = self.limits;

        let mut document = Document {
            fatal: false,
            format: Some(DocumentFormat::Pdf),
            kind: Some(DocumentKind::Text),
            units: Vec::with_capacity(pages.len()),
            outline: Vec::new(),
            objects: Vec::new(),
            embedded_fonts: Vec::new(),
            font_alternate_names: Vec::new(),
            diagnostics: store.diagnostics.clone(),
        };
        if include_embedded_fonts && self.has_active_content {
            document.diagnostics.push(
                Diagnostic::warning(
                    DiagnosticCode::ActiveContentBlocked,
                    Phase::Security,
                    Fidelity::Blocked,
                    "PDF_ACTIVE_CONTENT_BLOCKED: JavaScript and unsafe actions are not executed",
                )
                .in_part("document.pdf"),
            );
        }
        if include_embedded_fonts && self.has_attachments {
            document.diagnostics.push(
                Diagnostic::warning(
                    DiagnosticCode::ActiveContentBlocked,
                    Phase::Security,
                    Fidelity::Blocked,
                    "PDF_ATTACHMENTS_BLOCKED: embedded files are not exposed or executed",
                )
                .in_part("document.pdf"),
            );
        }

        if self.needs_xfa_rendering
            && let (Some(template), Some(datasets), Some(form)) = (
                self.xfa_packets.get("template"),
                self.xfa_packets.get("datasets"),
                self.xfa_packets.get("form"),
            )
        {
            match pdf_xfa::render(template, datasets, form, limits) {
                Ok(pages) if !pages.is_empty() => {
                    pdf_xfa::materialize(&pages, selected_unit, &mut document)?;
                    return Ok((document, BTreeSet::new()));
                }
                Ok(_) => {}
                Err(error) => document.diagnostics.push(error),
            }
        }

        let mut fonts = BTreeMap::new();
        let mut inline_fonts = BTreeMap::new();
        let mut image_resources = BTreeMap::new();
        let mut image_masks = BTreeMap::new();
        let page_indices = pages
            .iter()
            .enumerate()
            .filter_map(|(index, page)| u32::try_from(index).ok().map(|index| (page.id, index)))
            .collect();
        let named_destinations = collect_named_destinations(store);
        let optional_content = collect_optional_content_config(store);
        document.outline = collect_outline(store, &page_indices, &named_destinations);
        for (index, page) in pages.iter().enumerate() {
            let unit_index = u32::try_from(index).map_err(|_| object_limit())?;
            let media_box = page
                .media_box
                .as_ref()
                .and_then(|value| normalized_pdf_box(store, value));
            let ([media_x0, media_y0, media_x1, media_y1], media_reversed) =
                media_box.unwrap_or(([0.0, 0.0, 612.0, 792.0], false));
            if media_box.is_none() {
                document.diagnostics.push(
                    Diagnostic::warning(
                        DiagnosticCode::ApproximateLayout,
                        Phase::Layout,
                        Fidelity::Approximate,
                        "PDF_PAGE_BOX_FALLBACK: invalid MediaBox was replaced with US Letter",
                    )
                    .in_part("document.pdf")
                    .with_detail("page", (index + 1).to_string()),
                );
            }
            let crop_box = page
                .crop_box
                .as_ref()
                .and_then(|value| normalized_pdf_box(store, value));
            if page.crop_box.is_some() && crop_box.is_none() {
                document.diagnostics.push(
                    Diagnostic::warning(
                        DiagnosticCode::ApproximateLayout,
                        Phase::Layout,
                        Fidelity::Approximate,
                        "PDF_PAGE_BOX_FALLBACK: invalid CropBox was replaced with MediaBox",
                    )
                    .in_part("document.pdf")
                    .with_detail("page", (index + 1).to_string()),
                );
            }
            let (mut page_box, crop_reversed) =
                crop_box.unwrap_or(([media_x0, media_y0, media_x1, media_y1], false));
            if crop_box.is_some() {
                let intersection = [
                    page_box[0].max(media_x0),
                    page_box[1].max(media_y0),
                    page_box[2].min(media_x1),
                    page_box[3].min(media_y1),
                ];
                if intersection[2] > intersection[0] && intersection[3] > intersection[1] {
                    page_box = intersection;
                } else {
                    page_box = [media_x0, media_y0, media_x1, media_y1];
                    document.diagnostics.push(
                        Diagnostic::warning(
                            DiagnosticCode::ApproximateLayout,
                            Phase::Layout,
                            Fidelity::Approximate,
                            "PDF_PAGE_BOX_FALLBACK: empty CropBox and MediaBox intersection was replaced with MediaBox",
                        )
                        .in_part("document.pdf")
                        .with_detail("page", (index + 1).to_string()),
                    );
                }
            }
            if page_box.iter().any(|value| !value.is_finite())
                || page_box[2] - page_box[0] > MAX_PDF_PAGE_POINTS
                || page_box[3] - page_box[1] > MAX_PDF_PAGE_POINTS
            {
                page_box = [0.0, 0.0, 612.0, 792.0];
                document.diagnostics.push(
                    Diagnostic::warning(
                        DiagnosticCode::ApproximateLayout,
                        Phase::Layout,
                        Fidelity::Approximate,
                        "PDF_PAGE_BOX_FALLBACK: an implausibly large page box was replaced with US Letter",
                    )
                    .in_part("document.pdf")
                    .with_detail("page", (index + 1).to_string()),
                );
            }
            let [x0, y0, x1, y1] = page_box;
            if media_reversed || crop_reversed {
                document.diagnostics.push(
                    Diagnostic::warning(
                        DiagnosticCode::ApproximateLayout,
                        Phase::Layout,
                        Fidelity::Approximate,
                        "PDF_PAGE_BOX_NORMALIZED: reversed page-box coordinates were normalized",
                    )
                    .in_part("document.pdf")
                    .with_detail("page", (index + 1).to_string()),
                );
            }
            let rotation = ((page.rotate % 360) + 360) % 360;
            let user_unit = page
                .user_unit
                .as_ref()
                .and_then(|value| store.resolve(value))
                .and_then(number_f32)
                .filter(|value| value.is_finite() && (1.0..=75_000.0).contains(value))
                .unwrap_or(1.0);
            let (width_points, height_points) = if rotation == 90 || rotation == 270 {
                (y1 - y0, x1 - x0)
            } else {
                (x1 - x0, y1 - y0)
            };
            let width = (f64::from(width_points) * f64::from(user_unit) * (96.0 / 72.0)) as f32;
            let height = (f64::from(height_points) * f64::from(user_unit) * (96.0 / 72.0)) as f32;
            if !width.is_finite() || !height.is_finite() || width <= 0.0 || height <= 0.0 {
                return Err(Diagnostic::fatal(
                    DiagnosticCode::ImageDimensionLimit,
                    Phase::Layout,
                    Some(page.offset),
                    "PDF page dimensions exceed the configured render limit",
                )
                .in_part("document.pdf"));
            }
            document.units.push(Unit {
                kind: UnitKind::Page,
                index: unit_index,
                id: format!("pdf:page:{}", page.id.0),
                name: format!("Page {}", index + 1),
                width,
                height,
                rows: 0,
                columns: 0,
                frozen_rows: 0,
                frozen_columns: 0,
                frozen_width: 0.0,
                frozen_height: 0.0,
                row_axis: SheetAxis::default(),
                column_axis: SheetAxis::default(),
                show_grid_lines: false,
                tab_color: None,
                sheet: None,
                slide: None,
            });
            if selected_unit.is_some_and(|selected| selected != index) {
                continue;
            }
            let initial = page_matrix(x0, y0, x1, y1, rotation, user_unit);
            let mut context = PageContext {
                store,
                page_indices: &page_indices,
                named_destinations: &named_destinations,
                optional_content: &optional_content,
                limits,
                unit_index,
                page_bounds: Rect {
                    x: 0.0,
                    y: 0.0,
                    width,
                    height,
                },
                objects: Vec::new(),
                diagnostics: Vec::new(),
                diagnostic_keys: BTreeSet::new(),
                active_forms: BTreeSet::new(),
                form_cycle_count: 0,
                parent_numeric_id: None,
                fonts: &mut fonts,
                inline_fonts: &mut inline_fonts,
                image_resources: &mut image_resources,
                image_masks: &mut image_masks,
                shading_stops: BTreeMap::new(),
            };
            let resources = page.resources.as_ref();
            paint_page_annotations(
                &page.annotations,
                initial,
                &mut context,
                AnnotationLayer::Underlay,
            )?;
            let mut page_content = Vec::new();
            for content in content_streams(store, &page.contents)? {
                if pdf_content_is_image_stream(content) {
                    context.warning(
                        "content-image-stream",
                        "PDF_CONTENT_IMAGE_STREAM_OMITTED: an image stream misused as page Contents was ignored before decode",
                    );
                    continue;
                }
                let decoded = match decode_stream(content, store, limits) {
                    Ok(decoded) => decoded,
                    Err(error) if is_pdf_resource_limit(&error) => return Err(error),
                    Err(error) => {
                        if let Ok(decoded) = decode_damaged_content_stream(content, store, limits)
                            && !decoded.is_empty()
                        {
                            context.warning(
                                "content-stream-recovered",
                                "PDF_CONTENT_STREAM_RECOVERED: valid content preceding stream corruption was retained",
                            );
                            context.diagnostics.push(omitted_pdf_diagnostic(
                                error,
                                context.unit_index,
                                "PDF page content stream was partially recovered",
                            ));
                            decoded
                        } else {
                            context.warning(
                            "content-stream-invalid",
                            "PDF_CONTENT_STREAM_OMITTED: a malformed page content stream was isolated and omitted",
                        );
                            context.diagnostics.push(omitted_pdf_diagnostic(
                                error,
                                context.unit_index,
                                "PDF page content stream was omitted",
                            ));
                            continue;
                        }
                    }
                };
                let separator = usize::from(!page_content.is_empty());
                let next_length = page_content
                    .len()
                    .checked_add(separator)
                    .and_then(|length| length.checked_add(decoded.len()))
                    .ok_or_else(object_limit)?;
                if next_length > limits.max_entry_uncompressed_bytes {
                    return Err(pdf_error(
                        page.offset,
                        "PDF page content exceeds the decoded stream limit",
                    ));
                }
                if separator != 0 {
                    page_content.push(b'\n');
                }
                page_content.extend_from_slice(&decoded);
            }
            if !page_content.is_empty() {
                if let Err(error) = interpret_content(
                    &page_content,
                    resources,
                    &mut context,
                    GraphicsState::new(initial),
                    page.id.0,
                    0,
                ) {
                    if is_pdf_resource_limit(&error) {
                        return Err(error);
                    }
                    context.diagnostics.push(omitted_pdf_diagnostic(
                        error,
                        context.unit_index,
                        "Malformed PDF page operators were isolated after rendering valid preceding content",
                    ));
                }
            }
            paint_page_annotations(
                &page.annotations,
                initial,
                &mut context,
                AnnotationLayer::Overlay,
            )?;
            compact_pdf_text_batches(&mut context.objects);
            let base = u32::try_from(document.objects.len()).map_err(|_| object_limit())?;
            for mut object in context.objects {
                if base != 0 {
                    object.numeric_id = object
                        .numeric_id
                        .checked_add(base)
                        .ok_or_else(object_limit)?;
                    object.parent_numeric_id = object
                        .parent_numeric_id
                        .map(|parent| parent.checked_add(base).ok_or_else(object_limit))
                        .transpose()?;
                    object.stable_id = format!("pdf:{unit_index}:{}", object.numeric_id);
                    object.parent_stable_id = object
                        .parent_numeric_id
                        .map(|parent| format!("pdf:{unit_index}:{parent}"));
                }
                document.objects.push(object);
            }
            document.diagnostics.extend(context.diagnostics);
        }
        let mut new_font_ids = BTreeSet::new();
        if include_embedded_fonts {
            let extracted = extract_pdf_fonts(
                store,
                limits,
                Some(&fonts),
                &inline_fonts,
                emitted_font_ids,
                emitted_font_bytes,
            )?;
            document.embedded_fonts = extracted.fonts;
            document.diagnostics.extend(extracted.diagnostics);
            new_font_ids = extracted.ids;
        }
        Ok((document, new_font_ids))
    }
}

#[derive(Clone)]
struct PageEntry {
    id: ObjectId,
    offset: usize,
    media_box: Option<PdfValue>,
    crop_box: Option<PdfValue>,
    rotate: i32,
    user_unit: Option<PdfValue>,
    resources: Option<PdfValue>,
    contents: Option<PdfValue>,
    annotations: Option<PdfValue>,
}

#[derive(Clone, Default)]
struct InheritedPage {
    media_box: Option<PdfValue>,
    crop_box: Option<PdfValue>,
    rotate: i32,
    user_unit: Option<PdfValue>,
    resources: Option<PdfValue>,
}

fn collect_pages(store: &mut ObjectStore) -> Result<Vec<PageEntry>, Diagnostic> {
    let catalog_pages = store.objects.iter().find_map(|(_, object)| {
        let dict = store.dict(&object.value)?;
        (dict_name(dict, "Type") == Some("Catalog"))
            .then(|| dict.get("Pages"))
            .flatten()
            .and_then(|value| match value {
                PdfValue::Ref(id) => Some(*id),
                _ => None,
            })
    });
    let linearized = store.objects.values().find_map(|object| {
        let dict = store.dict(&object.value)?;
        (dict.get("Linearized").and_then(number_f32)? > 0.0).then(|| {
            (
                dict.get("O")
                    .and_then(number_usize)
                    .and_then(|value| u32::try_from(value).ok()),
                dict.get("N").and_then(number_usize),
            )
        })
    });
    let mut pages = Vec::new();
    let mut visited = BTreeSet::new();
    let mut page_tree_errors = Vec::new();
    let declared_page_count = catalog_pages.and_then(|root| {
        store
            .get(root)
            .and_then(|object| store.dict(&object.value))
            .and_then(|dict| dict.get("Count"))
            .and_then(number_usize)
    });
    if let Some(root) = catalog_pages
        && store.get(root).is_some()
    {
        if let Err(error) = collect_page_node(
            store,
            root,
            InheritedPage::default(),
            &mut pages,
            &mut visited,
            &mut page_tree_errors,
            0,
        ) {
            if is_pdf_resource_limit(&error) {
                return Err(error);
            }
            store.diagnostics.push(omitted_pdf_diagnostic(
                error,
                0,
                "A damaged PDF page-tree branch was isolated before direct-page recovery",
            ));
            pages.clear();
        }
    }
    if !page_tree_errors.is_empty() {
        store
            .diagnostics
            .extend(page_tree_errors.into_iter().map(|error| {
                omitted_pdf_diagnostic(
                    error,
                    0,
                    "A damaged PDF page-tree branch was isolated while preserving readable pages",
                )
            }));
        if let Some(expected) = declared_page_count {
            if expected > store.limits.max_document_objects {
                return Err(object_limit());
            }
            let template = pages.first().cloned();
            while pages.len() < expected {
                pages.push(recovered_blank_page_like(pages.len(), template.as_ref()));
            }
        }
    }
    if pages.is_empty()
        && let Some((&root, _)) = store.objects.iter().find(|(_, object)| {
            store
                .dict(&object.value)
                .is_some_and(|dict| dict.contains_key("Kids") && !dict.contains_key("Parent"))
        })
    {
        if let Err(error) = collect_page_node(
            store,
            root,
            InheritedPage::default(),
            &mut pages,
            &mut visited,
            &mut Vec::new(),
            0,
        ) {
            if is_pdf_resource_limit(&error) {
                return Err(error);
            }
            store.diagnostics.push(omitted_pdf_diagnostic(
                error,
                0,
                "A typeless PDF page tree was isolated before direct-page recovery",
            ));
            pages.clear();
        } else {
            store.diagnostics.push(
                Diagnostic::warning(
                    DiagnosticCode::FormatInvalid,
                    Phase::Parse,
                    Fidelity::Approximate,
                    "PDF_PAGE_TREE_TYPE_RECOVERED: a page tree missing its Type entries was recovered from its Kids structure",
                )
                .in_part("document.pdf"),
            );
        }
    }
    if pages.is_empty() {
        for (&id, object) in &store.objects {
            let Some(dict) = store.dict(&object.value) else {
                continue;
            };
            if dict_name(dict, "Type") != Some("Page") {
                continue;
            }
            let inherited = inherit_page(store, dict, InheritedPage::default());
            pages.push(page_entry(id, object.offset, dict, inherited));
        }
        pages.sort_by_key(|page| {
            (
                linearized
                    .and_then(|(first, _)| first)
                    .is_none_or(|first| page.id.0 != first),
                page.offset,
            )
        });
        if !pages.is_empty()
            && let Some(expected) = linearized.and_then(|(_, count)| count)
        {
            if expected > store.limits.max_document_objects {
                return Err(object_limit());
            }
            while pages.len() < expected {
                pages.push(recovered_blank_page(pages.len()));
            }
        }
    }
    Ok(pages)
}

fn collect_named_destinations(store: &ObjectStore) -> BTreeMap<String, PdfValue> {
    let mut destinations = BTreeMap::new();
    let Some(catalog) = store.objects.values().find_map(|object| {
        let dict = store.dict(&object.value)?;
        (dict_name(dict, "Type") == Some("Catalog")).then_some(dict)
    }) else {
        return destinations;
    };
    if let Some(dict) = catalog.get("Dests").and_then(|value| store.dict(value)) {
        destinations.extend(
            dict.iter()
                .map(|(name, value)| (name.clone(), value.clone())),
        );
    }
    let Some(tree) = catalog
        .get("Names")
        .and_then(|value| store.dict(value))
        .and_then(|names| names.get("Dests"))
    else {
        return destinations;
    };
    collect_destination_name_tree(tree, store, &mut destinations, &mut BTreeSet::new(), 0);
    destinations
}

fn collect_optional_content_config(store: &ObjectStore) -> OptionalContentConfig {
    let mut config = OptionalContentConfig {
        base_visible: true,
        visibility: BTreeMap::new(),
    };
    let Some(catalog) = store.objects.values().find_map(|object| {
        let dict = store.dict(&object.value)?;
        (dict_name(dict, "Type") == Some("Catalog")).then_some(dict)
    }) else {
        return config;
    };
    let Some(properties) = catalog
        .get("OCProperties")
        .and_then(|value| store.dict(value))
    else {
        return config;
    };
    let Some(default) = properties.get("D").and_then(|value| store.dict(value)) else {
        return config;
    };
    config.base_visible = dict_name(default, "BaseState") != Some("OFF");
    if let Some(PdfValue::Array(groups)) = properties
        .get("OCGs")
        .and_then(|value| store.resolve(value))
    {
        for group in groups {
            if let PdfValue::Ref(id) = group {
                config.visibility.insert(*id, config.base_visible);
            }
        }
    }
    for (key, visible) in [("ON", true), ("OFF", false)] {
        let Some(PdfValue::Array(groups)) = default.get(key).and_then(|value| store.resolve(value))
        else {
            continue;
        };
        for group in groups {
            if let PdfValue::Ref(id) = group {
                config.visibility.insert(*id, visible);
            }
        }
    }
    config
}

fn collect_destination_name_tree(
    value: &PdfValue,
    store: &ObjectStore,
    destinations: &mut BTreeMap<String, PdfValue>,
    visited: &mut BTreeSet<ObjectId>,
    depth: usize,
) {
    if depth > MAX_VALUE_DEPTH || destinations.len() >= store.limits.max_document_objects {
        return;
    }
    if let PdfValue::Ref(id) = value
        && !visited.insert(*id)
    {
        return;
    }
    let Some(dict) = store.dict(value) else {
        return;
    };
    if let Some(PdfValue::Array(names)) = dict.get("Names").and_then(|value| store.resolve(value)) {
        for pair in names.chunks_exact(2) {
            let Some(name) = destination_name(&pair[0]) else {
                continue;
            };
            if destinations.len() >= store.limits.max_document_objects {
                break;
            }
            destinations.insert(name, pair[1].clone());
        }
    }
    if let Some(PdfValue::Array(kids)) = dict.get("Kids").and_then(|value| store.resolve(value)) {
        for kid in kids {
            collect_destination_name_tree(kid, store, destinations, visited, depth + 1);
        }
    }
}

fn destination_name(value: &PdfValue) -> Option<String> {
    match value {
        PdfValue::Name(name) => Some(name.clone()),
        PdfValue::String(bytes) => Some(String::from_utf8_lossy(bytes).into_owned()),
        _ => None,
    }
}

fn pdf_text_string(value: &PdfValue) -> Option<String> {
    let bytes = pdf_string(value)?;
    let text = if let Some(bytes) = bytes.strip_prefix(&[0xfe, 0xff]) {
        utf16be(bytes)?
    } else {
        String::from_utf8_lossy(bytes).into_owned()
    };
    let text = text.trim().to_owned();
    (!text.is_empty()).then_some(text)
}

fn pdf_font_name(dict: &PdfDict, key: &str) -> Option<String> {
    let value = dict.get(key)?;
    let name = match value {
        PdfValue::Name(name) => name.clone(),
        PdfValue::String(_) => pdf_text_string(value)?.replace('\0', ""),
        _ => return None,
    };
    let name = name.trim().to_owned();
    (!name.is_empty()).then_some(name)
}

fn collect_outline(
    store: &ObjectStore,
    page_indices: &BTreeMap<ObjectId, u32>,
    named_destinations: &BTreeMap<String, PdfValue>,
) -> Vec<OutlineItem> {
    let Some(first) = store
        .objects
        .values()
        .find_map(|object| {
            let dict = store.dict(&object.value)?;
            (dict_name(dict, "Type") == Some("Catalog")).then_some(dict)
        })
        .and_then(|catalog| catalog.get("Outlines"))
        .and_then(|value| store.dict(value))
        .and_then(|outline| outline.get("First"))
    else {
        return Vec::new();
    };
    let mut items = Vec::new();
    let mut visited = BTreeSet::new();
    collect_outline_siblings(
        first,
        0,
        store,
        page_indices,
        named_destinations,
        &mut visited,
        &mut items,
    );
    items
}

fn collect_outline_siblings(
    first: &PdfValue,
    level: u32,
    store: &ObjectStore,
    page_indices: &BTreeMap<ObjectId, u32>,
    named_destinations: &BTreeMap<String, PdfValue>,
    visited: &mut BTreeSet<ObjectId>,
    items: &mut Vec<OutlineItem>,
) {
    let mut current = Some(first);
    while let Some(value) = current {
        if items.len() >= store.limits.max_document_objects {
            return;
        }
        if let PdfValue::Ref(id) = value
            && !visited.insert(*id)
        {
            return;
        }
        let Some(dict) = store.dict(value) else {
            return;
        };
        if let Some(title) = dict.get("Title").and_then(pdf_text_string) {
            let destination = dict
                .get("Dest")
                .or_else(|| {
                    dict.get("A")
                        .and_then(|action| store.dict(action))
                        .filter(|action| dict_name(action, "S") == Some("GoTo"))
                        .and_then(|action| action.get("D"))
                })
                .and_then(|destination| {
                    pdf_destination_unit_from_maps(
                        destination,
                        store,
                        page_indices,
                        named_destinations,
                        0,
                    )
                });
            if let Some(unit_index) = destination {
                items.push(OutlineItem {
                    title,
                    unit_index,
                    level,
                });
            }
        }
        if let Some(child) = dict.get("First") {
            collect_outline_siblings(
                child,
                level.saturating_add(1),
                store,
                page_indices,
                named_destinations,
                visited,
                items,
            );
        }
        current = dict.get("Next");
    }
}

fn recovered_blank_page(index: usize) -> PageEntry {
    recovered_blank_page_like(index, None)
}

fn recovered_blank_page_like(index: usize, template: Option<&PageEntry>) -> PageEntry {
    let index = u32::try_from(index).unwrap_or(u32::MAX);
    PageEntry {
        id: (u32::MAX.saturating_sub(index), 0),
        offset: 0,
        media_box: template
            .map(|page| page.media_box.clone())
            .unwrap_or_else(|| {
                Some(PdfValue::Array(vec![
                    PdfValue::Number(0.0),
                    PdfValue::Number(0.0),
                    PdfValue::Number(612.0),
                    PdfValue::Number(792.0),
                ]))
            }),
        crop_box: template.and_then(|page| page.crop_box.clone()),
        rotate: template.map_or(0, |page| page.rotate),
        user_unit: template.and_then(|page| page.user_unit.clone()),
        resources: template.and_then(|page| page.resources.clone()),
        contents: None,
        annotations: None,
    }
}

fn collect_page_node(
    store: &ObjectStore,
    id: ObjectId,
    inherited: InheritedPage,
    pages: &mut Vec<PageEntry>,
    visited: &mut BTreeSet<ObjectId>,
    branch_errors: &mut Vec<Diagnostic>,
    depth: usize,
) -> Result<(), Diagnostic> {
    if depth > MAX_VALUE_DEPTH || !visited.insert(id) {
        return Err(pdf_error(0, "PDF page tree is cyclic or too deep"));
    }
    let object = store
        .get(id)
        .ok_or_else(|| pdf_error(0, "PDF page tree references a missing object"))?;
    let dict = store
        .dict(&object.value)
        .ok_or_else(|| pdf_error(object.offset, "PDF page node is not a dictionary"))?;
    let inherited = inherit_page(store, dict, inherited);
    if dict_name(dict, "Type") == Some("Page") || !dict.contains_key("Kids") {
        pages.push(page_entry(id, object.offset, dict, inherited));
    } else {
        let kids = store
            .resolve(
                dict.get("Kids")
                    .ok_or_else(|| pdf_error(object.offset, "PDF Pages node has no Kids"))?,
            )
            .and_then(|value| match value {
                PdfValue::Array(values) => Some(values),
                _ => None,
            })
            .ok_or_else(|| pdf_error(object.offset, "PDF Pages Kids entry is not an array"))?;
        for kid in kids {
            match kid {
                PdfValue::Ref(kid) => {
                    if let Err(error) = collect_page_node(
                        store,
                        *kid,
                        inherited.clone(),
                        pages,
                        visited,
                        branch_errors,
                        depth + 1,
                    ) {
                        if is_pdf_resource_limit(&error) {
                            return Err(error);
                        }
                        branch_errors.push(error);
                    }
                }
                PdfValue::Dict(page) => {
                    let direct_inherited = inherit_page(store, page, inherited.clone());
                    let synthetic = (u32::MAX.saturating_sub(pages.len() as u32), 0);
                    pages.push(page_entry(synthetic, object.offset, page, direct_inherited));
                }
                _ => {
                    return Err(pdf_error(
                        object.offset,
                        "PDF page tree Kid is neither a reference nor a page dictionary",
                    ));
                }
            }
        }
    }
    visited.remove(&id);
    Ok(())
}

fn merge_page_resources(
    store: &ObjectStore,
    inherited: Option<PdfValue>,
    child: &PdfValue,
) -> PdfValue {
    let Some(parent) = inherited.as_ref().and_then(|value| store.dict(value)) else {
        return child.clone();
    };
    let Some(child_dict) = store.dict(child) else {
        return child.clone();
    };
    let mut merged = parent.clone();
    for (category, child_value) in child_dict {
        let combined = merged
            .get(category)
            .and_then(|parent_value| store.dict(parent_value))
            .zip(store.dict(child_value))
            .map(|(parent_entries, child_entries)| {
                let mut entries = parent_entries.clone();
                entries.extend(child_entries.clone());
                PdfValue::Dict(entries)
            })
            .unwrap_or_else(|| child_value.clone());
        merged.insert(category.clone(), combined);
    }
    PdfValue::Dict(merged)
}

fn inherit_page(
    store: &ObjectStore,
    dict: &PdfDict,
    mut inherited: InheritedPage,
) -> InheritedPage {
    if let Some(value) = dict.get("MediaBox") {
        inherited.media_box = Some(value.clone());
    }
    if let Some(value) = dict.get("CropBox") {
        inherited.crop_box = Some(value.clone());
    }
    if let Some(value) = dict.get("Resources") {
        inherited.resources = Some(merge_page_resources(store, inherited.resources, value));
    }
    if let Some(value) = dict.get("Rotate").and_then(number_i32) {
        inherited.rotate = value;
    }
    if let Some(value) = dict.get("UserUnit") {
        inherited.user_unit = Some(value.clone());
    }
    inherited
}

fn page_entry(id: ObjectId, offset: usize, dict: &PdfDict, inherited: InheritedPage) -> PageEntry {
    PageEntry {
        id,
        offset,
        media_box: dict.get("MediaBox").cloned().or(inherited.media_box),
        crop_box: dict.get("CropBox").cloned().or(inherited.crop_box),
        rotate: dict
            .get("Rotate")
            .and_then(number_i32)
            .unwrap_or(inherited.rotate),
        user_unit: dict.get("UserUnit").cloned().or(inherited.user_unit),
        resources: inherited.resources,
        contents: dict.get("Contents").cloned(),
        annotations: dict.get("Annots").cloned(),
    }
}

fn page_matrix(x0: f32, y0: f32, x1: f32, y1: f32, rotation: i32, user_unit: f32) -> Matrix {
    let s = PDF_POINT_TO_CSS * user_unit;
    match rotation {
        90 => Matrix {
            a: 0.0,
            b: s,
            c: s,
            d: 0.0,
            e: -y0 * s,
            f: -x0 * s,
        },
        180 => Matrix {
            a: -s,
            b: 0.0,
            c: 0.0,
            d: s,
            e: x1 * s,
            f: -y0 * s,
        },
        270 => Matrix {
            a: 0.0,
            b: -s,
            c: -s,
            d: 0.0,
            e: y1 * s,
            f: x1 * s,
        },
        _ => Matrix {
            a: s,
            b: 0.0,
            c: 0.0,
            d: -s,
            e: -x0 * s,
            f: y1 * s,
        },
    }
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum AnnotationLayer {
    Underlay,
    Overlay,
}

fn paint_page_annotations(
    annotations: &Option<PdfValue>,
    page_matrix: Matrix,
    context: &mut PageContext<'_>,
    layer: AnnotationLayer,
) -> Result<(), Diagnostic> {
    let Some(PdfValue::Array(values)) = annotations
        .as_ref()
        .and_then(|value| context.store.resolve(value))
    else {
        return Ok(());
    };
    for value in values {
        let object_number = match value {
            PdfValue::Ref((number, _)) => Some(*number),
            _ => None,
        };
        let Some(dict) = context.store.dict(value) else {
            continue;
        };
        let flags = dict.get("F").and_then(number_usize).unwrap_or(0);
        if flags & (1 | 2 | 32) != 0 {
            continue;
        }
        let source = || pdf_source("annotation", object_number, None, MappingQuality::Derived);
        let text = dict
            .get("Contents")
            .and_then(pdf_string)
            .map(|bytes| String::from_utf8_lossy(bytes).into_owned());
        match (dict_name(dict, "Subtype"), layer) {
            (Some("Widget"), AnnotationLayer::Overlay)
            | (Some("FreeText"), AnnotationLayer::Overlay) => {
                let first_object = context.objects.len();
                paint_annotation_normal_appearance(dict, page_matrix, context)?;
                if dict_name(dict, "Subtype") == Some("Widget") {
                    refresh_widget_text_appearance(dict, first_object, context);
                }
            }
            (Some("Link"), AnnotationLayer::Overlay) => {
                let Some(action) = pdf_link_action(dict, context) else {
                    continue;
                };
                let Some(rect) = annotation_number_array(dict.get("Rect"), context.store)
                    .and_then(|values| <[f32; 4]>::try_from(values).ok())
                else {
                    continue;
                };
                let points = [
                    page_matrix.point(rect[0], rect[1]),
                    page_matrix.point(rect[2], rect[1]),
                    page_matrix.point(rect[2], rect[3]),
                    page_matrix.point(rect[0], rect[3]),
                ];
                let Some(bounds) = bounds(&points) else {
                    continue;
                };
                context.push_object(
                    ObjectKind::Shape,
                    bounds,
                    text,
                    Visual::None,
                    pdf_link_source(object_number, action),
                )?;
            }
            (Some("Highlight"), AnnotationLayer::Underlay) => {
                let Some(points) = annotation_number_array(dict.get("QuadPoints"), context.store)
                else {
                    continue;
                };
                let color = annotation_color(dict, context.store, 0xffff_00ff);
                for quad in points.chunks_exact(8) {
                    let points = [
                        page_matrix.point(quad[0], quad[1]),
                        page_matrix.point(quad[2], quad[3]),
                        page_matrix.point(quad[6], quad[7]),
                        page_matrix.point(quad[4], quad[5]),
                    ];
                    push_annotation_path(
                        context,
                        &points,
                        true,
                        color,
                        0,
                        0.0,
                        text.clone(),
                        source(),
                    )?;
                }
            }
            (Some("Highlight"), AnnotationLayer::Overlay) if text.is_some() => {
                let Some(points) = annotation_number_array(dict.get("QuadPoints"), context.store)
                else {
                    continue;
                };
                let Some(quad) = points.get(..8) else {
                    continue;
                };
                let quad_points = [
                    page_matrix.point(quad[0], quad[1]),
                    page_matrix.point(quad[2], quad[3]),
                    page_matrix.point(quad[6], quad[7]),
                    page_matrix.point(quad[4], quad[5]),
                ];
                let Some(quad_bounds) = bounds(&quad_points) else {
                    continue;
                };
                let point_scale = page_matrix.scale();
                let indicator = Rect {
                    x: quad_bounds.x + quad_bounds.width + 5.0 * point_scale,
                    y: quad_bounds.y - 20.0 * point_scale,
                    width: 14.0 * point_scale,
                    height: 10.0 * point_scale,
                };
                context.push_object(
                    ObjectKind::Shape,
                    indicator,
                    text.clone(),
                    Visual::Shape {
                        geometry: Geometry::RoundedRectangle {
                            radius_x: 3.0 * point_scale,
                            radius_y: 3.0 * point_scale,
                        },
                        fill: 0xffff_00ff,
                        stroke: 0,
                        stroke_width: 0.0,
                    },
                    source(),
                )?;
                let line_points = [
                    (
                        indicator.x + indicator.width * 0.28,
                        indicator.y + indicator.height * 0.4,
                    ),
                    (
                        indicator.x + indicator.width * 0.72,
                        indicator.y + indicator.height * 0.4,
                    ),
                    (
                        indicator.x + indicator.width * 0.28,
                        indicator.y + indicator.height * 0.65,
                    ),
                    (
                        indicator.x + indicator.width * 0.58,
                        indicator.y + indicator.height * 0.65,
                    ),
                ];
                let commands = vec![
                    PathCommand::MoveTo {
                        x: line_points[0].0 - indicator.x,
                        y: line_points[0].1 - indicator.y,
                    },
                    PathCommand::LineTo {
                        x: line_points[1].0 - indicator.x,
                        y: line_points[1].1 - indicator.y,
                    },
                    PathCommand::MoveTo {
                        x: line_points[2].0 - indicator.x,
                        y: line_points[2].1 - indicator.y,
                    },
                    PathCommand::LineTo {
                        x: line_points[3].0 - indicator.x,
                        y: line_points[3].1 - indicator.y,
                    },
                ];
                context.push_object(
                    ObjectKind::Shape,
                    indicator,
                    None,
                    Visual::Shape {
                        geometry: Geometry::Path {
                            fill_rule: FillRule::NonZero,
                            commands,
                        },
                        fill: 0,
                        stroke: 0x0000_00ff,
                        stroke_width: 1.5,
                    },
                    source(),
                )?;
            }
            (Some("Ink"), AnnotationLayer::Overlay) if dict.contains_key("AP") => {
                paint_annotation_normal_appearance(dict, page_matrix, context)?;
            }
            (Some("Ink"), AnnotationLayer::Overlay) => {
                let Some(PdfValue::Array(paths)) = dict
                    .get("InkList")
                    .and_then(|value| context.store.resolve(value))
                else {
                    continue;
                };
                let mut points = Vec::new();
                let mut commands = Vec::new();
                for path in paths {
                    let Some(values) = annotation_number_array(Some(path), context.store) else {
                        continue;
                    };
                    for (index, pair) in values.chunks_exact(2).enumerate() {
                        let point = page_matrix.point(pair[0], pair[1]);
                        points.push(point);
                        commands.push(if index == 0 {
                            PathCommand::MoveTo {
                                x: point.0,
                                y: point.1,
                            }
                        } else {
                            PathCommand::LineTo {
                                x: point.0,
                                y: point.1,
                            }
                        });
                    }
                }
                if let Some(bounds) = bounds(&points) {
                    let width = annotation_border_width(dict, context.store) * page_matrix.scale();
                    context.push_object(
                        ObjectKind::Shape,
                        bounds,
                        text.clone(),
                        Visual::Shape {
                            geometry: Geometry::Path {
                                fill_rule: FillRule::NonZero,
                                commands: translate_path_commands(&commands, -bounds.x, -bounds.y),
                            },
                            fill: 0,
                            stroke: annotation_color(dict, context.store, 0xffff_00ff),
                            stroke_width: width.max(0.5),
                        },
                        source(),
                    )?;
                }
            }
            (Some("Text"), AnnotationLayer::Overlay) if dict.contains_key("AP") => {
                paint_annotation_normal_appearance(dict, page_matrix, context)?;
            }
            (Some("Text"), AnnotationLayer::Overlay) => {
                let Some([x0, y0, x1, y1]) = dict
                    .get("Rect")
                    .and_then(|value| pdf_box(context.store, value))
                else {
                    continue;
                };
                if (x1 - x0).abs() <= f32::EPSILON || (y1 - y0).abs() <= f32::EPSILON {
                    continue;
                }
                let anchor = page_matrix.point(x0.min(x1), y0.max(y1));
                let size = 20.0 * PDF_POINT_TO_CSS;
                let bounds = Rect {
                    x: anchor.0,
                    y: anchor.1,
                    width: size,
                    height: size,
                };
                let fold = size * 0.28;
                context.push_object(
                    ObjectKind::Shape,
                    bounds,
                    text.clone(),
                    Visual::Shape {
                        geometry: Geometry::Path {
                            fill_rule: FillRule::NonZero,
                            commands: vec![
                                PathCommand::MoveTo { x: 0.0, y: 0.0 },
                                PathCommand::LineTo { x: size, y: 0.0 },
                                PathCommand::LineTo {
                                    x: size,
                                    y: size - fold,
                                },
                                PathCommand::LineTo {
                                    x: size - fold,
                                    y: size,
                                },
                                PathCommand::LineTo { x: 0.0, y: size },
                                PathCommand::ClosePath,
                            ],
                        },
                        fill: annotation_color(dict, context.store, 0xffeb_60ff),
                        stroke: 0x0000_00ff,
                        stroke_width: 1.0,
                    },
                    source(),
                )?;
            }
            (Some(subtype @ ("Polygon" | "PolyLine")), AnnotationLayer::Overlay)
                if !dict.contains_key("AP") =>
            {
                let Some(vertices) = annotation_number_array(dict.get("Vertices"), context.store)
                else {
                    continue;
                };
                let points = vertices
                    .chunks_exact(2)
                    .map(|pair| page_matrix.point(pair[0], pair[1]))
                    .collect::<Vec<_>>();
                push_annotation_path(
                    context,
                    &points,
                    subtype == "Polygon",
                    if subtype == "Polygon" {
                        annotation_named_color(dict, "IC", context.store, 0)
                    } else {
                        0
                    },
                    annotation_color(dict, context.store, 0x0000_00ff),
                    annotation_border_width(dict, context.store) * page_matrix.scale(),
                    text.clone(),
                    source(),
                )?;
            }
            (Some(subtype @ ("Square" | "Circle")), AnnotationLayer::Overlay)
                if !dict.contains_key("AP") =>
            {
                let Some([x0, y0, x1, y1]) = dict
                    .get("Rect")
                    .and_then(|value| pdf_box(context.store, value))
                else {
                    continue;
                };
                let points = [
                    page_matrix.point(x0, y0),
                    page_matrix.point(x1, y0),
                    page_matrix.point(x1, y1),
                    page_matrix.point(x0, y1),
                ];
                let Some(bounds) = bounds(&points) else {
                    continue;
                };
                context.push_object(
                    ObjectKind::Shape,
                    bounds,
                    text.clone(),
                    Visual::Shape {
                        geometry: if subtype == "Circle" {
                            Geometry::Ellipse
                        } else {
                            Geometry::Rectangle
                        },
                        fill: annotation_named_color(dict, "IC", context.store, 0),
                        stroke: annotation_color(dict, context.store, 0x0000_00ff),
                        stroke_width: annotation_border_width(dict, context.store)
                            * page_matrix.scale(),
                    },
                    source(),
                )?;
            }
            (Some(_), AnnotationLayer::Overlay) if dict.contains_key("AP") => {
                paint_annotation_normal_appearance(dict, page_matrix, context)?;
            }
            _ => {}
        }
    }
    Ok(())
}

fn pdf_acroform_needs_appearances(store: &ObjectStore) -> bool {
    store.objects.values().any(|object| {
        let Some(catalog) = store.dict(&object.value) else {
            return false;
        };
        dict_name(catalog, "Type") == Some("Catalog")
            && catalog
                .get("AcroForm")
                .and_then(|value| store.dict(value))
                .and_then(|form| form.get("NeedAppearances"))
                .and_then(|value| store.resolve(value))
                .is_some_and(|value| matches!(value, PdfValue::Bool(true)))
    })
}

fn pdf_xfa_packets(store: &ObjectStore, limits: Limits) -> BTreeMap<String, Vec<u8>> {
    let Some(xfa) = store
        .objects
        .values()
        .find_map(|object| {
            let catalog = store.dict(&object.value)?;
            (dict_name(catalog, "Type") == Some("Catalog")).then_some(catalog)
        })
        .and_then(|catalog| catalog.get("AcroForm"))
        .and_then(|value| store.dict(value))
        .and_then(|form| form.get("XFA"))
        .and_then(|value| store.resolve(value))
    else {
        return BTreeMap::new();
    };
    match xfa {
        PdfValue::Array(values) => values
            .chunks_exact(2)
            .filter_map(|pair| {
                let name = destination_name(&pair[0])?;
                let bytes = decode_stream(store.resolve(&pair[1])?, store, limits).ok()?;
                Some((name, bytes))
            })
            .collect(),
        stream @ PdfValue::Stream { .. } => decode_stream(stream, store, limits)
            .ok()
            .map(|bytes| BTreeMap::from([("xdp".to_owned(), bytes)]))
            .unwrap_or_default(),
        _ => BTreeMap::new(),
    }
}

fn pdf_catalog_needs_rendering(store: &ObjectStore) -> bool {
    store.objects.values().any(|object| {
        let Some(catalog) = store.dict(&object.value) else {
            return false;
        };
        dict_name(catalog, "Type") == Some("Catalog")
            && catalog
                .get("NeedsRendering")
                .and_then(|value| store.resolve(value))
                .is_some_and(|value| matches!(value, PdfValue::Bool(true)))
    })
}

fn pdf_acroform_resources(store: &ObjectStore) -> Option<PdfValue> {
    store.objects.values().find_map(|object| {
        let catalog = store.dict(&object.value)?;
        (dict_name(catalog, "Type") == Some("Catalog"))
            .then(|| catalog.get("AcroForm").and_then(|value| store.dict(value)))
            .flatten()
            .and_then(|form| form.get("DR"))
            .cloned()
    })
}

fn pdf_default_appearance_font(bytes: &[u8], limits: Limits) -> Option<(String, f32)> {
    let mut parser = ContentParser::new(bytes, limits);
    let mut operands = Vec::new();
    let mut result = None;
    while let Ok(Some(token)) = parser.next() {
        match token {
            ContentToken::Value(value) => operands.push(value),
            ContentToken::Operator(operator, _) => {
                if operator == "Tf"
                    && operands.len() >= 2
                    && let PdfValue::Name(name) = &operands[operands.len() - 2]
                    && let Some(size) = operands.last().and_then(number_f32)
                {
                    result = Some((name.clone(), size.abs()));
                }
                operands.clear();
            }
        }
    }
    result
}

fn replace_pdf_visual_text(visual: &mut Visual, text: &str) -> bool {
    match visual {
        Visual::RichText { runs, .. } => {
            if runs.is_empty() {
                return false;
            }
            let characters = text.chars().collect::<Vec<_>>();
            let mut start = 0_usize;
            let last = runs.len() - 1;
            for (index, run) in runs.iter_mut().enumerate() {
                let end = if index == last {
                    characters.len()
                } else {
                    start
                        .saturating_add(run.text.chars().count())
                        .min(characters.len())
                };
                run.text = characters[start..end].iter().collect();
                start = end;
            }
            true
        }
        Visual::Effect { visual, .. }
        | Visual::Layer { visual, .. }
        | Visual::StrokeStyle { visual, .. }
        | Visual::AdvancedEffect { visual, .. }
        | Visual::TextLayout { visual, .. } => replace_pdf_visual_text(visual, text),
        _ => false,
    }
}

fn pdf_visual_font_size(visual: &Visual) -> Option<f32> {
    match visual {
        Visual::RichText { runs, .. } => runs.first().map(|run| run.font_size),
        Visual::Effect { visual, .. }
        | Visual::Layer { visual, .. }
        | Visual::StrokeStyle { visual, .. }
        | Visual::AdvancedEffect { visual, .. }
        | Visual::TextLayout { visual, .. } => pdf_visual_font_size(visual),
        _ => None,
    }
}

fn refresh_widget_text_appearance(
    annotation: &PdfDict,
    first_object: usize,
    context: &mut PageContext<'_>,
) {
    if !pdf_acroform_needs_appearances(context.store) {
        return;
    }
    if dict_name(annotation, "FT") != Some("Tx") {
        return;
    }
    let Some(value) = annotation
        .get("V")
        .and_then(pdf_string)
        .map(|bytes| String::from_utf8_lossy(bytes).into_owned())
    else {
        return;
    };
    let characters = value.chars().collect::<Vec<_>>();
    let appearance_font = annotation
        .get("DA")
        .and_then(pdf_string)
        .and_then(|bytes| pdf_default_appearance_font(bytes, context.limits));
    let acroform_resources = pdf_acroform_resources(context.store);
    let font = appearance_font
        .as_ref()
        .and_then(|(name, _)| font_info(acroform_resources.as_ref(), name, context).ok());
    let text_objects = context.objects[first_object..]
        .iter()
        .enumerate()
        .filter_map(|(index, object)| (object.kind == ObjectKind::TextBox).then_some(index))
        .collect::<Vec<_>>();
    let Some((&last, preceding)) = text_objects.split_last() else {
        return;
    };
    let mut start = 0_usize;
    for &index in preceding.iter().chain(std::iter::once(&last)) {
        let object = &mut context.objects[first_object + index];
        let end = if index == last {
            characters.len()
        } else {
            start
                .saturating_add(
                    object
                        .text
                        .as_deref()
                        .map(str::chars)
                        .map(Iterator::count)
                        .unwrap_or(0),
                )
                .min(characters.len())
        };
        let replacement = characters[start..end].iter().collect::<String>();
        if replace_pdf_visual_text(&mut object.visual, &replacement) {
            object.text = Some(replacement);
        }
        start = end;
    }
    let Some(font) = font.filter(|font| !font.vertical) else {
        return;
    };
    if start != characters.len() || text_objects.is_empty() {
        return;
    }
    let first = &context.objects[first_object + text_objects[0]];
    let Some(rendered_font_size) = pdf_visual_font_size(&first.visual) else {
        return;
    };
    let baseline_y = first.bounds.y;
    if text_objects
        .iter()
        .any(|index| (context.objects[first_object + *index].bounds.y - baseline_y).abs() > 0.01)
    {
        return;
    }
    let mut cursor = first.bounds.x;
    for index in text_objects {
        let object = &mut context.objects[first_object + index];
        let advance = object
            .text
            .as_deref()
            .unwrap_or_default()
            .chars()
            .map(|character| {
                font.widths
                    .get(&(character as u32))
                    .copied()
                    .unwrap_or(font.default_width)
            })
            .sum::<f32>()
            / 1_000.0
            * rendered_font_size;
        object.bounds.x = cursor;
        object.bounds.width = advance.max(0.0);
        cursor += advance;
    }
}

fn paint_annotation_normal_appearance(
    annotation: &PdfDict,
    page_matrix: Matrix,
    context: &mut PageContext<'_>,
) -> Result<(), Diagnostic> {
    let Some([rect_x0, rect_y0, rect_x1, rect_y1]) = annotation
        .get("Rect")
        .and_then(|value| pdf_box(context.store, value))
    else {
        return Ok(());
    };
    let Some(appearances) = annotation
        .get("AP")
        .and_then(|value| context.store.dict(value))
    else {
        return Ok(());
    };
    let Some(normal) = appearances.get("N") else {
        return Ok(());
    };
    let normal_id = match normal {
        PdfValue::Ref(id) => *id,
        _ => (0, 0),
    };
    let Some(normal) = context.store.resolve(normal) else {
        return Ok(());
    };
    let (appearance_id, appearance) = match normal {
        PdfValue::Stream { .. } => (normal_id, normal),
        PdfValue::Dict(states) => {
            let Some(state) = dict_name(annotation, "AS").and_then(|name| states.get(name)) else {
                return Ok(());
            };
            let id = match state {
                PdfValue::Ref(id) => *id,
                _ => (0, 0),
            };
            let Some(value) = context.store.resolve(state) else {
                return Ok(());
            };
            (id, value)
        }
        _ => return Ok(()),
    };
    let PdfValue::Stream { dict, .. } = appearance else {
        return Ok(());
    };
    if dict_name(dict, "Subtype") != Some("Form") {
        return Ok(());
    }
    let Some([bbox_x0, bbox_y0, bbox_x1, bbox_y1]) = dict
        .get("BBox")
        .and_then(|value| pdf_box(context.store, value))
    else {
        return Ok(());
    };
    let form_matrix = dict
        .get("Matrix")
        .and_then(|value| six_numbers_value(context.store, value))
        .map(matrix)
        .unwrap_or(Matrix::IDENTITY);
    let transformed_bbox = [
        form_matrix.point(bbox_x0, bbox_y0),
        form_matrix.point(bbox_x1, bbox_y0),
        form_matrix.point(bbox_x1, bbox_y1),
        form_matrix.point(bbox_x0, bbox_y1),
    ];
    let (mut bbox_min_x, mut bbox_min_y) = transformed_bbox[0];
    let (mut bbox_max_x, mut bbox_max_y) = transformed_bbox[0];
    for &(x, y) in &transformed_bbox[1..] {
        bbox_min_x = bbox_min_x.min(x);
        bbox_min_y = bbox_min_y.min(y);
        bbox_max_x = bbox_max_x.max(x);
        bbox_max_y = bbox_max_y.max(y);
    }
    let bbox_width = bbox_max_x - bbox_min_x;
    let bbox_height = bbox_max_y - bbox_min_y;
    let rect_min_x = rect_x0.min(rect_x1);
    let rect_min_y = rect_y0.min(rect_y1);
    let rect_width = (rect_x1 - rect_x0).abs();
    let rect_height = (rect_y1 - rect_y0).abs();
    if !bbox_width.is_finite()
        || !bbox_height.is_finite()
        || !rect_width.is_finite()
        || !rect_height.is_finite()
        || bbox_width <= 0.0
        || bbox_height <= 0.0
        || rect_width <= 0.0
        || rect_height <= 0.0
    {
        return Ok(());
    }
    let scale_x = rect_width / bbox_width;
    let scale_y = rect_height / bbox_height;
    let fit = Matrix {
        a: scale_x,
        b: 0.0,
        c: 0.0,
        d: scale_y,
        e: rect_min_x - bbox_min_x * scale_x,
        f: rect_min_y - bbox_min_y * scale_y,
    };
    let mut state = GraphicsState::new(page_matrix.concat(fit).concat(form_matrix));
    let rect_points = [
        page_matrix.point(rect_min_x, rect_min_y),
        page_matrix.point(rect_min_x + rect_width, rect_min_y),
        page_matrix.point(rect_min_x + rect_width, rect_min_y + rect_height),
        page_matrix.point(rect_min_x, rect_min_y + rect_height),
    ];
    if let Some(clip_bounds) = bounds(&rect_points) {
        state.clips.push(PdfClip {
            bounds: clip_bounds,
            fill_rule: FillRule::NonZero,
            commands: rect_points
                .iter()
                .enumerate()
                .map(|(index, &(x, y))| {
                    if index == 0 {
                        PathCommand::MoveTo {
                            x: x - clip_bounds.x,
                            y: y - clip_bounds.y,
                        }
                    } else {
                        PathCommand::LineTo {
                            x: x - clip_bounds.x,
                            y: y - clip_bounds.y,
                        }
                    }
                })
                .chain(std::iter::once(PathCommand::ClosePath))
                .collect(),
        });
    }
    let tracked = appearance_id != (0, 0);
    if tracked && !context.active_forms.insert(appearance_id) {
        return Err(pdf_error(0, "cyclic PDF annotation appearance reference"));
    }
    let resources = dict.get("Resources");
    let result = decode_stream(appearance, context.store, context.limits).and_then(|decoded| {
        interpret_content(&decoded, resources, context, state, appearance_id.0, 0)
    });
    if tracked {
        context.active_forms.remove(&appearance_id);
    }
    match result {
        Ok(()) => Ok(()),
        Err(error)
            if error.phase == Phase::Security
                || matches!(
                    error.code,
                    DiagnosticCode::InputTooLarge
                        | DiagnosticCode::AllocationFailed
                        | DiagnosticCode::ObjectLimit
                        | DiagnosticCode::ImageDimensionLimit
                        | DiagnosticCode::LayoutBudgetExceeded
                        | DiagnosticCode::FontBytesLimit
                ) =>
        {
            Err(error)
        }
        Err(error) => {
            let mut diagnostic = Diagnostic::warning(
                error.code,
                error.phase,
                Fidelity::Omitted,
                format!(
                    "PDF annotation appearance was partially omitted: {}",
                    error.message
                ),
            );
            diagnostic.location = error.location;
            diagnostic.details = error.details;
            diagnostic
                .details
                .push(("unitIndex".to_owned(), context.unit_index.to_string()));
            context.diagnostics.push(diagnostic);
            Ok(())
        }
    }
}

fn pdf_link_action(dict: &PdfDict, context: &PageContext<'_>) -> Option<PptxAction> {
    let tooltip = dict
        .get("Contents")
        .and_then(pdf_string)
        .map(|bytes| String::from_utf8_lossy(bytes).into_owned());
    if let Some(action) = dict.get("A").and_then(|value| context.store.dict(value)) {
        match dict_name(action, "S") {
            Some("URI") => {
                let target = action
                    .get("URI")
                    .and_then(pdf_string)
                    .map(|bytes| String::from_utf8_lossy(bytes).into_owned())?;
                return Some(PptxAction {
                    kind: "hyperlink".to_owned(),
                    action: None,
                    target: Some(target),
                    tooltip,
                });
            }
            Some("GoTo") => {
                return pdf_destination_unit(action.get("D")?, context, 0).map(|unit_index| {
                    PptxAction {
                        kind: "command".to_owned(),
                        action: Some("navigate".to_owned()),
                        target: Some(unit_index.to_string()),
                        tooltip,
                    }
                });
            }
            _ => return None,
        }
    }
    pdf_destination_unit(dict.get("Dest")?, context, 0).map(|unit_index| PptxAction {
        kind: "command".to_owned(),
        action: Some("navigate".to_owned()),
        target: Some(unit_index.to_string()),
        tooltip,
    })
}

fn pdf_destination_unit(value: &PdfValue, context: &PageContext<'_>, depth: usize) -> Option<u32> {
    pdf_destination_unit_from_maps(
        value,
        context.store,
        context.page_indices,
        context.named_destinations,
        depth,
    )
}

fn pdf_destination_unit_from_maps(
    value: &PdfValue,
    store: &ObjectStore,
    page_indices: &BTreeMap<ObjectId, u32>,
    named_destinations: &BTreeMap<String, PdfValue>,
    depth: usize,
) -> Option<u32> {
    if depth > MAX_VALUE_DEPTH {
        return None;
    }
    match store.resolve(value)? {
        PdfValue::Array(values) => match values.first()? {
            PdfValue::Ref(id) => page_indices.get(id).copied(),
            _ => None,
        },
        PdfValue::Dict(dict) => pdf_destination_unit_from_maps(
            dict.get("D")?,
            store,
            page_indices,
            named_destinations,
            depth.saturating_add(1),
        ),
        named @ (PdfValue::Name(_) | PdfValue::String(_)) => {
            let name = destination_name(named)?;
            let destination = named_destinations.get(&name)?;
            pdf_destination_unit_from_maps(
                destination,
                store,
                page_indices,
                named_destinations,
                depth.saturating_add(1),
            )
        }
        _ => None,
    }
}

#[allow(clippy::too_many_arguments)]
fn push_annotation_path(
    context: &mut PageContext<'_>,
    points: &[(f32, f32)],
    closed: bool,
    fill: u32,
    stroke: u32,
    stroke_width: f32,
    text: Option<String>,
    source: SourceRef,
) -> Result<(), Diagnostic> {
    let Some(bounds) = bounds(points) else {
        return Ok(());
    };
    let mut commands = Vec::with_capacity(points.len() + usize::from(closed));
    for (index, point) in points.iter().enumerate() {
        commands.push(if index == 0 {
            PathCommand::MoveTo {
                x: point.0 - bounds.x,
                y: point.1 - bounds.y,
            }
        } else {
            PathCommand::LineTo {
                x: point.0 - bounds.x,
                y: point.1 - bounds.y,
            }
        });
    }
    if closed {
        commands.push(PathCommand::ClosePath);
    }
    context.push_object(
        ObjectKind::Shape,
        bounds,
        text,
        Visual::Shape {
            geometry: Geometry::Path {
                fill_rule: FillRule::NonZero,
                commands,
            },
            fill,
            stroke,
            stroke_width,
        },
        source,
    )
}

fn annotation_number_array(value: Option<&PdfValue>, store: &ObjectStore) -> Option<Vec<f32>> {
    let PdfValue::Array(values) = store.resolve(value?)? else {
        return None;
    };
    values.iter().map(number_f32).collect()
}

fn annotation_color(dict: &PdfDict, store: &ObjectStore, fallback: u32) -> u32 {
    annotation_named_color(dict, "C", store, fallback)
}

fn annotation_named_color(dict: &PdfDict, key: &str, store: &ObjectStore, fallback: u32) -> u32 {
    let Some(values) = annotation_number_array(dict.get(key), store) else {
        return fallback;
    };
    let color = match values.as_slice() {
        [gray_value] => gray(*gray_value),
        [red, green, blue] => rgb([*red, *green, *blue]),
        [cyan, magenta, yellow, black] => cmyk([*cyan, *magenta, *yellow, *black]),
        _ => return fallback,
    };
    with_alpha(color, dict.get("CA").and_then(number_f32).unwrap_or(1.0))
}

fn annotation_border_width(dict: &PdfDict, store: &ObjectStore) -> f32 {
    annotation_number_array(dict.get("Border"), store)
        .and_then(|values| values.get(2).copied())
        .unwrap_or(1.0)
        .abs()
}

fn content_streams<'a>(
    store: &'a ObjectStore,
    contents: &'a Option<PdfValue>,
) -> Result<Vec<&'a PdfValue>, Diagnostic> {
    let Some(contents) = contents else {
        return Ok(Vec::new());
    };
    let Some(resolved) = store.resolve(contents) else {
        return Err(pdf_error(0, "PDF page Contents reference is invalid"));
    };
    match resolved {
        PdfValue::Stream { .. } => Ok(vec![resolved]),
        PdfValue::Array(values) => values
            .iter()
            .map(|value| {
                let resolved = store
                    .resolve(value)
                    .ok_or_else(|| pdf_error(0, "PDF content stream reference is invalid"))?;
                matches!(resolved, PdfValue::Stream { .. })
                    .then_some(resolved)
                    .ok_or_else(|| pdf_error(0, "PDF Contents array contains a non-stream object"))
            })
            .collect(),
        _ => Err(pdf_error(
            0,
            "PDF page Contents is not a stream or stream array",
        )),
    }
}

fn pdf_content_is_image_stream(value: &PdfValue) -> bool {
    let PdfValue::Stream { dict, .. } = value else {
        return false;
    };
    matches!(
        filter_names(dict).last().map(String::as_str),
        Some("CCITTFaxDecode" | "CCF" | "DCTDecode" | "DCT" | "JBIG2Decode" | "JPXDecode")
    )
}

fn pdf_line_dash(value: &PdfValue) -> Option<Vec<f32>> {
    let PdfValue::Array(values) = value else {
        return None;
    };
    if values.len() > 256 {
        return None;
    }
    let dash = values.iter().map(number_f32).collect::<Option<Vec<_>>>()?;
    (dash.iter().all(|value| value.is_finite() && *value >= 0.0)
        && (dash.is_empty() || dash.iter().any(|value| *value > 0.0)))
    .then_some(dash)
}

fn marked_content_property<'a>(
    value: &'a PdfValue,
    resources: Option<&'a PdfValue>,
    store: &'a ObjectStore,
) -> Option<(Option<ObjectId>, &'a PdfValue)> {
    if let PdfValue::Name(name) = value {
        let (id, value) = resource_entry(resources, "Properties", name, store)?;
        return Some(((id != (0, 0)).then_some(id), value));
    }
    let id = match value {
        PdfValue::Ref(id) => Some(*id),
        _ => None,
    };
    Some((id, store.resolve(value)?))
}

fn optional_content_visible(
    value: &PdfValue,
    resources: Option<&PdfValue>,
    store: &ObjectStore,
    config: &OptionalContentConfig,
) -> bool {
    let Some((id, value)) = marked_content_property(value, resources, store) else {
        return true;
    };
    optional_content_value_visible(id, value, store, config, 0)
}

fn optional_content_value_visible(
    id: Option<ObjectId>,
    value: &PdfValue,
    store: &ObjectStore,
    config: &OptionalContentConfig,
    depth: usize,
) -> bool {
    if depth > MAX_VALUE_DEPTH {
        return true;
    }
    let Some(dict) = store.dict(value) else {
        return true;
    };
    match dict_name(dict, "Type") {
        Some("OCG") => id
            .and_then(|id| config.visibility.get(&id).copied())
            .unwrap_or(config.base_visible),
        Some("OCMD") => {
            if let Some(PdfValue::Array(expression)) =
                dict.get("VE").and_then(|value| store.resolve(value))
            {
                return optional_content_expression_visible(expression, store, config, depth + 1);
            }
            let Some(raw_groups) = dict.get("OCGs") else {
                return true;
            };
            let groups = match raw_groups {
                PdfValue::Array(groups) => groups.as_slice(),
                PdfValue::Ref(_) => match store.resolve(raw_groups) {
                    Some(PdfValue::Array(groups)) => groups.as_slice(),
                    Some(_) => std::slice::from_ref(raw_groups),
                    None => return true,
                },
                group => std::slice::from_ref(group),
            };
            let visibility = groups
                .iter()
                .map(|group| optional_content_group_visible(group, store, config, depth + 1));
            match dict_name(dict, "P").unwrap_or("AnyOn") {
                "AllOn" => visibility.fold(true, |result, visible| result && visible),
                "AnyOff" => visibility.fold(false, |result, visible| result || !visible),
                "AllOff" => visibility.fold(true, |result, visible| result && !visible),
                _ => visibility.fold(false, |result, visible| result || visible),
            }
        }
        _ => true,
    }
}

fn optional_content_group_visible(
    value: &PdfValue,
    store: &ObjectStore,
    config: &OptionalContentConfig,
    depth: usize,
) -> bool {
    let id = match value {
        PdfValue::Ref(id) => Some(*id),
        _ => None,
    };
    let Some(value) = store.resolve(value) else {
        return true;
    };
    optional_content_value_visible(id, value, store, config, depth)
}

fn optional_content_expression_visible(
    expression: &[PdfValue],
    store: &ObjectStore,
    config: &OptionalContentConfig,
    depth: usize,
) -> bool {
    if depth > MAX_VALUE_DEPTH || expression.is_empty() {
        return true;
    }
    let Some(PdfValue::Name(operator)) = expression.first() else {
        return true;
    };
    let mut values = expression[1..].iter().map(|value| {
        if let Some(PdfValue::Array(nested)) = store.resolve(value) {
            optional_content_expression_visible(nested, store, config, depth + 1)
        } else {
            optional_content_group_visible(value, store, config, depth + 1)
        }
    });
    match operator.as_str() {
        "And" => values.fold(true, |result, visible| result && visible),
        "Or" => values.fold(false, |result, visible| result || visible),
        "Not" => !values.next().unwrap_or(true),
        _ => true,
    }
}

fn interpret_content(
    bytes: &[u8],
    resources: Option<&PdfValue>,
    context: &mut PageContext<'_>,
    mut state: GraphicsState,
    source_object: u32,
    depth: usize,
) -> Result<(), Diagnostic> {
    if depth > MAX_FORM_DEPTH {
        return Err(pdf_error(
            0,
            "PDF Form XObject nesting exceeds the parser limit",
        ));
    }
    let mut parser = ContentParser::new(bytes, context.limits);
    let mut operands = Vec::new();
    let mut stack = Vec::new();
    let mut marked_content = Vec::<MarkedContentState>::new();
    let mut compatibility_depth = 0_usize;
    let mut path = PdfPath::default();
    loop {
        let position = parser.parser.position;
        let token = match parser.next() {
            Ok(Some(token)) => token,
            Ok(None) => break,
            Err(error) if is_pdf_resource_limit(&error) => return Err(error),
            Err(error) if depth > 0 => return Err(error),
            Err(error) => {
                context.diagnostics.push(omitted_pdf_diagnostic(
                    error,
                    context.unit_index,
                    "Malformed PDF content token was skipped",
                ));
                operands.clear();
                if parser.parser.position <= position {
                    parser.parser.position = position + 1;
                }
                continue;
            }
        };
        match token {
            ContentToken::Value(value) => {
                if operands.len() >= 256 {
                    return Err(pdf_error(
                        0,
                        "PDF content operand stack exceeds the parser limit",
                    ));
                }
                operands.push(value);
            }
            ContentToken::Operator(operator, offset) => {
                let object_count = context.objects.len();
                let paint_visible = marked_content.last().is_none_or(|state| state.visible);
                if state.ignore_color_operators
                    && matches!(
                        operator,
                        "g" | "G"
                            | "rg"
                            | "RG"
                            | "k"
                            | "K"
                            | "cs"
                            | "CS"
                            | "sc"
                            | "scn"
                            | "SC"
                            | "SCN"
                            | "sh"
                            | "ri"
                    )
                {
                    operands.clear();
                    continue;
                }
                match operator {
                    "q" => stack.push(state.clone()),
                    "Q" => {
                        if let Some(saved) = stack.pop() {
                            state = saved;
                        }
                    }
                    "cm" => {
                        if let Some(values) = six_numbers(&operands) {
                            state.ctm = state.ctm.concat(matrix(values));
                        }
                    }
                    "w" => {
                        if let Some(value) = last_number(&operands) {
                            state.line_width = value.max(0.0);
                        }
                    }
                    "J" => {
                        if let Some(value) = operands.last().and_then(number_usize) {
                            if let Some(cap) = match value {
                                0 => Some(LineCap::Flat),
                                1 => Some(LineCap::Round),
                                2 => Some(LineCap::Square),
                                _ => None,
                            } {
                                state.line_cap = cap;
                            }
                        }
                    }
                    "j" => {
                        if let Some(value) = operands.last().and_then(number_usize) {
                            if let Some(join) = match value {
                                0 => Some(LineJoin::Miter),
                                1 => Some(LineJoin::Round),
                                2 => Some(LineJoin::Bevel),
                                _ => None,
                            } {
                                state.line_join = join;
                            }
                        }
                    }
                    "M" => {
                        if let Some(value) = last_number(&operands)
                            && value.is_finite()
                            && value > 0.0
                        {
                            state.miter_limit = value;
                        }
                    }
                    "d" => {
                        if operands.len() >= 2
                            && let Some(dash) = pdf_line_dash(&operands[operands.len() - 2])
                        {
                            state.line_dash = dash;
                        }
                    }
                    "g" => {
                        if let Some(value) = last_number(&operands) {
                            state.fill = gray(value);
                            state.fill_pattern = None;
                            state.fill_color_space = "DeviceGray".to_owned();
                        }
                    }
                    "G" => {
                        if let Some(value) = last_number(&operands) {
                            state.stroke = gray(value);
                            state.stroke_pattern = None;
                            state.stroke_color_space = "DeviceGray".to_owned();
                        }
                    }
                    "rg" => {
                        if let Some(values) = last_numbers::<3>(&operands) {
                            state.fill = rgb(values);
                            state.fill_pattern = None;
                            state.fill_color_space = "DeviceRGB".to_owned();
                        }
                    }
                    "RG" => {
                        if let Some(values) = last_numbers::<3>(&operands) {
                            state.stroke = rgb(values);
                            state.stroke_pattern = None;
                            state.stroke_color_space = "DeviceRGB".to_owned();
                        }
                    }
                    "k" => {
                        if let Some(values) = last_numbers::<4>(&operands) {
                            state.fill = cmyk(values);
                            state.fill_pattern = None;
                            state.fill_color_space = "DeviceCMYK".to_owned();
                        }
                    }
                    "K" => {
                        if let Some(values) = last_numbers::<4>(&operands) {
                            state.stroke = cmyk(values);
                            state.stroke_pattern = None;
                            state.stroke_color_space = "DeviceCMYK".to_owned();
                        }
                    }
                    "cs" | "CS" => {
                        if let Some(PdfValue::Name(name)) = operands.last() {
                            let pattern = is_pattern_color_space(name, resources, context.store)
                                .then(String::new);
                            if operator == "cs" {
                                state.fill_pattern = pattern;
                                state.fill_color_space = name.clone();
                            } else {
                                state.stroke_pattern = pattern;
                                state.stroke_color_space = name.clone();
                            }
                        }
                    }
                    "sc" | "scn" | "SC" | "SCN" => {
                        let stroke = operator.starts_with('S');
                        let pattern = if stroke {
                            &mut state.stroke_pattern
                        } else {
                            &mut state.fill_pattern
                        };
                        if pattern.is_some()
                            && let Some(PdfValue::Name(name)) = operands.last()
                        {
                            *pattern = Some(name.clone());
                            if let Some(color) = pattern_base_color(
                                resources,
                                &operands,
                                context.store,
                                if stroke {
                                    &state.stroke_color_space
                                } else {
                                    &state.fill_color_space
                                },
                            ) {
                                if stroke {
                                    state.stroke = color;
                                } else {
                                    state.fill = color;
                                }
                            }
                        } else if let Some(color) = color_from_operands(
                            resources,
                            &operands,
                            context.store,
                            if stroke {
                                &state.stroke_color_space
                            } else {
                                &state.fill_color_space
                            },
                        ) {
                            if stroke {
                                state.stroke = color;
                                state.stroke_pattern = None;
                            } else {
                                state.fill = color;
                                state.fill_pattern = None;
                            }
                        }
                    }
                    "gs" => {
                        if let Some(PdfValue::Name(name)) = operands.last()
                            && let Some((_, value)) =
                                resource_entry(resources, "ExtGState", name, context.store)
                            && let Some(dict) = context.store.dict(value)
                        {
                            if let Some(alpha) = dict.get("ca").and_then(number_f32) {
                                state.fill_alpha =
                                    alpha.clamp(0.0, 1.0) * state.transparency_group_fill_alpha;
                            }
                            if let Some(alpha) = dict.get("CA").and_then(number_f32) {
                                state.stroke_alpha =
                                    alpha.clamp(0.0, 1.0) * state.transparency_group_stroke_alpha;
                            }
                            if let Some(blend_mode) = pdf_blend_mode(dict.get("BM"), context.store) {
                                state.blend_mode = blend_mode;
                            }
                            if let Some(transfer) = dict.get("TR2").or_else(|| dict.get("TR")) {
                                state.transfer_maps = pdf_transfer_maps(transfer, context.store);
                            }
                            if let Some(value) = dict.get("LW").and_then(number_f32) {
                                state.line_width = value.max(0.0);
                            }
                            if let Some(value) = dict.get("LC").and_then(number_usize) {
                                if let Some(cap) = match value {
                                    0 => Some(LineCap::Flat),
                                    1 => Some(LineCap::Round),
                                    2 => Some(LineCap::Square),
                                    _ => None,
                                } {
                                    state.line_cap = cap;
                                }
                            }
                            if let Some(value) = dict.get("LJ").and_then(number_usize) {
                                if let Some(join) = match value {
                                    0 => Some(LineJoin::Miter),
                                    1 => Some(LineJoin::Round),
                                    2 => Some(LineJoin::Bevel),
                                    _ => None,
                                } {
                                    state.line_join = join;
                                }
                            }
                            if let Some(value) = dict.get("ML").and_then(number_f32)
                                && value.is_finite()
                                && value > 0.0
                            {
                                state.miter_limit = value;
                            }
                            if let Some(PdfValue::Array(values)) =
                                dict.get("D").and_then(|value| context.store.resolve(value))
                                && let Some(value) =
                                    values.first().and_then(|value| context.store.resolve(value))
                                && let Some(dash) = pdf_line_dash(value)
                            {
                                state.line_dash = dash;
                            }
                            if let Some(mask) = dict
                                .get("SMask")
                                .and_then(|value| context.store.resolve(value))
                            {
                                if matches!(mask, PdfValue::Name(name) if name == "None") {
                                    state.soft_masks = state.transparency_group_soft_masks.clone();
                                } else if let Some(mask) = pdf_linear_soft_mask(
                                    mask,
                                    state.ctm,
                                    context.store,
                                    context.limits,
                                ) {
                                    state.soft_masks = state.transparency_group_soft_masks.clone();
                                    state.soft_masks.push(mask);
                                } else {
                                    context.warning(
                                        "soft-mask",
                                        "PDF_SOFT_MASK_UNSUPPORTED: a non-linear transparency mask is approximated as opaque",
                                    );
                                }
                            }
                        }
                    }
                    "m" => {
                        if let Some([x, y]) = last_numbers::<2>(&operands) {
                            let point = state.ctm.point(x, y);
                            path.point(
                                PathCommand::MoveTo {
                                    x: point.0,
                                    y: point.1,
                                },
                                &[point],
                            );
                        }
                    }
                    "l" => {
                        if let Some([x, y]) = last_numbers::<2>(&operands) {
                            let point = state.ctm.point(x, y);
                            path.point(
                                PathCommand::LineTo {
                                    x: point.0,
                                    y: point.1,
                                },
                                &[point],
                            );
                        }
                    }
                    "c" => {
                        if let Some([x1, y1, x2, y2, x3, y3]) = last_numbers::<6>(&operands) {
                            let p1 = state.ctm.point(x1, y1);
                            let p2 = state.ctm.point(x2, y2);
                            let p3 = state.ctm.point(x3, y3);
                            path.point(
                                PathCommand::BezierCurveTo {
                                    cp1x: p1.0,
                                    cp1y: p1.1,
                                    cp2x: p2.0,
                                    cp2y: p2.1,
                                    x: p3.0,
                                    y: p3.1,
                                },
                                &[p1, p2, p3],
                            );
                        }
                    }
                    "v" => {
                        if let Some([x2, y2, x3, y3]) = last_numbers::<4>(&operands) {
                            let current = path
                                .points
                                .last()
                                .copied()
                                .unwrap_or_else(|| state.ctm.point(0.0, 0.0));
                            let p2 = state.ctm.point(x2, y2);
                            let p3 = state.ctm.point(x3, y3);
                            path.point(
                                PathCommand::BezierCurveTo {
                                    cp1x: current.0,
                                    cp1y: current.1,
                                    cp2x: p2.0,
                                    cp2y: p2.1,
                                    x: p3.0,
                                    y: p3.1,
                                },
                                &[p2, p3],
                            );
                        }
                    }
                    "y" => {
                        if let Some([x1, y1, x3, y3]) = last_numbers::<4>(&operands) {
                            let p1 = state.ctm.point(x1, y1);
                            let p3 = state.ctm.point(x3, y3);
                            path.point(
                                PathCommand::BezierCurveTo {
                                    cp1x: p1.0,
                                    cp1y: p1.1,
                                    cp2x: p3.0,
                                    cp2y: p3.1,
                                    x: p3.0,
                                    y: p3.1,
                                },
                                &[p1, p3],
                            );
                        }
                    }
                    "h" => path.commands.push(PathCommand::ClosePath),
                    "re" => {
                        if let Some([x, y, width, height]) = last_numbers::<4>(&operands) {
                            let points = [
                                state.ctm.point(x, y),
                                state.ctm.point(x + width, y),
                                state.ctm.point(x + width, y + height),
                                state.ctm.point(x, y + height),
                            ];
                            path.point(
                                PathCommand::MoveTo {
                                    x: points[0].0,
                                    y: points[0].1,
                                },
                                &[points[0]],
                            );
                            for point in &points[1..] {
                                path.point(
                                    PathCommand::LineTo {
                                        x: point.0,
                                        y: point.1,
                                    },
                                    &[*point],
                                );
                            }
                            path.commands.push(PathCommand::ClosePath);
                        }
                    }
                    "S" | "s" | "f" | "F" | "f*" | "B" | "B*" | "b" | "b*" => {
                        if matches!(operator, "s" | "b" | "b*") {
                            path.commands.push(PathCommand::ClosePath);
                        }
                        commit_clip(&path, &mut state, offset)?;
                        paint_path(
                            &mut path,
                            resources,
                            &state,
                            context,
                            (source_object, offset),
                            &operator,
                            depth,
                        )?;
                    }
                    "n" => {
                        commit_clip(&path, &mut state, offset)?;
                        path.clear();
                    }
                    "W" | "W*" => {
                        state.pending_clip = Some(if operator == "W*" {
                            FillRule::EvenOdd
                        } else {
                            FillRule::NonZero
                        });
                    }
                    "BT" => {
                        state.text_matrix = Matrix::IDENTITY;
                        state.line_matrix = Matrix::IDENTITY;
                    }
                    "ET" => {}
                    "Tf" => {
                        if operands.len() >= 2
                            && let PdfValue::Name(name) = &operands[operands.len() - 2]
                            && let Some(size) = operands.last().and_then(number_f32)
                        {
                            state.font_name = name.clone();
                            // The sign participates in the text rendering matrix.
                            state.font_size = size;
                        }
                    }
                    "Tm" => {
                        if let Some(values) = six_numbers(&operands) {
                            state.text_matrix = matrix(values);
                            state.line_matrix = state.text_matrix;
                        }
                    }
                    "Td" | "TD" => {
                        if let Some([tx, ty]) = last_numbers::<2>(&operands) {
                            if operator == "TD" {
                                state.leading = -ty;
                            }
                            state.line_matrix = state.line_matrix.concat(Matrix {
                                e: tx,
                                f: ty,
                                ..Matrix::IDENTITY
                            });
                            state.text_matrix = state.line_matrix;
                        }
                    }
                    "T*" => {
                        state.line_matrix = state.line_matrix.concat(Matrix {
                            e: 0.0,
                            f: -state.leading,
                            ..Matrix::IDENTITY
                        });
                        state.text_matrix = state.line_matrix;
                    }
                    "Tc" => {
                        if let Some(value) = last_number(&operands) {
                            state.char_spacing = value;
                        }
                    }
                    "Tw" => {
                        if let Some(value) = last_number(&operands) {
                            state.word_spacing = value;
                        }
                    }
                    "Tz" => {
                        if let Some(value) = last_number(&operands) {
                            state.horizontal_scale = value / 100.0;
                        }
                    }
                    "TL" => {
                        if let Some(value) = last_number(&operands) {
                            state.leading = value;
                        }
                    }
                    "Ts" => {
                        if let Some(value) = last_number(&operands) {
                            state.text_rise = value;
                        }
                    }
                    "Tr" => {
                        if let Some(mode) = operands.last().and_then(number_usize)
                            && mode <= 7
                        {
                            state.text_render_mode = mode as u8;
                        }
                    }
                    "Tj" => {
                        if let Some(PdfValue::String(text)) = operands.last() {
                            let actual_text = marked_content
                                .last_mut()
                                .and_then(|state| state.actual_text.take());
                            show_text(
                                text,
                                actual_text.as_deref(),
                                resources,
                                &mut state,
                                context,
                                source_object,
                                offset,
                                depth,
                            )?;
                        }
                    }
                    "TJ" => {
                        if let Some(PdfValue::Array(parts)) = operands.last() {
                            let vertical = font_info(resources, &state.font_name, context)?.vertical;
                            for part in parts {
                                match part {
                                    PdfValue::String(text) => show_text(
                                        text,
                                        marked_content
                                            .last_mut()
                                            .and_then(|state| state.actual_text.take())
                                            .as_deref(),
                                        resources,
                                        &mut state,
                                        context,
                                        source_object,
                                        offset,
                                        depth,
                                    )?,
                                    PdfValue::Number(adjustment) => {
                                        let adjustment = (*adjustment as f32 / 1000.0)
                                            * state.font_size
                                            * if vertical {
                                                1.0
                                            } else {
                                                -state.horizontal_scale
                                            };
                                        advance_text_matrix(&mut state, adjustment, vertical);
                                    }
                                    _ => {}
                                }
                            }
                        }
                    }
                    "'" => {
                        state.line_matrix = state.line_matrix.concat(Matrix {
                            e: 0.0,
                            f: -state.leading,
                            ..Matrix::IDENTITY
                        });
                        state.text_matrix = state.line_matrix;
                        if let Some(PdfValue::String(text)) = operands.last() {
                            let actual_text = marked_content
                                .last_mut()
                                .and_then(|state| state.actual_text.take());
                            show_text(
                                text,
                                actual_text.as_deref(),
                                resources,
                                &mut state,
                                context,
                                source_object,
                                offset,
                                depth,
                            )?;
                        }
                    }
                    "\"" => {
                        if operands.len() >= 3 {
                            state.word_spacing = number_f32(&operands[operands.len() - 3])
                                .unwrap_or(state.word_spacing);
                            state.char_spacing = number_f32(&operands[operands.len() - 2])
                                .unwrap_or(state.char_spacing);
                            state.line_matrix = state.line_matrix.concat(Matrix {
                                e: 0.0,
                                f: -state.leading,
                                ..Matrix::IDENTITY
                            });
                            state.text_matrix = state.line_matrix;
                            if let Some(PdfValue::String(text)) = operands.last() {
                                show_text(
                                    text,
                                    marked_content
                                        .last_mut()
                                        .and_then(|state| state.actual_text.take())
                                        .as_deref(),
                                    resources,
                                    &mut state,
                                    context,
                                    source_object,
                                    offset,
                                    depth,
                                )?;
                            }
                        }
                    }
                    "Do" => {
                        if let Some(PdfValue::Name(name)) = operands.last() {
                            paint_xobject(name, resources, &state, context, offset, depth)?;
                        }
                    }
                    "BI" => {
                        if let Some(image) = parser.inline_image()? {
                            paint_inline_image(&image, resources, &state, context, offset)?;
                        } else {
                            context.warning(
                                "inline-image",
                                "PDF_INLINE_IMAGE_UNSUPPORTED: an unterminated inline image was omitted",
                            );
                        }
                    }
                    "sh" => {
                        if let Some(PdfValue::Name(name)) = operands.last() {
                            paint_shading(name, resources, &state, context, offset)?;
                        }
                    }
                    "BMC" => marked_content.push(MarkedContentState {
                        actual_text: None,
                        visible: paint_visible,
                    }),
                    "BDC" => {
                        let property = operands.last().and_then(|value| {
                            marked_content_property(value, resources, context.store)
                        });
                        let is_optional_content = operands
                            .first()
                            .is_some_and(|value| matches!(value, PdfValue::Name(name) if name == "OC"));
                        let visible = paint_visible
                            && (!is_optional_content
                                || operands.last().is_none_or(|value| {
                                    optional_content_visible(
                                        value,
                                        resources,
                                        context.store,
                                        context.optional_content,
                                    )
                                }));
                        marked_content.push(MarkedContentState {
                            actual_text: property
                                .and_then(|(_, value)| context.store.dict(value))
                                .and_then(marked_content_actual_text),
                            visible,
                        });
                    }
                    "EMC" => {
                        marked_content.pop();
                    }
                    "BX" => compatibility_depth = compatibility_depth.saturating_add(1),
                    "EX" => compatibility_depth = compatibility_depth.saturating_sub(1),
                    "ri" | "i" | "d0" | "d1" | "MP" | "DP" => {}
                    _ if compatibility_depth == 0 => context.warning(
                        "content-operator",
                        "PDF_CONTENT_OPERATOR_UNSUPPORTED: an unknown PDF content operator was ignored",
                    ),
                    _ => {}
                }
                if !paint_visible {
                    context.objects.truncate(object_count);
                }
                if path.commands.len() > MAX_PATH_COMMANDS {
                    return Err(pdf_error(offset, "PDF path exceeds the command limit"));
                }
                operands.clear();
            }
        }
    }
    Ok(())
}

fn apply_pdf_stroke_style(visual: Visual, state: &GraphicsState, stroke: bool) -> Visual {
    if !stroke {
        return visual;
    }
    let style = StrokeStyle {
        cap: state.line_cap,
        join: state.line_join,
        miter_limit: state.miter_limit,
        dash: state
            .line_dash
            .iter()
            .map(|value| value * state.ctm.scale())
            .collect(),
        ..StrokeStyle::default()
    };
    if style == StrokeStyle::default() {
        visual
    } else {
        Visual::StrokeStyle {
            style,
            visual: Box::new(visual),
        }
    }
}

fn solid_raster_soft_mask_visual(
    color: u32,
    mask: &PdfSoftMask,
    bounds: Rect,
    geometry_clip: Option<Geometry>,
) -> Option<Visual> {
    let raster = mask.raster.as_ref()?;
    let aligned_mask = aligned_pdf_soft_mask_raster(mask, raster, bounds);
    let (mask_media_type, mask_bytes, mask_width, mask_height, aligned) =
        if let Some((bytes, width, height)) = aligned_mask {
            ("image/bmp".to_owned(), bytes, width, height, true)
        } else {
            (
                raster.media_type.clone(),
                raster.bytes.clone(),
                raster.width,
                raster.height,
                false,
            )
        };
    let [red, green, blue, alpha] = color.to_be_bytes();
    let image = rgba_bmp(1, 1, &[red, green, blue], &[alpha], RasterColorSpace::Rgb)?;
    let mut visual = Visual::MaskedImage {
        media_type: "image/bmp".to_owned(),
        bytes: image,
        resource_id: 0,
        mask_resource_id: 0,
        mask_width,
        mask_height,
        mask_media_type,
        alpha_mask: mask_bytes,
        crop: ImageCrop::default(),
    };
    if let Some(geometry) = geometry_clip {
        visual = Visual::Effect {
            shadow: None,
            clip: Some(geometry),
            visual: Box::new(visual),
        };
    }
    if !aligned && let Some(mask_clip) = &mask.clip {
        visual = clip_visual_to_pdf_clip(visual, bounds, mask_clip);
    }
    Some(visual)
}

fn aligned_pdf_soft_mask_raster(
    mask: &PdfSoftMask,
    raster: &PdfRasterSoftMask,
    object_bounds: Rect,
) -> Option<(Vec<u8>, u32, u32)> {
    let placement = raster.placement?;
    let source = raster.samples.as_deref()?;
    let source_width = usize::try_from(raster.width).ok()?;
    let source_height = usize::try_from(raster.height).ok()?;
    if source.len() != source_width.checked_mul(source_height)? {
        return None;
    }
    let image_bounds = bounds(&[
        placement.point(0.0, 0.0),
        placement.point(1.0, 0.0),
        placement.point(1.0, 1.0),
        placement.point(0.0, 1.0),
    ])?;
    let width_scale = object_bounds.width / image_bounds.width;
    let height_scale = object_bounds.height / image_bounds.height;
    let width = if (width_scale - 1.0).abs() <= 0.001 {
        source_width
    } else {
        (width_scale * source_width as f32).ceil().max(1.0) as usize
    };
    let height = if (height_scale - 1.0).abs() <= 0.001 {
        source_height
    } else {
        (height_scale * source_height as f32).ceil().max(1.0) as usize
    };
    let pixels = width.checked_mul(height)?;
    if pixels > 16_000_000 || pixels.checked_mul(5)? > 80_000_000 {
        return None;
    }
    let outside = channel(mask.outside);
    let mut samples = Vec::new();
    samples.try_reserve_exact(pixels).ok()?;
    for row in 0..height {
        let page_y = object_bounds.y + object_bounds.height * (row as f32 + 0.5) / height as f32;
        for column in 0..width {
            let page_x =
                object_bounds.x + object_bounds.width * (column as f32 + 0.5) / width as f32;
            if mask.bounds.is_some_and(|mask_bounds| {
                page_x < mask_bounds.x
                    || page_x > mask_bounds.x + mask_bounds.width
                    || page_y < mask_bounds.y
                    || page_y > mask_bounds.y + mask_bounds.height
            }) {
                samples.push(outside);
                continue;
            }
            let Some((image_x, image_y)) = placement.inverse_point(page_x, page_y) else {
                samples.push(outside);
                continue;
            };
            if !(0.0..=1.0).contains(&image_x) || !(0.0..=1.0).contains(&image_y) {
                samples.push(outside);
                continue;
            }
            let source_x = ((image_x * source_width as f32).floor() as usize).min(source_width - 1);
            let source_y =
                (((1.0 - image_y) * source_height as f32).floor() as usize).min(source_height - 1);
            samples.push(source[source_y * source_width + source_x]);
        }
    }
    let alpha = vec![255; pixels];
    Some((
        rgba_bmp(width, height, &samples, &alpha, RasterColorSpace::Gray)?,
        u32::try_from(width).ok()?,
        u32::try_from(height).ok()?,
    ))
}

fn paint_path(
    path: &mut PdfPath,
    resources: Option<&PdfValue>,
    state: &GraphicsState,
    context: &mut PageContext<'_>,
    source: (u32, usize),
    operator: &str,
    depth: usize,
) -> Result<(), Diagnostic> {
    let (source_object, offset) = source;
    if let Some((bounds, commands)) = path.painted() {
        let fill = matches!(operator, "f" | "F" | "f*" | "B" | "B*" | "b" | "b*");
        let stroke = matches!(operator, "S" | "s" | "B" | "B*" | "b" | "b*");
        let shading_pattern_clip = (fill && !stroke)
            .then(|| {
                state.fill_pattern.as_deref().and_then(|pattern| {
                    pdf_shading_pattern_bounds(pattern, resources, state, context)
                })
            })
            .flatten();
        let mut pattern_fill = None;
        if fill && let Some(pattern) = state.fill_pattern.as_deref() {
            pattern_fill = pdf_shading_pattern_paint(
                pattern,
                resources,
                state,
                context,
                bounds,
                state.fill_alpha,
            )
            .or(pdf_tiling_pattern_paint(
                pattern, resources, state, context,
            )?);
            if pattern_fill.is_none() {
                let object_count = context.objects.len();
                let cycle_count = context.form_cycle_count;
                paint_tiling_pattern(
                    pattern,
                    resources,
                    state,
                    context,
                    offset,
                    depth,
                    PdfClip {
                        bounds,
                        fill_rule: if operator.ends_with('*') {
                            crate::model::FillRule::EvenOdd
                        } else {
                            crate::model::FillRule::NonZero
                        },
                        commands: commands.clone(),
                    },
                )?;
                if context.objects.len() == object_count && context.form_cycle_count > cycle_count {
                    pattern_fill = Some(Paint::Solid(with_alpha(state.fill, state.fill_alpha)));
                }
            }
        }
        if fill && state.fill_pattern.is_some() && pattern_fill.is_none() && !stroke {
            path.clear();
            return Ok(());
        }
        let fill_paint = if fill {
            pattern_fill.unwrap_or_else(|| {
                if state.fill_pattern.is_none() {
                    Paint::Solid(with_alpha(state.fill, state.fill_alpha))
                } else {
                    Paint::None
                }
            })
        } else {
            Paint::None
        };
        let pattern_stroke = if stroke {
            state
                .stroke_pattern
                .as_deref()
                .map_or(Ok(None), |pattern| {
                    let mut pattern_state = state.clone();
                    pattern_state.fill = state.stroke;
                    pattern_state.fill_alpha = state.stroke_alpha;
                    Ok(pdf_shading_pattern_paint(
                        pattern,
                        resources,
                        state,
                        context,
                        bounds,
                        state.stroke_alpha,
                    )
                    .or(pdf_tiling_pattern_paint(
                        pattern,
                        resources,
                        &pattern_state,
                        context,
                    )?))
                })?
        } else {
            None
        };
        let stroke_paint = if stroke {
            pattern_stroke.unwrap_or_else(|| {
                if state.stroke_pattern.is_none() {
                    Paint::Solid(with_alpha(state.stroke, state.stroke_alpha))
                } else {
                    Paint::None
                }
            })
        } else {
            Paint::None
        };
        let geometry = Geometry::Path {
            fill_rule: if operator.ends_with('*') {
                crate::model::FillRule::EvenOdd
            } else {
                crate::model::FillRule::NonZero
            },
            commands,
        };
        if fill
            && !stroke
            && let Paint::Solid(color) = fill_paint
            && !state.text_clips.is_empty()
        {
            for clip in &state.text_clips {
                let visual = clip_visual_to_rect(
                    text_clip_visual_with_color(clip.visual.clone(), color),
                    clip.bounds,
                    bounds,
                );
                context.push_object(
                    ObjectKind::TextBox,
                    clip.bounds,
                    (!clip.text.is_empty()).then_some(clip.text.clone()),
                    apply_clips(visual, clip.bounds, state),
                    pdf_source(
                        "text",
                        Some(clip.source_object),
                        Some(clip.offset),
                        MappingQuality::Approximate,
                    ),
                )?;
            }
            path.clear();
            return Ok(());
        }
        if fill
            && !stroke
            && let [mask] = state.soft_masks.as_slice()
            && let Paint::Solid(color) = fill_paint
            && let Some(visual) =
                solid_raster_soft_mask_visual(color, mask, bounds, Some(geometry.clone()))
        {
            let visual = apply_clips(visual, bounds, state);
            push_knockout_clear(context, bounds, &visual, state, source_object, offset)?;
            context.push_object(
                ObjectKind::Shape,
                bounds,
                None,
                visual,
                pdf_source(
                    "path",
                    Some(source_object),
                    Some(offset),
                    MappingQuality::Exact,
                ),
            )?;
            path.clear();
            return Ok(());
        }
        if let [mask] = state.soft_masks.as_slice()
            && !mask.regions.is_empty()
        {
            let mut layers = Vec::with_capacity(mask.regions.len() + 1);
            if mask.outside > 0.0 {
                layers.push((None, mask.outside));
            }
            for (region, alpha) in &mask.regions {
                if *alpha > 0.0 {
                    layers.push((Some(*region), *alpha));
                }
            }
            for (index, (clip, alpha)) in layers.into_iter().enumerate() {
                let inside_mask = clip.is_some();
                let base = Visual::PaintedShape {
                    geometry: geometry.clone(),
                    fill: multiply_paint_alpha(fill_paint.clone(), alpha),
                    stroke: multiply_paint_alpha(stroke_paint.clone(), alpha),
                    stroke_width: state.line_width * state.ctm.scale(),
                };
                let mut visual = apply_pdf_stroke_style(base, state, stroke);
                if let Some(clip) = shading_pattern_clip {
                    visual = clip_visual_to_rect(visual, bounds, clip);
                }
                if let Some(clip) = clip {
                    visual = clip_visual_to_rect(visual, bounds, clip);
                } else if index == 0 {
                    visual = clip_visual_outside_rects(visual, bounds, &mask.regions);
                }
                if inside_mask && let Some(mask_clip) = &mask.clip {
                    visual = clip_visual_to_pdf_clip(visual, bounds, mask_clip);
                }
                let visual = apply_clips(visual, bounds, state);
                push_knockout_clear(context, bounds, &visual, state, source_object, offset)?;
                context.push_object(
                    ObjectKind::Shape,
                    bounds,
                    None,
                    visual,
                    pdf_source(
                        "path",
                        Some(source_object),
                        Some(offset),
                        MappingQuality::Exact,
                    ),
                )?;
            }
            path.clear();
            return Ok(());
        }
        let base = Visual::PaintedShape {
            geometry,
            fill: apply_linear_soft_masks_to_paint(fill_paint, bounds, &state.soft_masks),
            stroke: apply_linear_soft_masks_to_paint(stroke_paint, bounds, &state.soft_masks),
            stroke_width: state.line_width * state.ctm.scale(),
        };
        let mut visual = apply_pdf_stroke_style(base, state, stroke);
        if let Some(clip) = shading_pattern_clip {
            visual = clip_visual_to_rect(visual, bounds, clip);
        }
        let visual = apply_clips(visual, bounds, state);
        push_knockout_clear(context, bounds, &visual, state, source_object, offset)?;
        context.push_object(
            ObjectKind::Shape,
            bounds,
            None,
            visual,
            pdf_source(
                "path",
                Some(source_object),
                Some(offset),
                MappingQuality::Exact,
            ),
        )?;
    }
    path.clear();
    Ok(())
}

fn multiply_paint_alpha(paint: Paint, alpha: f32) -> Paint {
    match paint {
        Paint::Solid(color) => {
            let mut channels = color.to_be_bytes();
            channels[3] = channel(f32::from(channels[3]) / 255.0 * alpha);
            Paint::Solid(u32::from_be_bytes(channels))
        }
        paint => paint,
    }
}

fn clip_visual_to_rect(visual: Visual, bounds: Rect, clip: Rect) -> Visual {
    let x0 = clip.x - bounds.x;
    let y0 = clip.y - bounds.y;
    let x1 = x0 + clip.width;
    let y1 = y0 + clip.height;
    Visual::Effect {
        shadow: None,
        clip: Some(Geometry::Path {
            fill_rule: crate::model::FillRule::NonZero,
            commands: vec![
                PathCommand::MoveTo { x: x0, y: y0 },
                PathCommand::LineTo { x: x1, y: y0 },
                PathCommand::LineTo { x: x1, y: y1 },
                PathCommand::LineTo { x: x0, y: y1 },
                PathCommand::ClosePath,
            ],
        }),
        visual: Box::new(visual),
    }
}

fn clip_visual_to_pdf_clip(visual: Visual, bounds: Rect, clip: &PdfClip) -> Visual {
    Visual::Effect {
        shadow: None,
        clip: Some(Geometry::Path {
            fill_rule: clip.fill_rule,
            commands: translate_path_commands(
                &clip.commands,
                clip.bounds.x - bounds.x,
                clip.bounds.y - bounds.y,
            ),
        }),
        visual: Box::new(visual),
    }
}

fn clip_visual_outside_rects(visual: Visual, bounds: Rect, regions: &[(Rect, f32)]) -> Visual {
    let mut commands = vec![
        PathCommand::MoveTo { x: 0.0, y: 0.0 },
        PathCommand::LineTo {
            x: bounds.width,
            y: 0.0,
        },
        PathCommand::LineTo {
            x: bounds.width,
            y: bounds.height,
        },
        PathCommand::LineTo {
            x: 0.0,
            y: bounds.height,
        },
        PathCommand::ClosePath,
    ];
    for (region, _) in regions {
        let x0 = region.x - bounds.x;
        let y0 = region.y - bounds.y;
        let x1 = x0 + region.width;
        let y1 = y0 + region.height;
        commands.extend([
            PathCommand::MoveTo { x: x0, y: y0 },
            PathCommand::LineTo { x: x1, y: y0 },
            PathCommand::LineTo { x: x1, y: y1 },
            PathCommand::LineTo { x: x0, y: y1 },
            PathCommand::ClosePath,
        ]);
    }
    Visual::Effect {
        shadow: None,
        clip: Some(Geometry::Path {
            fill_rule: crate::model::FillRule::EvenOdd,
            commands,
        }),
        visual: Box::new(visual),
    }
}

fn commit_clip(path: &PdfPath, state: &mut GraphicsState, offset: usize) -> Result<(), Diagnostic> {
    let Some(fill_rule) = state.pending_clip.take() else {
        return Ok(());
    };
    let Some((bounds, commands)) = path.painted() else {
        return Ok(());
    };
    if state.clips.len() >= MAX_CLIP_DEPTH {
        return Err(pdf_error(
            offset,
            "PDF clipping depth exceeds the parser limit",
        ));
    }
    state.clips.push(PdfClip {
        bounds,
        fill_rule,
        commands,
    });
    Ok(())
}

fn apply_clips(mut visual: Visual, bounds: Rect, state: &GraphicsState) -> Visual {
    for clip in &state.clips {
        if visual_matches_clip(&visual, bounds, clip) {
            continue;
        }
        if let Some(clipped) = materialize_solid_rect_clip(&visual, bounds, clip) {
            visual = clipped;
            continue;
        }
        if axis_aligned_rect_clip_contains(clip, bounds) {
            continue;
        }
        let dx = clip.bounds.x - bounds.x;
        let dy = clip.bounds.y - bounds.y;
        visual = Visual::Effect {
            shadow: None,
            clip: Some(Geometry::Path {
                fill_rule: clip.fill_rule,
                commands: translate_path_commands(&clip.commands, dx, dy),
            }),
            visual: Box::new(visual),
        };
    }
    if state.blend_mode != BlendMode::Normal {
        visual = Visual::Layer {
            transform: AffineTransform::IDENTITY,
            opacity: 1.0,
            blend_mode: state.blend_mode,
            visual: Box::new(visual),
        };
    }
    if state.blend_mode == BlendMode::Normal
        && state.transparency_group_blend_mode != BlendMode::Normal
    {
        visual = Visual::Layer {
            transform: AffineTransform::IDENTITY,
            opacity: 1.0,
            blend_mode: state.transparency_group_blend_mode,
            visual: Box::new(visual),
        };
    }
    visual
}

fn visual_matches_clip(visual: &Visual, bounds: Rect, clip: &PdfClip) -> bool {
    let geometry = match visual {
        Visual::PaintedShape { geometry, .. } | Visual::Shape { geometry, .. } => geometry,
        _ => return false,
    };
    let Geometry::Path {
        fill_rule,
        commands,
    } = geometry
    else {
        return false;
    };
    *fill_rule == clip.fill_rule
        && *commands
            == translate_path_commands(
                &clip.commands,
                clip.bounds.x - bounds.x,
                clip.bounds.y - bounds.y,
            )
}

fn materialize_solid_rect_clip(visual: &Visual, bounds: Rect, clip: &PdfClip) -> Option<Visual> {
    if clip.bounds.x < bounds.x
        || clip.bounds.y < bounds.y
        || clip.bounds.x + clip.bounds.width > bounds.x + bounds.width
        || clip.bounds.y + clip.bounds.height > bounds.y + bounds.height
    {
        return None;
    }
    let geometry = Geometry::Path {
        fill_rule: clip.fill_rule,
        commands: translate_path_commands(
            &clip.commands,
            clip.bounds.x - bounds.x,
            clip.bounds.y - bounds.y,
        ),
    };
    match visual {
        Visual::PaintedShape {
            geometry: source,
            fill,
            stroke: Paint::None,
            stroke_width,
        } if geometry_is_axis_aligned_rect(source, bounds) => Some(Visual::PaintedShape {
            geometry,
            fill: fill.clone(),
            stroke: Paint::None,
            stroke_width: *stroke_width,
        }),
        Visual::Shape {
            geometry: source,
            fill,
            stroke,
            stroke_width,
        } if stroke & 0xff == 0 && geometry_is_axis_aligned_rect(source, bounds) => {
            Some(Visual::Shape {
                geometry,
                fill: *fill,
                stroke: *stroke,
                stroke_width: *stroke_width,
            })
        }
        _ => None,
    }
}

fn geometry_is_axis_aligned_rect(geometry: &Geometry, bounds: Rect) -> bool {
    match geometry {
        Geometry::Rectangle => true,
        Geometry::Path { commands, .. } => {
            axis_aligned_rect_commands(commands, bounds.width, bounds.height)
        }
        _ => false,
    }
}

fn axis_aligned_rect_clip_contains(clip: &PdfClip, bounds: Rect) -> bool {
    axis_aligned_rect_commands(&clip.commands, clip.bounds.width, clip.bounds.height)
        && bounds.x >= clip.bounds.x
        && bounds.y >= clip.bounds.y
        && bounds.x + bounds.width <= clip.bounds.x + clip.bounds.width
        && bounds.y + bounds.height <= clip.bounds.y + clip.bounds.height
}

fn axis_aligned_rect_commands(commands: &[PathCommand], width: f32, height: f32) -> bool {
    let [
        PathCommand::MoveTo { x: x0, y: y0 },
        PathCommand::LineTo { x: x1, y: y1 },
        PathCommand::LineTo { x: x2, y: y2 },
        PathCommand::LineTo { x: x3, y: y3 },
        PathCommand::ClosePath,
    ] = commands
    else {
        return false;
    };
    let epsilon = 0.001;
    let corner = |x: f32, y: f32| -> Option<u8> {
        let right = (x - width).abs() <= epsilon;
        let bottom = (y - height).abs() <= epsilon;
        if !(x.abs() <= epsilon || right) || !(y.abs() <= epsilon || bottom) {
            return None;
        }
        Some(u8::from(right) | (u8::from(bottom) << 1))
    };
    let Some(corners) = [(*x0, *y0), (*x1, *y1), (*x2, *y2), (*x3, *y3)]
        .into_iter()
        .try_fold(0_u8, |seen, (x, y)| {
            corner(x, y).map(|index| seen | (1 << index))
        })
    else {
        return false;
    };
    corners == 0b1111
}

fn transform_image_visual(visual: Visual, bounds: Rect, ctm: Matrix) -> Visual {
    let top_left = ctm.point(0.0, 1.0);
    let top_right = ctm.point(1.0, 1.0);
    let bottom_left = ctm.point(0.0, 0.0);
    let transform = AffineTransform {
        a: (top_right.0 - top_left.0) / bounds.width,
        b: (top_right.1 - top_left.1) / bounds.width,
        c: (bottom_left.0 - top_left.0) / bounds.height,
        d: (bottom_left.1 - top_left.1) / bounds.height,
        e: 0.0,
        f: 0.0,
    };
    let transform = AffineTransform {
        e: top_left.0 - transform.a * bounds.x - transform.c * bounds.y,
        f: top_left.1 - transform.b * bounds.x - transform.d * bounds.y,
        ..transform
    };
    let identity = AffineTransform::IDENTITY;
    if (transform.a - identity.a).abs() <= 1e-6
        && (transform.b - identity.b).abs() <= 1e-6
        && (transform.c - identity.c).abs() <= 1e-6
        && (transform.d - identity.d).abs() <= 1e-6
        && transform.e.abs() <= 1e-4
        && transform.f.abs() <= 1e-4
    {
        visual
    } else {
        Visual::Layer {
            transform,
            opacity: 1.0,
            blend_mode: BlendMode::Normal,
            visual: Box::new(visual),
        }
    }
}

fn pdf_blend_mode(value: Option<&PdfValue>, store: &ObjectStore) -> Option<BlendMode> {
    match store.resolve(value?)? {
        PdfValue::Name(name) => match name.as_str() {
            "Normal" | "Compatible" => Some(BlendMode::Normal),
            "Multiply" => Some(BlendMode::Multiply),
            "Screen" => Some(BlendMode::Screen),
            "Overlay" => Some(BlendMode::Overlay),
            "Darken" => Some(BlendMode::Darken),
            "Lighten" => Some(BlendMode::Lighten),
            "ColorDodge" => Some(BlendMode::ColorDodge),
            "ColorBurn" => Some(BlendMode::ColorBurn),
            "HardLight" => Some(BlendMode::HardLight),
            "SoftLight" => Some(BlendMode::SoftLight),
            "Difference" => Some(BlendMode::Difference),
            "Exclusion" => Some(BlendMode::Exclusion),
            "Hue" => Some(BlendMode::Hue),
            "Saturation" => Some(BlendMode::Saturation),
            "Color" => Some(BlendMode::Color),
            "Luminosity" => Some(BlendMode::Luminosity),
            _ => None,
        },
        PdfValue::Array(values) => values
            .iter()
            .find_map(|value| pdf_blend_mode(Some(value), store)),
        _ => None,
    }
}

fn translate_path_commands(commands: &[PathCommand], dx: f32, dy: f32) -> Vec<PathCommand> {
    commands
        .iter()
        .map(|command| match *command {
            PathCommand::MoveTo { x, y } => PathCommand::MoveTo {
                x: x + dx,
                y: y + dy,
            },
            PathCommand::LineTo { x, y } => PathCommand::LineTo {
                x: x + dx,
                y: y + dy,
            },
            PathCommand::QuadraticCurveTo { cpx, cpy, x, y } => PathCommand::QuadraticCurveTo {
                cpx: cpx + dx,
                cpy: cpy + dy,
                x: x + dx,
                y: y + dy,
            },
            PathCommand::BezierCurveTo {
                cp1x,
                cp1y,
                cp2x,
                cp2y,
                x,
                y,
            } => PathCommand::BezierCurveTo {
                cp1x: cp1x + dx,
                cp1y: cp1y + dy,
                cp2x: cp2x + dx,
                cp2y: cp2y + dy,
                x: x + dx,
                y: y + dy,
            },
            PathCommand::ClosePath => PathCommand::ClosePath,
        })
        .collect()
}

fn pdf_tiling_pattern_paint(
    name: &str,
    resources: Option<&PdfValue>,
    state: &GraphicsState,
    context: &PageContext<'_>,
) -> Result<Option<Paint>, Diagnostic> {
    let Some((_, value)) = resource_entry(resources, "Pattern", name, context.store) else {
        return Ok(None);
    };
    let PdfValue::Stream { dict, .. } = value else {
        return Ok(None);
    };
    if dict.get("PatternType").and_then(number_usize) != Some(1) {
        return Ok(None);
    }
    let Some(x_step) = dict.get("XStep").and_then(number_f32).map(f32::abs) else {
        return Ok(None);
    };
    let Some(y_step) = dict.get("YStep").and_then(number_f32).map(f32::abs) else {
        return Ok(None);
    };
    let scale = state.ctm.scale();
    let spacing = ((x_step + y_step) * 0.5 * scale).clamp(1.0, 64.0);
    let pattern_matrix = dict
        .get("Matrix")
        .and_then(|value| six_numbers_value(context.store, value))
        .map(matrix)
        .unwrap_or(Matrix::IDENTITY);
    let pattern_origin = state
        .pattern_base_ctm
        .concat(pattern_matrix)
        .point(0.0, 0.0);
    let pattern_resources = dict.get("Resources").or(resources);
    let decoded = decode_stream(value, context.store, context.limits)?;
    let mut parser = ContentParser::new(&decoded, context.limits);
    let mut operands = Vec::new();
    let mut current = None;
    let mut segments = Vec::new();
    let mut line_width = 1.0;
    let mut foreground = state.fill;
    let mut fill_color_space = "DeviceGray".to_owned();
    let mut curve_fill = false;
    let mut curve_stroke = false;
    let mut explicit_stroke_colors = Vec::new();
    let mut pending_rectangle = None;
    let mut filled_rectangles = Vec::new();
    while let Some(token) = parser.next()? {
        match token {
            ContentToken::Value(value) => operands.push(value),
            ContentToken::Operator(operator, _) => {
                match operator {
                    // The batched paint below represents only self-contained
                    // geometric hatch/dot cells. Delegated resources, alpha,
                    // and transforms need the full pattern interpreter;
                    // classifying a nested shading as a dot repeats arbitrary
                    // fragments across the painted path.
                    "Do" | "sh" | "cm" => return Ok(None),
                    "re" => pending_rectangle = last_numbers::<4>(&operands),
                    "m" => current = last_numbers::<2>(&operands),
                    "l" => {
                        if let (Some(start), Some(end)) = (current, last_numbers::<2>(&operands)) {
                            segments.push((end[0] - start[0], end[1] - start[1]));
                            current = Some(end);
                        }
                    }
                    "w" => {
                        if let Some(width) = last_number(&operands) {
                            line_width = width.abs() * scale;
                        }
                    }
                    "RG" => {
                        if let Some(values) = last_numbers::<3>(&operands) {
                            foreground = rgb(values);
                            explicit_stroke_colors.push(foreground);
                        }
                    }
                    "G" => {
                        if let Some(value) = last_number(&operands) {
                            foreground = gray(value);
                            explicit_stroke_colors.push(foreground);
                        }
                    }
                    "g" => {
                        if let Some(value) = last_number(&operands) {
                            foreground = gray(value);
                        }
                    }
                    "rg" => {
                        if let Some(values) = last_numbers::<3>(&operands) {
                            foreground = rgb(values);
                        }
                    }
                    "k" => {
                        if let Some(values) = last_numbers::<4>(&operands) {
                            foreground = cmyk(values);
                        }
                    }
                    "cs" => {
                        if let Some(PdfValue::Name(name)) = operands.last() {
                            fill_color_space = name.clone();
                        }
                    }
                    "sc" | "scn" => {
                        let Some(color) = color_from_operands(
                            pattern_resources,
                            &operands,
                            context.store,
                            &fill_color_space,
                        ) else {
                            return Ok(None);
                        };
                        foreground = color;
                    }
                    "gs" => {
                        let Some(PdfValue::Name(name)) = operands.last() else {
                            return Ok(None);
                        };
                        let Some((_, value)) =
                            resource_entry(pattern_resources, "ExtGState", name, context.store)
                        else {
                            return Ok(None);
                        };
                        let Some(graphics_state) = context.store.dict(value) else {
                            return Ok(None);
                        };
                        let default_name = |key: &str| {
                            graphics_state.get(key).is_none_or(|value| {
                                matches!(
                                    context.store.resolve(value),
                                    Some(PdfValue::Name(name)) if name == "Default" || name == "Identity" || name == "Normal" || name == "None"
                                )
                            })
                        };
                        if !default_name("BM")
                            || !default_name("SMask")
                            || !default_name("TR")
                            || !default_name("TR2")
                            || graphics_state
                                .get("ca")
                                .and_then(number_f32)
                                .is_some_and(|alpha| (alpha - state.fill_alpha).abs() > 0.001)
                        {
                            return Ok(None);
                        }
                    }
                    "K" => {
                        if let Some(values) = last_numbers::<4>(&operands) {
                            foreground = cmyk(values);
                            explicit_stroke_colors.push(foreground);
                        }
                    }
                    "c" | "v" | "y" => curve_stroke = true,
                    "f" | "F" | "f*" => {
                        curve_fill = true;
                        if let Some(rectangle) = pending_rectangle.take() {
                            filled_rectangles.push((rectangle, foreground));
                        }
                    }
                    _ => {}
                }
                operands.clear();
            }
        }
    }
    if filled_rectangles.len() == 3 {
        let mut rectangles = filled_rectangles.iter().collect::<Vec<_>>();
        rectangles.sort_by(|left, right| {
            (right.0[2].abs() * right.0[3].abs()).total_cmp(&(left.0[2].abs() * left.0[3].abs()))
        });
        let (cell, background) = rectangles[0];
        let tiles = &rectangles[1..];
        let half_x = x_step / 2.0;
        let half_y = y_step / 2.0;
        if (cell[2].abs() - x_step).abs() < 0.01
            && (cell[3].abs() - y_step).abs() < 0.01
            && tiles.iter().all(|(tile, _)| {
                (tile[2].abs() - half_x).abs() < 0.01 && (tile[3].abs() - half_y).abs() < 0.01
            })
            && tiles[0].1 == tiles[1].1
        {
            return Ok(Some(Paint::Pattern {
                preset: format!(
                    "pdf:checker:{:.4}:0.1:{:.4}:{:.4}",
                    (spacing / 2.0).max(1.0),
                    pattern_origin.0,
                    pattern_origin.1,
                ),
                foreground: with_alpha(tiles[0].1, state.fill_alpha),
                background: with_alpha(*background, state.fill_alpha),
            }));
        }
    }
    if filled_rectangles.len() == 1 && segments.is_empty() && !curve_stroke {
        let ([x, y, width, height], color) = filled_rectangles[0];
        let Some([left, bottom, right, top]) = dict
            .get("BBox")
            .and_then(|value| context.store.resolve(value))
            .and_then(|value| match value {
                PdfValue::Array(values) => last_numbers::<4>(values),
                _ => None,
            })
        else {
            return Ok(None);
        };
        if (x.min(x + width) - left.min(right)).abs() < 0.01
            && (x.max(x + width) - left.max(right)).abs() < 0.01
            && (y.min(y + height) - bottom.min(top)).abs() < 0.01
            && (y.max(y + height) - bottom.max(top)).abs() < 0.01
        {
            return Ok(Some(Paint::Solid(with_alpha(color, state.fill_alpha))));
        }
    }
    if !filled_rectangles.is_empty() {
        return Ok(None);
    }
    // A single-color filled curve can be represented by the compact dot
    // preset. Stroked curves and multi-color cells need the real tiling
    // interpreter; reducing them to one dot loses both their outline and the
    // per-path colors (issue2177.pdf).
    if curve_stroke
        || explicit_stroke_colors
            .windows(2)
            .any(|colors| colors[0] != colors[1])
    {
        return Ok(None);
    }
    let kind = if curve_fill && segments.is_empty() {
        "dot"
    } else if segments.is_empty() {
        return Ok(None);
    } else {
        let vertical = segments.iter().all(|(dx, _)| dx.abs() < 0.001);
        let horizontal = segments.iter().all(|(_, dy)| dy.abs() < 0.001);
        let positive = segments.iter().any(|(dx, dy)| dx * dy > 0.0);
        let negative = segments.iter().any(|(dx, dy)| dx * dy < 0.0);
        if vertical {
            "vert"
        } else if horizontal {
            "horz"
        } else if positive && negative {
            "cross"
        } else if positive {
            "up"
        } else {
            "down"
        }
    };
    Ok(Some(Paint::Pattern {
        preset: format!(
            "pdf:{kind}:{spacing:.4}:{:.4}:{:.4}:{:.4}",
            line_width.clamp(0.1, 8.0),
            pattern_origin.0,
            pattern_origin.1,
        ),
        foreground: with_alpha(foreground, state.fill_alpha),
        background: 0,
    }))
}

fn paint_tiling_pattern(
    name: &str,
    resources: Option<&PdfValue>,
    state: &GraphicsState,
    context: &mut PageContext<'_>,
    offset: usize,
    depth: usize,
    painted_path: PdfClip,
) -> Result<(), Diagnostic> {
    let Some((id, value)) = resource_entry(resources, "Pattern", name, context.store) else {
        context.warning(
            "pattern",
            "PDF_PATTERN_APPROXIMATE: unresolved tiling patterns are omitted instead of painted with an incorrect fallback color",
        );
        return Ok(());
    };
    let Some(dict) = context.store.dict(value) else {
        return Ok(());
    };
    let pattern_type = dict.get("PatternType").and_then(number_usize);
    let pattern_matrix = dict
        .get("Matrix")
        .and_then(|value| six_numbers_value(context.store, value))
        .map(matrix)
        .unwrap_or(Matrix::IDENTITY);
    if pattern_type == Some(2) {
        let Some(shading) = dict.get("Shading") else {
            return Ok(());
        };
        let mut pattern_state = state.clone();
        pattern_state.ctm = pattern_state.pattern_base_ctm.concat(pattern_matrix);
        pattern_state.fill_pattern = None;
        pattern_state.stroke_pattern = None;
        pattern_state.clips.push(painted_path);
        let shading_id = match shading {
            PdfValue::Ref(id) => Some(*id),
            _ => None,
        };
        return paint_shading_value(shading_id, shading, &pattern_state, context, offset);
    }
    let PdfValue::Stream { .. } = value else {
        context.warning(
            "pattern",
            "PDF_PATTERN_APPROXIMATE: unsupported non-stream pattern was omitted",
        );
        return Ok(());
    };
    if pattern_type != Some(1) {
        context.warning(
            "pattern",
            "PDF_PATTERN_APPROXIMATE: only colored tiling pattern streams are rendered",
        );
        return Ok(());
    }
    if !context.active_forms.insert(id) {
        return Err(pdf_error(offset, "cyclic PDF pattern reference"));
    }
    let pattern_resources = dict.get("Resources").or(resources);
    let decoded = decode_stream(value, context.store, context.limits)?;
    let base = state.pattern_base_ctm.concat(pattern_matrix);
    let Some([bbox_left, bbox_bottom, bbox_right, bbox_top]) = dict
        .get("BBox")
        .and_then(|value| context.store.resolve(value))
        .and_then(|value| match value {
            PdfValue::Array(values) => last_numbers::<4>(values),
            _ => None,
        })
    else {
        context.active_forms.remove(&id);
        return Ok(());
    };
    let x_step = dict
        .get("XStep")
        .and_then(number_f32)
        .unwrap_or_else(|| (bbox_right - bbox_left).abs());
    let y_step = dict
        .get("YStep")
        .and_then(number_f32)
        .unwrap_or_else(|| (bbox_top - bbox_bottom).abs());
    if x_step <= 0.0 || y_step <= 0.0 {
        context.warning(
            "pattern-step",
            "PDF_PATTERN_APPROXIMATE: a text tiling pattern with a non-positive step was omitted",
        );
        context.active_forms.remove(&id);
        return Ok(());
    }
    let clip_corners = [
        (painted_path.bounds.x, painted_path.bounds.y),
        (
            painted_path.bounds.x + painted_path.bounds.width,
            painted_path.bounds.y,
        ),
        (
            painted_path.bounds.x + painted_path.bounds.width,
            painted_path.bounds.y + painted_path.bounds.height,
        ),
        (
            painted_path.bounds.x,
            painted_path.bounds.y + painted_path.bounds.height,
        ),
    ];
    let pattern_corners = clip_corners
        .into_iter()
        .map(|(x, y)| base.inverse_point(x, y))
        .collect::<Option<Vec<_>>>();
    let Some(pattern_corners) = pattern_corners else {
        context.active_forms.remove(&id);
        return Ok(());
    };
    let min_x = pattern_corners
        .iter()
        .map(|point| point.0)
        .fold(f32::INFINITY, f32::min);
    let max_x = pattern_corners
        .iter()
        .map(|point| point.0)
        .fold(f32::NEG_INFINITY, f32::max);
    let min_y = pattern_corners
        .iter()
        .map(|point| point.1)
        .fold(f32::INFINITY, f32::min);
    let max_y = pattern_corners
        .iter()
        .map(|point| point.1)
        .fold(f32::NEG_INFINITY, f32::max);
    let x_epsilon = x_step * 0.0001;
    let y_epsilon = y_step * 0.0001;
    let first_x = ((min_x - bbox_right + x_epsilon) / x_step).floor() as i32 + 1;
    let last_x = ((max_x - bbox_left - x_epsilon) / x_step).ceil() as i32 - 1;
    let first_y = ((min_y - bbox_top + y_epsilon) / y_step).floor() as i32 + 1;
    let last_y = ((max_y - bbox_bottom - y_epsilon) / y_step).ceil() as i32 - 1;
    let columns = i64::from(last_x) - i64::from(first_x) + 1;
    let rows = i64::from(last_y) - i64::from(first_y) + 1;
    let tile_count = columns.max(0).checked_mul(rows.max(0));
    if tile_count.is_none_or(|count| count as usize > context.limits.max_document_objects) {
        context.active_forms.remove(&id);
        return Err(object_limit());
    }
    let mut result = Ok(());
    'tiles: for row in first_y..=last_y {
        for column in first_x..=last_x {
            let mut pattern_state = state.clone();
            pattern_state.ctm = base.concat(Matrix {
                e: column as f32 * x_step,
                f: row as f32 * y_step,
                ..Matrix::IDENTITY
            });
            pattern_state.fill_pattern = None;
            pattern_state.stroke_pattern = None;
            pattern_state.clips.push(painted_path.clone());
            result = interpret_content(
                &decoded,
                pattern_resources,
                context,
                pattern_state,
                id.0,
                depth + 1,
            );
            if result.is_err() {
                break 'tiles;
            }
        }
    }
    context.active_forms.remove(&id);
    result
}

fn paint_shading(
    name: &str,
    resources: Option<&PdfValue>,
    state: &GraphicsState,
    context: &mut PageContext<'_>,
    offset: usize,
) -> Result<(), Diagnostic> {
    let Some((id, value)) = resource_entry(resources, "Shading", name, context.store) else {
        context.warning(
            "shading",
            "PDF_SHADING_UNSUPPORTED: unresolved shading resources are omitted",
        );
        return Ok(());
    };
    paint_shading_value((id != (0, 0)).then_some(id), value, state, context, offset)
}

fn paint_shading_value(
    shading_id: Option<ObjectId>,
    value: &PdfValue,
    state: &GraphicsState,
    context: &mut PageContext<'_>,
    offset: usize,
) -> Result<(), Diagnostic> {
    let Some(value) = context.store.resolve(value) else {
        return Ok(());
    };
    let Some(dict) = context.store.dict(value) else {
        return Ok(());
    };
    let shading_type = dict.get("ShadingType").and_then(number_usize);
    if shading_type == Some(1) {
        return paint_function_shading(dict, state, context, offset);
    }
    if shading_type == Some(4) {
        return paint_free_form_mesh(value, dict, state, context, offset);
    }
    if shading_type == Some(5) {
        return paint_lattice_mesh(value, dict, state, context, offset);
    }
    if shading_type == Some(6) {
        return paint_coons_mesh(value, dict, state, context, offset);
    }
    if shading_type == Some(7) {
        return paint_tensor_mesh(value, dict, state, context, offset);
    }
    if !matches!(shading_type, Some(2 | 3)) {
        context.warning(
            "shading",
            "PDF_SHADING_UNSUPPORTED: only axial and radial shadings are currently rendered",
        );
        return Ok(());
    }
    let bbox = dict
        .get("BBox")
        .and_then(|value| context.store.resolve(value))
        .and_then(|value| match value {
            PdfValue::Array(values) => last_numbers::<4>(values),
            _ => None,
        });
    let Some(function) = dict.get("Function") else {
        return Ok(());
    };
    let Some(color_space) = dict.get("ColorSpace") else {
        return Ok(());
    };
    let cache_key = shading_id.map(|id| (id, state.fill_alpha.to_bits()));
    let stops = cache_key
        .and_then(|key| context.shading_stops.get(&key).cloned())
        .or_else(|| {
            shading_stops(
                function,
                color_space,
                context.store,
                context.limits,
                state.fill_alpha,
            )
        });
    let Some(stops) = stops else {
        context.warning(
            "shading",
            "PDF_SHADING_UNSUPPORTED: gradient shading uses an unsupported function",
        );
        return Ok(());
    };
    if let Some(key) = cache_key {
        context
            .shading_stops
            .entry(key)
            .or_insert_with(|| stops.clone());
    }
    let constant_color = stops
        .first()
        .map(|stop| stop.color)
        .filter(|color| stops.iter().all(|stop| stop.color == *color));
    let extend = dict
        .get("Extend")
        .and_then(|value| context.store.resolve(value))
        .and_then(|value| match value {
            PdfValue::Array(values) if values.len() >= 2 => Some([
                matches!(values[0], PdfValue::Bool(true)),
                matches!(values[1], PdfValue::Bool(true)),
            ]),
            _ => None,
        })
        .unwrap_or([false, false]);
    let bounds = if let Some([left, bottom, right, top]) = bbox {
        let corners = [
            state.ctm.point(left, bottom),
            state.ctm.point(right, bottom),
            state.ctm.point(right, top),
            state.ctm.point(left, top),
        ];
        let Some(bounds) = bounds(&corners) else {
            return Ok(());
        };
        bounds
    } else if let Some(clip) = state.clips.last() {
        clip.bounds
    } else {
        context.page_bounds
    };
    let coords = dict
        .get("Coords")
        .and_then(|value| context.store.resolve(value))
        .and_then(|value| match value {
            PdfValue::Array(values) => {
                Some(values.iter().filter_map(number_f32).collect::<Vec<_>>())
            }
            _ => None,
        })
        .unwrap_or_default();
    let extend = if shading_type == Some(2) && coords.len() == 4 {
        axial_effective_extensions(bounds, state.ctm, &coords, extend)
    } else {
        extend
    };
    let stops = shading_stops_with_extensions(stops, extend);
    let axis_x = state.ctm.a.hypot(state.ctm.b);
    let axis_y = state.ctm.c.hypot(state.ctm.d);
    let orthogonality = state.ctm.a * state.ctm.c + state.ctm.b * state.ctm.d;
    let non_conformal = (axis_x - axis_y).abs() > axis_x.max(axis_y).max(1.0) * 0.000_1
        || orthogonality.abs() > (axis_x * axis_y).max(1.0) * 0.000_1;
    if shading_type == Some(3) && coords.len() == 6 && non_conformal {
        let Some(bytes) = rasterize_radial_shading(
            bounds,
            state.ctm,
            &coords,
            &stops,
            &state.soft_masks,
            context.limits,
        ) else {
            return Ok(());
        };
        return context.push_object(
            ObjectKind::Image,
            bounds,
            None,
            apply_clips(
                Visual::Image {
                    media_type: "image/bmp".to_owned(),
                    bytes,
                    crop: ImageCrop::default(),
                },
                bounds,
                state,
            ),
            pdf_source("path", None, Some(offset), MappingQuality::Exact),
        );
    }
    let fill = match shading_type {
        Some(2) if coords.len() == 4 => {
            let start = state.ctm.point(coords[0], coords[1]);
            let end = state.ctm.point(coords[2], coords[3]);
            let stops = apply_linear_soft_masks(stops, start, end, &state.soft_masks);
            Paint::LinearGradient {
                x0: start.0 - bounds.x,
                y0: start.1 - bounds.y,
                x1: end.0 - bounds.x,
                y1: end.1 - bounds.y,
                stops,
            }
        }
        Some(3) if coords.len() == 6 => {
            let start = state.ctm.point(coords[0], coords[1]);
            let end = state.ctm.point(coords[3], coords[4]);
            let scale = state.ctm.scale();
            let start_radius = coords[2].abs() * scale;
            let end_radius = coords[5].abs() * scale;
            let stops = apply_radial_soft_masks(
                stops,
                start,
                start_radius,
                end,
                end_radius,
                &state.soft_masks,
            );
            Paint::RadialGradient {
                x0: start.0 - bounds.x,
                y0: start.1 - bounds.y,
                r0: start_radius,
                x1: end.0 - bounds.x,
                y1: end.1 - bounds.y,
                r1: end_radius,
                stops,
            }
        }
        _ => return Ok(()),
    };
    let visual = if let ([mask], Some(color)) = (state.soft_masks.as_slice(), constant_color)
        && let Some(visual) = solid_raster_soft_mask_visual(color, mask, bounds, None)
    {
        visual
    } else {
        Visual::PaintedShape {
            geometry: Geometry::Rectangle,
            fill,
            stroke: Paint::None,
            stroke_width: 0.0,
        }
    };
    context.push_object(
        ObjectKind::Shape,
        bounds,
        None,
        apply_clips(visual, bounds, state),
        pdf_source("path", None, Some(offset), MappingQuality::Exact),
    )
}

fn shading_stops_with_extensions(
    mut stops: Vec<GradientStop>,
    extend: [bool; 2],
) -> Vec<GradientStop> {
    const EDGE_EPSILON: f32 = 1e-6;
    if !extend[0]
        && let Some(first) = stops.first_mut()
    {
        first.offset = first.offset.max(EDGE_EPSILON);
        stops.insert(
            0,
            GradientStop {
                offset: 0.0,
                color: 0,
            },
        );
    }
    if !extend[1]
        && let Some(last) = stops.last_mut()
    {
        last.offset = last.offset.min(1.0 - EDGE_EPSILON);
        stops.push(GradientStop {
            offset: 1.0,
            color: 0,
        });
    }
    stops
}

fn axial_effective_extensions(
    bounds: Rect,
    transform: Matrix,
    coords: &[f32],
    mut extend: [bool; 2],
) -> [bool; 2] {
    let start = transform.point(coords[0], coords[1]);
    let end = transform.point(coords[2], coords[3]);
    let axis = (end.0 - start.0, end.1 - start.1);
    let length_squared = axis.0 * axis.0 + axis.1 * axis.1;
    if length_squared <= f32::EPSILON {
        return extend;
    }
    let parameters = [
        (bounds.x, bounds.y),
        (bounds.x + bounds.width, bounds.y),
        (bounds.x + bounds.width, bounds.y + bounds.height),
        (bounds.x, bounds.y + bounds.height),
    ]
    .map(|point| ((point.0 - start.0) * axis.0 + (point.1 - start.1) * axis.1) / length_squared);
    let minimum = parameters.iter().copied().fold(f32::INFINITY, f32::min);
    let maximum = parameters.iter().copied().fold(f32::NEG_INFINITY, f32::max);
    const DOMAIN_EPSILON: f32 = 1e-5;
    extend[0] |= minimum >= -DOMAIN_EPSILON;
    extend[1] |= maximum <= 1.0 + DOMAIN_EPSILON;
    extend
}

fn radial_parameter(point: (f32, f32), coords: &[f32]) -> Option<f32> {
    let axis = (coords[3] - coords[0], coords[4] - coords[1]);
    let radius_delta = coords[5].abs() - coords[2].abs();
    let point = (point.0 - coords[0], point.1 - coords[1]);
    let quadratic = axis.0 * axis.0 + axis.1 * axis.1 - radius_delta * radius_delta;
    let linear = -2.0 * (point.0 * axis.0 + point.1 * axis.1 + coords[2].abs() * radius_delta);
    let constant = point.0 * point.0 + point.1 * point.1 - coords[2].abs().powi(2);
    if quadratic.abs() <= f32::EPSILON {
        return (linear.abs() > f32::EPSILON).then_some(-constant / linear);
    }
    let discriminant = linear * linear - 4.0 * quadratic * constant;
    if discriminant < 0.0 {
        return None;
    }
    let root = discriminant.sqrt();
    let first = (-linear - root) / (2.0 * quadratic);
    let second = (-linear + root) / (2.0 * quadratic);
    [first, second]
        .into_iter()
        .filter(|value| *value >= 0.0)
        .min_by(|left, right| left.total_cmp(right))
}

fn rasterize_radial_shading(
    bounds: Rect,
    transform: Matrix,
    coords: &[f32],
    stops: &[GradientStop],
    masks: &[PdfSoftMask],
    limits: Limits,
) -> Option<Vec<u8>> {
    let (width, height) = shading_raster_dimensions(bounds, limits)?;
    let pixels = width.checked_mul(height)?;
    let mut colors = Vec::new();
    let mut alpha = Vec::new();
    colors.try_reserve_exact(pixels.checked_mul(3)?).ok()?;
    alpha.try_reserve_exact(pixels).ok()?;
    for row in 0..height {
        let page_y = bounds.y + bounds.height * (row as f32 + 0.5) / height as f32;
        for column in 0..width {
            let page_x = bounds.x + bounds.width * (column as f32 + 0.5) / width as f32;
            let color = transform
                .inverse_point(page_x, page_y)
                .and_then(|point| radial_parameter(point, coords))
                .map(|offset| gradient_color_at(stops, offset))
                .unwrap_or(0);
            let mut channels = color.to_be_bytes();
            let mask_alpha = masks
                .iter()
                .map(|mask| linear_soft_mask_alpha(mask, (page_x, page_y)))
                .product::<f32>();
            channels[3] = channel(f32::from(channels[3]) / 255.0 * mask_alpha);
            colors.extend_from_slice(&channels[..3]);
            alpha.push(channels[3]);
        }
    }
    rgba_bmp(width, height, &colors, &alpha, RasterColorSpace::Rgb)
}

fn paint_function_shading(
    dict: &PdfDict,
    state: &GraphicsState,
    context: &mut PageContext<'_>,
    offset: usize,
) -> Result<(), Diagnostic> {
    let function = dict.get("Function").ok_or_else(object_limit)?;
    let color_space = dict.get("ColorSpace").ok_or_else(object_limit)?;
    let domain: Vec<_> = match dict
        .get("Domain")
        .and_then(|value| context.store.resolve(value))
    {
        Some(PdfValue::Array(values)) => values.iter().filter_map(number_f32).collect(),
        _ => vec![0.0, 1.0, 0.0, 1.0],
    };
    if domain.len() != 4 || domain[1] <= domain[0] || domain[3] <= domain[2] {
        return Ok(());
    }
    let shading_matrix = dict
        .get("Matrix")
        .and_then(|value| six_numbers_value(context.store, value))
        .map(matrix)
        .unwrap_or(Matrix::IDENTITY);
    let transform = state.ctm.concat(shading_matrix);
    let corners = [
        transform.point(domain[0], domain[2]),
        transform.point(domain[1], domain[2]),
        transform.point(domain[1], domain[3]),
        transform.point(domain[0], domain[3]),
    ];
    let Some(bounds) = bounds(&corners) else {
        return Ok(());
    };
    let Some((width, height)) = shading_raster_dimensions(bounds, context.limits) else {
        return Err(object_limit());
    };
    let mut samples = Vec::new();
    samples
        .try_reserve_exact(width.saturating_mul(height).saturating_mul(3))
        .map_err(|_| object_limit())?;
    for row in 0..height {
        let page_y = bounds.y + bounds.height * (row as f32 + 0.5) / height as f32;
        for column in 0..width {
            let page_x = bounds.x + bounds.width * (column as f32 + 0.5) / width as f32;
            let Some((x, y)) = transform.inverse_point(page_x, page_y) else {
                return Ok(());
            };
            let input = [x.clamp(domain[0], domain[1]), y.clamp(domain[2], domain[3])];
            let Some(components) =
                evaluate_shading_function_inputs(function, &input, context.store, context.limits)
            else {
                context.warning(
                    "shading",
                    "PDF_SHADING_UNSUPPORTED: a function-based shading could not be evaluated",
                );
                return Ok(());
            };
            let Some(color) = color_from_space_value(color_space, &components, context.store, 0)
            else {
                return Ok(());
            };
            samples.extend_from_slice(&color.to_be_bytes()[..3]);
        }
    }
    let Some(bytes) = pdf_raster_asset(width, height, 3, &samples, context.limits) else {
        return Err(object_limit());
    };
    let mut visual = Visual::Image {
        media_type: "image/x-officeviewer-pdf-raster".to_owned(),
        bytes,
        crop: ImageCrop::default(),
    };
    visual = Visual::Effect {
        shadow: None,
        clip: Some(Geometry::Path {
            fill_rule: FillRule::NonZero,
            commands: vec![
                PathCommand::MoveTo {
                    x: corners[0].0 - bounds.x,
                    y: corners[0].1 - bounds.y,
                },
                PathCommand::LineTo {
                    x: corners[1].0 - bounds.x,
                    y: corners[1].1 - bounds.y,
                },
                PathCommand::LineTo {
                    x: corners[2].0 - bounds.x,
                    y: corners[2].1 - bounds.y,
                },
                PathCommand::LineTo {
                    x: corners[3].0 - bounds.x,
                    y: corners[3].1 - bounds.y,
                },
                PathCommand::ClosePath,
            ],
        }),
        visual: Box::new(visual),
    };
    context.push_object(
        ObjectKind::Image,
        bounds,
        None,
        apply_clips(visual, bounds, state),
        pdf_source("path", None, Some(offset), MappingQuality::Exact),
    )
}

fn shading_raster_dimensions(bounds: Rect, limits: Limits) -> Option<(usize, usize)> {
    let mut width = (bounds.width * 0.75).ceil().max(1.0) as usize;
    let mut height = (bounds.height * 0.75).ceil().max(1.0) as usize;
    let pixel_limit = limits
        .max_render_pixels
        .min(limits.max_entry_uncompressed_bytes / 3);
    let pixels = width.checked_mul(height)?;
    if pixels > pixel_limit {
        let scale = (pixel_limit as f64 / pixels as f64).sqrt();
        width = ((width as f64 * scale).floor() as usize).max(1);
        height = ((height as f64 * scale).floor() as usize).max(1);
    }
    (width.checked_mul(height)? <= pixel_limit).then_some((width, height))
}

fn evaluate_shading_function_inputs(
    value: &PdfValue,
    input: &[f32],
    store: &ObjectStore,
    limits: Limits,
) -> Option<Vec<f32>> {
    match store
        .dict(value)?
        .get("FunctionType")
        .and_then(number_usize)?
    {
        0 => evaluate_sampled_function_inputs(value, input, store, limits),
        2 => evaluate_type2_function(value, input, store),
        3 if input.len() == 1 => {
            evaluate_stitched_shading_function(value, input[0], store, limits, 0)
        }
        4 => evaluate_type4_function(value, input, store),
        _ => None,
    }
}

fn apply_linear_soft_masks(
    stops: Vec<GradientStop>,
    start: (f32, f32),
    end: (f32, f32),
    masks: &[PdfSoftMask],
) -> Vec<GradientStop> {
    if masks.is_empty() {
        return stops;
    }
    (0..=64)
        .map(|index| {
            let offset = index as f32 / 64.0;
            let point = (
                start.0 + (end.0 - start.0) * offset,
                start.1 + (end.1 - start.1) * offset,
            );
            let color = gradient_color_at(&stops, offset);
            let mut channels = color.to_be_bytes();
            let mask_alpha = masks
                .iter()
                .map(|mask| linear_soft_mask_alpha(mask, point))
                .product::<f32>();
            channels[3] = channel(f32::from(channels[3]) / 255.0 * mask_alpha);
            GradientStop {
                offset,
                color: u32::from_be_bytes(channels),
            }
        })
        .collect()
}

fn apply_radial_soft_masks(
    stops: Vec<GradientStop>,
    start: (f32, f32),
    start_radius: f32,
    end: (f32, f32),
    end_radius: f32,
    masks: &[PdfSoftMask],
) -> Vec<GradientStop> {
    if masks.is_empty() {
        return stops;
    }
    (0..=64)
        .map(|index| {
            let offset = index as f32 / 64.0;
            let center = (
                start.0 + (end.0 - start.0) * offset,
                start.1 + (end.1 - start.1) * offset,
            );
            let radius = start_radius + (end_radius - start_radius) * offset;
            let point = (center.0 + radius, center.1);
            let mut channels = gradient_color_at(&stops, offset).to_be_bytes();
            let mask_alpha = masks
                .iter()
                .map(|mask| linear_soft_mask_alpha(mask, point))
                .product::<f32>();
            channels[3] = channel(f32::from(channels[3]) / 255.0 * mask_alpha);
            GradientStop {
                offset,
                color: u32::from_be_bytes(channels),
            }
        })
        .collect()
}

fn apply_linear_soft_masks_to_paint(paint: Paint, bounds: Rect, masks: &[PdfSoftMask]) -> Paint {
    match (paint, masks.first()) {
        (Paint::Solid(color), Some(_)) => Paint::LinearGradient {
            x0: 0.0,
            y0: bounds.height * 0.5,
            x1: bounds.width,
            y1: bounds.height * 0.5,
            stops: apply_linear_soft_masks(
                vec![
                    GradientStop { offset: 0.0, color },
                    GradientStop { offset: 1.0, color },
                ],
                (bounds.x, bounds.y + bounds.height * 0.5),
                (bounds.x + bounds.width, bounds.y + bounds.height * 0.5),
                masks,
            ),
        },
        (paint, _) => paint,
    }
}

fn gradient_color_at(stops: &[GradientStop], offset: f32) -> u32 {
    let Some(first) = stops.first() else {
        return 0;
    };
    let Some(last) = stops.last() else {
        return first.color;
    };
    let (left, right) = stops
        .windows(2)
        .find_map(|pair| (offset <= pair[1].offset).then_some((&pair[0], &pair[1])))
        .unwrap_or((last, last));
    let width = right.offset - left.offset;
    let amount = if width.abs() <= f32::EPSILON {
        0.0
    } else {
        ((offset - left.offset) / width).clamp(0.0, 1.0)
    };
    let left = left.color.to_be_bytes();
    let right = right.color.to_be_bytes();
    u32::from_be_bytes(std::array::from_fn(|index| {
        (f32::from(left[index]) + (f32::from(right[index]) - f32::from(left[index])) * amount)
            .round() as u8
    }))
}

fn linear_soft_mask_alpha(mask: &PdfSoftMask, point: (f32, f32)) -> f32 {
    if let Some(bounds) = mask.bounds
        && (point.0 < bounds.x
            || point.0 > bounds.x + bounds.width
            || point.1 < bounds.y
            || point.1 > bounds.y + bounds.height)
    {
        return mask.outside;
    }
    let axis = (mask.end.0 - mask.start.0, mask.end.1 - mask.start.1);
    let offset = if let Some((start_radius, end_radius)) = mask.radii {
        let radius_delta = end_radius - start_radius;
        let point = (point.0 - mask.start.0, point.1 - mask.start.1);
        let quadratic = axis.0 * axis.0 + axis.1 * axis.1 - radius_delta * radius_delta;
        let linear = -2.0 * (point.0 * axis.0 + point.1 * axis.1 + start_radius * radius_delta);
        let constant = point.0 * point.0 + point.1 * point.1 - start_radius * start_radius;
        if quadratic.abs() <= f32::EPSILON {
            if linear.abs() <= f32::EPSILON {
                0.0
            } else {
                -constant / linear
            }
        } else {
            let discriminant = linear * linear - 4.0 * quadratic * constant;
            if discriminant < 0.0 {
                0.0
            } else {
                let root = discriminant.sqrt();
                let first = (-linear - root) / (2.0 * quadratic);
                let second = (-linear + root) / (2.0 * quadratic);
                [first, second]
                    .into_iter()
                    .filter(|value| *value >= 0.0)
                    .min_by(|left, right| left.total_cmp(right))
                    .unwrap_or(0.0)
            }
        }
        .clamp(0.0, 1.0)
    } else {
        let length_squared = axis.0 * axis.0 + axis.1 * axis.1;
        if length_squared <= f32::EPSILON {
            return mask.stops.first().map(|stop| stop.1).unwrap_or(1.0);
        }
        (((point.0 - mask.start.0) * axis.0 + (point.1 - mask.start.1) * axis.1) / length_squared)
            .clamp(0.0, 1.0)
    };
    let Some(first) = mask.stops.first() else {
        return 1.0;
    };
    let Some(last) = mask.stops.last() else {
        return first.1;
    };
    let (left, right) = mask
        .stops
        .windows(2)
        .find_map(|pair| (offset <= pair[1].0).then_some((pair[0], pair[1])))
        .unwrap_or((*last, *last));
    let width = right.0 - left.0;
    if width.abs() <= f32::EPSILON {
        left.1
    } else {
        left.1 + (right.1 - left.1) * ((offset - left.0) / width).clamp(0.0, 1.0)
    }
}

fn read_packed_bits(bytes: &[u8], bit_offset: &mut usize, width: usize) -> Option<u32> {
    if width == 0 || width > 32 || bit_offset.checked_add(width)? > bytes.len().checked_mul(8)? {
        return None;
    }
    let mut value = 0_u32;
    for _ in 0..width {
        value = (value << 1) | u32::from((bytes[*bit_offset / 8] >> (7 - *bit_offset % 8)) & 1);
        *bit_offset += 1;
    }
    Some(value)
}

fn mesh_function_components(
    function: &PdfValue,
    input: f32,
    store: &ObjectStore,
) -> Option<Vec<f32>> {
    evaluate_color_function(function, &[input], store)
}

fn push_mesh_triangle(
    triangle: [(f32, f32, u32); 3],
    state: &GraphicsState,
    context: &mut PageContext<'_>,
    offset: usize,
    parent_numeric_id: Option<u32>,
) -> Result<(), Diagnostic> {
    let points = triangle.map(|(x, y, _)| (x, y));
    let Some(bounds) = bounds(&points) else {
        return Ok(());
    };
    let commands = vec![
        PathCommand::MoveTo {
            x: points[0].0 - bounds.x,
            y: points[0].1 - bounds.y,
        },
        PathCommand::LineTo {
            x: points[1].0 - bounds.x,
            y: points[1].1 - bounds.y,
        },
        PathCommand::LineTo {
            x: points[2].0 - bounds.x,
            y: points[2].1 - bounds.y,
        },
        PathCommand::ClosePath,
    ];
    let channels = triangle.map(|(_, _, color)| color.to_be_bytes());
    let fill = Paint::Solid(with_alpha(
        rgba(
            ((u16::from(channels[0][0]) + u16::from(channels[1][0]) + u16::from(channels[2][0]))
                / 3) as u8,
            ((u16::from(channels[0][1]) + u16::from(channels[1][1]) + u16::from(channels[2][1]))
                / 3) as u8,
            ((u16::from(channels[0][2]) + u16::from(channels[1][2]) + u16::from(channels[2][2]))
                / 3) as u8,
        ),
        state.fill_alpha,
    ));
    let visual = Visual::PaintedShape {
        geometry: Geometry::Path {
            fill_rule: FillRule::NonZero,
            commands,
        },
        fill,
        stroke: Paint::None,
        stroke_width: 0.0,
    };
    context
        .push_object_with_parent(
            ObjectKind::Shape,
            bounds,
            None,
            if parent_numeric_id.is_some() {
                visual
            } else {
                apply_clips(visual, bounds, state)
            },
            pdf_source("path", None, Some(offset), MappingQuality::Exact),
            parent_numeric_id,
        )
        .map(|_| ())
}

fn mesh_clip_group(
    state: &GraphicsState,
    context: &mut PageContext<'_>,
    offset: usize,
) -> Result<Option<u32>, Diagnostic> {
    let Some(bounds) = state.clips.first().map(|clip| clip.bounds) else {
        return Ok(None);
    };
    let parent_numeric_id = context.parent_numeric_id;
    context
        .push_object_with_parent(
            ObjectKind::Group,
            bounds,
            None,
            apply_clips(Visual::None, bounds, state),
            pdf_source("path", None, Some(offset), MappingQuality::Exact),
            parent_numeric_id,
        )
        .map(Some)
}

fn paint_free_form_mesh(
    value: &PdfValue,
    dict: &BTreeMap<String, PdfValue>,
    state: &GraphicsState,
    context: &mut PageContext<'_>,
    offset: usize,
) -> Result<(), Diagnostic> {
    if !matches!(value, PdfValue::Stream { .. }) {
        context.warning(
            "shading",
            "PDF_SHADING_UNSUPPORTED: a Type 4 mesh without a data stream was omitted",
        );
        return Ok(());
    }
    let coordinate_bits = dict
        .get("BitsPerCoordinate")
        .and_then(number_usize)
        .filter(|bits| matches!(bits, 1 | 2 | 4 | 8 | 12 | 16 | 24 | 32))
        .ok_or_else(object_limit)?;
    let component_bits = dict
        .get("BitsPerComponent")
        .and_then(number_usize)
        .filter(|bits| matches!(bits, 1 | 2 | 4 | 8 | 12 | 16))
        .ok_or_else(object_limit)?;
    let flag_bits = dict
        .get("BitsPerFlag")
        .and_then(number_usize)
        .filter(|bits| matches!(bits, 2 | 4 | 8))
        .ok_or_else(object_limit)?;
    let decode: Vec<_> = match dict
        .get("Decode")
        .and_then(|value| context.store.resolve(value))
    {
        Some(PdfValue::Array(values)) => values.iter().filter_map(number_f32).collect(),
        _ => return Ok(()),
    };
    let function = dict.get("Function");
    let component_count = if function.is_some() {
        1
    } else {
        decode.len().saturating_sub(4) / 2
    };
    if decode.len() != 4 + component_count * 2 || component_count == 0 || component_count > 4 {
        return Ok(());
    }
    let color_space = dict.get("ColorSpace").ok_or_else(object_limit)?;
    let Ok(bytes) = decode_stream(value, context.store, context.limits) else {
        context.warning(
            "shading",
            "PDF_SHADING_UNSUPPORTED: an invalid Type 4 mesh stream was omitted",
        );
        return Ok(());
    };
    let mut bit_offset = 0;
    let coordinate_max = ((1_u64 << coordinate_bits) - 1) as f32;
    let component_max = ((1_u64 << component_bits) - 1) as f32;
    let decode_value =
        |raw: u32, low: f32, high: f32, maximum: f32| low + raw as f32 / maximum * (high - low);
    let mut vertices = Vec::new();
    let bits_per_vertex = flag_bits + coordinate_bits * 2 + component_bits * component_count;
    while bit_offset + bits_per_vertex <= bytes.len() * 8 && vertices.len() < 65_536 {
        let flag = read_packed_bits(&bytes, &mut bit_offset, flag_bits).unwrap_or(0);
        let x = decode_value(
            read_packed_bits(&bytes, &mut bit_offset, coordinate_bits).unwrap_or(0),
            decode[0],
            decode[1],
            coordinate_max,
        );
        let y = decode_value(
            read_packed_bits(&bytes, &mut bit_offset, coordinate_bits).unwrap_or(0),
            decode[2],
            decode[3],
            coordinate_max,
        );
        let mut components = Vec::with_capacity(component_count);
        for index in 0..component_count {
            components.push(decode_value(
                read_packed_bits(&bytes, &mut bit_offset, component_bits).unwrap_or(0),
                decode[4 + index * 2],
                decode[5 + index * 2],
                component_max,
            ));
        }
        let components = match function {
            Some(function) => mesh_function_components(function, components[0], context.store),
            None => Some(components),
        };
        let Some(color) = components.and_then(|components| {
            color_from_space_value(color_space, &components, context.store, 0)
        }) else {
            return Ok(());
        };
        vertices.push((flag, state.ctm.point(x, y), color));
    }
    let mut index = 0;
    let mut previous: Option<[(f32, f32, u32); 3]> = None;
    let mut triangles = Vec::new();
    while index < vertices.len() {
        let (flag, point, color) = vertices[index];
        let triangle = if let Some(previous) = previous.filter(|_| flag != 0) {
            index += 1;
            if flag == 1 {
                [previous[1], previous[2], (point.0, point.1, color)]
            } else {
                [previous[0], previous[2], (point.0, point.1, color)]
            }
        } else {
            let Some(second) = vertices.get(index + 1) else {
                break;
            };
            let Some(third) = vertices.get(index + 2) else {
                break;
            };
            index += 3;
            [
                (point.0, point.1, color),
                (second.1.0, second.1.1, second.2),
                (third.1.0, third.1.1, third.2),
            ]
        };
        previous = Some(triangle);
        triangles.push(triangle);
    }
    if let Some((bounds, bytes)) = rasterize_mesh_triangles(&triangles, state, context.limits) {
        return context.push_object(
            ObjectKind::Image,
            bounds,
            None,
            apply_clips(
                Visual::Image {
                    media_type: "image/bmp".to_owned(),
                    bytes,
                    crop: ImageCrop::default(),
                },
                bounds,
                state,
            ),
            pdf_source("path", None, Some(offset), MappingQuality::Exact),
        );
    }
    let parent_numeric_id = mesh_clip_group(state, context, offset)?;
    for triangle in triangles {
        push_mesh_triangle(triangle, state, context, offset, parent_numeric_id)?;
    }
    Ok(())
}

fn paint_lattice_mesh(
    value: &PdfValue,
    dict: &BTreeMap<String, PdfValue>,
    state: &GraphicsState,
    context: &mut PageContext<'_>,
    offset: usize,
) -> Result<(), Diagnostic> {
    if !matches!(value, PdfValue::Stream { .. }) {
        return Ok(());
    }
    let vertices_per_row = dict
        .get("VerticesPerRow")
        .and_then(number_usize)
        .filter(|count| *count >= 2)
        .ok_or_else(object_limit)?;
    let coordinate_bits = dict
        .get("BitsPerCoordinate")
        .and_then(number_usize)
        .filter(|bits| matches!(bits, 1 | 2 | 4 | 8 | 12 | 16 | 24 | 32))
        .ok_or_else(object_limit)?;
    let component_bits = dict
        .get("BitsPerComponent")
        .and_then(number_usize)
        .filter(|bits| matches!(bits, 1 | 2 | 4 | 8 | 12 | 16))
        .ok_or_else(object_limit)?;
    let decode = match dict
        .get("Decode")
        .and_then(|value| context.store.resolve(value))
    {
        Some(PdfValue::Array(values)) => values.iter().filter_map(number_f32).collect::<Vec<_>>(),
        _ => return Ok(()),
    };
    let function = dict.get("Function");
    let component_count = if function.is_some() {
        1
    } else {
        decode.len().saturating_sub(4) / 2
    };
    if decode.len() != 4 + component_count * 2 || component_count == 0 || component_count > 4 {
        return Ok(());
    }
    let color_space = dict.get("ColorSpace").ok_or_else(object_limit)?;
    let Ok(bytes) = decode_stream(value, context.store, context.limits) else {
        context.warning(
            "shading",
            "PDF_SHADING_UNSUPPORTED: an invalid Type 5 mesh stream was omitted",
        );
        return Ok(());
    };
    let coordinate_max = ((1_u64 << coordinate_bits) - 1) as f32;
    let component_max = ((1_u64 << component_bits) - 1) as f32;
    let bits_per_vertex = coordinate_bits * 2 + component_bits * component_count;
    let mut bit_offset = 0;
    let mut vertices = Vec::new();
    while bit_offset + bits_per_vertex <= bytes.len() * 8 && vertices.len() < 65_536 {
        let x = mesh_decode_value(
            read_packed_bits(&bytes, &mut bit_offset, coordinate_bits).unwrap_or(0),
            decode[0],
            decode[1],
            coordinate_max,
        );
        let y = mesh_decode_value(
            read_packed_bits(&bytes, &mut bit_offset, coordinate_bits).unwrap_or(0),
            decode[2],
            decode[3],
            coordinate_max,
        );
        let mut components = Vec::with_capacity(component_count);
        for index in 0..component_count {
            components.push(mesh_decode_value(
                read_packed_bits(&bytes, &mut bit_offset, component_bits).unwrap_or(0),
                decode[4 + index * 2],
                decode[5 + index * 2],
                component_max,
            ));
        }
        let components = match function {
            Some(function) => mesh_function_components(function, components[0], context.store),
            None => Some(components),
        };
        let Some(color) = components.and_then(|components| {
            color_from_space_value(color_space, &components, context.store, 0)
        }) else {
            return Ok(());
        };
        let point = state.ctm.point(x, y);
        vertices.push((point.0, point.1, color));
    }
    let row_count = vertices.len() / vertices_per_row;
    let mut triangles = Vec::new();
    for row in 0..row_count.saturating_sub(1) {
        for column in 0..vertices_per_row - 1 {
            let top_left = row * vertices_per_row + column;
            let bottom_left = top_left + vertices_per_row;
            triangles.push([
                vertices[top_left],
                vertices[top_left + 1],
                vertices[bottom_left],
            ]);
            triangles.push([
                vertices[top_left + 1],
                vertices[bottom_left + 1],
                vertices[bottom_left],
            ]);
        }
    }
    if let Some((bounds, bytes)) = rasterize_mesh_triangles(&triangles, state, context.limits) {
        return context.push_object(
            ObjectKind::Image,
            bounds,
            None,
            apply_clips(
                Visual::Image {
                    media_type: "image/bmp".to_owned(),
                    bytes,
                    crop: ImageCrop::default(),
                },
                bounds,
                state,
            ),
            pdf_source("path", None, Some(offset), MappingQuality::Exact),
        );
    }
    let parent_numeric_id = mesh_clip_group(state, context, offset)?;
    for triangle in triangles {
        push_mesh_triangle(triangle, state, context, offset, parent_numeric_id)?;
    }
    Ok(())
}

fn rasterize_mesh_triangles(
    triangles: &[[(f32, f32, u32); 3]],
    state: &GraphicsState,
    limits: Limits,
) -> Option<(Rect, Vec<u8>)> {
    if triangles.is_empty() || triangles.len() > 65_536 {
        return None;
    }
    let points = triangles
        .iter()
        .flat_map(|triangle| triangle.iter().map(|(x, y, _)| (*x, *y)))
        .collect::<Vec<_>>();
    let mut bounds = bounds(&points)?;
    if let Some(clip) = state.clips.last() {
        let left = bounds.x.max(clip.bounds.x);
        let top = bounds.y.max(clip.bounds.y);
        let right = (bounds.x + bounds.width).min(clip.bounds.x + clip.bounds.width);
        let bottom = (bounds.y + bounds.height).min(clip.bounds.y + clip.bounds.height);
        if right <= left || bottom <= top {
            return None;
        }
        bounds = Rect {
            x: left,
            y: top,
            width: right - left,
            height: bottom - top,
        };
    }
    let (width, height) = shading_raster_dimensions(bounds, limits)?;
    let pixels = width.checked_mul(height)?;
    let mut colors = vec![0_u8; pixels.checked_mul(3)?];
    let mut alpha = vec![0_u8; pixels];
    let mut painted = vec![false; pixels];
    let mut work = 0_usize;
    for triangle in triangles {
        let [(x0, y0, c0), (x1, y1, c1), (x2, y2, c2)] = *triangle;
        let denominator = (y1 - y2) * (x0 - x2) + (x2 - x1) * (y0 - y2);
        if denominator.abs() <= f32::EPSILON {
            continue;
        }
        let column_at = |x: f32| (x - bounds.x) / bounds.width * width as f32 - 0.5;
        let row_at = |y: f32| (y - bounds.y) / bounds.height * height as f32 - 0.5;
        let first_column = column_at(x0.min(x1).min(x2)).ceil().max(0.0) as usize;
        let last_column =
            (column_at(x0.max(x1).max(x2)).floor() + 1.0).clamp(0.0, width as f32) as usize;
        let first_row = row_at(y0.min(y1).min(y2)).ceil().max(0.0) as usize;
        let last_row =
            (row_at(y0.max(y1).max(y2)).floor() + 1.0).clamp(0.0, height as f32) as usize;
        work = work.checked_add(
            last_column
                .saturating_sub(first_column)
                .checked_mul(last_row.saturating_sub(first_row))?,
        )?;
        if work > 50_000_000 {
            return None;
        }
        let channels = [c0.to_be_bytes(), c1.to_be_bytes(), c2.to_be_bytes()];
        for row in first_row..last_row {
            let y = bounds.y + bounds.height * (row as f32 + 0.5) / height as f32;
            for column in first_column..last_column {
                let pixel = row * width + column;
                if painted[pixel] {
                    continue;
                }
                let x = bounds.x + bounds.width * (column as f32 + 0.5) / width as f32;
                let w0 = ((y1 - y2) * (x - x2) + (x2 - x1) * (y - y2)) / denominator;
                let w1 = ((y2 - y0) * (x - x2) + (x0 - x2) * (y - y2)) / denominator;
                let w2 = 1.0 - w0 - w1;
                if w0 < -0.000_1 || w1 < -0.000_1 || w2 < -0.000_1 {
                    continue;
                }
                let output: [u8; 4] = std::array::from_fn(|index| {
                    (f32::from(channels[0][index]) * w0
                        + f32::from(channels[1][index]) * w1
                        + f32::from(channels[2][index]) * w2)
                        .round()
                        .clamp(0.0, 255.0) as u8
                });
                colors[pixel * 3..pixel * 3 + 3].copy_from_slice(&output[..3]);
                alpha[pixel] = channel(f32::from(output[3]) / 255.0 * state.fill_alpha);
                painted[pixel] = true;
            }
        }
    }
    Some((
        bounds,
        rgba_bmp(width, height, &colors, &alpha, RasterColorSpace::Rgb)?,
    ))
}

fn mesh_decode_value(raw: u32, low: f32, high: f32, maximum: f32) -> f32 {
    low + raw as f32 / maximum * (high - low)
}

fn coons_interior_point(points: &[(f32, f32); 16], terms: [(usize, f32); 8]) -> (f32, f32) {
    terms.into_iter().fold((0.0, 0.0), |sum, (index, weight)| {
        (
            sum.0 + points[index].0 * weight / 9.0,
            sum.1 + points[index].1 * weight / 9.0,
        )
    })
}

fn cubic_basis(offset: f32) -> [f32; 4] {
    let inverse = 1.0 - offset;
    [
        inverse * inverse * inverse,
        3.0 * offset * inverse * inverse,
        3.0 * offset * offset * inverse,
        offset * offset * offset,
    ]
}

fn bilinear_mesh_color(colors: &[u32; 4], x: f32, y: f32) -> u32 {
    let channels = colors.map(u32::to_be_bytes);
    let weights = [(1.0 - x) * (1.0 - y), x * (1.0 - y), (1.0 - x) * y, x * y];
    u32::from_be_bytes(std::array::from_fn(|channel_index| {
        channels
            .iter()
            .zip(weights)
            .map(|(color, weight)| f32::from(color[channel_index]) * weight)
            .sum::<f32>()
            .round()
            .clamp(0.0, 255.0) as u8
    }))
}

fn tessellate_coons_patch(
    points: [(f32, f32); 16],
    colors: [u32; 4],
    triangles: &mut Vec<[(f32, f32, u32); 3]>,
) -> Result<(), Diagnostic> {
    const MAX_SPLITS: usize = 20;
    const TARGET_EDGE_LENGTH: f32 = 4.0;
    let extent = bounds(&points)
        .map(|bounds| bounds.width.max(bounds.height))
        .unwrap_or(0.0);
    let splits = ((extent / TARGET_EDGE_LENGTH).ceil() as usize).clamp(1, MAX_SPLITS);
    let mut vertices = Vec::new();
    vertices
        .try_reserve_exact((splits + 1) * (splits + 1))
        .map_err(|_| object_limit())?;
    for row in 0..=splits {
        let y = row as f32 / splits as f32;
        let row_basis = cubic_basis(y);
        for column in 0..=splits {
            let x = column as f32 / splits as f32;
            let column_basis = cubic_basis(x);
            let mut point = (0.0, 0.0);
            for (row_index, row_weight) in row_basis.into_iter().enumerate() {
                for (column_index, column_weight) in column_basis.into_iter().enumerate() {
                    let weight = row_weight * column_weight;
                    let control = points[row_index * 4 + column_index];
                    point.0 += control.0 * weight;
                    point.1 += control.1 * weight;
                }
            }
            vertices.push((point.0, point.1, bilinear_mesh_color(&colors, x, y)));
        }
    }
    for row in 0..splits {
        for column in 0..splits {
            let top_left = vertices[row * (splits + 1) + column];
            let top_right = vertices[row * (splits + 1) + column + 1];
            let bottom_left = vertices[(row + 1) * (splits + 1) + column];
            let bottom_right = vertices[(row + 1) * (splits + 1) + column + 1];
            triangles.push([top_left, top_right, bottom_right]);
            triangles.push([top_left, bottom_right, bottom_left]);
        }
    }
    Ok(())
}

fn paint_coons_mesh(
    value: &PdfValue,
    dict: &BTreeMap<String, PdfValue>,
    state: &GraphicsState,
    context: &mut PageContext<'_>,
    offset: usize,
) -> Result<(), Diagnostic> {
    if !matches!(value, PdfValue::Stream { .. }) {
        return Ok(());
    }
    let coordinate_bits = dict
        .get("BitsPerCoordinate")
        .and_then(number_usize)
        .filter(|bits| matches!(bits, 1 | 2 | 4 | 8 | 12 | 16 | 24 | 32))
        .ok_or_else(object_limit)?;
    let component_bits = dict
        .get("BitsPerComponent")
        .and_then(number_usize)
        .filter(|bits| matches!(bits, 1 | 2 | 4 | 8 | 12 | 16))
        .ok_or_else(object_limit)?;
    let flag_bits = dict
        .get("BitsPerFlag")
        .and_then(number_usize)
        .filter(|bits| matches!(bits, 2 | 4 | 8))
        .ok_or_else(object_limit)?;
    let decode: Vec<_> = match dict
        .get("Decode")
        .and_then(|value| context.store.resolve(value))
    {
        Some(PdfValue::Array(values)) => values.iter().filter_map(number_f32).collect(),
        _ => return Ok(()),
    };
    let function = dict.get("Function");
    let component_count = if function.is_some() {
        1
    } else {
        decode.len().saturating_sub(4) / 2
    };
    if decode.len() != 4 + component_count * 2 || component_count == 0 || component_count > 4 {
        return Ok(());
    }
    let color_space = dict.get("ColorSpace").ok_or_else(object_limit)?;
    let Ok(bytes) = decode_stream(value, context.store, context.limits) else {
        context.warning(
            "shading",
            "PDF_SHADING_UNSUPPORTED: an invalid Type 6 mesh stream was omitted",
        );
        return Ok(());
    };
    let coordinate_max = ((1_u64 << coordinate_bits) - 1) as f32;
    let component_max = ((1_u64 << component_bits) - 1) as f32;
    let mut bit_offset = 0_usize;
    let mut points = [(0.0, 0.0); 16];
    let mut colors = [0_u32; 4];
    let mut has_previous = false;
    let mut triangles = Vec::new();
    while bit_offset + flag_bits <= bytes.len() * 8 {
        let Some(flag) = read_packed_bits(&bytes, &mut bit_offset, flag_bits) else {
            break;
        };
        if flag > 3 || (flag != 0 && !has_previous) {
            context.warning(
                "shading",
                "PDF_SHADING_UNSUPPORTED: an invalid Type 6 mesh patch flag was omitted",
            );
            break;
        }
        let coordinate_count = if flag == 0 { 12 } else { 8 };
        let color_count = if flag == 0 { 4 } else { 2 };
        let required_bits =
            coordinate_count * 2 * coordinate_bits + color_count * component_count * component_bits;
        if bit_offset + required_bits > bytes.len() * 8 {
            break;
        }
        let mut incoming_points = Vec::with_capacity(coordinate_count);
        for _ in 0..coordinate_count {
            let x = mesh_decode_value(
                read_packed_bits(&bytes, &mut bit_offset, coordinate_bits).unwrap_or(0),
                decode[0],
                decode[1],
                coordinate_max,
            );
            let y = mesh_decode_value(
                read_packed_bits(&bytes, &mut bit_offset, coordinate_bits).unwrap_or(0),
                decode[2],
                decode[3],
                coordinate_max,
            );
            incoming_points.push(state.ctm.point(x, y));
        }
        let mut incoming_colors = Vec::with_capacity(color_count);
        for _ in 0..color_count {
            let mut components = Vec::with_capacity(component_count);
            for index in 0..component_count {
                components.push(mesh_decode_value(
                    read_packed_bits(&bytes, &mut bit_offset, component_bits).unwrap_or(0),
                    decode[4 + index * 2],
                    decode[5 + index * 2],
                    component_max,
                ));
            }
            let components = match function {
                Some(function) => mesh_function_components(function, components[0], context.store),
                None => Some(components),
            };
            let Some(color) = components.and_then(|components| {
                color_from_space_value(color_space, &components, context.store, 0)
            }) else {
                return Ok(());
            };
            incoming_colors.push(color);
        }
        match flag {
            0 => {
                points[12] = incoming_points[3];
                points[13] = incoming_points[4];
                points[14] = incoming_points[5];
                points[15] = incoming_points[6];
                points[8] = incoming_points[2];
                points[11] = incoming_points[7];
                points[4] = incoming_points[1];
                points[7] = incoming_points[8];
                points[0] = incoming_points[0];
                points[1] = incoming_points[11];
                points[2] = incoming_points[10];
                points[3] = incoming_points[9];
                colors = [
                    incoming_colors[0],
                    incoming_colors[3],
                    incoming_colors[1],
                    incoming_colors[2],
                ];
            }
            1 => {
                let previous = points;
                points[12] = previous[15];
                points[13] = incoming_points[0];
                points[14] = incoming_points[1];
                points[15] = incoming_points[2];
                points[8] = previous[14];
                points[11] = incoming_points[3];
                points[4] = previous[13];
                points[7] = incoming_points[4];
                points[0] = previous[12];
                points[1] = incoming_points[7];
                points[2] = incoming_points[6];
                points[3] = incoming_points[5];
                colors = [colors[2], incoming_colors[1], colors[3], incoming_colors[0]];
            }
            2 => {
                let previous = points;
                points[12] = previous[3];
                points[13] = incoming_points[0];
                points[14] = incoming_points[1];
                points[15] = incoming_points[2];
                points[8] = previous[7];
                points[11] = incoming_points[3];
                points[4] = previous[11];
                points[7] = incoming_points[4];
                points[0] = previous[15];
                points[1] = incoming_points[7];
                points[2] = incoming_points[6];
                points[3] = incoming_points[5];
                colors = [colors[3], incoming_colors[1], colors[1], incoming_colors[0]];
            }
            _ => {
                let previous = points;
                points[12] = previous[0];
                points[13] = incoming_points[0];
                points[14] = incoming_points[1];
                points[15] = incoming_points[2];
                points[8] = previous[1];
                points[11] = incoming_points[3];
                points[4] = previous[2];
                points[7] = incoming_points[4];
                points[0] = previous[3];
                points[1] = incoming_points[7];
                points[2] = incoming_points[6];
                points[3] = incoming_points[5];
                colors = [colors[1], incoming_colors[1], colors[0], incoming_colors[0]];
            }
        }
        points[5] = coons_interior_point(
            &points,
            [
                (0, -4.0),
                (15, -1.0),
                (4, 6.0),
                (1, 6.0),
                (12, -2.0),
                (3, -2.0),
                (13, 3.0),
                (7, 3.0),
            ],
        );
        points[6] = coons_interior_point(
            &points,
            [
                (3, -4.0),
                (12, -1.0),
                (2, 6.0),
                (7, 6.0),
                (0, -2.0),
                (15, -2.0),
                (4, 3.0),
                (14, 3.0),
            ],
        );
        points[9] = coons_interior_point(
            &points,
            [
                (12, -4.0),
                (3, -1.0),
                (8, 6.0),
                (13, 6.0),
                (0, -2.0),
                (15, -2.0),
                (11, 3.0),
                (1, 3.0),
            ],
        );
        points[10] = coons_interior_point(
            &points,
            [
                (15, -4.0),
                (0, -1.0),
                (11, 6.0),
                (14, 6.0),
                (12, -2.0),
                (3, -2.0),
                (2, 3.0),
                (8, 3.0),
            ],
        );
        tessellate_coons_patch(points, colors, &mut triangles)?;
        has_previous = true;
        bit_offset = bit_offset.div_ceil(8) * 8;
    }
    if let Some((bounds, bytes)) = rasterize_mesh_triangles(&triangles, state, context.limits) {
        return context.push_object(
            ObjectKind::Image,
            bounds,
            None,
            apply_clips(
                Visual::Image {
                    media_type: "image/bmp".to_owned(),
                    bytes,
                    crop: ImageCrop::default(),
                },
                bounds,
                state,
            ),
            pdf_source("path", None, Some(offset), MappingQuality::Exact),
        );
    }
    let parent_numeric_id = mesh_clip_group(state, context, offset)?;
    for triangle in triangles {
        push_mesh_triangle(triangle, state, context, offset, parent_numeric_id)?;
    }
    Ok(())
}

fn paint_tensor_mesh(
    value: &PdfValue,
    dict: &BTreeMap<String, PdfValue>,
    state: &GraphicsState,
    context: &mut PageContext<'_>,
    offset: usize,
) -> Result<(), Diagnostic> {
    if !matches!(value, PdfValue::Stream { .. }) {
        return Ok(());
    }
    let coordinate_bits = dict
        .get("BitsPerCoordinate")
        .and_then(number_usize)
        .filter(|bits| matches!(bits, 1 | 2 | 4 | 8 | 12 | 16 | 24 | 32))
        .ok_or_else(object_limit)?;
    let component_bits = dict
        .get("BitsPerComponent")
        .and_then(number_usize)
        .filter(|bits| matches!(bits, 1 | 2 | 4 | 8 | 12 | 16))
        .ok_or_else(object_limit)?;
    let flag_bits = dict
        .get("BitsPerFlag")
        .and_then(number_usize)
        .filter(|bits| matches!(bits, 2 | 4 | 8))
        .ok_or_else(object_limit)?;
    let decode: Vec<_> = match dict
        .get("Decode")
        .and_then(|value| context.store.resolve(value))
    {
        Some(PdfValue::Array(values)) => values.iter().filter_map(number_f32).collect(),
        _ => return Ok(()),
    };
    let function = dict.get("Function");
    let component_count = if function.is_some() {
        1
    } else {
        decode.len().saturating_sub(4) / 2
    };
    if decode.len() != 4 + component_count * 2 || component_count == 0 || component_count > 4 {
        return Ok(());
    }
    let color_space = dict.get("ColorSpace").ok_or_else(object_limit)?;
    let Ok(bytes) = decode_stream(value, context.store, context.limits) else {
        context.warning(
            "shading",
            "PDF_SHADING_UNSUPPORTED: an invalid Type 7 mesh stream was omitted",
        );
        return Ok(());
    };
    let coordinate_max = ((1_u64 << coordinate_bits) - 1) as f32;
    let component_max = ((1_u64 << component_bits) - 1) as f32;
    let mut bit_offset = 0_usize;
    let mut points = [(0.0, 0.0); 16];
    let mut colors = [0_u32; 4];
    let mut has_previous = false;
    let mut triangles = Vec::new();
    while bit_offset + flag_bits <= bytes.len() * 8 {
        let Some(flag) = read_packed_bits(&bytes, &mut bit_offset, flag_bits) else {
            break;
        };
        if flag > 3 || (flag != 0 && !has_previous) {
            context.warning(
                "shading",
                "PDF_SHADING_UNSUPPORTED: an invalid Type 7 mesh patch flag was omitted",
            );
            break;
        }
        let coordinate_count = if flag == 0 { 16 } else { 12 };
        let color_count = if flag == 0 { 4 } else { 2 };
        let required_bits =
            coordinate_count * 2 * coordinate_bits + color_count * component_count * component_bits;
        if bit_offset + required_bits > bytes.len() * 8 {
            break;
        }
        let mut incoming_points = Vec::with_capacity(coordinate_count);
        for _ in 0..coordinate_count {
            let x = mesh_decode_value(
                read_packed_bits(&bytes, &mut bit_offset, coordinate_bits).unwrap_or(0),
                decode[0],
                decode[1],
                coordinate_max,
            );
            let y = mesh_decode_value(
                read_packed_bits(&bytes, &mut bit_offset, coordinate_bits).unwrap_or(0),
                decode[2],
                decode[3],
                coordinate_max,
            );
            incoming_points.push(state.ctm.point(x, y));
        }
        let mut incoming_colors = Vec::with_capacity(color_count);
        for _ in 0..color_count {
            let mut components = Vec::with_capacity(component_count);
            for index in 0..component_count {
                components.push(mesh_decode_value(
                    read_packed_bits(&bytes, &mut bit_offset, component_bits).unwrap_or(0),
                    decode[4 + index * 2],
                    decode[5 + index * 2],
                    component_max,
                ));
            }
            let components = match function {
                Some(function) => mesh_function_components(function, components[0], context.store),
                None => Some(components),
            };
            let Some(parsed) = components.and_then(|components| {
                color_from_space_value(color_space, &components, context.store, 0)
            }) else {
                return Ok(());
            };
            incoming_colors.push(parsed);
        }
        match flag {
            0 => {
                points[12] = incoming_points[3];
                points[13] = incoming_points[4];
                points[14] = incoming_points[5];
                points[15] = incoming_points[6];
                points[8] = incoming_points[2];
                points[9] = incoming_points[13];
                points[10] = incoming_points[14];
                points[11] = incoming_points[7];
                points[4] = incoming_points[1];
                points[5] = incoming_points[12];
                points[6] = incoming_points[15];
                points[7] = incoming_points[8];
                points[0] = incoming_points[0];
                points[1] = incoming_points[11];
                points[2] = incoming_points[10];
                points[3] = incoming_points[9];
                colors = [
                    incoming_colors[0],
                    incoming_colors[3],
                    incoming_colors[1],
                    incoming_colors[2],
                ];
            }
            1 => {
                let previous = points;
                points[12] = previous[15];
                points[13] = incoming_points[0];
                points[14] = incoming_points[1];
                points[15] = incoming_points[2];
                points[8] = previous[14];
                points[9] = incoming_points[9];
                points[10] = incoming_points[10];
                points[11] = incoming_points[3];
                points[4] = previous[13];
                points[5] = incoming_points[8];
                points[6] = incoming_points[11];
                points[7] = incoming_points[4];
                points[0] = previous[12];
                points[1] = incoming_points[7];
                points[2] = incoming_points[6];
                points[3] = incoming_points[5];
                colors = [colors[2], incoming_colors[1], colors[3], incoming_colors[0]];
            }
            2 => {
                let previous = points;
                points[12] = previous[3];
                points[13] = incoming_points[0];
                points[14] = incoming_points[1];
                points[15] = incoming_points[2];
                points[8] = previous[7];
                points[9] = incoming_points[9];
                points[10] = incoming_points[10];
                points[11] = incoming_points[3];
                points[4] = previous[11];
                points[5] = incoming_points[8];
                points[6] = incoming_points[11];
                points[7] = incoming_points[4];
                points[0] = previous[15];
                points[1] = incoming_points[7];
                points[2] = incoming_points[6];
                points[3] = incoming_points[5];
                colors = [colors[3], incoming_colors[1], colors[1], incoming_colors[0]];
            }
            _ => {
                let previous = points;
                points[12] = previous[0];
                points[13] = incoming_points[0];
                points[14] = incoming_points[1];
                points[15] = incoming_points[2];
                points[8] = previous[1];
                points[9] = incoming_points[9];
                points[10] = incoming_points[10];
                points[11] = incoming_points[3];
                points[4] = previous[2];
                points[5] = incoming_points[8];
                points[6] = incoming_points[11];
                points[7] = incoming_points[4];
                points[0] = previous[3];
                points[1] = incoming_points[7];
                points[2] = incoming_points[6];
                points[3] = incoming_points[5];
                colors = [colors[1], incoming_colors[1], colors[0], incoming_colors[0]];
            }
        }
        tessellate_coons_patch(points, colors, &mut triangles)?;
        has_previous = true;
        bit_offset = bit_offset.div_ceil(8) * 8;
    }
    if let Some((bounds, bytes)) = rasterize_mesh_triangles(&triangles, state, context.limits) {
        return context.push_object(
            ObjectKind::Image,
            bounds,
            None,
            apply_clips(
                Visual::Image {
                    media_type: "image/bmp".to_owned(),
                    bytes,
                    crop: ImageCrop::default(),
                },
                bounds,
                state,
            ),
            pdf_source("path", None, Some(offset), MappingQuality::Exact),
        );
    }
    let parent_numeric_id = mesh_clip_group(state, context, offset)?;
    for triangle in triangles {
        push_mesh_triangle(triangle, state, context, offset, parent_numeric_id)?;
    }
    Ok(())
}

fn shading_stops(
    function: &PdfValue,
    color_space: &PdfValue,
    store: &ObjectStore,
    limits: Limits,
    alpha: f32,
) -> Option<Vec<GradientStop>> {
    const PDFJS_GRADIENT_SAMPLES: usize = 840;
    let dict = store.dict(function)?;
    let function_type = dict.get("FunctionType").and_then(number_usize)?;
    let sampled_bytes = if function_type == 0 {
        Some(decoded_function_stream(function, store, limits)?)
    } else {
        None
    };
    let components = match function_type {
        0 => (0..PDFJS_GRADIENT_SAMPLES)
            .map(|index| {
                let offset = index as f32 / PDFJS_GRADIENT_SAMPLES as f32;
                Some((
                    offset,
                    evaluate_sampled_function_with_decoded(
                        function,
                        offset,
                        sampled_bytes.as_deref()?.as_slice(),
                        store,
                        limits,
                    )?,
                ))
            })
            .collect::<Option<Vec<_>>>()?,
        2 => vec![
            (0.0, evaluate_type2_function(function, &[0.0], store)?),
            (1.0, evaluate_type2_function(function, &[1.0], store)?),
        ],
        3 => {
            let domain = dict
                .get("Domain")
                .and_then(|value| store.resolve(value))
                .and_then(|value| match value {
                    PdfValue::Array(values) => last_numbers::<2>(values),
                    _ => None,
                })
                .unwrap_or([0.0, 1.0]);
            if domain[1] <= domain[0] {
                return None;
            }
            (0..=PDFJS_GRADIENT_SAMPLES)
                .map(|index| {
                    let offset = index as f32 / PDFJS_GRADIENT_SAMPLES as f32;
                    let input = domain[0] + offset * (domain[1] - domain[0]);
                    Some((
                        offset,
                        evaluate_shading_function(function, input, store, limits)?,
                    ))
                })
                .collect::<Option<Vec<_>>>()?
        }
        4 => (0..=64)
            .map(|index| {
                let offset = index as f32 / 64.0;
                Some((offset, evaluate_type4_function(function, &[offset], store)?))
            })
            .collect::<Option<Vec<_>>>()?,
        _ => return None,
    };
    let stops = components
        .into_iter()
        .map(|(offset, components)| {
            let color = color_from_space_value(color_space, &components, store, 0)?;
            Some(GradientStop {
                offset: offset.clamp(0.0, 1.0),
                color: with_alpha(color, alpha),
            })
        })
        .collect::<Option<Vec<_>>>()?;
    Some(compact_constant_gradient_runs(if function_type == 0 {
        compress_pdfjs_gradient_samples(stops)
    } else {
        stops
    }))
}

fn compact_constant_gradient_runs(stops: Vec<GradientStop>) -> Vec<GradientStop> {
    if stops.len() < 3 {
        return stops;
    }
    let mut result = Vec::with_capacity(stops.len());
    result.push(stops[0].clone());
    for window in stops.windows(3) {
        if window[0].color != window[1].color || window[1].color != window[2].color {
            result.push(window[1].clone());
        }
    }
    result.push(stops.last().cloned().unwrap());
    result
}

fn compress_pdfjs_gradient_samples(samples: Vec<GradientStop>) -> Vec<GradientStop> {
    if samples.len() < 3 {
        return samples;
    }
    let channels = |color: u32| {
        let [red, green, blue, _] = color.to_be_bytes();
        [i32::from(red), i32::from(green), i32::from(blue)]
    };
    let mut result = vec![samples[0].clone()];
    let mut base_index = 0_usize;
    let mut base = channels(samples[0].color);
    let mut previous_index = 1_usize;
    let mut previous = channels(samples[1].color);
    let mut maximum_slopes = [0.0_f32; 3];
    let mut minimum_slopes = [0.0_f32; 3];
    for component in 0..3 {
        maximum_slopes[component] = (previous[component] - base[component] + 1) as f32;
        minimum_slopes[component] = (previous[component] - base[component] - 1) as f32;
    }
    for (index, sample) in samples.iter().enumerate().skip(2) {
        let current = channels(sample.color);
        let run = (index - base_index) as f32;
        for component in 0..3 {
            maximum_slopes[component] = maximum_slopes[component]
                .min((current[component] - base[component] + 1) as f32 / run);
            minimum_slopes[component] = minimum_slopes[component]
                .max((current[component] - base[component] - 1) as f32 / run);
        }
        if (0..3).any(|component| minimum_slopes[component] > maximum_slopes[component]) {
            let mut stop = samples[previous_index].clone();
            stop.offset = previous_index as f32 / samples.len() as f32;
            result.push(stop);
            for component in 0..3 {
                maximum_slopes[component] = (current[component] - previous[component] + 1) as f32;
                minimum_slopes[component] = (current[component] - previous[component] - 1) as f32;
            }
            base_index = previous_index;
            base = previous;
        }
        previous_index = index;
        previous = current;
    }
    let mut last = samples.last().cloned().unwrap();
    last.offset = 1.0;
    result.push(last);
    result
}

fn evaluate_shading_function(
    value: &PdfValue,
    input: f32,
    store: &ObjectStore,
    limits: Limits,
) -> Option<Vec<f32>> {
    evaluate_shading_function_at_depth(value, input, store, limits, 0)
}

fn evaluate_shading_function_at_depth(
    value: &PdfValue,
    input: f32,
    store: &ObjectStore,
    limits: Limits,
    depth: usize,
) -> Option<Vec<f32>> {
    if depth > 16 {
        return None;
    }
    match store
        .dict(value)?
        .get("FunctionType")
        .and_then(number_usize)?
    {
        0 => evaluate_sampled_function(value, input, store, limits),
        2 => evaluate_type2_function(value, &[input], store),
        3 => evaluate_stitched_shading_function(value, input, store, limits, depth + 1),
        4 => evaluate_type4_function(value, &[input], store),
        _ => None,
    }
}

fn evaluate_stitched_shading_function(
    value: &PdfValue,
    input: f32,
    store: &ObjectStore,
    limits: Limits,
    depth: usize,
) -> Option<Vec<f32>> {
    let dict = store.dict(value)?;
    let PdfValue::Array(functions) = dict
        .get("Functions")
        .and_then(|value| store.resolve(value))?
    else {
        return None;
    };
    if functions.is_empty() || functions.len() > 64 {
        return None;
    }
    let domain = dict
        .get("Domain")
        .and_then(|value| store.resolve(value))
        .and_then(|value| match value {
            PdfValue::Array(values) => last_numbers::<2>(values),
            _ => None,
        })
        .unwrap_or([0.0, 1.0]);
    if domain[1] <= domain[0] {
        return None;
    }
    let bounds: Vec<_> = match dict.get("Bounds").and_then(|value| store.resolve(value)) {
        Some(PdfValue::Array(values)) => values.iter().filter_map(number_f32).collect(),
        _ => Vec::new(),
    };
    if bounds.len() + 1 != functions.len() {
        return None;
    }
    let encode: Vec<_> = match dict.get("Encode").and_then(|value| store.resolve(value)) {
        Some(PdfValue::Array(values)) => values.iter().filter_map(number_f32).collect(),
        _ => [0.0, 1.0].repeat(functions.len()),
    };
    if encode.len() != functions.len() * 2 {
        return None;
    }
    let input = input.clamp(domain[0], domain[1]);
    let index = bounds
        .iter()
        .position(|bound| input < *bound)
        .unwrap_or(functions.len() - 1);
    let start = if index == 0 {
        domain[0]
    } else {
        bounds[index - 1]
    };
    let end = bounds.get(index).copied().unwrap_or(domain[1]);
    let amount = if end > start {
        (input - start) / (end - start)
    } else {
        0.0
    };
    let encoded = encode[index * 2] + amount * (encode[index * 2 + 1] - encode[index * 2]);
    evaluate_shading_function_at_depth(&functions[index], encoded, store, limits, depth)
}

fn text_matrix_with_rise(text_matrix: Matrix, rise: f32) -> Matrix {
    text_matrix.concat(Matrix {
        f: rise,
        ..Matrix::IDENTITY
    })
}

fn advance_text_matrix(state: &mut GraphicsState, advance: f32, vertical: bool) {
    state.text_matrix = state.text_matrix.concat(if vertical {
        Matrix {
            f: -advance,
            ..Matrix::IDENTITY
        }
    } else {
        Matrix {
            e: advance,
            ..Matrix::IDENTITY
        }
    });
}

fn pdf_shading_pattern_paint(
    name: &str,
    resources: Option<&PdfValue>,
    state: &GraphicsState,
    context: &PageContext<'_>,
    bounds: Rect,
    alpha: f32,
) -> Option<Paint> {
    let (_, pattern_value) = resource_entry(resources, "Pattern", name, context.store)?;
    let pattern = context.store.dict(pattern_value)?;
    if pattern.get("PatternType").and_then(number_usize) != Some(2) {
        return None;
    }
    let shading = pattern
        .get("Shading")
        .and_then(|value| context.store.resolve(value))?;
    let shading = context.store.dict(shading)?;
    let shading_type = shading.get("ShadingType").and_then(number_usize)?;
    if !matches!(shading_type, 2 | 3) {
        return None;
    }
    let function = shading.get("Function")?;
    let color_space = shading.get("ColorSpace")?;
    let stops = shading_stops(function, color_space, context.store, context.limits, alpha)?;
    let extend = shading
        .get("Extend")
        .and_then(|value| context.store.resolve(value))
        .and_then(|value| match value {
            PdfValue::Array(values) if values.len() >= 2 => Some([
                matches!(values[0], PdfValue::Bool(true)),
                matches!(values[1], PdfValue::Bool(true)),
            ]),
            _ => None,
        })
        .unwrap_or([false, false]);
    let stops = shading_stops_with_extensions(stops, extend);
    let coords = shading
        .get("Coords")
        .and_then(|value| context.store.resolve(value))
        .and_then(|value| match value {
            PdfValue::Array(values) => {
                Some(values.iter().filter_map(number_f32).collect::<Vec<_>>())
            }
            _ => None,
        })?;
    let pattern_matrix = pattern
        .get("Matrix")
        .and_then(|value| six_numbers_value(context.store, value))
        .map(matrix)
        .unwrap_or(Matrix::IDENTITY);
    let transform = state.pattern_base_ctm.concat(pattern_matrix);
    let axis_x = transform.a.hypot(transform.b);
    let axis_y = transform.c.hypot(transform.d);
    let orthogonality = transform.a * transform.c + transform.b * transform.d;
    let non_conformal = (axis_x - axis_y).abs() > axis_x.max(axis_y).max(1.0) * 0.000_1
        || orthogonality.abs() > (axis_x * axis_y).max(1.0) * 0.000_1;
    if shading_type == 3 && coords.len() == 6 && non_conformal {
        let bytes = rasterize_radial_shading(
            bounds,
            transform,
            &coords,
            &stops,
            &state.soft_masks,
            context.limits,
        )?;
        return Some(Paint::Image {
            mapping: None,
            media_type: "image/bmp".to_owned(),
            bytes,
            crop: ImageCrop::default(),
            tile: false,
            tile_width: None,
            tile_height: None,
        });
    }
    match shading_type {
        2 if coords.len() == 4 => {
            let start = transform.point(coords[0], coords[1]);
            let end = transform.point(coords[2], coords[3]);
            Some(Paint::LinearGradient {
                x0: start.0 - bounds.x,
                y0: start.1 - bounds.y,
                x1: end.0 - bounds.x,
                y1: end.1 - bounds.y,
                stops: apply_linear_soft_masks(stops, start, end, &state.soft_masks),
            })
        }
        3 if coords.len() == 6 => {
            let start = transform.point(coords[0], coords[1]);
            let end = transform.point(coords[3], coords[4]);
            let scale = transform.scale();
            let start_radius = coords[2].abs() * scale;
            let end_radius = coords[5].abs() * scale;
            Some(Paint::RadialGradient {
                x0: start.0 - bounds.x,
                y0: start.1 - bounds.y,
                r0: start_radius,
                x1: end.0 - bounds.x,
                y1: end.1 - bounds.y,
                r1: end_radius,
                stops: apply_radial_soft_masks(
                    stops,
                    start,
                    start_radius,
                    end,
                    end_radius,
                    &state.soft_masks,
                ),
            })
        }
        _ => None,
    }
}

fn pdf_shading_pattern_bounds(
    name: &str,
    resources: Option<&PdfValue>,
    state: &GraphicsState,
    context: &PageContext<'_>,
) -> Option<Rect> {
    let (_, pattern_value) = resource_entry(resources, "Pattern", name, context.store)?;
    let pattern = context.store.dict(pattern_value)?;
    if pattern.get("PatternType").and_then(number_usize) != Some(2) {
        return None;
    }
    let shading = pattern
        .get("Shading")
        .and_then(|value| context.store.resolve(value))?;
    let shading = context.store.dict(shading)?;
    let [left, bottom, right, top] = shading
        .get("BBox")
        .and_then(|value| context.store.resolve(value))
        .and_then(|value| match value {
            PdfValue::Array(values) => last_numbers::<4>(values),
            _ => None,
        })?;
    let pattern_matrix = pattern
        .get("Matrix")
        .and_then(|value| six_numbers_value(context.store, value))
        .map(matrix)
        .unwrap_or(Matrix::IDENTITY);
    let transform = state.pattern_base_ctm.concat(pattern_matrix);
    bounds(&[
        transform.point(left, bottom),
        transform.point(right, bottom),
        transform.point(right, top),
        transform.point(left, top),
    ])
}

fn show_text(
    encoded: &[u8],
    actual_text: Option<&str>,
    resources: Option<&PdfValue>,
    state: &mut GraphicsState,
    context: &mut PageContext<'_>,
    source_object: u32,
    offset: usize,
    depth: usize,
) -> Result<(), Diagnostic> {
    show_text_decoded(
        encoded,
        actual_text,
        resources,
        state,
        context,
        source_object,
        offset,
        depth,
        None,
    )
}

fn show_text_decoded(
    encoded: &[u8],
    actual_text: Option<&str>,
    resources: Option<&PdfValue>,
    state: &mut GraphicsState,
    context: &mut PageContext<'_>,
    source_object: u32,
    offset: usize,
    depth: usize,
    decoded_glyph: Option<DecodedGlyph>,
) -> Result<(), Diagnostic> {
    let font = font_info(resources, &state.font_name, context)?;
    let split_glyphs = decoded_glyph.is_none();
    let glyphs = decoded_glyph
        .map(|glyph| vec![glyph])
        .unwrap_or_else(|| decode_pdf_glyphs(encoded, &font));
    // Embedded browser fonts have their cmap and advances rebuilt from the PDF
    // metrics, and the emitted run is scaled to the authored total advance.
    // Keeping a whole horizontal show-text operation avoids thousands of
    // single-glyph scene objects without changing its final bounds. Missing
    // and vertical fonts still require explicit per-glyph positioning.
    if split_glyphs
        && actual_text.is_none()
        && (state.word_spacing.abs() > f32::EPSILON && glyphs.iter().any(|glyph| glyph.code == 32)
            || font.browser_position_glyphs
                && (!font.browser_scale_to_pdf_advance
                    || font.vertical
                    || glyphs
                        .iter()
                        .any(|glyph| !font.widths.contains_key(&glyph.code))))
        && glyphs.len() > 1
    {
        for glyph in glyphs {
            show_text_decoded(
                &[],
                None,
                resources,
                state,
                context,
                source_object,
                offset,
                depth,
                Some(glyph),
            )?;
        }
        return Ok(());
    }
    let text = actual_text.map(str::to_owned).unwrap_or_else(|| {
        glyphs
            .iter()
            .map(|glyph| glyph.text.as_str())
            .collect::<String>()
    });
    let visual_text = if font.browser_cid_font {
        cid_glyph_text(&glyphs)
    } else if font.browser_source_glyph_font
        || font.browser_contextual_source_glyphs
        || !font.browser_source_glyph_codes.is_empty()
    {
        simple_glyph_text(&glyphs, &font)
    } else if actual_text.is_none() {
        glyphs
            .iter()
            .filter(|glyph| {
                !glyph.text.chars().all(char::is_whitespace)
                    || !font
                        .widths
                        .get(&glyph.code)
                        .is_some_and(|width| *width <= 0.0)
            })
            .map(|glyph| glyph.text.as_str())
            .collect()
    } else {
        text.clone()
    };
    let advance = glyphs
        .iter()
        .map(|glyph| {
            font.widths
                .get(&glyph.code)
                .copied()
                .unwrap_or(font.default_width)
                / 1000.0
                * state.font_size
                + state.char_spacing
                + if glyph.code == 32 {
                    state.word_spacing
                } else {
                    0.0
                }
        })
        .sum::<f32>()
        * if font.vertical {
            1.0
        } else {
            state.horizontal_scale
        };
    if state.font_size == 0.0 {
        advance_text_matrix(state, advance, font.vertical);
        return Ok(());
    }
    let visual_advance = if actual_text.is_some_and(|text| {
        let mut characters = text.chars();
        matches!(
            (characters.next(), characters.next(), characters.next()),
            (Some(first), Some(second), None)
                if ('\u{1f1e6}'..='\u{1f1ff}').contains(&first)
                    && ('\u{1f1e6}'..='\u{1f1ff}').contains(&second)
        )
    }) {
        advance * 0.65
    } else {
        advance
    };
    if !font.source_glyph_outlines.is_empty()
        && state.text_render_mode != 7
        && glyphs
            .iter()
            .any(|glyph| font.source_glyph_outlines.contains_key(&glyph.code))
    {
        if !matches!(state.text_render_mode, 3 | 7) {
            paint_source_glyph_outlines(&glyphs, &font, state, context, source_object, offset)?;
        }
        if matches!(state.text_render_mode, 4..=7) {
            if state.clips.len() >= MAX_CLIP_DEPTH {
                return Err(pdf_error(
                    offset,
                    "PDF clipping depth exceeds the parser limit",
                ));
            }
            if let Some(clip) = source_glyph_clip(&glyphs, &font, state) {
                state.clips.push(clip);
            }
        }
        let combined = state
            .ctm
            .concat(text_matrix_with_rise(state.text_matrix, state.text_rise));
        let horizontal_scale = combined.a.hypot(combined.b).max(f32::EPSILON);
        let vertical_scale = combined.c.hypot(combined.d).max(f32::EPSILON);
        let font_size = state.font_size.abs() * vertical_scale;
        let width = (visual_advance.abs() * horizontal_scale).max(font_size * 0.05);
        let ascent = if font.ascent > 0.0 {
            font.ascent
        } else {
            800.0
        };
        let descent = if font.descent < 0.0 {
            font.descent
        } else {
            -200.0
        };
        let height = ((ascent - descent) / 1000.0 * font_size).max(font_size);
        let center = combined.point(
            visual_advance / 2.0,
            (ascent + descent) / 2_000.0 * state.font_size,
        );
        context.push_object(
            ObjectKind::TextBox,
            Rect {
                x: center.0 - width / 2.0,
                y: center.1 - height / 2.0,
                width,
                height,
            },
            (!text.is_empty()).then_some(text),
            Visual::None,
            pdf_source(
                "text",
                Some(source_object),
                Some(offset),
                MappingQuality::Exact,
            ),
        )?;
        advance_text_matrix(state, advance, font.vertical);
        return Ok(());
    }
    if let Some(font_matrix) = font.type3_font_matrix {
        if !visual_text.is_empty() && !matches!(state.text_render_mode, 3 | 7) {
            paint_type3_glyphs(
                &glyphs,
                &font,
                font_matrix,
                resources,
                state,
                context,
                offset,
                depth,
            )?;
        }
        let combined = state
            .ctm
            .concat(text_matrix_with_rise(state.text_matrix, state.text_rise));
        let horizontal_scale = combined.a.hypot(combined.b).max(f32::EPSILON);
        let vertical_scale = combined.c.hypot(combined.d).max(f32::EPSILON);
        let font_size = state.font_size.abs() * vertical_scale;
        let width = (visual_advance.abs() * horizontal_scale).max(font_size * 0.05);
        let ascent = if font.ascent > 0.0 {
            font.ascent
        } else {
            800.0
        };
        let descent = if font.descent < 0.0 {
            font.descent
        } else {
            -200.0
        };
        let height = ((ascent - descent) / 1000.0 * font_size).max(font_size);
        let center = combined.point(
            visual_advance / 2.0,
            (ascent + descent) / 2_000.0 * state.font_size,
        );
        context.push_object(
            ObjectKind::TextBox,
            Rect {
                x: center.0 - width / 2.0,
                y: center.1 - height / 2.0,
                width,
                height,
            },
            (!text.is_empty()).then_some(text),
            Visual::None,
            pdf_source(
                "text",
                Some(source_object),
                Some(offset),
                MappingQuality::Exact,
            ),
        )?;
        advance_text_matrix(state, advance, font.vertical);
        return Ok(());
    }
    if visual_text.is_empty() || state.text_render_mode == 3 {
        advance_text_matrix(state, advance, font.vertical);
        return Ok(());
    }
    let combined = state
        .ctm
        .concat(text_matrix_with_rise(state.text_matrix, state.text_rise));
    let horizontal_scale = combined.a.hypot(combined.b).max(f32::EPSILON);
    let vertical_scale = combined.c.hypot(combined.d).max(f32::EPSILON);
    let font_size = state.font_size.abs() * vertical_scale;
    let glyph_horizontal_scale = if font.vertical {
        1.0
    } else {
        state.horizontal_scale.abs() * horizontal_scale / vertical_scale
    };
    let ascent = if font.ascent > 0.0 {
        font.ascent
    } else {
        800.0
    };
    let descent = if font.descent < 0.0 {
        font.descent
    } else {
        -200.0
    };
    let line_height = if font.vertical {
        font_size
    } else {
        ((ascent - descent) / 1000.0 * font_size).max(font_size)
    };
    // Browser fallback suit glyphs are materially smaller than the PDF Base14
    // ZapfDingbats outlines at the same em size. Preserve the authored PDF
    // advance and baseline while matching the standard font's ink box.
    let visual_font_size = if font.family.eq_ignore_ascii_case("ZapfDingbats") {
        if visual_text
            .chars()
            .all(|character| matches!(character, '\u{2660}' | '\u{2665}' | '\u{2666}' | '\u{2663}'))
        {
            font_size
        } else if font_size <= 48.0 {
            font_size * 1.45
        } else {
            font_size
        }
    } else {
        font_size
    };
    let angle = combined.b.atan2(combined.a).to_degrees();
    let color = if matches!(state.text_render_mode, 1 | 5) {
        with_alpha(state.stroke, state.stroke_alpha)
    } else {
        with_alpha(state.fill, state.fill_alpha)
    };
    let (width, height, center) = if font.vertical {
        (
            (state.font_size.abs() * horizontal_scale).max(font_size * 0.05),
            (visual_advance.abs() * vertical_scale).max(font_size),
            combined.point(0.0, -visual_advance / 2.0),
        )
    } else {
        (
            (visual_advance.abs() * horizontal_scale).max(font_size * 0.05),
            line_height,
            combined.point(
                visual_advance / 2.0,
                (ascent + descent) / 2_000.0 * state.font_size,
            ),
        )
    };
    let bounds = Rect {
        x: center.0 - width / 2.0,
        y: center.1 - height / 2.0,
        width,
        height,
    };
    let text_paint = if matches!(state.text_render_mode, 0 | 2 | 4 | 6) {
        if let Some(pattern) = state.fill_pattern.as_deref() {
            pdf_shading_pattern_paint(pattern, resources, state, context, bounds, state.fill_alpha)
                .or(pdf_tiling_pattern_paint(
                    pattern, resources, state, context,
                )?)
        } else {
            None
        }
    } else {
        None
    };
    let text_stroke_paint = if matches!(state.text_render_mode, 1 | 2 | 5 | 6) {
        if let Some(pattern) = state.stroke_pattern.as_deref() {
            let mut pattern_state = state.clone();
            pattern_state.fill = state.stroke;
            pattern_state.fill_alpha = state.stroke_alpha;
            pdf_shading_pattern_paint(
                pattern,
                resources,
                state,
                context,
                bounds,
                state.stroke_alpha,
            )
            .or(pdf_tiling_pattern_paint(
                pattern,
                resources,
                &pattern_state,
                context,
            )?)
        } else {
            None
        }
    } else {
        None
    };
    let mut text_stroke_width = state.line_width * state.ctm.scale();
    // Canvas under-covers subpixel text strokes compared with PDFKit. Keep
    // authored widths at one CSS pixel and above exact, and compensate only
    // the antialiased hairline range used by PDF fill-and-stroke text.
    if text_stroke_width < 1.0 {
        text_stroke_width *= 1.25;
    }
    let visual = if visual_text.chars().all(char::is_whitespace) {
        Visual::None
    } else {
        Visual::TextLayout {
            layout: TextLayout {
                inset_left: 0.0,
                inset_right: 0.0,
                inset_top: 0.0,
                inset_bottom: 0.0,
                orientation: if font.vertical {
                    TextOrientation::VerticalRl
                } else {
                    TextOrientation::Horizontal
                },
                rotation_degrees: angle,
                wrap: false,
                text_fill: matches!(state.text_render_mode, 0 | 2 | 4 | 6),
                text_paint: text_paint.unwrap_or(Paint::None),
                // Character and word spacing change only the advance after a
                // glyph. Do not infer outline scaling from a collapsed advance.
                // Embedded browser fonts additionally follow the authored PDF
                // advance when no separate spacing term would be distorted.
                text_scale_to_fit: (glyph_horizontal_scale - 1.0).abs() > 0.025
                    || (font.browser_scale_to_pdf_advance
                        && state.char_spacing.abs() < f32::EPSILON
                        && state.word_spacing.abs() < f32::EPSILON),
                text_matrix_scale_to_fit: (glyph_horizontal_scale - 1.0).abs() > 0.025,
                low_resolution_supersample: font.browser_low_resolution_supersample,
                text_stroke_color: if matches!(state.text_render_mode, 1 | 2 | 5 | 6)
                    && state.stroke_pattern.is_none()
                {
                    with_alpha(state.stroke, state.stroke_alpha)
                } else {
                    0
                },
                text_stroke_paint: text_stroke_paint.unwrap_or(Paint::None),
                text_stroke_width: if matches!(state.text_render_mode, 1 | 2 | 5 | 6) {
                    text_stroke_width
                } else {
                    0.0
                },
                text_baseline: if font.vertical {
                    font.vertical_origin_y / 1000.0 * font_size + 1.0
                } else if let Some(ascent) = font.browser_ascent {
                    ascent.min(1_000.0) / 1000.0 * font_size
                } else {
                    ascent / 1000.0 * font_size + 1.0
                },
                ..TextLayout::default()
            },
            visual: Box::new(Visual::RichText {
                geometry: Geometry::Rectangle,
                fill: Paint::None,
                stroke: Paint::None,
                stroke_width: 0.0,
                align: TextAlign::Start,
                line_height,
                runs: pdf_visual_font_runs(&visual_text, &font.family)
                    .into_iter()
                    .map(|(text, font_family)| TextRun {
                        paint: None,
                        east_asian_line_breaks: true,
                        text,
                        font_family,
                        font_size: visual_font_size,
                        color,
                        bold: font.bold,
                        italic: font.italic,
                        underline: false,
                        strikethrough: false,
                        highlight: 0,
                        baseline_shift: 0.0,
                        letter_spacing: state.char_spacing * horizontal_scale,
                        horizontal_scale: 1.0,
                    })
                    .collect(),
            }),
        }
    };
    let visual = apply_pdf_stroke_style(
        visual,
        state,
        matches!(state.text_render_mode, 1 | 2 | 5 | 6),
    );
    if matches!(state.text_render_mode, 4..=7) {
        state.text_clips.push(PdfTextClip {
            bounds,
            text: text.clone(),
            visual: text_clip_visual_with_color(
                visual.clone(),
                with_alpha(state.fill, state.fill_alpha),
            ),
            source_object,
            offset,
        });
        if state.text_render_mode == 7 {
            advance_text_matrix(state, advance, font.vertical);
            return Ok(());
        }
    }
    context.push_object(
        ObjectKind::TextBox,
        bounds,
        (!text.is_empty()).then_some(text.clone()),
        apply_clips(visual, bounds, state),
        pdf_source(
            "text",
            Some(source_object),
            Some(offset),
            MappingQuality::Approximate,
        ),
    )?;
    advance_text_matrix(state, advance, font.vertical);
    Ok(())
}

fn text_clip_visual_with_color(mut visual: Visual, color: u32) -> Visual {
    match &mut visual {
        Visual::TextLayout {
            layout,
            visual: nested,
        } => {
            layout.text_fill = true;
            layout.text_paint = Paint::None;
            layout.text_stroke_color = 0;
            layout.text_stroke_paint = Paint::None;
            layout.text_stroke_width = 0.0;
            **nested = text_clip_visual_with_color((**nested).clone(), color);
        }
        Visual::RichText { runs, .. } => {
            for run in runs {
                run.color = color;
            }
        }
        Visual::Effect { visual: nested, .. }
        | Visual::Layer { visual: nested, .. }
        | Visual::StrokeStyle { visual: nested, .. }
        | Visual::AdvancedEffect { visual: nested, .. } => {
            **nested = text_clip_visual_with_color((**nested).clone(), color);
        }
        _ => {}
    }
    visual
}

#[allow(clippy::too_many_arguments)]
fn paint_type3_glyphs(
    glyphs: &[DecodedGlyph],
    font: &FontInfo,
    font_matrix: Matrix,
    resources: Option<&PdfValue>,
    state: &GraphicsState,
    context: &mut PageContext<'_>,
    offset: usize,
    depth: usize,
) -> Result<(), Diagnostic> {
    let font_resources = resource_entry(resources, "Font", &state.font_name, context.store)
        .and_then(|(_, value)| context.store.dict(value))
        .and_then(|root| root.get("Resources"))
        .or(resources);
    let mut text_matrix = state.text_matrix;
    for glyph in glyphs {
        let glyph_advance = (font
            .widths
            .get(&glyph.code)
            .copied()
            .unwrap_or(font.default_width)
            / 1000.0
            * state.font_size
            + state.char_spacing
            + if glyph.code == 32 {
                state.word_spacing
            } else {
                0.0
            })
            * state.horizontal_scale;
        let Some(id) = font.type3_char_procs.get(&glyph.code).copied() else {
            context.warning(
                "type3-glyph",
                "PDF_TYPE3_GLYPH_OMITTED: a Type 3 glyph procedure could not be resolved",
            );
            text_matrix = text_matrix.concat(Matrix {
                e: glyph_advance,
                f: 0.0,
                ..Matrix::IDENTITY
            });
            continue;
        };
        let Some(value) = context.store.objects.get(&id).map(|object| &object.value) else {
            continue;
        };
        let decoded = decode_stream(value, context.store, context.limits)?;
        if !context.active_forms.insert(id) {
            return Err(pdf_error(offset, "cyclic PDF Type 3 glyph procedure"));
        }
        let mut glyph_state = state.clone();
        glyph_state.ctm = state
            .ctm
            .concat(text_matrix_with_rise(text_matrix, state.text_rise))
            .concat(Matrix {
                a: state.font_size * state.horizontal_scale,
                d: state.font_size,
                ..Matrix::IDENTITY
            })
            .concat(font_matrix);
        glyph_state.pattern_base_ctm = glyph_state.ctm;
        glyph_state.text_matrix = Matrix::IDENTITY;
        glyph_state.line_matrix = Matrix::IDENTITY;
        glyph_state.fill_pattern = None;
        glyph_state.stroke_pattern = None;
        glyph_state.ignore_color_operators =
            type3_glyph_uses_inherited_color(&decoded, context.limits);
        let result = interpret_content(
            &decoded,
            font_resources,
            context,
            glyph_state,
            id.0,
            depth + 1,
        );
        context.active_forms.remove(&id);
        result?;
        text_matrix = text_matrix.concat(Matrix {
            e: glyph_advance,
            f: 0.0,
            ..Matrix::IDENTITY
        });
    }
    Ok(())
}

fn type3_glyph_uses_inherited_color(bytes: &[u8], limits: Limits) -> bool {
    let mut parser = ContentParser::new(bytes, limits);
    while let Ok(Some(token)) = parser.next() {
        if let ContentToken::Operator(operator, _) = token {
            return operator == "d1";
        }
    }
    false
}

fn paint_source_glyph_outlines(
    glyphs: &[DecodedGlyph],
    font: &FontInfo,
    state: &GraphicsState,
    context: &mut PageContext<'_>,
    source_object: u32,
    offset: usize,
) -> Result<(), Diagnostic> {
    let mut text_matrix = state.text_matrix;
    for glyph in glyphs {
        let glyph_advance = (font
            .widths
            .get(&glyph.code)
            .copied()
            .unwrap_or(font.default_width)
            / 1000.0
            * state.font_size
            + state.char_spacing
            + if glyph.code == 32 {
                state.word_spacing
            } else {
                0.0
            })
            * state.horizontal_scale;
        let Some(commands) = font.source_glyph_outlines.get(&glyph.code) else {
            context.warning(
                "source-glyph-outline",
                "PDF_SOURCE_GLYPH_OMITTED: an embedded source glyph outline could not be resolved",
            );
            text_matrix = text_matrix.concat(Matrix {
                e: glyph_advance,
                f: 0.0,
                ..Matrix::IDENTITY
            });
            continue;
        };
        if commands.len() > MAX_PATH_COMMANDS {
            context.warning(
                "source-glyph-outline-limit",
                "PDF_SOURCE_GLYPH_OMITTED: an embedded source glyph outline exceeded the path limit",
            );
            text_matrix = text_matrix.concat(Matrix {
                e: glyph_advance,
                f: 0.0,
                ..Matrix::IDENTITY
            });
            continue;
        }
        let transform = state
            .ctm
            .concat(text_matrix_with_rise(text_matrix, state.text_rise))
            .concat(Matrix {
                a: state.font_size * state.horizontal_scale / 1000.0,
                d: state.font_size / 1000.0,
                ..Matrix::IDENTITY
            });
        if let Some((bounds, commands)) = transformed_source_glyph_path(commands, transform) {
            let fill = matches!(state.text_render_mode, 0 | 2 | 4 | 6);
            let stroke = matches!(state.text_render_mode, 1 | 2 | 5 | 6);
            context.push_object(
                ObjectKind::Shape,
                bounds,
                None,
                apply_clips(
                    apply_pdf_stroke_style(
                        Visual::PaintedShape {
                            geometry: Geometry::Path {
                                fill_rule: FillRule::NonZero,
                                commands,
                            },
                            fill: if fill {
                                Paint::Solid(with_alpha(state.fill, state.fill_alpha))
                            } else {
                                Paint::None
                            },
                            stroke: if stroke {
                                Paint::Solid(with_alpha(state.stroke, state.stroke_alpha))
                            } else {
                                Paint::None
                            },
                            stroke_width: if stroke {
                                state.line_width * state.ctm.scale()
                            } else {
                                0.0
                            },
                        },
                        state,
                        stroke,
                    ),
                    bounds,
                    state,
                ),
                pdf_source(
                    "path",
                    Some(source_object),
                    Some(offset),
                    MappingQuality::Exact,
                ),
            )?;
        }
        text_matrix = text_matrix.concat(Matrix {
            e: glyph_advance,
            f: 0.0,
            ..Matrix::IDENTITY
        });
    }
    Ok(())
}

fn source_glyph_clip(
    glyphs: &[DecodedGlyph],
    font: &FontInfo,
    state: &GraphicsState,
) -> Option<PdfClip> {
    let mut text_matrix = state.text_matrix;
    let mut paths = Vec::new();
    let mut total_commands = 0_usize;
    for glyph in glyphs {
        let glyph_advance = (font
            .widths
            .get(&glyph.code)
            .copied()
            .unwrap_or(font.default_width)
            / 1000.0
            * state.font_size
            + state.char_spacing
            + if glyph.code == 32 {
                state.word_spacing
            } else {
                0.0
            })
            * state.horizontal_scale;
        if let Some(commands) = font.source_glyph_outlines.get(&glyph.code) {
            total_commands = total_commands.checked_add(commands.len())?;
            if total_commands > MAX_PATH_COMMANDS {
                return None;
            }
            let transform = state
                .ctm
                .concat(text_matrix_with_rise(text_matrix, state.text_rise))
                .concat(Matrix {
                    a: state.font_size * state.horizontal_scale / 1000.0,
                    d: state.font_size / 1000.0,
                    ..Matrix::IDENTITY
                });
            if let Some(path) = transformed_source_glyph_path(commands, transform) {
                paths.push(path);
            }
        }
        text_matrix = text_matrix.concat(Matrix {
            e: glyph_advance,
            f: 0.0,
            ..Matrix::IDENTITY
        });
    }
    let first = paths.first()?.0;
    let clip_bounds = paths.iter().skip(1).fold(first, |bounds, (path, _)| {
        let x0 = bounds.x.min(path.x);
        let y0 = bounds.y.min(path.y);
        let x1 = (bounds.x + bounds.width).max(path.x + path.width);
        let y1 = (bounds.y + bounds.height).max(path.y + path.height);
        Rect {
            x: x0,
            y: y0,
            width: x1 - x0,
            height: y1 - y0,
        }
    });
    let mut commands = Vec::with_capacity(total_commands);
    for (path_bounds, path_commands) in paths {
        commands.extend(translate_path_commands(
            &path_commands,
            path_bounds.x - clip_bounds.x,
            path_bounds.y - clip_bounds.y,
        ));
    }
    Some(PdfClip {
        bounds: clip_bounds,
        fill_rule: FillRule::NonZero,
        commands,
    })
}

fn transformed_source_glyph_path(
    commands: &[PathCommand],
    transform: Matrix,
) -> Option<(Rect, Vec<PathCommand>)> {
    let mut path = PdfPath::default();
    for command in commands {
        match *command {
            PathCommand::MoveTo { x, y } => {
                let point = transform.point(x, y);
                path.point(
                    PathCommand::MoveTo {
                        x: point.0,
                        y: point.1,
                    },
                    &[point],
                );
            }
            PathCommand::LineTo { x, y } => {
                let point = transform.point(x, y);
                path.point(
                    PathCommand::LineTo {
                        x: point.0,
                        y: point.1,
                    },
                    &[point],
                );
            }
            PathCommand::QuadraticCurveTo { cpx, cpy, x, y } => {
                let control = transform.point(cpx, cpy);
                let point = transform.point(x, y);
                path.point(
                    PathCommand::QuadraticCurveTo {
                        cpx: control.0,
                        cpy: control.1,
                        x: point.0,
                        y: point.1,
                    },
                    &[control, point],
                );
            }
            PathCommand::BezierCurveTo {
                cp1x,
                cp1y,
                cp2x,
                cp2y,
                x,
                y,
            } => {
                let control_1 = transform.point(cp1x, cp1y);
                let control_2 = transform.point(cp2x, cp2y);
                let point = transform.point(x, y);
                path.point(
                    PathCommand::BezierCurveTo {
                        cp1x: control_1.0,
                        cp1y: control_1.1,
                        cp2x: control_2.0,
                        cp2y: control_2.1,
                        x: point.0,
                        y: point.1,
                    },
                    &[control_1, control_2, point],
                );
            }
            PathCommand::ClosePath => path.commands.push(PathCommand::ClosePath),
        }
    }
    path.painted()
}

fn cid_glyph_text(glyphs: &[DecodedGlyph]) -> String {
    glyphs
        .iter()
        .filter(|glyph| glyph.code != 0)
        .filter_map(|glyph| char::from_u32(pdf_cid_glyph_codepoint(glyph.code)?))
        .collect()
}

fn pdf_cid_glyph_codepoint(cid: u32) -> Option<u32> {
    // Chromium and Firefox reliably select CFF glyphs through a BMP cmap. Keep
    // the common low CID range there, as PDF.js does, and reserve plane 15 for
    // larger collections that cannot fit in the BMP private-use area.
    if cid <= 0xf8ff - PDF_CID_BMP_PUA_START {
        PDF_CID_BMP_PUA_START.checked_add(cid)
    } else {
        PDF_CID_PUA_START
            .checked_add(cid)
            .filter(|codepoint| *codepoint <= 0x10_ffff)
    }
}

fn simple_glyph_text(glyphs: &[DecodedGlyph], font: &FontInfo) -> String {
    glyphs
        .iter()
        .flat_map(|glyph| {
            if glyph.text.chars().all(char::is_whitespace)
                && font
                    .widths
                    .get(&glyph.code)
                    .is_some_and(|width| *width <= 0.0)
            {
                return Vec::new();
            }
            let source_glyph = font.browser_source_glyph_font
                || font.browser_source_glyph_codes.contains(&glyph.code)
                || (font.browser_contextual_source_glyphs && is_arabic_glyph_text(&glyph.text));
            let visual = if source_glyph {
                u8::try_from(glyph.code)
                    .ok()
                    .and_then(|code| char::from_u32(PDF_SIMPLE_GLYPH_PUA_START + u32::from(code)))
                    .map(|character| character.to_string())
            } else {
                Some(glyph.text.clone())
            };
            visual.unwrap_or_default().chars().collect::<Vec<_>>()
        })
        .collect()
}

#[cfg(feature = "pdf-formats")]
struct PdfGlyphOutlinePen {
    commands: Vec<PathCommand>,
    scale: f32,
}

#[cfg(feature = "pdf-formats")]
impl Default for PdfGlyphOutlinePen {
    fn default() -> Self {
        Self {
            commands: Vec::new(),
            scale: 1.0,
        }
    }
}

#[cfg(feature = "pdf-formats")]
impl OutlinePen for PdfGlyphOutlinePen {
    fn move_to(&mut self, x: f32, y: f32) {
        self.commands.push(PathCommand::MoveTo {
            x: x * self.scale,
            y: y * self.scale,
        });
    }

    fn line_to(&mut self, x: f32, y: f32) {
        self.commands.push(PathCommand::LineTo {
            x: x * self.scale,
            y: y * self.scale,
        });
    }

    fn quad_to(&mut self, cpx: f32, cpy: f32, x: f32, y: f32) {
        self.commands.push(PathCommand::QuadraticCurveTo {
            cpx: cpx * self.scale,
            cpy: cpy * self.scale,
            x: x * self.scale,
            y: y * self.scale,
        });
    }

    fn curve_to(&mut self, cp1x: f32, cp1y: f32, cp2x: f32, cp2y: f32, x: f32, y: f32) {
        self.commands.push(PathCommand::BezierCurveTo {
            cp1x: cp1x * self.scale,
            cp1y: cp1y * self.scale,
            cp2x: cp2x * self.scale,
            cp2y: cp2y * self.scale,
            x: x * self.scale,
            y: y * self.scale,
        });
    }

    fn close(&mut self) {
        self.commands.push(PathCommand::ClosePath);
    }
}

#[cfg(feature = "pdf-formats")]
fn source_glyph_outlines(font_bytes: &[u8], info: &FontInfo) -> BTreeMap<u32, Vec<PathCommand>> {
    let Ok(font) = FontRef::new(font_bytes) else {
        return BTreeMap::new();
    };
    let scale = sfnt_table(font_bytes, b"head")
        .and_then(|head| read_u16(head, 18))
        .filter(|units_per_em| *units_per_em > 0)
        .map_or(1.0, |units_per_em| 1_000.0 / f32::from(units_per_em));
    let charmap = font.charmap();
    let outlines = font.outline_glyphs();
    let mut result = BTreeMap::new();
    for code in u8::MIN..=u8::MAX {
        let codepoint = if info.browser_source_glyph_font {
            Some(PDF_SIMPLE_GLYPH_PUA_START + u32::from(code))
        } else {
            info.to_unicode.get(&[code][..]).and_then(|text| {
                let mut characters = text.chars();
                let character = characters.next()?;
                characters.next().is_none().then_some(character as u32)
            })
        };
        let Some(character) = codepoint.and_then(char::from_u32) else {
            continue;
        };
        let Some(glyph_id) = charmap.map(character) else {
            continue;
        };
        let Some(glyph) = outlines.get(glyph_id) else {
            continue;
        };
        let mut pen = PdfGlyphOutlinePen {
            commands: Vec::new(),
            scale,
        };
        if glyph
            .draw(
                DrawSettings::unhinted(Size::unscaled(), LocationRef::default()),
                &mut pen,
            )
            .is_ok()
            && !pen.commands.is_empty()
            && pen.commands.len() <= MAX_PATH_COMMANDS
        {
            result.insert(u32::from(code), pen.commands);
        }
    }
    result
}

fn pdf_jpx_media_type(bytes: &[u8]) -> &'static str {
    if bytes.starts_with(b"\xff\x4f\xff\x51") {
        "image/j2k"
    } else {
        "image/jp2"
    }
}

fn pdf_jpeg_asset(mut bytes: Vec<u8>) -> Vec<u8> {
    if bytes.starts_with(&[0xff, 0xd8]) && !bytes.windows(2).any(|window| window == [0xff, 0xd9]) {
        bytes.extend_from_slice(&[0xff, 0xd9]);
    }
    bytes
}

fn pdf_image_media_type(media_type: String, dict: &PdfDict) -> String {
    if matches!(dict.get("Interpolate"), Some(PdfValue::Bool(true)))
        || media_type.contains(";interpolate=")
    {
        media_type
    } else {
        format!("{media_type};interpolate=false")
    }
}

fn pdf_pattern_stencil_visual(
    pattern_name: &str,
    resources: Option<&PdfValue>,
    state: &GraphicsState,
    context: &PageContext<'_>,
    bounds: Rect,
    image_dict: &PdfDict,
    painted_sample: u8,
    mask_media_type: &str,
    mask_bytes: &[u8],
) -> Option<Visual> {
    let (_, pattern) = resource_entry(resources, "Pattern", pattern_name, context.store)?;
    let pattern = context.store.dict(pattern)?;
    if pattern.get("PatternType").and_then(number_usize) != Some(2) {
        return None;
    }
    let shading = pattern
        .get("Shading")
        .and_then(|value| context.store.resolve(value))?;
    let shading = context.store.dict(shading)?;
    if shading.get("ShadingType").and_then(number_usize) != Some(2) {
        return None;
    }
    let [x0, y0, x1, y1] = shading
        .get("Coords")
        .and_then(|value| context.store.resolve(value))
        .and_then(|value| match value {
            PdfValue::Array(values) => last_numbers::<4>(values),
            _ => None,
        })?;
    let function = shading.get("Function")?;
    let color_space = shading.get("ColorSpace")?;
    let stops = shading_stops(function, color_space, context.store, context.limits, 1.0)?;
    let pattern_matrix = pattern
        .get("Matrix")
        .and_then(|value| six_numbers_value(context.store, value))
        .map(matrix)
        .unwrap_or(Matrix::IDENTITY);
    let transform = state.pattern_base_ctm.concat(pattern_matrix);
    let start = transform.point(x0, y0);
    let end = transform.point(x1, y1);
    let axis = (end.0 - start.0, end.1 - start.1);
    let length_squared = axis.0 * axis.0 + axis.1 * axis.1;
    if !length_squared.is_finite() || length_squared <= f32::EPSILON {
        return None;
    }
    let width = image_dict.get("Width").and_then(number_usize)?;
    let height = image_dict.get("Height").and_then(number_usize)?;
    let pixels = width.checked_mul(height)?;
    if width == 0
        || height == 0
        || bounds.width <= 0.0
        || bounds.height <= 0.0
        || pixels > context.limits.max_render_pixels
    {
        return None;
    }
    let scale_x = width as f32 / bounds.width;
    let scale_y = height as f32 / bounds.height;
    let svg_start = (
        (start.0 - bounds.x) * scale_x,
        (bounds.y + bounds.height - start.1) * scale_y,
    );
    let svg_end = (
        (end.0 - bounds.x) * scale_x,
        (bounds.y + bounds.height - end.1) * scale_y,
    );
    if ![svg_start.0, svg_start.1, svg_end.0, svg_end.1]
        .into_iter()
        .all(f32::is_finite)
    {
        return None;
    }
    let mut svg = format!(
        "<svg xmlns='http://www.w3.org/2000/svg' width='{width}' height='{height}' viewBox='0 0 {width} {height}'><defs><linearGradient id='g' gradientUnits='userSpaceOnUse' x1='{}' y1='{}' x2='{}' y2='{}'>",
        svg_start.0, svg_start.1, svg_end.0, svg_end.1
    );
    for stop in stops {
        let [red, green, blue, alpha] = stop.color.to_be_bytes();
        svg.push_str(&format!(
            "<stop offset='{}' stop-color='#{red:02x}{green:02x}{blue:02x}' stop-opacity='{}'/>",
            stop.offset.clamp(0.0, 1.0),
            f32::from(alpha) / 255.0
        ));
    }
    svg.push_str("</linearGradient></defs><rect width='100%' height='100%' fill='url(#g)'/></svg>");
    let bytes = svg.into_bytes();
    if bytes.len() > context.limits.max_entry_uncompressed_bytes {
        return None;
    }
    Some(Visual::MaskedImage {
        media_type: "image/svg+xml".to_owned(),
        bytes,
        resource_id: 0,
        mask_resource_id: 0,
        mask_width: u32::try_from(width).ok()?,
        mask_height: u32::try_from(height).ok()?,
        // The complete patterned image is converted from PDF image space by
        // transform_image_visual; flipping the decoded stencil independently
        // would invert its content relative to the page-fixed shading raster.
        mask_media_type: format!("{mask_media_type};pdf-stencil-painted={painted_sample}"),
        alpha_mask: mask_bytes.to_vec(),
        crop: ImageCrop::default(),
    })
}

fn pdf_reduced_raster_dimensions(
    width: usize,
    height: usize,
    max_pixels: usize,
) -> Option<(u8, usize, usize)> {
    let mut reduce_power = 0_u8;
    let mut reduced_width = width;
    let mut reduced_height = height;
    while reduced_width
        .checked_mul(reduced_height)
        .is_none_or(|pixels| pixels > max_pixels)
    {
        reduce_power = reduce_power.checked_add(1)?;
        if reduce_power >= usize::BITS as u8 {
            return None;
        }
        let factor = 1_usize << reduce_power;
        reduced_width = width.div_ceil(factor);
        reduced_height = height.div_ceil(factor);
    }
    Some((reduce_power, reduced_width, reduced_height))
}

fn pdf_safe_decoded_raster_pixels(limits: Limits) -> usize {
    limits
        .max_render_pixels
        .min(limits.max_entry_uncompressed_bytes / 4)
}

fn pdf_jpx_reduced_asset(dict: &PdfDict, mut bytes: Vec<u8>, limits: Limits) -> Vec<u8> {
    let Some((reduce_power, _, _)) = dict
        .get("Width")
        .and_then(number_usize)
        .zip(dict.get("Height").and_then(number_usize))
        .and_then(|(width, height)| {
            pdf_reduced_raster_dimensions(width, height, pdf_safe_decoded_raster_pixels(limits))
        })
    else {
        return bytes;
    };
    if reduce_power > 0 {
        if bytes.starts_with(b"\0\0\0\x0cjP  \r\n\x87\n") {
            bytes.extend_from_slice(&17_u32.to_be_bytes());
            bytes.extend_from_slice(b"free");
        }
        bytes.extend_from_slice(b"OVPJPXRD");
        bytes.push(reduce_power);
    }
    bytes
}

fn pdf_jpx_asset(
    dict: &PdfDict,
    mut bytes: Vec<u8>,
    store: &ObjectStore,
    limits: Limits,
) -> Vec<u8> {
    if dict.get("SMaskInData").and_then(number_usize) != Some(2) {
        if dict
            .get("SMask")
            .and_then(|value| store.resolve(value))
            .is_some_and(|value| matches!(value, PdfValue::Stream { .. }))
        {
            if bytes.starts_with(b"\0\0\0\x0cjP  \r\n\x87\n") {
                bytes.extend_from_slice(&17_u32.to_be_bytes());
                bytes.extend_from_slice(b"free");
            }
            let components = dict
                .get("ColorSpace")
                .and_then(|value| image_color_space(value, store, 0))
                .map_or(0, RasterColorSpace::components);
            bytes.extend_from_slice(b"OVPJPXOP");
            bytes.push(u8::try_from(components).unwrap_or(0));
        }
        return pdf_jpx_reduced_asset(dict, bytes, limits);
    }
    let color = match dict.get("Matte").and_then(|value| store.resolve(value)) {
        Some(PdfValue::Array(values)) => {
            let components: Vec<_> = values.iter().filter_map(number_f32).collect();
            let color_space = dict
                .get("ColorSpace")
                .cloned()
                .unwrap_or_else(|| PdfValue::Name("DeviceRGB".to_owned()));
            color_from_space_value(&color_space, &components, store, 0).unwrap_or(0x0000_00ff)
        }
        _ => 0x0000_00ff,
    };
    if bytes.starts_with(b"\0\0\0\x0cjP  \r\n\x87\n") {
        bytes.extend_from_slice(&19_u32.to_be_bytes());
        bytes.extend_from_slice(b"free");
    }
    bytes.extend_from_slice(b"OVPMATTE");
    bytes.extend_from_slice(&color.to_be_bytes()[..3]);
    pdf_jpx_reduced_asset(dict, bytes, limits)
}

fn paint_inline_image(
    value: &PdfValue,
    resources: Option<&PdfValue>,
    state: &GraphicsState,
    context: &mut PageContext<'_>,
    offset: usize,
) -> Result<(), Diagnostic> {
    let PdfValue::Stream { dict, .. } = value else {
        return Ok(());
    };
    let Some(bounds) = bounds(&[
        state.ctm.point(0.0, 0.0),
        state.ctm.point(1.0, 0.0),
        state.ctm.point(1.0, 1.0),
        state.ctm.point(0.0, 1.0),
    ]) else {
        return Ok(());
    };
    let stencil_sample = pdf_stencil_painted_sample(dict, context.store);
    let filter = filter_names(dict);
    let ccitt = pdf_oversized_ccitt_bmp_asset(value, dict, context.store, context.limits)
        .map(|(_, _, bytes)| ("image/bmp".to_owned(), bytes))
        .or_else(|| {
            pdf_ccitt_tiff_asset(value, dict, context.store, context.limits)
                .map(|bytes| ("image/tiff".to_owned(), bytes))
        });
    let ccitt_stencil = ccitt.as_ref().and(stencil_sample);
    let cmyk_jpeg = pdf_cmyk_jpeg_asset(value, dict, context.store, context.limits);
    let rgb_jpeg = pdf_rgb_jpeg_asset(value, dict, context.store, context.limits);
    let (media_type, mut bytes) = if let Some(bytes) = cmyk_jpeg {
        ("image/bmp".to_owned(), bytes)
    } else if let Some(bytes) = rgb_jpeg {
        ("image/bmp".to_owned(), bytes)
    } else if let Some((media_type, bytes)) = ccitt {
        (media_type, bytes)
    } else {
        match filter.last().map(String::as_str) {
            Some("DCTDecode") => (
                "image/jpeg".to_owned(),
                pdf_jpeg_asset(decode_stream(value, context.store, context.limits)?),
            ),
            Some("JPXDecode") => {
                let bytes = pdf_jpx_asset(
                    dict,
                    decode_stream(value, context.store, context.limits)?,
                    context.store,
                    context.limits,
                );
                (pdf_jpx_media_type(&bytes).to_owned(), bytes)
            }
            _ if filter.iter().any(|filter| filter == "JBIG2Decode") => {
                let Some(bytes) = pdf_jbig2_bmp_asset(value, dict, context.store, context.limits)
                else {
                    context.warning_at(
                        "image-filter-jbig2",
                        "PDF_IMAGE_FILTER_UNSUPPORTED: JBIG2Decode image could not be materialized",
                        Some(bounds),
                    );
                    return Ok(());
                };
                ("image/bmp".to_owned(), bytes)
            }
            _ => {
                let decoded = decode_stream(value, context.store, context.limits)?;
                let stencil = state.fill_pattern.is_none().then(|| {
                    pdf_stencil_mask_to_bmp(
                        dict,
                        &decoded,
                        context.store,
                        context.limits,
                        state.fill,
                    )
                });
                let Some(bytes) = stencil
                    .flatten()
                    .or_else(|| pdf_image_to_bmp(dict, &decoded, context.store, context.limits))
                else {
                    context.warning_at(
                    "inline-image",
                    "PDF_INLINE_IMAGE_UNSUPPORTED: the inline image color space, bit depth, predictor, or mask is not supported",
                    Some(bounds),
                );
                    return Ok(());
                };
                ("image/bmp".to_owned(), bytes)
            }
        }
    };
    if media_type == "image/bmp"
        && let Some(maps) = &state.transfer_maps
    {
        let _ = apply_pdf_transfer_maps_to_bmp(&mut bytes, maps);
    }
    let patterned_stencil = match (
        state.fill_pattern.as_deref(),
        ccitt_stencil,
        media_type.starts_with("image/").then_some(bytes.as_slice()),
    ) {
        (Some(pattern), Some(painted_sample), Some(mask)) => pdf_pattern_stencil_visual(
            pattern,
            resources,
            state,
            context,
            bounds,
            dict,
            painted_sample,
            &media_type,
            mask,
        ),
        _ => None,
    };
    if stencil_sample.is_some() && state.fill_pattern.is_some() && patterned_stencil.is_none() {
        context.warning_at(
            "image-stencil-pattern",
            "PDF_IMAGE_MASK_UNSUPPORTED: a stencil image uses an unsupported pattern paint",
            Some(bounds),
        );
        return Ok(());
    }
    let has_patterned_stencil = patterned_stencil.is_some();
    let mut visual = patterned_stencil.unwrap_or_else(|| Visual::Image {
        media_type: pdf_image_media_type(media_type, dict),
        bytes,
        crop: ImageCrop::default(),
    });
    if !has_patterned_stencil && let Some(painted_sample) = ccitt_stencil {
        visual = pdf_stencil_visual(visual, painted_sample, state.fill);
    }
    let visual = if state.fill_alpha < 1.0 {
        Visual::Layer {
            transform: AffineTransform::IDENTITY,
            opacity: state.fill_alpha,
            blend_mode: BlendMode::Normal,
            visual: Box::new(visual),
        }
    } else {
        visual
    };
    let visual = transform_image_visual(visual, bounds, state.ctm);
    context.push_object(
        ObjectKind::Image,
        bounds,
        None,
        apply_clips(visual, bounds, state),
        pdf_source("image", None, Some(offset), MappingQuality::Exact),
    )
}

fn paint_xobject(
    name: &str,
    resources: Option<&PdfValue>,
    state: &GraphicsState,
    context: &mut PageContext<'_>,
    offset: usize,
    depth: usize,
) -> Result<(), Diagnostic> {
    let Some((id, value)) = resource_entry(resources, "XObject", name, context.store) else {
        return Ok(());
    };
    let PdfValue::Stream { dict, .. } = value else {
        return Ok(());
    };
    if dict.get("OC").is_some_and(|optional_content| {
        !optional_content_visible(
            optional_content,
            resources,
            context.store,
            context.optional_content,
        )
    }) {
        return Ok(());
    }
    match dict_name(dict, "Subtype") {
        Some("Image") => {
            let image_bounds = bounds(&[
                state.ctm.point(0.0, 0.0),
                state.ctm.point(1.0, 0.0),
                state.ctm.point(1.0, 1.0),
                state.ctm.point(0.0, 1.0),
            ]);
            let stencil_sample = pdf_stencil_painted_sample(dict, context.store);
            let filter = filter_names(dict);
            let compressed_raster = state
                .transfer_maps
                .is_none()
                .then(|| pdf_compressed_raster_asset(value, dict, context.store, context.limits))
                .flatten();
            let ccitt_raster =
                pdf_oversized_ccitt_bmp_asset(value, dict, context.store, context.limits)
                    .map(|(_, _, bytes)| ("image/bmp".to_owned(), bytes))
                    .or_else(|| {
                        pdf_ccitt_tiff_asset(value, dict, context.store, context.limits)
                            .map(|bytes| ("image/tiff".to_owned(), bytes))
                    });
            let ccitt_stencil = ccitt_raster.as_ref().and(stencil_sample);
            let cmyk_jpeg = pdf_cmyk_jpeg_asset(value, dict, context.store, context.limits);
            let rgb_jpeg = pdf_rgb_jpeg_asset(value, dict, context.store, context.limits);
            let has_explicit_image_mask = dict
                .get("Mask")
                .and_then(|value| context.store.resolve(value))
                .is_some_and(|value| matches!(value, PdfValue::Stream { .. }));
            let independently_decoded_mask = cmyk_jpeg.is_some()
                || rgb_jpeg.is_some()
                || compressed_raster.is_some()
                || ccitt_raster.is_some()
                || has_explicit_image_mask
                || matches!(
                    filter.last().map(String::as_str),
                    Some("DCTDecode" | "JPXDecode")
                );
            let has_soft_mask = pdf_image_has_soft_mask(dict, context.store);
            let reusable_masked_image = independently_decoded_mask && has_soft_mask;
            let cached_media_type = (reusable_masked_image && id != (0, 0))
                .then(|| context.image_resources.get(&id))
                .flatten()
                .cloned();
            let (media_type, mut image_bytes) = if let Some(media_type) = cached_media_type {
                (media_type, Vec::new())
            } else if let Some(bytes) = cmyk_jpeg {
                ("image/bmp".to_owned(), bytes)
            } else if let Some(bytes) = rgb_jpeg {
                ("image/bmp".to_owned(), bytes)
            } else if let Some((media_type, bytes)) = ccitt_raster {
                (media_type, bytes)
            } else if filter.last().map(String::as_str) == Some("DCTDecode") {
                (
                    "image/jpeg".to_owned(),
                    pdf_jpeg_asset(decode_stream(value, context.store, context.limits)?),
                )
            } else if filter.last().map(String::as_str) == Some("JPXDecode") {
                let bytes = pdf_jpx_asset(
                    dict,
                    decode_stream(value, context.store, context.limits)?,
                    context.store,
                    context.limits,
                );
                (pdf_jpx_media_type(&bytes).to_owned(), bytes)
            } else if let Some(bytes) =
                pdf_jbig2_bmp_asset(value, dict, context.store, context.limits)
            {
                ("image/bmp".to_owned(), bytes)
            } else if filter.iter().any(|filter| filter == "JBIG2Decode") {
                context.warning_at(
                    "image-filter-jbig2",
                    "PDF_IMAGE_FILTER_UNSUPPORTED: JBIG2Decode image could not be materialized",
                    image_bounds,
                );
                return Ok(());
            } else if let Some(bytes) = compressed_raster {
                ("image/x-officeviewer-pdf-raster".to_owned(), bytes)
            } else {
                let decoded = decode_stream(value, context.store, context.limits)?;
                let stencil = state.fill_pattern.is_none().then(|| {
                    pdf_stencil_mask_to_bmp(
                        dict,
                        &decoded,
                        context.store,
                        context.limits,
                        state.fill,
                    )
                });
                match stencil
                    .flatten()
                    .or_else(|| pdf_image_to_bmp(dict, &decoded, context.store, context.limits))
                {
                    Some(bytes) => ("image/bmp".to_owned(), bytes),
                    None => {
                        context.warning_at("image-filter", "PDF_IMAGE_FILTER_UNSUPPORTED: the PDF image color space, bit depth, predictor, or mask is not yet supported", image_bounds);
                        return Ok(());
                    }
                }
            };
            if media_type == "image/bmp"
                && let Some(maps) = &state.transfer_maps
            {
                let _ = apply_pdf_transfer_maps_to_bmp(&mut image_bytes, maps);
            }
            let media_type = pdf_image_media_type(media_type, dict);
            if reusable_masked_image && id != (0, 0) && !context.image_resources.contains_key(&id) {
                context.image_resources.insert(id, media_type.clone());
            }
            let mask = if independently_decoded_mask && has_soft_mask {
                let mask_id = match dict.get("SMask").or_else(|| dict.get("Mask")) {
                    Some(PdfValue::Ref(id)) => *id,
                    _ => (0, 0),
                };
                let Some(width) = dict.get("Width").and_then(number_usize) else {
                    return Ok(());
                };
                let Some(height) = dict.get("Height").and_then(number_usize) else {
                    return Ok(());
                };
                let (mask_media_type, mask_width, mask_height, mask) = if mask_id != (0, 0)
                    && let Some((media_type, mask_width, mask_height)) =
                        context.image_masks.get(&mask_id)
                {
                    (media_type.clone(), *mask_width, *mask_height, Vec::new())
                } else {
                    let Some((mask_media_type, mask_width, mask_height, mask)) =
                        pdf_image_soft_mask_asset(
                            dict,
                            context.store,
                            context.limits,
                            width,
                            height,
                        )
                    else {
                        context.warning_at(
                                "image-mask",
                                "PDF_IMAGE_MASK_UNSUPPORTED: the PDF image soft mask could not be decoded",
                                image_bounds,
                            );
                        return Ok(());
                    };
                    if mask_id != (0, 0) {
                        context
                            .image_masks
                            .insert(mask_id, (mask_media_type.clone(), mask_width, mask_height));
                    }
                    (mask_media_type, mask_width, mask_height, mask)
                };
                Some((mask_id.0, mask_width, mask_height, mask_media_type, mask))
            } else {
                None
            };
            let bounds = image_bounds.ok_or_else(object_limit)?;
            let patterned_stencil = match (
                state.fill_pattern.as_deref(),
                ccitt_stencil,
                (media_type.starts_with("image/")).then_some(image_bytes.as_slice()),
            ) {
                (Some(pattern), Some(painted_sample), Some(mask)) => pdf_pattern_stencil_visual(
                    pattern,
                    resources,
                    state,
                    context,
                    bounds,
                    dict,
                    painted_sample,
                    &media_type,
                    mask,
                ),
                _ => None,
            };
            if stencil_sample.is_some()
                && state.fill_pattern.is_some()
                && patterned_stencil.is_none()
            {
                context.warning_at(
                    "image-stencil-pattern",
                    "PDF_IMAGE_MASK_UNSUPPORTED: a stencil image uses an unsupported pattern paint",
                    Some(bounds),
                );
                return Ok(());
            }
            let mut visual = if let Some(visual) = patterned_stencil {
                visual
            } else if let Some((
                mask_resource_id,
                mask_width,
                mask_height,
                mask_media_type,
                alpha_mask,
            )) = mask
            {
                Visual::MaskedImage {
                    media_type,
                    bytes: image_bytes,
                    resource_id: id.0,
                    mask_resource_id,
                    mask_width,
                    mask_height,
                    mask_media_type,
                    alpha_mask,
                    crop: ImageCrop::default(),
                }
            } else {
                Visual::Image {
                    media_type,
                    bytes: image_bytes,
                    crop: ImageCrop::default(),
                }
            };
            if state.fill_pattern.is_none()
                && let Some(painted_sample) = ccitt_stencil
            {
                visual = pdf_stencil_visual(visual, painted_sample, state.fill);
            }
            let visual = if state.fill_alpha < 1.0 {
                Visual::Layer {
                    transform: AffineTransform::IDENTITY,
                    opacity: state.fill_alpha,
                    blend_mode: BlendMode::Normal,
                    visual: Box::new(visual),
                }
            } else {
                visual
            };
            let visual = transform_image_visual(visual, bounds, state.ctm);
            context.push_object(
                ObjectKind::Image,
                bounds,
                None,
                apply_clips(visual, bounds, state),
                pdf_source("image", Some(id.0), Some(offset), MappingQuality::Exact),
            )?;
        }
        Some("Form") => {
            let nested_knockout_group = is_knockout_transparency_group(dict, context.store);
            let knockout_invocation =
                state.knockout_group && context.objects.len() > state.knockout_group_start;
            if !context.active_forms.insert(id) {
                context.form_cycle_count = context.form_cycle_count.saturating_add(1);
                context.warning(
                    "form-cycle",
                    "PDF_FORM_CYCLE_OMITTED: a recursive Form XObject invocation was isolated and omitted",
                );
                return Ok(());
            }
            let form_matrix = dict
                .get("Matrix")
                .and_then(|value| six_numbers_value(context.store, value))
                .map(matrix)
                .unwrap_or(Matrix::IDENTITY);
            let resources = dict.get("Resources").or(resources);
            let decoded = decode_stream(value, context.store, context.limits)?;
            let mut form_state = state.clone();
            form_state.ctm = form_state.ctm.concat(form_matrix);
            form_state.pattern_base_ctm = form_state.ctm;
            if let Some([x0, y0, x1, y1]) = dict
                .get("BBox")
                .and_then(|value| pdf_box(context.store, value))
            {
                if form_state.clips.len() >= MAX_CLIP_DEPTH {
                    context.active_forms.remove(&id);
                    return Err(pdf_error(
                        offset,
                        "PDF clipping depth exceeds the parser limit",
                    ));
                }
                let points = [
                    form_state.ctm.point(x0, y0),
                    form_state.ctm.point(x1, y0),
                    form_state.ctm.point(x1, y1),
                    form_state.ctm.point(x0, y1),
                ];
                let mut path = PdfPath::default();
                path.point(
                    PathCommand::MoveTo {
                        x: points[0].0,
                        y: points[0].1,
                    },
                    &[points[0]],
                );
                for &(x, y) in &points[1..] {
                    path.point(PathCommand::LineTo { x, y }, &[(x, y)]);
                }
                path.commands.push(PathCommand::ClosePath);
                if let Some((bounds, commands)) = path.painted() {
                    form_state.clips.push(PdfClip {
                        bounds,
                        fill_rule: FillRule::NonZero,
                        commands,
                    });
                }
            }
            if is_transparency_group(dict, context.store) {
                // A transparency-group Form is first painted into its own
                // backdrop and then composited with the caller's graphics
                // state. Keep invocation alpha and blend mode separate when
                // the Form content selects its own ExtGState (commonly
                // `/ca 1` and `/BM /Normal`).
                form_state.transparency_group_fill_alpha = state.fill_alpha;
                form_state.transparency_group_stroke_alpha = state.stroke_alpha;
                form_state.transparency_group_soft_masks = state.soft_masks.clone();
                form_state.transparency_group_blend_mode = state.blend_mode;
                form_state.blend_mode = BlendMode::Normal;
                form_state.knockout_group = is_knockout_transparency_group(dict, context.store);
                if form_state.knockout_group {
                    form_state.knockout_group_start = context.objects.len();
                    form_state.knockout_backdrop_end = context.objects.len();
                }
            }
            let object_start = context.objects.len();
            let previous_parent = context.parent_numeric_id;
            let shared_clip = form_state
                .clips
                .iter()
                .map(|clip| clip.commands.len())
                .sum::<usize>()
                > 512;
            if shared_clip && let Some(bounds) = form_state.clips.first().map(|clip| clip.bounds) {
                let group = context.push_object_with_parent(
                    ObjectKind::Group,
                    bounds,
                    None,
                    apply_clips(Visual::None, bounds, &form_state),
                    pdf_source("form", Some(id.0), Some(offset), MappingQuality::Exact),
                    previous_parent,
                )?;
                context.parent_numeric_id = Some(group);
                form_state.clips.clear();
            }
            let result =
                interpret_content(&decoded, resources, context, form_state, id.0, depth + 1);
            context.parent_numeric_id = previous_parent;
            context.active_forms.remove(&id);
            if let Err(error) = result {
                if is_pdf_resource_limit(&error) {
                    return Err(error);
                }
                context.diagnostics.push(omitted_pdf_diagnostic(
                    error,
                    context.unit_index,
                    "A malformed PDF Form XObject was partially omitted",
                ));
                return Ok(());
            }
            if knockout_invocation {
                let clear_visuals = context.objects[object_start..]
                    .iter()
                    .map(|object| (object.bounds, object.visual.clone()))
                    .collect::<Vec<_>>();
                let knockout_z = i32::try_from(object_start.saturating_sub(1)).unwrap_or(i32::MAX);
                for (bounds, visual) in clear_visuals {
                    push_knockout_backdrop_restore(
                        context,
                        bounds,
                        &visual,
                        state,
                        id.0,
                        offset,
                        Some(knockout_z),
                        nested_knockout_group,
                    )?;
                }
            }
        }
        _ => {}
    }
    Ok(())
}

fn is_transparency_group(dict: &BTreeMap<String, PdfValue>, store: &ObjectStore) -> bool {
    dict.get("Group")
        .and_then(|value| store.dict(value))
        .and_then(|group| group.get("S"))
        .and_then(|value| store.resolve(value))
        .is_some_and(|value| matches!(value, PdfValue::Name(name) if name == "Transparency"))
}

fn is_knockout_transparency_group(dict: &PdfDict, store: &ObjectStore) -> bool {
    dict.get("Group")
        .and_then(|value| store.dict(value))
        .is_some_and(|group| {
            dict_name(group, "S") == Some("Transparency")
                && matches!(group.get("K"), Some(PdfValue::Bool(true)))
        })
}

fn knockout_clear_paint(paint: &Paint, preserve_alpha: bool) -> Paint {
    let alpha_stops = |stops: &[GradientStop]| {
        stops
            .iter()
            .map(|stop| GradientStop {
                offset: stop.offset,
                color: stop.color & 0xff,
            })
            .collect()
    };
    match paint {
        Paint::None => Paint::None,
        Paint::Solid(color) if preserve_alpha => Paint::Solid(*color & 0xff),
        Paint::LinearGradient {
            x0,
            y0,
            x1,
            y1,
            stops,
        } if preserve_alpha => Paint::LinearGradient {
            x0: *x0,
            y0: *y0,
            x1: *x1,
            y1: *y1,
            stops: alpha_stops(stops),
        },
        Paint::RadialGradient {
            x0,
            y0,
            r0,
            x1,
            y1,
            r1,
            stops,
        } if preserve_alpha => Paint::RadialGradient {
            x0: *x0,
            y0: *y0,
            r0: *r0,
            x1: *x1,
            y1: *y1,
            r1: *r1,
            stops: alpha_stops(stops),
        },
        Paint::Pattern {
            preset,
            foreground,
            background,
        } if preserve_alpha => Paint::Pattern {
            preset: preset.clone(),
            foreground: *foreground & 0xff,
            background: *background & 0xff,
        },
        _ => Paint::Solid(rgba(0, 0, 0)),
    }
}

fn knockout_clear_visual(visual: &Visual, preserve_alpha: bool) -> Option<Visual> {
    match visual {
        Visual::PaintedShape {
            geometry,
            fill,
            stroke,
            stroke_width,
        } => Some(Visual::PaintedShape {
            geometry: geometry.clone(),
            fill: knockout_clear_paint(fill, preserve_alpha),
            stroke: knockout_clear_paint(stroke, preserve_alpha),
            stroke_width: *stroke_width,
        }),
        Visual::Effect {
            shadow,
            clip,
            visual,
        } => knockout_clear_visual(visual, preserve_alpha).map(|visual| Visual::Effect {
            shadow: shadow.clone(),
            clip: clip.clone(),
            visual: Box::new(visual),
        }),
        Visual::StrokeStyle { style, visual } => {
            knockout_clear_visual(visual, preserve_alpha).map(|visual| Visual::StrokeStyle {
                style: style.clone(),
                visual: Box::new(visual),
            })
        }
        // PDF blend-mode layers use identity geometry here. Do not retain the
        // nested compositing operation: it would override the destination-out
        // operation used to clear the knockout backdrop.
        Visual::Layer { visual, .. } => knockout_clear_visual(visual, preserve_alpha),
        _ => None,
    }
}

fn push_knockout_clear(
    context: &mut PageContext<'_>,
    bounds: Rect,
    visual: &Visual,
    state: &GraphicsState,
    source_object: u32,
    offset: usize,
) -> Result<(), Diagnostic> {
    if !state.knockout_group || context.objects.len() <= state.knockout_group_start {
        return Ok(());
    }
    push_knockout_backdrop_restore(
        context,
        bounds,
        visual,
        state,
        source_object,
        offset,
        None,
        !state.soft_masks.is_empty(),
    )
}

fn push_knockout_backdrop_restore(
    context: &mut PageContext<'_>,
    bounds: Rect,
    visual: &Visual,
    state: &GraphicsState,
    source_object: u32,
    offset: usize,
    z: Option<i32>,
    preserve_alpha: bool,
) -> Result<(), Diagnostic> {
    let Some(clear) = knockout_clear_visual(visual, preserve_alpha) else {
        return Ok(());
    };
    let Some(Geometry::Path {
        fill_rule,
        commands,
    }) = knockout_clear_geometry(&clear)
    else {
        return Ok(());
    };
    context.push_object(
        ObjectKind::Shape,
        bounds,
        None,
        Visual::Layer {
            transform: AffineTransform::IDENTITY,
            opacity: 1.0,
            blend_mode: BlendMode::DestinationOut,
            visual: Box::new(clear),
        },
        pdf_source(
            "path",
            Some(source_object),
            Some(offset),
            MappingQuality::Approximate,
        ),
    )?;
    if let Some(z) = z
        && let Some(cleared) = context.objects.last_mut()
    {
        cleared.z = z;
    }
    let backdrop = context.objects[..state.knockout_backdrop_end]
        .iter()
        .filter(|object| object.visual != Visual::None && rects_overlap(object.bounds, bounds))
        .cloned()
        .collect::<Vec<_>>();
    for object in backdrop {
        let clip = Geometry::Path {
            fill_rule,
            commands: translate_path_commands(
                &commands,
                bounds.x - object.bounds.x,
                bounds.y - object.bounds.y,
            ),
        };
        let restored = Visual::Effect {
            shadow: None,
            clip: Some(clip),
            visual: Box::new(object.visual),
        };
        context.push_object_with_parent(
            object.kind,
            object.bounds,
            None,
            restored,
            pdf_source(
                "knockout-backdrop",
                Some(source_object),
                Some(offset),
                MappingQuality::Approximate,
            ),
            object.parent_numeric_id,
        )?;
        if let Some(z) = z
            && let Some(restored) = context.objects.last_mut()
        {
            restored.z = z;
        }
    }
    Ok(())
}

fn knockout_clear_geometry(visual: &Visual) -> Option<Geometry> {
    match visual {
        Visual::PaintedShape { geometry, fill, .. } if *fill != Paint::None => {
            Some(geometry.clone())
        }
        Visual::Effect { visual, .. }
        | Visual::StrokeStyle { visual, .. }
        | Visual::Layer { visual, .. } => knockout_clear_geometry(visual),
        _ => None,
    }
}

fn rects_overlap(left: Rect, right: Rect) -> bool {
    left.x < right.x + right.width
        && right.x < left.x + left.width
        && left.y < right.y + right.height
        && right.y < left.y + left.height
}

fn pdf_linear_soft_mask(
    mask: &PdfValue,
    invocation_ctm: Matrix,
    store: &ObjectStore,
    limits: Limits,
) -> Option<PdfSoftMask> {
    let mask = store.dict(mask)?;
    let alpha_mask = match mask.get("S").and_then(|value| store.resolve(value)) {
        Some(PdfValue::Name(name)) if name == "Alpha" => true,
        Some(PdfValue::Name(name)) if name == "Luminosity" => false,
        _ => return None,
    };
    let form = store.resolve(mask.get("G")?)?;
    let PdfValue::Stream { dict, .. } = form else {
        return None;
    };
    let resources = dict.get("Resources");
    let form_matrix = dict
        .get("Matrix")
        .and_then(|value| six_numbers_value(store, value))
        .map(matrix)
        .unwrap_or(Matrix::IDENTITY);
    let mut ctm = invocation_ctm.concat(form_matrix);
    let mask_clip = dict
        .get("BBox")
        .and_then(|value| pdf_box(store, value))
        .and_then(|[x0, y0, x1, y1]| {
            let points = [
                ctm.point(x0, y0),
                ctm.point(x1, y0),
                ctm.point(x1, y1),
                ctm.point(x0, y1),
            ];
            let mut path = PdfPath::default();
            path.point(
                PathCommand::MoveTo {
                    x: points[0].0,
                    y: points[0].1,
                },
                &[points[0]],
            );
            for &(x, y) in &points[1..] {
                path.point(PathCommand::LineTo { x, y }, &[(x, y)]);
            }
            path.commands.push(PathCommand::ClosePath);
            path.painted().map(|(bounds, commands)| PdfClip {
                bounds,
                fill_rule: FillRule::NonZero,
                commands,
            })
        });
    let mask_bounds = mask_clip.as_ref().map(|clip| clip.bounds);
    let transfer = |value: f32| {
        mask.get("TR")
            .and_then(|function| evaluate_color_function(function, &[value], store))
            .and_then(|values| values.first().copied())
            .unwrap_or(value)
            .clamp(0.0, 1.0)
    };
    let backdrop = if alpha_mask {
        0.0
    } else {
        mask.get("BC")
            .and_then(|value| store.resolve(value))
            .and_then(|value| match value {
                PdfValue::Array(values) => values.first().and_then(number_f32),
                _ => None,
            })
            .unwrap_or(0.0)
    };
    // A soft-mask backdrop is transformed once before it becomes the mask
    // sample outside the transparency-group form. Premultiplying it again
    // makes non-zero backdrops too transparent.
    let outside = transfer(backdrop);
    let decoded = decode_stream(form, store, limits).ok()?;
    let mut parser = ContentParser::new(&decoded, limits);
    let mut operands = Vec::new();
    let mut gray = 0.0;
    let mut fill_alpha = 1.0;
    let mut rectangle = None;
    let mut path_points = Vec::new();
    let mut stack = Vec::new();
    let mut rectangles = Vec::new();
    while let Some(token) = parser.next().ok()? {
        match token {
            ContentToken::Value(value) => operands.push(value),
            ContentToken::Operator(operator, _) => {
                if operator == "q" {
                    stack.push((ctm, gray, fill_alpha));
                } else if operator == "Q" {
                    if let Some(saved) = stack.pop() {
                        (ctm, gray, fill_alpha) = saved;
                    }
                } else if operator == "cm" {
                    if let Some(values) = six_numbers(&operands) {
                        ctm = ctm.concat(matrix(values));
                    }
                } else if matches!(operator, "g" | "G") {
                    if let Some(value) = last_number(&operands) {
                        gray = value.clamp(0.0, 1.0);
                    }
                } else if matches!(operator, "rg" | "RG") {
                    if let Some([red, green, blue]) = last_numbers::<3>(&operands) {
                        gray = (0.2126 * red + 0.7152 * green + 0.0722 * blue).clamp(0.0, 1.0);
                    }
                } else if matches!(operator, "sc" | "SC" | "scn" | "SCN") {
                    if let Some(PdfValue::Name(name)) = operands.last()
                        && let Some((_, pattern)) =
                            resource_entry(resources, "Pattern", name, store)
                        && let Some(pattern) = store.dict(pattern)
                        && pattern.get("PatternType").and_then(number_usize) == Some(2)
                        && let Some(shading) = pattern
                            .get("Shading")
                            .and_then(|value| store.resolve(value))
                        && let Some(shading) = store.dict(shading)
                    {
                        let shading_type = shading.get("ShadingType").and_then(number_usize);
                        let coordinates = shading
                            .get("Coords")
                            .and_then(|value| store.resolve(value))
                            .and_then(|value| match value {
                                PdfValue::Array(values) => {
                                    Some(values.iter().filter_map(number_f32).collect::<Vec<_>>())
                                }
                                _ => None,
                            })?;
                        let function = shading.get("Function")?;
                        let color_space = shading.get("ColorSpace")?;
                        let stops = shading_stops(function, color_space, store, limits, 1.0)?
                            .into_iter()
                            .map(|stop| {
                                let [red, green, blue, _] = stop.color.to_be_bytes();
                                let value = if alpha_mask {
                                    fill_alpha
                                } else {
                                    (0.2126 * f32::from(red)
                                        + 0.7152 * f32::from(green)
                                        + 0.0722 * f32::from(blue))
                                        / 255.0
                                        * fill_alpha
                                };
                                (stop.offset, transfer(value))
                            })
                            .collect();
                        let pattern_matrix = pattern
                            .get("Matrix")
                            .and_then(|value| six_numbers_value(store, value))
                            .map(matrix)
                            .unwrap_or(Matrix::IDENTITY);
                        let transform = ctm.concat(pattern_matrix);
                        let (start, end, radii) = match shading_type {
                            Some(2) if coordinates.len() == 4 => (
                                transform.point(coordinates[0], coordinates[1]),
                                transform.point(coordinates[2], coordinates[3]),
                                None,
                            ),
                            Some(3) if coordinates.len() == 6 => (
                                transform.point(coordinates[0], coordinates[1]),
                                transform.point(coordinates[3], coordinates[4]),
                                Some((
                                    coordinates[2].abs() * transform.scale(),
                                    coordinates[5].abs() * transform.scale(),
                                )),
                            ),
                            _ => return None,
                        };
                        return Some(PdfSoftMask {
                            start,
                            end,
                            radii,
                            stops,
                            bounds: mask_bounds,
                            clip: mask_clip,
                            outside,
                            regions: Vec::new(),
                            raster: None,
                        });
                    }
                    if let Some(value) = last_number(&operands) {
                        // A one-component ICCBased/DeviceGray soft-mask color
                        // is also its luminosity sample.
                        gray = value.clamp(0.0, 1.0);
                    }
                } else if operator == "Do"
                    && mask.get("TR").is_none()
                    && let Some(PdfValue::Name(name)) = operands.last()
                    && let Some((_, image)) = resource_entry(resources, "XObject", name, store)
                    && let PdfValue::Stream {
                        dict: image_dict, ..
                    } = image
                    && dict_name(image_dict, "Subtype") == Some("Image")
                {
                    if !alpha_mask
                        && image_dict.get("SMask").is_none()
                        && image_dict.get("BitsPerComponent").and_then(number_usize) == Some(8)
                        && image_color_space(image_dict.get("ColorSpace")?, store, 0)
                            == Some(RasterColorSpace::Gray)
                        && filter_names(image_dict).last().map(String::as_str) != Some("DCTDecode")
                    {
                        let width = image_dict.get("Width").and_then(number_usize)?;
                        let height = image_dict.get("Height").and_then(number_usize)?;
                        let decoded = decode_stream(image, store, limits).ok()?;
                        let samples = decode_image_predictor(
                            &decoded, image_dict, store, width, height, 1, 8,
                        )?;
                        if samples.len() != width.checked_mul(height)? {
                            return None;
                        }
                        let expected_bounds = mask_bounds?;
                        return Some(PdfSoftMask {
                            start: (expected_bounds.x, expected_bounds.y),
                            end: (expected_bounds.x + expected_bounds.width, expected_bounds.y),
                            radii: None,
                            stops: Vec::new(),
                            bounds: Some(expected_bounds),
                            clip: mask_clip,
                            outside,
                            regions: Vec::new(),
                            raster: Some(PdfRasterSoftMask {
                                media_type: "application/x-officeviewer-gray-samples".to_owned(),
                                bytes: Vec::new(),
                                width: u32::try_from(width).ok()?,
                                height: u32::try_from(height).ok()?,
                                placement: Some(ctm),
                                samples: Some(samples),
                            }),
                        });
                    }
                    let (raster, raster_dict) = if let Some(
                        mask_image @ PdfValue::Stream {
                            dict: mask_dict, ..
                        },
                    ) = image_dict
                        .get("SMask")
                        .and_then(|value| store.resolve(value))
                        && filter_names(mask_dict).last().map(String::as_str) == Some("DCTDecode")
                    {
                        (mask_image, mask_dict)
                    } else if filter_names(image_dict).last().map(String::as_str)
                        == Some("DCTDecode")
                    {
                        (image, image_dict)
                    } else {
                        return None;
                    };
                    let width =
                        u32::try_from(raster_dict.get("Width").and_then(number_usize)?).ok()?;
                    let height =
                        u32::try_from(raster_dict.get("Height").and_then(number_usize)?).ok()?;
                    let raster_bytes = pdf_jpeg_asset(decode_stream(raster, store, limits).ok()?);
                    let image_bounds = bounds(&[
                        ctm.point(0.0, 0.0),
                        ctm.point(1.0, 0.0),
                        ctm.point(1.0, 1.0),
                        ctm.point(0.0, 1.0),
                    ])?;
                    let expected_bounds = mask_bounds?;
                    let tolerance =
                        0.01 * expected_bounds.width.max(expected_bounds.height).max(1.0);
                    if (image_bounds.x - expected_bounds.x).abs() > tolerance
                        || (image_bounds.y - expected_bounds.y).abs() > tolerance
                        || (image_bounds.width - expected_bounds.width).abs() > tolerance
                        || (image_bounds.height - expected_bounds.height).abs() > tolerance
                    {
                        return None;
                    }
                    return Some(PdfSoftMask {
                        start: (expected_bounds.x, expected_bounds.y),
                        end: (expected_bounds.x + expected_bounds.width, expected_bounds.y),
                        radii: None,
                        stops: Vec::new(),
                        bounds: Some(expected_bounds),
                        clip: mask_clip,
                        outside,
                        regions: Vec::new(),
                        raster: Some(PdfRasterSoftMask {
                            media_type: pdf_image_media_type("image/jpeg".to_owned(), raster_dict),
                            bytes: raster_bytes,
                            width,
                            height,
                            placement: None,
                            samples: None,
                        }),
                    });
                } else if operator == "gs" {
                    if let Some(PdfValue::Name(name)) = operands.last()
                        && let Some((_, value)) =
                            resource_entry(resources, "ExtGState", name, store)
                        && let Some(dict) = store.dict(value)
                        && let Some(alpha) = dict.get("ca").and_then(number_f32)
                    {
                        fill_alpha = alpha.clamp(0.0, 1.0);
                    }
                } else if matches!(operator, "m" | "l") {
                    if let Some([x, y]) = last_numbers::<2>(&operands) {
                        path_points.push(ctm.point(x, y));
                    }
                } else if operator == "re" {
                    rectangle = last_numbers::<4>(&operands);
                } else if matches!(operator, "f" | "F" | "f*") {
                    let rect = if let Some([x, y, width, height]) = rectangle.take() {
                        bounds(&[
                            ctm.point(x, y),
                            ctm.point(x + width, y),
                            ctm.point(x + width, y + height),
                            ctm.point(x, y + height),
                        ])
                    } else {
                        bounds(&path_points)
                    };
                    path_points.clear();
                    if let Some(mut rect) = rect {
                        if let Some(mask_bounds) = mask_bounds {
                            let x0 = rect.x.max(mask_bounds.x);
                            let y0 = rect.y.max(mask_bounds.y);
                            let x1 = (rect.x + rect.width).min(mask_bounds.x + mask_bounds.width);
                            let y1 = (rect.y + rect.height).min(mask_bounds.y + mask_bounds.height);
                            if x1 <= x0 || y1 <= y0 {
                                operands.clear();
                                continue;
                            }
                            rect = Rect {
                                x: x0,
                                y: y0,
                                width: x1 - x0,
                                height: y1 - y0,
                            };
                        }
                        let sample = if alpha_mask {
                            fill_alpha
                        } else {
                            gray * fill_alpha
                        };
                        rectangles.push((rect, transfer(sample)));
                    }
                } else if operator == "n" {
                    rectangle = None;
                    path_points.clear();
                } else if operator == "sh"
                    && let Some(PdfValue::Name(name)) = operands.last()
                {
                    let (_, shading) = resource_entry(resources, "Shading", name, store)?;
                    let shading = store.dict(shading)?;
                    if shading.get("ShadingType").and_then(number_usize) != Some(2) {
                        return None;
                    }
                    let [x0, y0, x1, y1] = shading
                        .get("Coords")
                        .and_then(|value| store.resolve(value))
                        .and_then(|value| match value {
                            PdfValue::Array(values) => last_numbers::<4>(values),
                            _ => None,
                        })?;
                    let function = shading.get("Function")?;
                    let color_space = shading.get("ColorSpace")?;
                    let stops: Vec<(f32, f32)> =
                        shading_stops(function, color_space, store, limits, 1.0)?
                            .into_iter()
                            .map(|stop| {
                                let [red, green, blue, _] = stop.color.to_be_bytes();
                                let luminance = (0.2126 * f32::from(red)
                                    + 0.7152 * f32::from(green)
                                    + 0.0722 * f32::from(blue))
                                    / 255.0;
                                (stop.offset, luminance)
                            })
                            .collect();
                    return Some(PdfSoftMask {
                        start: ctm.point(x0, y0),
                        end: ctm.point(x1, y1),
                        radii: None,
                        stops: stops
                            .into_iter()
                            .map(|(offset, value)| (offset, transfer(value)))
                            .collect(),
                        bounds: mask_bounds,
                        clip: mask_clip,
                        outside,
                        regions: Vec::new(),
                        raster: None,
                    });
                }
                operands.clear();
            }
        }
    }
    let mask_bounds = mask_bounds?;
    if rectangles.is_empty() {
        return Some(PdfSoftMask {
            start: (mask_bounds.x, mask_bounds.y + mask_bounds.height * 0.5),
            end: (
                mask_bounds.x + mask_bounds.width,
                mask_bounds.y + mask_bounds.height * 0.5,
            ),
            radii: None,
            stops: vec![(0.0, outside), (1.0, outside)],
            bounds: Some(mask_bounds),
            clip: mask_clip,
            outside,
            regions: Vec::new(),
            raster: None,
        });
    }
    rectangles.sort_by(|left, right| left.0.x.total_cmp(&right.0.x));
    let mut stops = vec![(0.0, outside)];
    let mut current = outside;
    for (rect, value) in &rectangles {
        let start = ((rect.x - mask_bounds.x) / mask_bounds.width).clamp(0.0, 1.0);
        let end = ((rect.x + rect.width - mask_bounds.x) / mask_bounds.width).clamp(0.0, 1.0);
        stops.push((start, current));
        stops.push((start, *value));
        stops.push((end, *value));
        stops.push((end, outside));
        current = outside;
    }
    stops.push((1.0, current));
    Some(PdfSoftMask {
        start: (mask_bounds.x, mask_bounds.y + mask_bounds.height * 0.5),
        end: (
            mask_bounds.x + mask_bounds.width,
            mask_bounds.y + mask_bounds.height * 0.5,
        ),
        radii: None,
        stops,
        bounds: Some(mask_bounds),
        clip: mask_clip,
        outside,
        regions: rectangles,
        raster: None,
    })
}

fn resource_entry<'a>(
    resources: Option<&'a PdfValue>,
    category: &str,
    name: &str,
    store: &'a ObjectStore,
) -> Option<(ObjectId, &'a PdfValue)> {
    let resources = store.dict(resources?)?;
    let category = store.dict(resources.get(category)?)?;
    let value = category.get(name)?;
    let id = match value {
        PdfValue::Ref(id) => *id,
        _ => (0, 0),
    };
    Some((id, store.resolve(value)?))
}

fn is_pattern_color_space(name: &str, resources: Option<&PdfValue>, store: &ObjectStore) -> bool {
    if name == "Pattern" {
        return true;
    }
    let Some((_, value)) = resource_entry(resources, "ColorSpace", name, store) else {
        return false;
    };
    matches!(
        store.resolve(value),
        Some(PdfValue::Array(values))
            if matches!(values.first(), Some(PdfValue::Name(kind)) if kind == "Pattern")
    )
}

fn pdf_font_family(name: &str) -> String {
    // A six-letter prefix identifies one embedded PDF subset. Preserve it so
    // disjoint subsets of the same base family remain distinct browser faces.
    name.replace(',', " ")
}

fn legacy_gbk_font_family(name: &str) -> Option<String> {
    let bytes = name
        .chars()
        .map(|character| u8::try_from(character as u32).ok())
        .collect::<Option<Vec<_>>>()?;
    if !bytes.iter().any(|byte| *byte >= 0x80) {
        return None;
    }
    let family = encoding_rs::GBK
        .decode_without_bom_handling_and_without_replacement(&bytes)?
        .into_owned();
    (family
        .chars()
        .filter(|character| matches!(*character as u32, 0x3400..=0x9fff | 0xf900..=0xfaff))
        .count()
        >= 2)
        .then_some(family)
}

fn pdf_font_family_for_object(name: &str, object_id: ObjectId) -> String {
    let family = pdf_font_family(name);
    if object_id == (0, 0) {
        family
    } else {
        format!("{family} PDF {} {}", object_id.0, object_id.1)
    }
}

fn pdf_system_font_family(name: &str) -> String {
    let base = name.rsplit_once('+').map_or(name, |(_, family)| family);
    let normalized = base.to_ascii_lowercase().replace([' ', '-', ','], "");
    if normalized.contains("arialnarrow") {
        "Arial Narrow".to_owned()
    } else if normalized.contains("arialblack") {
        "Arial Black".to_owned()
    } else if normalized.contains("arial") {
        "Arial".to_owned()
    } else if normalized.contains("timesnewroman") {
        "Times New Roman".to_owned()
    } else if normalized.contains("couriernew") {
        "Courier New".to_owned()
    } else {
        base.replace(',', " ")
    }
}

fn pdf_font_family_is_bold(name: &str) -> bool {
    let lowercase = name.to_ascii_lowercase();
    let compact = lowercase.replace([' ', '-', ',', '_'], "");
    lowercase.contains("bold")
        || lowercase
            .split(|character: char| !character.is_ascii_alphanumeric())
            .any(|part| matches!(part, "black" | "heavy"))
        || ["black", "heavy"]
            .iter()
            .any(|suffix| compact.ends_with(suffix))
}

fn is_computer_modern_symbol_font(family: &str) -> bool {
    let base = family.split_ascii_whitespace().next().unwrap_or(family);
    let base = base.rsplit_once('+').map_or(base, |(_, name)| name);
    base.to_ascii_lowercase()
        .strip_prefix("cmsy")
        .is_some_and(|size| !size.is_empty() && size.bytes().all(|byte| byte.is_ascii_digit()))
}

fn is_computer_modern_math_italic_font(family: &str) -> bool {
    let base = family.split_ascii_whitespace().next().unwrap_or(family);
    let base = base.rsplit_once('+').map_or(base, |(_, name)| name);
    base.to_ascii_lowercase()
        .strip_prefix("cmmi")
        .is_some_and(|size| !size.is_empty() && size.bytes().all(|byte| byte.is_ascii_digit()))
}

fn is_computer_modern_extension_font(family: &str) -> bool {
    let base = family.split_ascii_whitespace().next().unwrap_or(family);
    let base = base.rsplit_once('+').map_or(base, |(_, name)| name);
    base.eq_ignore_ascii_case("cmex10")
}

fn uses_browser_independent_source_glyph_outlines(family: &str) -> bool {
    is_computer_modern_extension_font(family)
        || is_computer_modern_symbol_font(family)
        || is_computer_modern_math_italic_font(family)
}

fn is_arabic_glyph_text(text: &str) -> bool {
    text.chars().any(|character| {
        matches!(
            character,
            '\u{0600}'..='\u{06ff}'
                | '\u{0750}'..='\u{077f}'
                | '\u{0870}'..='\u{089f}'
                | '\u{08a0}'..='\u{08ff}'
                | '\u{fb50}'..='\u{fdff}'
                | '\u{fe70}'..='\u{feff}'
                | '\u{1ee00}'..='\u{1eeff}'
        )
    })
}

fn is_indic_glyph_text(text: &str) -> bool {
    text.chars().any(|character| {
        matches!(
            character,
            '\u{0900}'..='\u{0dff}' | '\u{a800}'..='\u{abff}' | '\u{11000}'..='\u{11fff}'
        )
    })
}

fn is_contextual_arabic_glyph_name(name: &str) -> bool {
    let text = glyph_name_text(name);
    let contextual_form = name
        .rsplit_once('.')
        .is_some_and(|(_, suffix)| matches!(suffix, "init" | "medi" | "fina" | "isol"));
    text.is_some_and(|text| {
        is_arabic_glyph_text(&text) && (contextual_form || text.chars().count() > 1)
    })
}

fn apply_simple_font_encoding(
    info: &mut FontInfo,
    encoding: &BTreeMap<u8, String>,
    preserve_contextual_source_glyphs: bool,
) {
    // Some simple PDF fonts contain already-shaped Arabic glyphs. Keep their
    // semantic Unicode for text APIs, but reserve source-code glyphs for paint.
    info.browser_contextual_source_glyphs |= preserve_contextual_source_glyphs
        && encoding
            .values()
            .any(|name| is_contextual_arabic_glyph_name(name));
    for (&code, name) in encoding {
        if matches!(name.as_str(), ".notdef" | ".null" | "nonmarkingreturn") {
            info.notdef_codes.insert(u32::from(code));
            continue;
        }
        if let Some(text) = glyph_name_text(name) {
            info.to_unicode.entry(vec![code]).or_insert(text);
            info.max_code_bytes = info.max_code_bytes.max(1);
        }
    }
}

