fn apply_zapf_dingbats_encoding(info: &mut FontInfo) {
    for (code, &codepoint) in ZAPF_DINGBATS_UNICODE.iter().enumerate() {
        if let Some(character) = char::from_u32(u32::from(codepoint)).filter(|_| codepoint != 0) {
            info.to_unicode
                .entry(vec![code as u8])
                .or_insert_with(|| character.to_string());
        } else {
            info.notdef_codes.insert(code as u32);
        }
    }
    info.max_code_bytes = info.max_code_bytes.max(1);
}

fn apply_zapf_dingbats_differences(info: &mut FontInfo, encoding: &BTreeMap<u8, String>) {
    for (&code, name) in encoding {
        let text = match name.as_str() {
            "a109" => "\u{2660}",
            "a110" => "\u{2665}",
            "a111" => "\u{2666}",
            "a112" => "\u{2663}",
            _ => continue,
        };
        info.to_unicode.insert(vec![code], text.to_owned());
    }
}

