fn truetype_post_glyphs(tables: &SfntTables, glyph_count: usize) -> Option<BTreeMap<String, u16>> {
    let post = tables
        .iter()
        .find_map(|(tag, bytes)| (tag == b"post").then_some(bytes))?;
    let standard = MAC_STANDARD_GLYPH_NAMES
        .split_ascii_whitespace()
        .collect::<Vec<_>>();
    if standard.len() != 258 || glyph_count > u16::MAX as usize {
        return None;
    }
    let indices = match read_u32(post, 0)? {
        0x0001_0000 => (0..glyph_count).collect::<Vec<_>>(),
        0x0002_0000 => {
            let count = usize::from(read_u16(post, 32)?);
            if count != glyph_count {
                return None;
            }
            (0..count)
                .map(|index| read_u16(post, 34 + index * 2).map(usize::from))
                .collect::<Option<Vec<_>>>()?
        }
        _ => return None,
    };
    let custom_count = indices
        .iter()
        .copied()
        .max()
        .unwrap_or(257)
        .saturating_sub(257);
    let mut position = 34_usize.checked_add(glyph_count.checked_mul(2)?)?;
    let mut custom = Vec::with_capacity(custom_count);
    if read_u32(post, 0)? == 0x0002_0000 {
        for _ in 0..custom_count {
            let length = usize::from(*post.get(position)?);
            position += 1;
            let name = str::from_utf8(post.get(position..position.checked_add(length)?)?).ok()?;
            custom.push(name);
            position += length;
        }
    }
    let mut result = BTreeMap::new();
    for (gid, index) in indices.into_iter().enumerate() {
        let name = if index < standard.len() {
            standard[index]
        } else {
            *custom.get(index - standard.len())?
        };
        result.entry(name.to_owned()).or_insert(gid as u16);
    }
    Some(result)
}

type SfntTables = Vec<([u8; 4], Vec<u8>)>;

fn sfnt_table<'a>(font: &'a [u8], wanted: &[u8; 4]) -> Option<&'a [u8]> {
    let table_count = usize::from(read_u16(font, 4)?);
    if table_count == 0 || table_count > 4_096 {
        return None;
    }
    for index in 0..table_count {
        let record = 12_usize.checked_add(index.checked_mul(16)?)?;
        if font.get(record..record + 4)? != wanted {
            continue;
        }
        let offset = usize::try_from(read_u32(font, record + 8)?).ok()?;
        let length = usize::try_from(read_u32(font, record + 12)?).ok()?;
        return font.get(offset..offset.checked_add(length)?);
    }
    None
}

fn truetype_vertical_metrics(font: &[u8]) -> Option<(f32, f32)> {
    let head = sfnt_table(font, b"head")?;
    let hhea = sfnt_table(font, b"hhea")?;
    let units_per_em = f32::from(read_u16(head, 18)?);
    if units_per_em <= 0.0 {
        return None;
    }
    let ascent = f32::from(read_u16(hhea, 4)? as i16) * 1_000.0 / units_per_em;
    let descent = f32::from(read_u16(hhea, 6)? as i16) * 1_000.0 / units_per_em;
    (ascent > 0.0 && descent <= 0.0).then_some((ascent, descent))
}

fn extract_truetype_collection_face(collection: &[u8], family: &str) -> Option<Vec<u8>> {
    if collection.get(..4)? != b"ttcf" {
        return None;
    }
    let count = usize::try_from(read_u32(collection, 8)?).ok()?;
    if count == 0 || count > 64 {
        return None;
    }
    let wanted = family
        .rsplit_once('+')
        .map_or(family, |(_, family)| family)
        .chars()
        .filter(|character| character.is_ascii_alphanumeric())
        .flat_map(char::to_lowercase)
        .collect::<String>();
    let mut fallback = None;
    let mut math_fallback = None;
    for index in 0..count {
        let face_offset = usize::try_from(read_u32(collection, 12 + index * 4)?).ok()?;
        let signature: [u8; 4] = collection
            .get(face_offset..face_offset + 4)?
            .try_into()
            .ok()?;
        if !matches!(&signature, b"\0\x01\0\0" | b"true" | b"OTTO") {
            continue;
        }
        let table_count = usize::from(read_u16(collection, face_offset + 4)?);
        if table_count == 0 || table_count > 4_096 {
            continue;
        }
        let mut tables = Vec::with_capacity(table_count);
        for table_index in 0..table_count {
            let record = face_offset + 12 + table_index * 16;
            let tag: [u8; 4] = collection.get(record..record + 4)?.try_into().ok()?;
            let offset = usize::try_from(read_u32(collection, record + 8)?).ok()?;
            let length = usize::try_from(read_u32(collection, record + 12)?).ok()?;
            tables.push((
                tag,
                collection
                    .get(offset..offset.checked_add(length)?)?
                    .to_vec(),
            ));
        }
        let has_math_table = tables.iter().any(|(tag, _)| tag == b"MATH");
        let face = build_sfnt(signature, tables)?;
        if wanted.contains("math") {
            if has_math_table {
                return Some(face);
            }
            if truetype_cmap_subtables(&face)
                .is_some_and(|cmaps| best_truetype_cmap_gid(&cmaps, 0x2220, false).is_some())
            {
                math_fallback.get_or_insert(face.clone());
            }
        }
        let names = sfnt_family_names(&face);
        if !wanted.contains("math")
            && names.iter().any(|name| {
                let normalized = name
                    .chars()
                    .filter(|character| character.is_ascii_alphanumeric())
                    .flat_map(char::to_lowercase)
                    .collect::<String>();
                !normalized.is_empty()
                    && (normalized == wanted
                        || normalized.contains(&wanted)
                        || (wanted.contains("math") && normalized == "math"))
            })
        {
            return Some(face);
        }
        fallback.get_or_insert(face);
    }
    math_fallback.or(fallback)
}

fn sfnt_family_names(font: &[u8]) -> Vec<String> {
    let Some(table) = sfnt_table(font, b"name") else {
        return Vec::new();
    };
    let Some(count) = read_u16(table, 2).map(usize::from) else {
        return Vec::new();
    };
    let Some(storage) = read_u16(table, 4).map(usize::from) else {
        return Vec::new();
    };
    (0..count.min(4_096))
        .filter_map(|index| {
            let record = 6 + index * 12;
            let platform = read_u16(table, record)?;
            let name_id = read_u16(table, record + 6)?;
            if !matches!(name_id, 1 | 2 | 4 | 6 | 17) {
                return None;
            }
            let length = usize::from(read_u16(table, record + 8)?);
            let offset = storage.checked_add(usize::from(read_u16(table, record + 10)?))?;
            let bytes = table.get(offset..offset.checked_add(length)?)?;
            if matches!(platform, 0 | 3) {
                let text = bytes
                    .chunks_exact(2)
                    .map(|pair| u16::from_be_bytes([pair[0], pair[1]]))
                    .collect::<Vec<_>>();
                String::from_utf16(&text).ok()
            } else {
                str::from_utf8(bytes).ok().map(str::to_owned)
            }
        })
        .collect()
}

fn truetype_parts(font: &[u8]) -> Option<([u8; 4], SfntTables, usize)> {
    let signature: [u8; 4] = font.get(..4)?.try_into().ok()?;
    if !matches!(&signature, b"\0\x01\0\0" | b"true") {
        return None;
    }
    let table_count = usize::from(read_u16(font, 4)?);
    if table_count == 0 || table_count > 4_096 {
        return None;
    }
    let mut tables = Vec::with_capacity(table_count);
    let mut glyph_count = None;
    for index in 0..table_count {
        let Some(record) = 12_usize.checked_add(index.checked_mul(16)?) else {
            break;
        };
        let Some(tag) = font
            .get(record..record + 4)
            .and_then(|tag| <[u8; 4]>::try_from(tag).ok())
            .filter(|tag| tag.iter().all(|byte| (0x20..=0x7e).contains(byte)))
        else {
            continue;
        };
        let Some(offset) = read_u32(font, record + 8).and_then(|value| usize::try_from(value).ok())
        else {
            continue;
        };
        let Some(length) =
            read_u32(font, record + 12).and_then(|value| usize::try_from(value).ok())
        else {
            continue;
        };
        let Some(mut data) = (length != 0)
            .then(|| offset.checked_add(length))
            .flatten()
            .and_then(|end| font.get(offset..end))
            .map(<[u8]>::to_vec)
        else {
            continue;
        };
        if &tag == b"maxp" {
            glyph_count = Some(usize::from(read_u16(&data, 4)?));
        }
        if &tag == b"head" {
            data.get_mut(8..12)?.fill(0);
            if read_u16(&data, 50) == Some(0x0100) {
                set_u16(&mut data, 50, 1)?;
            }
        }
        // PDF text placement already owns glyph advances. Retaining a legacy
        // kerning table after replacing the cmap can make otherwise valid
        // subsets fail browser font sanitization.
        if !matches!(&tag, b"cmap" | b"DSIG" | b"kern") {
            tables.push((tag, data));
        }
    }
    let mut glyph_count = glyph_count?;
    let loca_capacity = tables
        .iter()
        .find_map(|(tag, bytes)| (tag == b"head").then_some(bytes))
        .and_then(|head| read_u16(head, 50))
        .and_then(|format| {
            let entry_size = match format {
                0 => 2,
                1 => 4,
                _ => return None,
            };
            tables
                .iter()
                .find_map(|(tag, bytes)| (tag == b"loca").then_some(bytes.len() / entry_size))
        })
        .and_then(|entries| entries.checked_sub(1));
    if let Some(loca_capacity) = loca_capacity.filter(|capacity| *capacity > 0)
        && loca_capacity < glyph_count
    {
        glyph_count = loca_capacity;
        let glyph_count_u16 = u16::try_from(glyph_count).ok()?;
        if let Some(maxp) = tables
            .iter_mut()
            .find_map(|(tag, bytes)| (tag == b"maxp").then_some(bytes))
        {
            set_u16(maxp, 4, glyph_count_u16)?;
        }
    }
    let horizontal_metric_count = tables
        .iter()
        .find_map(|(tag, bytes)| (tag == b"hhea").then_some(bytes))
        .and_then(|hhea| read_u16(hhea, 34))
        .map(usize::from);
    if horizontal_metric_count.is_some_and(|count| count > glyph_count) {
        let glyph_count_u16 = u16::try_from(glyph_count).ok()?;
        if let Some(hhea) = tables
            .iter_mut()
            .find_map(|(tag, bytes)| (tag == b"hhea").then_some(bytes))
        {
            set_u16(hhea, 34, glyph_count_u16)?;
        }
        if let Some(hmtx) = tables
            .iter_mut()
            .find_map(|(tag, bytes)| (tag == b"hmtx").then_some(bytes))
        {
            hmtx.truncate(glyph_count.checked_mul(4)?);
        }
    }
    Some((signature, tables, glyph_count))
}

fn repair_truetype_loca_offsets(tables: &mut SfntTables, glyph_count: usize) -> usize {
    let Some(glyf) = tables
        .iter()
        .find_map(|(tag, bytes)| (tag == b"glyf").then_some(bytes.clone()))
    else {
        return 0;
    };
    let glyf_length = glyf.len();
    let Some(index_to_loc_format) = tables
        .iter()
        .find_map(|(tag, bytes)| (tag == b"head").then_some(bytes))
        .and_then(|head| read_u16(head, 50))
    else {
        return 0;
    };
    let Some(loca) = tables
        .iter()
        .find_map(|(tag, bytes)| (tag == b"loca").then_some(bytes.clone()))
    else {
        return 0;
    };
    let Some(offset_count) = glyph_count.checked_add(1) else {
        return 0;
    };
    let entry_size = match index_to_loc_format {
        0 => 2,
        1 => 4,
        _ => return 0,
    };
    if loca.len() < offset_count.saturating_mul(entry_size) {
        return 0;
    }
    let offsets = (0..offset_count)
        .map(|index| {
            let position = index * entry_size;
            if entry_size == 2 {
                read_u16(&loca, position)
                    .map(usize::from)
                    .and_then(|offset| offset.checked_mul(2))
            } else {
                read_u32(&loca, position).and_then(|offset| usize::try_from(offset).ok())
            }
        })
        .collect::<Option<Vec<_>>>();
    let Some(offsets) =
        offsets.filter(|offsets| offsets.iter().all(|offset| *offset <= glyf_length))
    else {
        return 0;
    };
    if offsets.windows(2).all(|pair| pair[0] <= pair[1]) {
        return 0;
    }

    // Some producers emit a permuted loca table: every entry points at a
    // valid glyph record, but the records are not ordered by glyph id. Recover
    // each record using the next physical offset, then serialize the records
    // back in glyph-id order so browser sanitizers can consume the font.
    let mut physical_offsets = offsets.clone();
    physical_offsets.push(glyf_length);
    physical_offsets.sort_unstable();
    physical_offsets.dedup();
    let mut rebuilt_glyf = Vec::with_capacity(glyf_length);
    let mut rebuilt_offsets = Vec::with_capacity(offset_count);
    for &source in offsets.iter().take(glyph_count) {
        rebuilt_offsets.push(rebuilt_glyf.len());
        let end = physical_offsets
            .get(physical_offsets.partition_point(|offset| *offset <= source))
            .copied()
            .unwrap_or(glyf_length);
        if end > source {
            rebuilt_glyf.extend_from_slice(&glyf[source..end]);
            if rebuilt_glyf.len() % 2 != 0 {
                rebuilt_glyf.push(0);
            }
        }
        if rebuilt_glyf.len() > glyf_length.saturating_mul(4).max(glyf_length + 1_048_576) {
            return 0;
        }
    }
    rebuilt_offsets.push(rebuilt_glyf.len());
    let mut rebuilt_loca = loca;
    for (index, offset) in rebuilt_offsets.into_iter().enumerate() {
        let position = index * entry_size;
        if entry_size == 2 {
            let Some(value) = u16::try_from(offset / 2).ok() else {
                return 0;
            };
            rebuilt_loca[position..position + 2].copy_from_slice(&value.to_be_bytes());
        } else {
            let Some(value) = u32::try_from(offset).ok() else {
                return 0;
            };
            rebuilt_loca[position..position + 4].copy_from_slice(&value.to_be_bytes());
        }
    }
    if let Some(target) = tables
        .iter_mut()
        .find_map(|(tag, bytes)| (tag == b"glyf").then_some(bytes))
    {
        *target = rebuilt_glyf;
    }
    if let Some(target) = tables
        .iter_mut()
        .find_map(|(tag, bytes)| (tag == b"loca").then_some(bytes))
    {
        *target = rebuilt_loca;
    }
    glyph_count
}

fn repair_truetype_simple_glyph_flags(tables: &mut SfntTables, glyph_count: usize) -> usize {
    let Some(glyf_length) = tables
        .iter()
        .find_map(|(tag, bytes)| (tag == b"glyf").then_some(bytes.len()))
    else {
        return 0;
    };
    let Some(head) = tables
        .iter()
        .find_map(|(tag, bytes)| (tag == b"head").then_some(bytes))
    else {
        return 0;
    };
    let Some(loca) = tables
        .iter()
        .find_map(|(tag, bytes)| (tag == b"loca").then_some(bytes))
    else {
        return 0;
    };
    let Some(offset_count) = glyph_count.checked_add(1) else {
        return 0;
    };
    let offsets = match read_u16(head, 50) {
        Some(0) => (0..offset_count)
            .map(|index| {
                read_u16(loca, index.checked_mul(2)?)
                    .map(usize::from)?
                    .checked_mul(2)
            })
            .collect::<Option<Vec<_>>>(),
        Some(1) => (0..offset_count)
            .map(|index| usize::try_from(read_u32(loca, index.checked_mul(4)?)?).ok())
            .collect::<Option<Vec<_>>>(),
        _ => None,
    };
    let Some(offsets) = offsets.filter(|offsets| {
        offsets.last().is_some_and(|offset| *offset <= glyf_length)
            && offsets.windows(2).all(|pair| pair[0] <= pair[1])
    }) else {
        return 0;
    };
    let Some(glyf) = tables
        .iter_mut()
        .find_map(|(tag, bytes)| (tag == b"glyf").then_some(bytes))
    else {
        return 0;
    };
    let mut repaired = 0;
    for range in offsets.windows(2) {
        let Some(glyph) = glyf.get_mut(range[0]..range[1]) else {
            continue;
        };
        if glyph.is_empty() {
            continue;
        }
        let Some(contour_count) = glyph.get(..2).and_then(|bytes| {
            let count = i16::from_be_bytes(bytes.try_into().ok()?);
            usize::try_from(count).ok()
        }) else {
            // Composite glyph flags have a different two-byte layout.
            continue;
        };
        if contour_count == 0 {
            continue;
        }
        let Some(end_points_length) = contour_count.checked_mul(2) else {
            continue;
        };
        let Some(instruction_length_offset) = 10_usize.checked_add(end_points_length) else {
            continue;
        };
        let Some(point_count) = read_u16(glyph, instruction_length_offset.saturating_sub(2))
            .map(usize::from)
            .and_then(|last| last.checked_add(1))
        else {
            continue;
        };
        let Some(flags_start) = read_u16(glyph, instruction_length_offset)
            .map(usize::from)
            .and_then(|length| instruction_length_offset.checked_add(2 + length))
        else {
            continue;
        };
        let mut flag_positions = Vec::new();
        let mut expanded_flags = Vec::with_capacity(point_count);
        let mut position = flags_start;
        while expanded_flags.len() < point_count {
            let Some(&flag) = glyph.get(position) else {
                flag_positions.clear();
                break;
            };
            flag_positions.push(position);
            position += 1;
            let repeat = if flag & 0x08 != 0 {
                let Some(&repeat) = glyph.get(position) else {
                    flag_positions.clear();
                    break;
                };
                position += 1;
                usize::from(repeat)
            } else {
                0
            };
            let Some(next_count) = expanded_flags.len().checked_add(repeat + 1) else {
                flag_positions.clear();
                break;
            };
            if next_count > point_count {
                flag_positions.clear();
                break;
            }
            expanded_flags.resize(next_count, flag);
        }
        if flag_positions.is_empty() || expanded_flags.len() != point_count {
            continue;
        }
        let Some(coordinate_bytes) = expanded_flags.iter().try_fold(0_usize, |total, flag| {
            let x = if flag & 0x02 != 0 {
                1
            } else if flag & 0x10 == 0 {
                2
            } else {
                0
            };
            let y = if flag & 0x04 != 0 {
                1
            } else if flag & 0x20 == 0 {
                2
            } else {
                0
            };
            total.checked_add(x + y)
        }) else {
            continue;
        };
        if position
            .checked_add(coordinate_bytes)
            .is_none_or(|end| end > glyph.len())
        {
            continue;
        }
        for position in flag_positions {
            let flag = &mut glyph[position];
            if *flag & 0x80 != 0 {
                *flag &= !0x80;
                repaired += 1;
            }
        }
    }
    repaired
}

fn repair_truetype_composite_glyph_references(
    tables: &mut SfntTables,
    glyph_count: usize,
) -> usize {
    let Some(glyf_length) = tables
        .iter()
        .find_map(|(tag, bytes)| (tag == b"glyf").then_some(bytes.len()))
    else {
        return 0;
    };
    let Some(format) = tables
        .iter()
        .find_map(|(tag, bytes)| (tag == b"head").then_some(bytes))
        .and_then(|head| read_u16(head, 50))
    else {
        return 0;
    };
    let Some(loca) = tables
        .iter()
        .find_map(|(tag, bytes)| (tag == b"loca").then_some(bytes))
    else {
        return 0;
    };
    let offsets = (0..=glyph_count)
        .map(|index| match format {
            0 => read_u16(loca, index.checked_mul(2)?)
                .map(usize::from)?
                .checked_mul(2),
            1 => usize::try_from(read_u32(loca, index.checked_mul(4)?)?).ok(),
            _ => None,
        })
        .collect::<Option<Vec<_>>>();
    let Some(offsets) = offsets.filter(|offsets| {
        offsets.last().is_some_and(|offset| *offset <= glyf_length)
            && offsets.windows(2).all(|pair| pair[0] <= pair[1])
    }) else {
        return 0;
    };
    let Some(glyf) = tables
        .iter_mut()
        .find_map(|(tag, bytes)| (tag == b"glyf").then_some(bytes))
    else {
        return 0;
    };
    let mut repaired = 0;
    for range in offsets.windows(2) {
        let Some(glyph) = glyf.get_mut(range[0]..range[1]) else {
            continue;
        };
        if glyph.len() < 10
            || i16::from_be_bytes([glyph[0], glyph[1]]) >= 0
            || valid_truetype_composite_glyph(glyph, glyph_count)
        {
            continue;
        }
        glyph.fill(0);
        repaired += 1;
    }
    repaired
}

fn valid_truetype_composite_glyph(glyph: &[u8], glyph_count: usize) -> bool {
    let mut position = 10_usize;
    loop {
        let Some(flags) = read_u16(glyph, position) else {
            return false;
        };
        let Some(component) = read_u16(glyph, position + 2) else {
            return false;
        };
        if usize::from(component) >= glyph_count {
            return false;
        }
        let arguments = if flags & 0x0001 != 0 { 4 } else { 2 };
        let transform = if flags & 0x0080 != 0 {
            8
        } else if flags & 0x0040 != 0 {
            4
        } else if flags & 0x0008 != 0 {
            2
        } else {
            0
        };
        let Some(next) = position.checked_add(4 + arguments + transform) else {
            return false;
        };
        if next > glyph.len() {
            return false;
        }
        if flags & 0x0020 == 0 {
            return true;
        }
        position = next;
    }
}

fn finish_truetype_cmap(
    signature: [u8; 4],
    mut tables: SfntTables,
    glyph_count: usize,
    mut mappings: BTreeMap<u32, u16>,
    info: &FontInfo,
) -> Option<Vec<u8>> {
    mappings.retain(|_, gid| usize::from(*gid) < glyph_count);
    if mappings.is_empty() {
        return None;
    }
    let horizontal_metric_count = tables
        .iter()
        .find_map(|(tag, bytes)| (tag == b"hhea").then_some(bytes))
        .and_then(|hhea| read_u16(hhea, 34))
        .map(usize::from);
    if let Some(horizontal_metric_count) = horizontal_metric_count
        && horizontal_metric_count > 0
        && horizontal_metric_count <= glyph_count
    {
        let complete_metrics_length = horizontal_metric_count.checked_mul(4)?;
        let required_length = glyph_count
            .checked_sub(horizontal_metric_count)?
            .checked_mul(2)?
            .checked_add(complete_metrics_length)?;
        if let Some(hmtx) = tables
            .iter_mut()
            .find_map(|(tag, bytes)| (tag == b"hmtx").then_some(bytes))
            && hmtx.len() >= complete_metrics_length
            && hmtx.len() < required_length
            && (hmtx.len() - complete_metrics_length) % 2 == 0
        {
            // Some PDF subsets omit trailing left-side bearings because PDF
            // widths own layout. Browsers still require one for every glyph.
            hmtx.resize(required_length, 0);
        }
    }
    let vertical_metric_count = tables
        .iter()
        .find_map(|(tag, bytes)| (tag == b"vhea").then_some(bytes))
        .and_then(|vhea| read_u16(vhea, 34))
        .map(usize::from);
    if let Some(vertical_metric_count) = vertical_metric_count
        && vertical_metric_count > 0
        && vertical_metric_count <= glyph_count
    {
        let complete_metrics_length = vertical_metric_count.checked_mul(4)?;
        let required_length = glyph_count
            .checked_sub(vertical_metric_count)?
            .checked_mul(2)?
            .checked_add(complete_metrics_length)?;
        if let Some(vmtx) = tables
            .iter_mut()
            .find_map(|(tag, bytes)| (tag == b"vmtx").then_some(bytes))
            && vmtx.len() >= complete_metrics_length
            && vmtx.len() < required_length
            && (vmtx.len() - complete_metrics_length) % 2 == 0
        {
            // PDF producers sometimes subset vertical side bearings more
            // aggressively than OpenType permits. PDF text placement owns
            // the authored positions, but browsers still require one entry
            // per glyph before they will accept the embedded face.
            vmtx.resize(required_length, 0);
        }
    }
    repair_truetype_loca_offsets(&mut tables, glyph_count);
    repair_truetype_composite_glyph_references(&mut tables, glyph_count);
    repair_truetype_simple_glyph_flags(&mut tables, glyph_count);
    if !tables.iter().any(|(tag, _)| tag == b"OS/2") {
        let ascent = info.ascent.round().clamp(i16::MIN as f32, i16::MAX as f32) as i16;
        let descent = info.descent.round().clamp(i16::MIN as f32, i16::MAX as f32) as i16;
        // Older embedded TrueType subsets may omit OS/2, which PDF readers
        // accept but browser font sanitizers reject. Supply only the required
        // metrics table while preserving the document's glyph outlines.
        tables.push((*b"OS/2", otf_os2(&mappings, ascent, descent)));
    }
    // Glyph-name mappings have already been consumed. Replace the optional
    // source table because malformed PDF subsets commonly declare a format-2
    // glyph-name count without including the corresponding names, which makes
    // Chromium reject an otherwise usable face.
    tables.retain(|(tag, _)| tag != b"post");
    tables.push((*b"post", otf_post()));
    if !tables.iter().any(|(tag, _)| tag == b"name") {
        let family = info.family.trim();
        tables.push((
            *b"name",
            otf_name(if family.is_empty() {
                "PDF Embedded Font"
            } else {
                family
            }),
        ));
    }
    tables.push((*b"cmap", otf_cmap(&mappings)?));
    build_sfnt(signature, tables)
}

fn truetype_cmap_subtables(font: &[u8]) -> Option<Vec<(u16, u16, &[u8])>> {
    let table_count = usize::from(read_u16(font, 4)?);
    if table_count == 0 || table_count > 4_096 {
        return None;
    }
    let cmap = (0..table_count).find_map(|index| {
        let record = 12_usize.checked_add(index.checked_mul(16)?)?;
        (font.get(record..record + 4)? == b"cmap").then(|| {
            let offset = usize::try_from(read_u32(font, record + 8)?).ok()?;
            let length = usize::try_from(read_u32(font, record + 12)?).ok()?;
            font.get(offset..offset.checked_add(length)?)
        })?
    })?;
    let encoding_count = usize::from(read_u16(cmap, 2)?);
    if encoding_count == 0 || encoding_count > 4_096 {
        return None;
    }
    let mut subtables = Vec::with_capacity(encoding_count);
    for index in 0..encoding_count {
        let record = 4_usize.checked_add(index.checked_mul(8)?)?;
        let platform = read_u16(cmap, record)?;
        let encoding = read_u16(cmap, record + 2)?;
        let offset = usize::try_from(read_u32(cmap, record + 4)?).ok()?;
        let Some(subtable) = cmap.get(offset..) else {
            continue;
        };
        let Some(format) = read_u16(subtable, 0) else {
            continue;
        };
        let Some(length) = (match format {
            0 | 4 | 6 => read_u16(subtable, 2).map(usize::from),
            12 => read_u32(subtable, 4).and_then(|value| usize::try_from(value).ok()),
            _ => None,
        }) else {
            continue;
        };
        let Some(subtable) = subtable.get(..length) else {
            continue;
        };
        subtables.push((platform, encoding, subtable));
    }
    (!subtables.is_empty()).then_some(subtables)
}

fn best_truetype_cmap_gid(
    subtables: &[(u16, u16, &[u8])],
    code: u32,
    prefer_symbolic: bool,
) -> Option<u16> {
    subtables
        .iter()
        .filter_map(|(platform, encoding, subtable)| {
            let gid = truetype_cmap_gid(subtable, code).filter(|gid| *gid != 0)?;
            let priority = if prefer_symbolic {
                match (*platform, *encoding) {
                    (3, 0) => 0,
                    (1, 0) => 1,
                    (0, _) => 2,
                    (3, 10) => 3,
                    (3, 1) => 4,
                    _ => 5,
                }
            } else {
                match (*platform, *encoding) {
                    (0, _) => 0,
                    (3, 10) => 1,
                    (3, 1) => 2,
                    (1, 0) => 3,
                    (3, 0) => 4,
                    _ => 5,
                }
            };
            Some((priority, gid))
        })
        .min_by_key(|(priority, _)| *priority)
        .map(|(_, gid)| gid)
}

fn truetype_cmap_gid(cmap: &[u8], code: u32) -> Option<u16> {
    match read_u16(cmap, 0)? {
        0 if code <= 0xff => Some(u16::from(*cmap.get(6 + code as usize)?)),
        4 if code <= 0xffff => {
            let segment_count = usize::from(read_u16(cmap, 6)?) / 2;
            if segment_count == 0 || segment_count > 32_768 {
                return None;
            }
            let end_codes = 14_usize;
            let start_codes = end_codes
                .checked_add(segment_count.checked_mul(2)?)?
                .checked_add(2)?;
            let deltas = start_codes.checked_add(segment_count.checked_mul(2)?)?;
            let range_offsets = deltas.checked_add(segment_count.checked_mul(2)?)?;
            for index in 0..segment_count {
                let end = u32::from(read_u16(cmap, end_codes + index * 2)?);
                let start = u32::from(read_u16(cmap, start_codes + index * 2)?);
                if code < start || code > end {
                    continue;
                }
                let delta = read_u16(cmap, deltas + index * 2)?;
                let range_offset_position = range_offsets + index * 2;
                let range_offset = usize::from(read_u16(cmap, range_offset_position)?);
                return if range_offset == 0 {
                    Some((code as u16).wrapping_add(delta))
                } else {
                    let glyph_position = range_offset_position
                        .checked_add(range_offset)?
                        .checked_add(usize::try_from(code - start).ok()?.checked_mul(2)?)?;
                    let gid = read_u16(cmap, glyph_position)?;
                    Some(if gid == 0 { 0 } else { gid.wrapping_add(delta) })
                };
            }
            None
        }
        6 if code <= 0xffff => {
            let first = u32::from(read_u16(cmap, 6)?);
            let count = u32::from(read_u16(cmap, 8)?);
            let index = code.checked_sub(first)?;
            (index < count).then(|| read_u16(cmap, 10 + index as usize * 2))?
        }
        12 => {
            let group_count = usize::try_from(read_u32(cmap, 12)?).ok()?;
            if group_count > 65_536 {
                return None;
            }
            for index in 0..group_count {
                let offset = 16_usize.checked_add(index.checked_mul(12)?)?;
                let start = read_u32(cmap, offset)?;
                let end = read_u32(cmap, offset + 4)?;
                if code >= start && code <= end {
                    let gid = read_u32(cmap, offset + 8)?.checked_add(code - start)?;
                    return u16::try_from(gid).ok();
                }
            }
            None
        }
        _ => None,
    }
}

fn cff_cid_glyphs(cff: &[u8]) -> Option<(usize, BTreeMap<u32, u16>)> {
    let header_size = usize::from(*cff.get(2)?);
    if cff.first() != Some(&1) || header_size < 4 || header_size > cff.len() {
        return None;
    }
    let (_, after_names) = cff_index(cff, header_size)?;
    let (top_dicts, _) = cff_index(cff, after_names)?;
    let top_dict = *top_dicts.first()?;
    let (charset_offset, _, char_strings_offset) = cff_top_dict_offsets(top_dict)?;
    let (char_strings, _) = cff_index(cff, char_strings_offset)?;
    let glyph_count = char_strings.len();
    if glyph_count == 0 || glyph_count > u16::MAX as usize {
        return None;
    }
    let mut cid_to_gid = BTreeMap::from([(0, 0)]);
    if charset_offset <= 2 {
        for gid in 1..glyph_count {
            cid_to_gid.insert(gid as u32, gid as u16);
        }
        return Some((glyph_count, cid_to_gid));
    }
    let format = *cff.get(charset_offset)?;
    let mut position = charset_offset + 1;
    let mut gid = 1_usize;
    match format {
        0 => {
            while gid < glyph_count {
                let cid = read_u16(cff, position)?;
                cid_to_gid.insert(u32::from(cid), gid as u16);
                gid += 1;
                position += 2;
            }
        }
        1 | 2 => {
            while gid < glyph_count {
                let first = u32::from(read_u16(cff, position)?);
                position += 2;
                let left = if format == 1 {
                    let value = u32::from(*cff.get(position)?);
                    position += 1;
                    value
                } else {
                    let value = u32::from(read_u16(cff, position)?);
                    position += 2;
                    value
                };
                for delta in 0..=left {
                    if gid >= glyph_count {
                        break;
                    }
                    cid_to_gid.insert(first.checked_add(delta)?, gid as u16);
                    gid += 1;
                }
            }
        }
        _ => return None,
    }
    Some((glyph_count, cid_to_gid))
}

type CffNameKeyedGlyphs = (usize, BTreeMap<String, u16>, BTreeMap<u8, u16>);

