    fn visual_text(visual: &Visual) -> String {
        match visual {
            Visual::RichText { runs, .. } => runs.iter().map(|run| run.text.as_str()).collect(),
            Visual::Effect { visual, .. }
            | Visual::Layer { visual, .. }
            | Visual::TextEffects { visual, .. }
            | Visual::StrokeStyle { visual, .. }
            | Visual::AdvancedEffect { visual, .. }
            | Visual::TextLayout { visual, .. } => visual_text(visual),
            _ => String::new(),
        }
    }

    fn collect_text_runs<'a>(visual: &'a Visual, runs: &mut Vec<&'a TextRun>) {
        match visual {
            Visual::RichText {
                runs: visual_runs, ..
            } => runs.extend(visual_runs),
            Visual::Group { children } => {
                for child in children {
                    collect_text_runs(&child.visual, runs);
                }
            }
            Visual::Effect { visual, .. }
            | Visual::Layer { visual, .. }
            | Visual::TextEffects { visual, .. }
            | Visual::StrokeStyle { visual, .. }
            | Visual::AdvancedEffect { visual, .. }
            | Visual::TextLayout { visual, .. } => collect_text_runs(visual, runs),
            _ => {}
        }
    }

    fn all_text_runs(visual: &Visual) -> Vec<&TextRun> {
        let mut runs = Vec::new();
        collect_text_runs(visual, &mut runs);
        runs
    }

    fn pdf_text_objects(document: &Document) -> Vec<Object> {
        let mut result = Vec::new();
        for object in &document.objects {
            let Visual::Group { children } = &object.visual else {
                if object.text.is_some() {
                    result.push(object.clone());
                }
                continue;
            };
            if object.kind != ObjectKind::TextBox || object.text.is_none() {
                continue;
            }
            let semantic = object
                .text
                .as_deref()
                .unwrap_or_default()
                .chars()
                .collect::<Vec<_>>();
            let mut cursor = 0;
            for (index, child) in children.iter().enumerate() {
                let visual_length = visual_text(&child.visual).chars().count();
                let remaining_children = children.len() - index;
                let remaining_text = semantic.len().saturating_sub(cursor);
                let length = if remaining_children == 1 {
                    remaining_text
                } else {
                    visual_length
                        .max(1)
                        .min(remaining_text.saturating_sub(remaining_children - 1))
                };
                let mut item = object.clone();
                item.bounds = child.bounds;
                item.text = Some(semantic[cursor..cursor + length].iter().collect());
                item.visual = child.visual.clone();
                result.push(item);
                cursor += length;
            }
        }
        result
    }

    #[test]
    fn extracts_xfa_packets_from_the_pdfjs_corpus() {
        let Some(bytes) = pdfjs_fixture("xfa_filled_imm1344e.pdf") else {
            return;
        };
        let prepared = prepare(&bytes, Limits::default(), None).unwrap().unwrap();
        let packets = super::pdf_xfa_packets(&prepared.store, Limits::default());
        assert!(packets.get("template").is_some_and(|packet| {
            packet
                .windows(b"pageSet".len())
                .any(|value| value == b"pageSet")
        }));
        assert!(packets.get("datasets").is_some_and(|packet| {
            packet
                .windows(b"Leonhard".len())
                .any(|value| value == b"Leonhard")
        }));
        let pages = super::pdf_xfa::render(
            &packets["template"],
            &packets["datasets"],
            &packets["form"],
            Limits::default(),
        )
        .unwrap();
        assert_eq!(pages.len(), 7);
        assert!(pages.iter().all(|page| page.svg.starts_with(b"<svg")));
        assert!(pages.iter().any(|page| page.text.contains("Leonhard")));
        assert!(pages[0].text.contains("Gauss"));
        assert!(pages[0].text.contains("Johanna"));
        assert!(!pages[0].text.contains("SPONSOR CONTACT INFORMATION"));
        assert!(pages[1].text.contains("SPONSOR CONTACT INFORMATION"));
        assert!(pages[6].text.contains("DECLARATION"));
        let (document, _) = prepared
            .materialize(None, true, &BTreeSet::new(), 0)
            .unwrap();
        assert_eq!(document.units.len(), 7);
        assert_eq!(document.objects.len(), 7);
        assert!(document.objects.iter().all(|object| matches!(
            object.visual,
            Visual::Image {
                ref media_type,
                ..
            } if media_type == "image/svg+xml"
        )));
    }

