    #[test]
    fn preserves_rotated_soft_mask_bbox_as_a_path_clip() {
        let Some(bytes) = pdfjs_fixture("issue16742.pdf") else {
            return;
        };
        let document = detect_and_parse(&bytes, Limits::default())
            .unwrap()
            .unwrap();
        let has_diagonal_clip = document.objects.iter().any(|object| {
            let mut visual = &object.visual;
            while let Visual::Effect {
                clip,
                visual: nested,
                ..
            } = visual
            {
                if let Some(Geometry::Path { commands, .. }) = clip {
                    let points = commands.iter().filter_map(|command| match command {
                        PathCommand::MoveTo { x, y } | PathCommand::LineTo { x, y } => {
                            Some((*x, *y))
                        }
                        _ => None,
                    });
                    if points.clone().zip(points.skip(1)).any(|(left, right)| {
                        (left.0 - right.0).abs() > 0.01 && (left.1 - right.1).abs() > 0.01
                    }) {
                        return true;
                    }
                }
                visual = nested;
            }
            false
        });
        assert!(has_diagonal_clip);
    }

