    #[test]
    fn preserves_nested_knockout_group_alpha_while_clearing_the_parent_member() {
        fn backdrop_alpha(visual: &Visual) -> Option<u8> {
            match visual {
                Visual::Layer {
                    blend_mode: BlendMode::DestinationOut,
                    visual,
                    ..
                } => solid_alpha(visual),
                Visual::Effect { visual, .. }
                | Visual::Layer { visual, .. }
                | Visual::StrokeStyle { visual, .. }
                | Visual::TextLayout { visual, .. }
                | Visual::AdvancedEffect { visual, .. } => backdrop_alpha(visual),
                _ => None,
            }
        }
        fn solid_alpha(visual: &Visual) -> Option<u8> {
            match visual {
                Visual::PaintedShape {
                    fill: Paint::Solid(color),
                    ..
                } => Some(color.to_be_bytes()[3]),
                Visual::Effect { visual, .. }
                | Visual::Layer { visual, .. }
                | Visual::StrokeStyle { visual, .. }
                | Visual::TextLayout { visual, .. }
                | Visual::AdvancedEffect { visual, .. } => solid_alpha(visual),
                _ => None,
            }
        }
        let Some(bytes) = pdfjs_fixture("knockout_nested.pdf") else {
            return;
        };
        let document = detect_and_parse(&bytes, Limits::default())
            .unwrap()
            .unwrap();
        assert_eq!(document.objects.len(), 3);
        assert_eq!(
            document
                .objects
                .iter()
                .find_map(|object| backdrop_alpha(&object.visual)),
            Some(128),
        );
    }

    #[cfg(feature = "pdf-formats")]
    #[test]
    fn downsamples_oversized_ccitt_images_without_dropping_the_page() {
        fn embedded_image(visual: &Visual) -> Option<(&str, &[u8])> {
            match visual {
                Visual::Image {
                    media_type, bytes, ..
                } => Some((media_type, bytes)),
                Visual::ImageColorChange { visual, .. }
                | Visual::Layer { visual, .. }
                | Visual::Effect { visual, .. }
                | Visual::TextLayout { visual, .. }
                | Visual::StrokeStyle { visual, .. }
                | Visual::AdvancedEffect { visual, .. } => embedded_image(visual),
                _ => None,
            }
        }
        let Some(bytes) = pdfjs_fixture("freeculture.pdf") else {
            return;
        };
        let document = detect_and_parse(&bytes, Limits::default())
            .unwrap()
            .unwrap();
        let image = document.objects.iter().find(|object| {
            object.unit_index == 254
                && object.kind == ObjectKind::Image
                && object.bounds.width > 400.0
                && object.bounds.height > 500.0
                && matches!(
                    object.source.locator,
                    SourceLocator::Pdf {
                        kind: "image",
                        object_number: Some(900),
                        ..
                    }
                )
        });
        let (media_type, bytes) = embedded_image(&image.unwrap().visual).unwrap();
        assert!(media_type.starts_with("image/bmp"));
        assert!(bytes.len() < 4 * 1024 * 1024);
        assert!(bytes[62..].contains(&0));
        assert!(bytes[62..].contains(&255));
        assert!(!document.diagnostics.iter().any(|diagnostic| {
            diagnostic
                .details
                .iter()
                .any(|(key, value)| key == "unitIndex" && value == "254")
                && diagnostic.message.contains("CCITTFaxDecode")
        }));
    }

