    fn embedded_cmap_gid(font: &[u8], codepoint: u32) -> Option<u16> {
        super::best_truetype_cmap_gid(&super::truetype_cmap_subtables(font)?, codepoint, false)
    }

    fn single_glyph_truetype_font(flag: u8) -> Vec<u8> {
        let mut cmap = vec![0_u8; 24];
        super::set_u16(&mut cmap, 2, 1).unwrap();
        super::set_u16(&mut cmap, 4, 3).unwrap();
        super::set_u16(&mut cmap, 6, 1).unwrap();
        super::set_u32(&mut cmap, 8, 12).unwrap();
        super::set_u16(&mut cmap, 12, 6).unwrap();
        super::set_u16(&mut cmap, 14, 12).unwrap();
        super::set_u16(&mut cmap, 18, u16::from(b'A')).unwrap();
        super::set_u16(&mut cmap, 20, 1).unwrap();
        super::set_u16(&mut cmap, 22, 1).unwrap();
        let mut maxp = vec![0_u8; 32];
        maxp[..4].copy_from_slice(&0x0001_0000_u32.to_be_bytes());
        super::set_u16(&mut maxp, 4, 2).unwrap();
        let mut loca = vec![0_u8; 6];
        super::set_u16(&mut loca, 4, 9).unwrap();
        let mut glyf = vec![0_u8; 18];
        super::set_u16(&mut glyf, 0, 1).unwrap();
        super::set_u16(&mut glyf, 10, 0).unwrap();
        super::set_u16(&mut glyf, 12, 0).unwrap();
        glyf[14] = flag;
        glyf[15] = 1;
        glyf[16] = 1;
        super::build_sfnt(
            *b"true",
            vec![
                (*b"cmap", cmap),
                (*b"glyf", glyf),
                (*b"head", super::otf_head([0, 0, 1_000, 1_000])),
                (*b"hhea", super::otf_hhea(&[500, 600], 800, -200, 1_000)),
                (*b"hmtx", super::otf_hmtx(&[500, 600])),
                (*b"loca", loca),
                (*b"maxp", maxp),
            ],
        )
        .unwrap()
    }

    fn hex(bytes: &[u8]) -> String {
        bytes.iter().map(|byte| format!("{byte:02x}")).collect()
    }

    fn unhex(value: &str) -> Vec<u8> {
        value
            .as_bytes()
            .chunks_exact(2)
            .map(|pair| u8::from_str_radix(std::str::from_utf8(pair).unwrap(), 16).unwrap())
            .collect()
    }

