    fn encrypted_pdf_r2() -> Vec<u8> {
        let user_password = b"secret";
        let owner_key = &md5(&padded_password(b"owner"))[..5];
        let owner = rc4(owner_key, &padded_password(user_password));
        let permissions = -4_i32;
        let file_id = b"0123456789abcdef";
        let file_key = legacy_file_key(user_password, &owner, permissions, file_id, 2, 5, true);
        let user = rc4(&file_key, &super::PASSWORD_PADDING);
        let mut object_key_input = file_key;
        object_key_input.extend_from_slice(&4_u32.to_le_bytes()[..3]);
        object_key_input.extend_from_slice(&0_u16.to_le_bytes());
        let object_key = md5(&object_key_input);
        let content = b"0.9 g 10 20 100 40 re f BT /F1 12 Tf 1 0 0 1 72 720 Tm (Hello PDF) Tj ET\n";
        let encrypted_content = rc4(&object_key[..10], content);
        let mut bytes = format!(
            "%PDF-1.4\n\
1 0 obj << /Type /Catalog /Pages 2 0 R >> endobj\n\
2 0 obj << /Type /Pages /Kids [3 0 R] /Count 1 /MediaBox [0 0 612 792] >> endobj\n\
3 0 obj << /Type /Page /Parent 2 0 R /Resources << /Font << /F1 5 0 R >> >> /Contents 4 0 R >> endobj\n\
4 0 obj << /Length {} >> stream\n",
            encrypted_content.len(),
        )
        .into_bytes();
        bytes.extend_from_slice(&encrypted_content);
        bytes.extend_from_slice(
            format!(
                "\nendstream endobj\n\
5 0 obj << /Type /Font /Subtype /Type1 /BaseFont /Helvetica >> endobj\n\
6 0 obj << /Filter /Standard /V 1 /R 2 /O <{}> /U <{}> /P {} >> endobj\n\
trailer << /Root 1 0 R /Encrypt 6 0 R /ID [<{}> <{}>] >>\n%%EOF",
                hex(&owner),
                hex(&user),
                permissions,
                hex(file_id),
                hex(file_id),
            )
            .as_bytes(),
        );
        bytes
    }

    fn pack_lzw_codes(codes: &[(usize, usize)]) -> Vec<u8> {
        let bit_count = codes.iter().map(|(_, width)| width).sum::<usize>();
        let mut bytes = vec![0_u8; bit_count.div_ceil(8)];
        let mut bit_position = 0_usize;
        for &(code, width) in codes {
            assert!(width <= 12 && code < 1 << width);
            for shift in (0..width).rev() {
                bytes[bit_position / 8] |= ((code >> shift) as u8 & 1) << (7 - bit_position % 8);
                bit_position += 1;
            }
        }
        bytes
    }

