    #[test]
    fn decodes_lzw_pdf_rasters() {
        let mut bytes = b"%PDF-1.7
1 0 obj << /Type /Catalog /Pages 2 0 R >> endobj
2 0 obj << /Type /Pages /Kids [3 0 R] /Count 1 /MediaBox [0 0 10 10] >> endobj
3 0 obj << /Type /Page /Parent 2 0 R /Resources << /XObject << /Im0 5 0 R >> >> /Contents 4 0 R >> endobj
4 0 obj << >> stream
q 10 0 0 10 0 0 cm /Im0 Do Q
endstream endobj
5 0 obj << /Type /XObject /Subtype /Image /Width 1 /Height 1 /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /LZWDecode /Length 6 >> stream
"
        .to_vec();
        // Clear, 0x10, 0x20, 0x30, EOD as MSB-first 9-bit PDF LZW codes.
        bytes.extend_from_slice(&[0x80, 0x04, 0x04, 0x03, 0x08, 0x08]);
        bytes.extend_from_slice(b"\nendstream endobj\ntrailer << /Root 1 0 R >>\n%%EOF");

        let document = detect_and_parse(&bytes, Limits::default())
            .unwrap()
            .unwrap();
        let Visual::Image {
            media_type, bytes, ..
        } = &document.objects[0].visual
        else {
            panic!("LZW PDF raster must remain an image");
        };
        assert_eq!(media_type, "image/bmp;interpolate=false");
        assert_eq!(&bytes[70..74], &[0x30, 0x20, 0x10, 0xff]);
    }

    #[test]
    fn decodes_jbig2_pdf_images_to_bounded_monochrome_bmp() {
        let mut bytes = b"%PDF-1.7
1 0 obj << /Type /Catalog /Pages 2 0 R >> endobj
2 0 obj << /Type /Pages /Kids [3 0 R] /Count 1 /MediaBox [0 0 100 100] >> endobj
3 0 obj << /Type /Page /Parent 2 0 R /Resources << /Font << /F1 6 0 R >> /XObject << /Im0 5 0 R >> >> /Contents 4 0 R >> endobj
4 0 obj << >> stream
BT /F1 10 Tf 1 0 0 1 10 80 Tm (Readable text) Tj ET
q 80 0 0 40 10 10 cm /Im0 Do Q
endstream endobj
5 0 obj << /Type /XObject /Subtype /Image /Width 95 /Height 409 /BitsPerComponent 1 /ColorSpace /DeviceGray /Filter /JBIG2Decode /Length 104 >> stream
"
        .to_vec();
        bytes.extend_from_slice(&[
            0, 0, 0, 0, 48, 0, 1, 0, 0, 0, 19, 0, 0, 0, 95, 0, 0, 1, 153, 0, 0, 0, 0, 0, 0, 0, 0,
            64, 0, 0, 0, 0, 0, 1, 38, 0, 1, 0, 0, 0, 63, 0, 0, 0, 95, 0, 0, 1, 153, 0, 0, 0, 0, 0,
            0, 0, 0, 2, 0, 3, 255, 253, 255, 2, 254, 254, 254, 163, 83, 136, 153, 177, 117, 34, 28,
            8, 18, 77, 251, 30, 51, 73, 117, 175, 250, 245, 54, 229, 5, 43, 180, 4, 87, 86, 182,
            167, 12, 26, 214, 74, 227, 127, 255, 172,
        ]);
        bytes.extend_from_slice(
            b"
endstream endobj
6 0 obj << /Type /Font /Subtype /Type1 /BaseFont /Helvetica >> endobj
trailer << /Root 1 0 R >>
%%EOF",
        );

        let document = detect_and_parse(&bytes, Limits::default())
            .unwrap()
            .unwrap();

        assert!(
            document
                .objects
                .iter()
                .any(|object| object.text.as_deref() == Some("Readable text"))
        );
        let image = document
            .objects
            .iter()
            .find(|object| object.kind == ObjectKind::Image)
            .unwrap();
        let Visual::Image {
            media_type, bytes, ..
        } = &image.visual
        else {
            panic!("JBIG2 PDF resource must remain an image");
        };
        assert_eq!(media_type, "image/bmp;interpolate=false");
        assert_eq!(&bytes[..2], b"BM");
        assert_eq!(u32::from_le_bytes(bytes[10..14].try_into().unwrap()), 62);
        assert_eq!(u32::from_le_bytes(bytes[18..22].try_into().unwrap()), 95);
        assert_eq!(u32::from_le_bytes(bytes[22..26].try_into().unwrap()), 409);
        let row_stride = 12;
        let black_pixels = (0..409)
            .flat_map(|row| {
                (0..95).map(move |column| {
                    bytes[62 + row * row_stride + column / 8] & (1 << (7 - column % 8)) != 0
                })
            })
            .filter(|black| *black)
            .count();
        assert_eq!(black_pixels, 42);
        assert!(
            document
                .diagnostics
                .iter()
                .all(|diagnostic| { !diagnostic.message.contains("PDF_IMAGE_FILTER_UNSUPPORTED") })
        );
    }

