    #[test]
    fn switches_lzw_code_width_for_both_early_change_modes() {
        let mut early_codes = vec![(256, 9)];
        early_codes.extend((0..255).map(|index| (index, if index < 254 { 9 } else { 10 })));
        early_codes.push((257, 10));
        assert_eq!(
            decode_lzw(&pack_lzw_codes(&early_codes), 1, Limits::default()).unwrap(),
            (0_u8..=254).collect::<Vec<_>>(),
        );

        let mut late_codes = vec![(256, 9)];
        late_codes.extend((0..256).map(|index| (index, if index < 255 { 9 } else { 10 })));
        late_codes.push((257, 10));
        assert_eq!(
            decode_lzw(&pack_lzw_codes(&late_codes), 0, Limits::default()).unwrap(),
            (0_u8..=255).collect::<Vec<_>>(),
        );
    }

    #[test]
    fn rejects_truncated_invalid_and_over_budget_lzw_streams() {
        assert!(
            decode_lzw(&[], 2, Limits::default())
                .unwrap_err()
                .message
                .contains("EarlyChange")
        );

        let truncated = pack_lzw_codes(&[(256, 9), (65, 9)]);
        assert!(
            decode_lzw(&truncated, 1, Limits::default())
                .unwrap_err()
                .message
                .contains("truncated")
        );

        let invalid = pack_lzw_codes(&[(256, 9), (300, 9), (257, 9)]);
        assert!(
            decode_lzw(&invalid, 1, Limits::default())
                .unwrap_err()
                .message
                .contains("invalid PDF LZWDecode code")
        );

        let over_budget = pack_lzw_codes(&[(256, 9), (65, 9), (66, 9), (257, 9)]);
        let limits = Limits {
            max_entry_uncompressed_bytes: 1,
            ..Limits::default()
        };
        assert!(
            decode_lzw(&over_budget, 1, limits)
                .unwrap_err()
                .message
                .contains("configured byte limit")
        );
    }

