    #[test]
    fn preserves_all_standard_blend_modes_from_the_exact_pdf_fixture() {
        let Some(bytes) = pdfjs_fixture("blendmode.pdf") else {
            return;
        };
        let document = detect_and_parse(&bytes, Limits::default())
            .unwrap()
            .unwrap();
        let modes = document
            .objects
            .iter()
            .filter_map(|object| match &object.visual {
                Visual::Layer { blend_mode, .. } if *blend_mode != BlendMode::Normal => {
                    Some(*blend_mode)
                }
                _ => None,
            })
            .collect::<Vec<_>>();
        assert_eq!(
            modes,
            [
                BlendMode::Multiply,
                BlendMode::Screen,
                BlendMode::Overlay,
                BlendMode::Darken,
                BlendMode::Lighten,
                BlendMode::ColorDodge,
                BlendMode::ColorBurn,
                BlendMode::HardLight,
                BlendMode::SoftLight,
                BlendMode::Difference,
                BlendMode::Exclusion,
                BlendMode::Hue,
                BlendMode::Saturation,
                BlendMode::Color,
                BlendMode::Luminosity,
            ]
        );
    }

    #[test]
    fn parses_fixed_page_text_and_vector_path_without_a_pdf_dependency() {
        let document = detect_and_parse(&simple_pdf(""), Limits::default())
            .unwrap()
            .unwrap();
        assert_eq!(document.format, Some(DocumentFormat::Pdf));
        assert_eq!(document.units.len(), 1);
        assert!((document.units[0].width - 816.0).abs() < 0.01);
        assert!((document.units[0].height - 1056.0).abs() < 0.01);
        assert!(
            document
                .objects
                .iter()
                .any(|object| object.kind == ObjectKind::Shape)
        );
        let text = document
            .objects
            .iter()
            .find(|object| object.text.as_deref() == Some("Hello PDF"))
            .unwrap();
        assert!(matches!(text.visual, Visual::TextLayout { .. }));
        assert!(matches!(
            text.source.locator,
            SourceLocator::Pdf { kind: "text", .. }
        ));
    }

    #[test]
    fn preserves_pdf_line_dash_arrays_on_stroked_paths() {
        let bytes = b"%PDF-1.7
1 0 obj << /Type /Catalog /Pages 2 0 R >> endobj
2 0 obj << /Type /Pages /Kids [3 0 R] /Count 1 /MediaBox [0 0 100 100] >> endobj
3 0 obj << /Type /Page /Parent 2 0 R /Contents 4 0 R >> endobj
4 0 obj << >> stream
1 J 2 j 3 M [0 2] 0 d 2 w 10 20 m 90 20 l S
endstream endobj
trailer << /Root 1 0 R >>
%%EOF";
        let document = detect_and_parse(bytes, Limits::default()).unwrap().unwrap();
        let Visual::StrokeStyle { style, visual } = &document.objects[0].visual else {
            panic!("a dashed PDF path must retain its stroke style");
        };
        assert_eq!(style.cap, LineCap::Round);
        assert_eq!(style.join, LineJoin::Bevel);
        assert_eq!(style.miter_limit, 3.0);
        assert_eq!(style.dash, vec![0.0, 8.0 / 3.0]);
        assert!(matches!(visual.as_ref(), Visual::PaintedShape { .. }));
    }

    #[test]
    fn preserves_pdf_extended_line_graphics_state() {
        let bytes = b"%PDF-1.7
1 0 obj << /Type /Catalog /Pages 2 0 R >> endobj
2 0 obj << /Type /Pages /Kids [3 0 R] /Count 1 /MediaBox [0 0 100 100] >> endobj
3 0 obj << /Type /Page /Parent 2 0 R /Resources << /ExtGState << /GS0 5 0 R >> >> /Contents 4 0 R >> endobj
4 0 obj << >> stream
/GS0 gs 10 20 m 90 20 l S
endstream endobj
5 0 obj << /Type /ExtGState /LW 2 /LC 1 /LJ 2 /ML 3 /D [[6 2] 0] >> endobj
trailer << /Root 1 0 R >>
%%EOF";
        let document = detect_and_parse(bytes, Limits::default()).unwrap().unwrap();
        let Visual::StrokeStyle { style, visual } = &document.objects[0].visual else {
            panic!("an ExtGState dashed path must retain its stroke style");
        };
        assert_eq!(style.cap, LineCap::Round);
        assert_eq!(style.join, LineJoin::Bevel);
        assert_eq!(style.miter_limit, 3.0);
        assert_eq!(style.dash, vec![8.0, 8.0 / 3.0]);
        let Visual::PaintedShape { stroke_width, .. } = visual.as_ref() else {
            panic!("the stroke style must wrap a painted path");
        };
        assert_eq!(*stroke_width, 8.0 / 3.0);
    }

    #[test]
    fn applies_pdf_text_rise_to_text_geometry() {
        let bytes = b"%PDF-1.7
1 0 obj << /Type /Catalog /Pages 2 0 R >> endobj
2 0 obj << /Type /Pages /Kids [3 0 R] /Count 1 /MediaBox [0 0 100 100] >> endobj
3 0 obj << /Type /Page /Parent 2 0 R /Resources << /Font << /F1 5 0 R >> >> /Contents 4 0 R >> endobj
4 0 obj << >> stream
BT /F1 10 Tf 1 0 0 1 10 50 Tm (A) Tj ET
BT /F1 10 Tf 10 Ts 1 0 0 1 10 50 Tm (B) Tj ET
endstream endobj
5 0 obj << /Type /Font /Subtype /Type1 /BaseFont /Helvetica >> endobj
trailer << /Root 1 0 R >>
%%EOF";
        let document = detect_and_parse(bytes, Limits::default()).unwrap().unwrap();
        let first = document
            .objects
            .iter()
            .find(|object| object.text.as_deref() == Some("A"))
            .unwrap();
        let raised = document
            .objects
            .iter()
            .find(|object| object.text.as_deref() == Some("B"))
            .unwrap();
        assert!((first.bounds.y - raised.bounds.y - 40.0 / 3.0).abs() < 0.01);
    }

