    #[test]
    fn maps_canvas_subset_differences_through_the_symbolic_cmap() {
        let bytes = pdfjs_fixture_or_skip!("canvas.pdf");
        let prepared = prepare(&bytes, Limits::default(), None).unwrap().unwrap();
        let source = super::decode_stream(
            &prepared.store.objects[&(39, 0)].value,
            &prepared.store,
            Limits::default(),
        )
        .unwrap();
        let stale_unicode_gid = super::best_truetype_cmap_gid(
            &super::truetype_cmap_subtables(&source).unwrap(),
            '(' as u32,
            false,
        )
        .unwrap();
        let expected = super::best_truetype_cmap_gid(
            &super::truetype_cmap_subtables(&source).unwrap(),
            0xf01a,
            true,
        )
        .unwrap();
        assert_ne!(stale_unicode_gid, expected);
        let document = prepared
            .materialize(Some(1), true, &BTreeSet::new(), 0)
            .unwrap()
            .0;
        let font = document
            .embedded_fonts
            .iter()
            .find(|font| font.family.starts_with("JONZVR+TrebuchetMS"))
            .unwrap();
        assert_eq!(embedded_cmap_gid(&font.bytes, '(' as u32), Some(expected));
        assert_eq!(sfnt_checksum(&font.bytes), 0xb1b0_afba);
    }

