    #[test]
    fn clears_reserved_simple_glyph_flags_when_rebuilding_pdf_truetype_fonts() {
        let (signature, tables, glyph_count) =
            super::truetype_parts(&single_glyph_truetype_font(0x97)).unwrap();

        let font = super::finish_truetype_cmap(
            signature,
            tables,
            glyph_count,
            BTreeMap::from([('中' as u32, 1)]),
            &FontInfo::default(),
        )
        .unwrap();
        let (_, tables, _) = super::truetype_parts(&font).unwrap();
        let glyf = tables
            .iter()
            .find_map(|(tag, bytes)| (tag == b"glyf").then_some(bytes))
            .unwrap();

        assert_eq!(glyf[14], 0x17);
        assert_eq!(sfnt_checksum(&font), 0xb1b0_afba);
    }

    #[test]
    fn pads_missing_left_side_bearings_when_rebuilding_pdf_truetype_fonts() {
        let (signature, mut tables, glyph_count) =
            super::truetype_parts(&single_glyph_truetype_font(0x17)).unwrap();
        super::set_u16(
            tables
                .iter_mut()
                .find_map(|(tag, bytes)| (tag == b"hhea").then_some(bytes))
                .unwrap(),
            34,
            1,
        )
        .unwrap();
        tables
            .iter_mut()
            .find_map(|(tag, bytes)| (tag == b"hmtx").then_some(bytes))
            .unwrap()
            .truncate(4);

        let font = super::finish_truetype_cmap(
            signature,
            tables,
            glyph_count,
            BTreeMap::from([('中' as u32, 1)]),
            &FontInfo::default(),
        )
        .unwrap();
        let (_, tables, _) = super::truetype_parts(&font).unwrap();
        let hmtx = tables
            .iter()
            .find_map(|(tag, bytes)| (tag == b"hmtx").then_some(bytes))
            .unwrap();

        assert_eq!(hmtx, &[0x01, 0xf4, 0x00, 0x00, 0x00, 0x00]);
    }

