    #[test]
    fn recovers_linearized_pages_when_the_page_tree_object_is_missing() {
        let bytes = b"%PDF-1.4
9 0 obj << /Linearized 1 /N 3 /O 10 >> endobj
1 0 obj << /Type /Catalog /Pages 99 0 R >> endobj
10 0 obj << /Type /Page /Parent 99 0 R /MediaBox [0 0 100 200] /Resources << /Font << /F1 12 0 R >> /XObject << /Im0 13 0 R >> >> /Contents 14 0 R >> endobj
11 0 obj << /Type /Page /Parent 99 0 R /MediaBox [0 0 200 100] >> endobj
12 0 obj << /Type /Font /Subtype /Type0 /BaseFont /Test /Encoding /Identity-H /DescendantFonts [15 0 R] /ToUnicode 16 0 R >> endobj
13 0 obj << /Type /XObject /Subtype /Image /Width 1 /Height 1 /BitsPerComponent 8 /ColorSpace /DeviceRGB /Length 3 >> stream
\xff\0\0
endstream endobj
14 0 obj << >> stream
BT /F1 12 Tf <0036> Tj ET q 1 0 0 1 0 0 cm /Im0 Do Q
endstream endobj
15 0 obj << /Type /Font /Subtype /CIDFontType2 /BaseFont /Test /DW 500 >> endobj
16 0 obj << >> stream
1 beginbfchar <0036> <0053> endbfchar
endstream endobj
trailer << /Root 1 0 R >>
%%EOF";
        let document = detect_and_parse(bytes, Limits::default()).unwrap().unwrap();
        assert_eq!(document.units.len(), 3);
        assert_eq!(document.units[0].id, "pdf:page:10");
        assert!(
            document
                .objects
                .iter()
                .any(|object| { object.unit_index == 0 && object.text.as_deref() == Some("S") })
        );
        assert!(
            document
                .objects
                .iter()
                .any(|object| { object.unit_index == 0 && object.kind == ObjectKind::Image })
        );
        assert!((document.units[2].width - 816.0).abs() < 0.01);
        assert!((document.units[2].height - 1056.0).abs() < 0.01);

        let no_recoverable_page = b"%PDF-1.4
9 0 obj << /Linearized 1 /N 1 /O 10 >> endobj
1 0 obj << /Type /Catalog /Pages 99 0 R >> endobj
%%EOF";
        assert!(detect_and_parse(no_recoverable_page, Limits::default()).is_err());
    }

