    #[test]
    fn uses_nested_image_soft_masks_as_transparency_group_rasters() {
        fn nested_mask(visual: &Visual) -> Option<(u32, u32, &str, &[u8])> {
            match visual {
                Visual::MaskedImage {
                    mask_width,
                    mask_height,
                    mask_media_type,
                    alpha_mask,
                    ..
                } => Some((*mask_width, *mask_height, mask_media_type, alpha_mask)),
                Visual::Effect { visual, .. }
                | Visual::Layer { visual, .. }
                | Visual::StrokeStyle { visual, .. }
                | Visual::TextLayout { visual, .. }
                | Visual::AdvancedEffect { visual, .. } => nested_mask(visual),
                _ => None,
            }
        }
        let Some(bytes) = pdfjs_fixture("issue18956.pdf") else {
            return;
        };
        let document = detect_and_parse(&bytes, Limits::default())
            .unwrap()
            .unwrap();
        let (width, height, media_type, mask) = document
            .objects
            .iter()
            .find_map(|object| nested_mask(&object.visual))
            .expect("the nested image SMask must survive as the group raster mask");
        assert_eq!((width, height), (728, 90));
        assert!(
            mask.starts_with(&[0xff, 0xd8]),
            "media_type={media_type}, prefix={:?}",
            mask.get(..mask.len().min(8))
        );
        assert!(mask.windows(2).any(|window| window == [0xff, 0xd9]));
    }

    #[test]
    fn preserves_empty_alpha_soft_masks_as_fully_transparent() {
        fn fill_alphas(visual: &Visual) -> Option<Vec<u8>> {
            match visual {
                Visual::PaintedShape {
                    fill: Paint::LinearGradient { stops, .. },
                    ..
                } => Some(
                    stops
                        .iter()
                        .map(|stop| stop.color.to_be_bytes()[3])
                        .collect(),
                ),
                Visual::Effect { visual, .. }
                | Visual::Layer { visual, .. }
                | Visual::StrokeStyle { visual, .. }
                | Visual::TextLayout { visual, .. }
                | Visual::AdvancedEffect { visual, .. } => fill_alphas(visual),
                _ => None,
            }
        }

        let bytes = pdfjs_fixture_or_skip!("nonisolated_blend_smask.pdf");
        let document = detect_and_parse(&bytes, Limits::default())
            .unwrap()
            .unwrap();
        let alphas = document
            .objects
            .iter()
            .filter(|object| object.bounds.y < 100.0 && object.bounds.x > 200.0)
            .find_map(|object| fill_alphas(&object.visual))
            .expect("the empty soft mask must remain attached to its red source shape");
        assert!(!alphas.is_empty());
        assert!(alphas.iter().all(|alpha| *alpha == 0));
        assert!(
            document
                .diagnostics
                .iter()
                .all(|diagnostic| { !diagnostic.message.contains("PDF_SOFT_MASK_UNSUPPORTED") })
        );
    }

