    #[test]
    fn applies_a_form_transparency_group_invocation_blend_mode() {
        fn has_difference(visual: &Visual) -> bool {
            match visual {
                Visual::Layer {
                    blend_mode: BlendMode::Difference,
                    ..
                } => true,
                Visual::Layer { visual, .. }
                | Visual::Effect { visual, .. }
                | Visual::TextLayout { visual, .. }
                | Visual::StrokeStyle { visual, .. }
                | Visual::AdvancedEffect { visual, .. }
                | Visual::ImageColorChange { visual, .. } => has_difference(visual),
                Visual::Media { poster, .. } => has_difference(poster),
                _ => false,
            }
        }

        let Some(bytes) = pdfjs_fixture("transparency_group.pdf") else {
            return;
        };
        let document = detect_and_parse(&bytes, Limits::default())
            .unwrap()
            .unwrap();

        assert!(
            document
                .objects
                .iter()
                .any(|object| has_difference(&object.visual)),
            "the Difference blend selected for the Form invocation must survive the Form's internal Normal graphics state"
        );
    }

    #[test]
    fn renders_the_tracemonkey_figures_and_title_spacing() {
        fn preserves_clip(visual: &Visual) -> bool {
            match visual {
                Visual::Effect { clip: Some(_), .. } => true,
                Visual::PaintedShape {
                    geometry: Geometry::Path { .. },
                    ..
                } => true,
                Visual::Layer { visual, .. }
                | Visual::Effect { visual, .. }
                | Visual::TextLayout { visual, .. }
                | Visual::StrokeStyle { visual, .. }
                | Visual::AdvancedEffect { visual, .. }
                | Visual::ImageColorChange { visual, .. } => preserves_clip(visual),
                Visual::Media { poster, .. } => preserves_clip(poster),
                _ => false,
            }
        }

        let Some(bytes) = pdfjs_fixture("tracemonkey.pdf") else {
            return;
        };
        let document = detect_and_parse(&bytes, Limits::default())
            .unwrap()
            .unwrap();
        let page_six = document
            .objects
            .iter()
            .filter(|object| object.unit_index == 5)
            .collect::<Vec<_>>();
        assert!(page_six.iter().any(|object| {
            matches!(
                object.source.locator,
                SourceLocator::Pdf {
                    object_number: Some(118),
                    ..
                }
            ) && object.text.as_deref() == Some("Side\u{2029}Exit")
        }));
        assert!(page_six.iter().any(|object| {
            matches!(
                object.source.locator,
                SourceLocator::Pdf {
                    object_number: Some(119),
                    ..
                }
            ) && object.bounds.width > 700.0
                && preserves_clip(&object.visual)
        }));
        assert!(
            document
                .objects
                .iter()
                .filter(|object| object.unit_index == 0)
                .filter_map(|object| object.text.as_deref())
                .collect::<String>()
                .contains("race-based")
        );
        assert!(document.objects.iter().any(|object| {
            object.unit_index == 0
                && matches!(
                    &object.visual,
                    Visual::TextLayout { layout, .. } if layout.text_scale_to_fit
                )
        }));
    }

    #[cfg(feature = "pdf-formats")]
    #[test]
    fn keeps_tracemonkey_annotation_fonts_browser_valid() {
        fn text_runs(visual: &Visual) -> Option<&[TextRun]> {
            match visual {
                Visual::RichText { runs, .. } => Some(runs),
                Visual::Layer { visual, .. }
                | Visual::Effect { visual, .. }
                | Visual::TextLayout { visual, .. }
                | Visual::StrokeStyle { visual, .. }
                | Visual::AdvancedEffect { visual, .. }
                | Visual::ImageColorChange { visual, .. } => text_runs(visual),
                Visual::Media { poster, .. } => text_runs(poster),
                _ => None,
            }
        }

        let bytes = pdfjs_fixture_or_skip!("tracemonkey_with_annotations.pdf");
        let document = detect_and_parse(&bytes, Limits::default())
            .unwrap()
            .unwrap();
        assert_eq!(document.embedded_fonts.len(), 18);
        assert!(
            document
                .embedded_fonts
                .iter()
                .all(|font| !super::uses_browser_independent_source_glyph_outlines(&font.family))
        );
        let mut cff_count = 0;
        for font in &document.embedded_fonts {
            assert_eq!(sfnt_checksum(&font.bytes), 0xb1b0_afba);
            let runs = document
                .objects
                .iter()
                .filter_map(|object| text_runs(&object.visual))
                .flatten()
                .filter(|run| run.font_family == font.family)
                .collect::<Vec<_>>();
            let missing = runs
                .iter()
                .flat_map(|run| run.text.chars())
                .filter(|character| {
                    embedded_cmap_gid(&font.bytes, *character as u32).unwrap_or(0) == 0
                })
                .collect::<BTreeSet<_>>();
            assert!(missing.is_empty(), "{} missing {missing:?}", font.family);
            let Some(cff) = super::sfnt_table(&font.bytes, b"CFF ") else {
                continue;
            };
            cff_count += 1;
            let header_size = usize::from(cff[2]);
            let (_, after_names) = super::cff_index(cff, header_size).unwrap();
            let (top_dicts, _) = super::cff_index(cff, after_names).unwrap();
            let char_strings_offset =
                usize::try_from(super::cff_dict_integer_operands(top_dicts[0], 17).unwrap()[0])
                    .unwrap();
            let (char_strings, _) = super::cff_index(cff, char_strings_offset).unwrap();
            assert!(
                char_strings
                    .iter()
                    .all(|charstring| super::pdf_type1::browser_safe_type2_charstring(charstring)),
                "{} has a browser-invalid CFF charstring",
                font.family,
            );
        }
        assert_eq!(cff_count, 9);
    }

