    #[test]
    fn preserves_issue13211_embedded_math_fonts_and_baselines() {
        fn text_runs(visual: &Visual) -> Option<&[TextRun]> {
            match visual {
                Visual::RichText { runs, .. } => Some(runs),
                Visual::Layer { visual, .. }
                | Visual::Effect { visual, .. }
                | Visual::TextLayout { visual, .. }
                | Visual::StrokeStyle { visual, .. }
                | Visual::AdvancedEffect { visual, .. }
                | Visual::ImageColorChange { visual, .. } => text_runs(visual),
                Visual::Media { poster, .. } => text_runs(poster),
                _ => None,
            }
        }

        let bytes = pdfjs_fixture_or_skip!("issue13211.pdf");
        let document = detect_and_parse(&bytes, Limits::default())
            .unwrap()
            .unwrap();
        let text_objects = pdf_text_objects(&document);
        for font in &document.embedded_fonts {
            let runs = text_objects
                .iter()
                .filter_map(|object| text_runs(&object.visual))
                .flatten()
                .filter(|run| run.font_family == font.family)
                .collect::<Vec<_>>();
            if font.family.contains("Symbol") || font.family.contains("MTExtra") {
                assert!(
                    !runs.is_empty(),
                    "{} must paint with its embedded face",
                    font.family
                );
            }
            let missing = runs
                .into_iter()
                .flat_map(|run| run.text.chars())
                .filter(|character| {
                    embedded_cmap_gid(&font.bytes, *character as u32).unwrap_or(0) == 0
                })
                .collect::<BTreeSet<_>>();
            assert!(missing.is_empty(), "{} missing {missing:?}", font.family);
        }

        let number = text_objects
            .iter()
            .find(|object| {
                object.text.as_deref() == Some("1")
                    && text_runs(&object.visual).is_some_and(|runs| {
                        runs.first()
                            .is_some_and(|run| run.font_family.contains("CmPrasanmit PDF 25"))
                    })
            })
            .expect("first answer number");
        let Visual::TextLayout { layout, .. } = &number.visual else {
            panic!("expected positioned answer number");
        };
        let run = text_runs(&number.visual).unwrap().first().unwrap();
        assert!((layout.text_baseline - run.font_size * 0.8).abs() < 0.01);

        let question_16_number = text_objects
            .iter()
            .find(|object| {
                object.text.as_deref() == Some("1") && (320.0..340.0).contains(&object.bounds.y)
            })
            .expect("question 16 first answer number");
        assert!(question_16_number.bounds.x > 110.0);

        let numerator = text_objects
            .iter()
            .find(|object| object.text.as_deref() == Some("kk"))
            .expect("question 16 numerator");
        let Visual::TextLayout { layout, .. } = &numerator.visual else {
            panic!("expected positioned numerator");
        };
        let fraction_bar = document
            .objects
            .iter()
            .find(|object| {
                object.kind == ObjectKind::Shape
                    && object.bounds.height <= 0.02
                    && object.bounds.x <= numerator.bounds.x
                    && object.bounds.x + object.bounds.width
                        >= numerator.bounds.x + numerator.bounds.width
                    && object.bounds.y >= numerator.bounds.y
                    && object.bounds.y <= numerator.bounds.y + numerator.bounds.height
            })
            .expect("question 16 fraction bar");
        assert!(
            numerator.bounds.y + layout.text_baseline < fraction_bar.bounds.y,
            "numerator baseline {} crosses fraction bar {}",
            numerator.bounds.y + layout.text_baseline,
            fraction_bar.bounds.y
        );
    }

