    #[test]
    fn accepts_libreoffice_revision_three_open_and_permission_passwords() {
        let dictionary = BTreeMap::from([
            ("Filter".to_owned(), PdfValue::Name("Standard".to_owned())),
            ("V".to_owned(), PdfValue::Number(2.0)),
            ("Length".to_owned(), PdfValue::Number(128.0)),
            ("R".to_owned(), PdfValue::Number(3.0)),
            (
                "O".to_owned(),
                PdfValue::String(unhex(
                    "27ee85c8447a38715eae7d6003dc487619ca05a05b68b65eccaa26394df7169c",
                )),
            ),
            (
                "U".to_owned(),
                PdfValue::String(unhex(
                    "8fc5f6b7b6105307bb68b58098b6884800000000000000000000000000000000",
                )),
            ),
            ("P".to_owned(), PdfValue::Number(-1028.0)),
        ]);
        let file_id = unhex("401d00642aa19414cca931828bf769b3");
        assert_eq!(
            hex(&legacy_file_key(
                b"openpassword",
                dictionary.get("O").and_then(super::pdf_string).unwrap(),
                -1028,
                &file_id,
                3,
                16,
                true,
            )),
            "a00b076fe09db742602e800e57f0efac"
        );
        assert!(legacy_security_handler(&dictionary, &file_id, b"openpassword", 3, 0).is_ok());
        assert!(
            legacy_security_handler(&dictionary, &file_id, b"permissionpassword", 3, 0).is_ok()
        );
    }

