    #[test]
    fn tolerates_raw_deflate_and_corrupt_adler_wrappers_used_by_viewers() {
        let raw = [0xcb, 0x48, 0xcd, 0xc9, 0xc9, 0x07, 0x00];
        assert_eq!(inflate_zlib(&raw, Limits::default()).unwrap(), b"hello");

        let corrupt_checksum = [
            0x78, 0x9c, 0xcb, 0x48, 0xcd, 0xc9, 0xc9, 0x07, 0x00, 0x00, 0x00, 0x00, 0x00,
        ];
        assert_eq!(
            inflate_zlib(&corrupt_checksum, Limits::default()).unwrap(),
            b"hello"
        );
    }

    #[test]
    #[cfg(feature = "pdf-formats")]
    fn decodes_brotli_streams_within_the_pdf_entry_limit() {
        let bytes = [0x0f, 0x02, 0x80, 0x68, 0x65, 0x6c, 0x6c, 0x6f, 0x03];
        assert_eq!(decode_brotli(&bytes, Limits::default()).unwrap(), b"hello");
        assert!(
            decode_brotli(
                &bytes,
                Limits {
                    max_entry_uncompressed_bytes: 4,
                    ..Limits::default()
                }
            )
            .is_err()
        );
        assert!(decode_brotli(&[0xff], Limits::default()).is_err());
    }

    #[test]
    fn tolerates_one_pdf_eol_after_a_complete_zlib_member() {
        let member = [
            0x78, 0x9c, 0xcb, 0x48, 0xcd, 0xc9, 0xc9, 0x07, 0x00, 0x06, 0x2c, 0x02, 0x15,
        ];
        for eol in [b"\n".as_slice(), b"\r".as_slice(), b"\r\n".as_slice()] {
            let bytes = [member.as_slice(), eol].concat();
            assert_eq!(inflate_zlib(&bytes, Limits::default()).unwrap(), b"hello");
        }
        let invalid = [member.as_slice(), b"x"].concat();
        assert!(inflate_zlib(&invalid, Limits::default()).is_err());
    }

    #[test]
    fn tolerates_pdf_flate_streams_missing_the_final_block_and_adler_checksum() {
        let bytes = [0x78, 0x9c, 0xcb, 0x48, 0xcd, 0xc9, 0xc9, 0x07];
        assert_eq!(
            crate::deflate::decompress(&bytes[2..], 32, None)
                .unwrap_err()
                .kind,
            crate::deflate::DeflateErrorKind::UnexpectedEnd
        );
        assert_eq!(inflate_zlib(&bytes, Limits::default()).unwrap(), b"hello");
    }

