    #[test]
    fn batches_contiguous_pdf_text_without_relaying_out_child_visuals() {
        let bytes = b"%PDF-1.7
1 0 obj << /Type /Catalog /Pages 2 0 R >> endobj
2 0 obj << /Type /Pages /Kids [3 0 R] /Count 1 /MediaBox [0 0 100 100] >> endobj
3 0 obj << /Type /Page /Parent 2 0 R /Resources << /Font << /F1 5 0 R >> >> /Contents 4 0 R >> endobj
4 0 obj << >> stream
BT /F1 10 Tf 1 0 0 1 10 80 Tm [(A) 0 (A) 0 (A)] TJ ET
endstream endobj
5 0 obj << /Type /Font /Subtype /Type1 /BaseFont /Test /FirstChar 65 /LastChar 65 /Widths [700] /FontDescriptor 6 0 R >> endobj
6 0 obj << /Type /FontDescriptor /FontName /Test /Ascent 750 /Descent -250 >> endobj
trailer << /Root 1 0 R >>
%%EOF";
        let document = detect_and_parse(bytes, Limits::default()).unwrap().unwrap();
        assert_eq!(document.objects.len(), 1);
        let batch = &document.objects[0];
        assert_eq!(batch.kind, ObjectKind::TextBox);
        assert_eq!(batch.text.as_deref(), Some("AAA"));
        assert_eq!(batch.source.mapping, MappingQuality::Derived);
        let Visual::Group { children } = &batch.visual else {
            panic!("contiguous PDF text must retain its original visuals in a batch");
        };
        assert_eq!(children.len(), 3);
        for pair in children.windows(2) {
            assert!((pair[0].bounds.x + pair[0].bounds.width - pair[1].bounds.x).abs() < 0.01);
            assert!(matches!(pair[0].visual, Visual::TextLayout { .. }));
        }
        assert!(matches!(children[2].visual, Visual::TextLayout { .. }));
    }

