    #[test]
    fn renders_type3_stencil_image_glyphs_in_the_current_fill_color() {
        let mut bytes = b"%PDF-1.7
1 0 obj << /Type /Catalog /Pages 2 0 R >> endobj
2 0 obj << /Type /Pages /Kids [3 0 R] /Count 1 /MediaBox [0 0 100 100] >> endobj
3 0 obj << /Type /Page /Parent 2 0 R /Resources << /Font << /F1 5 0 R >> >> /Contents 4 0 R >> endobj
4 0 obj << >> stream
1 0 0 rg BT -100 Tz /F1 -20 Tf 1 0 0 1 10 20 Tm (AA) Tj ET
endstream endobj
5 0 obj << /Type /Font /Subtype /Type3 /FontBBox [0 0 1000 1000] /FontMatrix [.001 0 0 .001 0 0] /CharProcs << /A 6 0 R >> /Encoding << /Differences [65 /A] >> /FirstChar 65 /LastChar 65 /Widths [1000] /Resources << /XObject << /Im0 7 0 R >> >> >> endobj
6 0 obj << >> stream
1000 0 0 0 1000 1000 d1 q 1000 0 0 1000 0 0 cm /Im0 Do Q
endstream endobj
7 0 obj << /Type /XObject /Subtype /Image /Width 8 /Height 1 /BitsPerComponent 1 /ImageMask true /Decode [1 0] /Length 1 >> stream
"
        .to_vec();
        bytes.push(0x80);
        bytes.extend_from_slice(
            b"
endstream endobj
trailer << /Root 1 0 R >>
%%EOF",
        );

        let document = detect_and_parse(&bytes, Limits::default())
            .unwrap()
            .unwrap();
        let images: Vec<_> = document
            .objects
            .iter()
            .filter(|object| object.kind == ObjectKind::Image)
            .collect();
        assert_eq!(images.len(), 2);
        assert!(
            images[0].bounds.x < images[1].bounds.x,
            "negative Tf and Tz must cancel rather than reverse glyph order"
        );
        let Visual::Image {
            media_type, bytes, ..
        } = (match &images[0].visual {
            Visual::Layer { visual, .. } => visual.as_ref(),
            visual => visual,
        })
        else {
            panic!("the Type 3 stencil glyph must use an image visual");
        };
        assert_eq!(media_type, "image/bmp;interpolate=false");
        assert_eq!(&bytes[70..74], &[0, 0, 255, 255]);
        assert_eq!(&bytes[74..78], &[0, 0, 255, 0]);
        assert!(
            document
                .diagnostics
                .iter()
                .all(|diagnostic| !diagnostic.message.contains("PDF_IMAGE_FILTER_UNSUPPORTED"))
        );
    }

