    #[test]
    fn preserves_pdfjs_text_stroke_patterns_and_authored_matrix_scaling() {
        fn text_layout(visual: &Visual) -> Option<&crate::model::TextLayout> {
            match visual {
                Visual::TextLayout { layout, .. } => Some(layout),
                Visual::Layer { visual, .. }
                | Visual::Effect { visual, .. }
                | Visual::StrokeStyle { visual, .. }
                | Visual::AdvancedEffect { visual, .. } => text_layout(visual),
                _ => None,
            }
        }

        let issue19360 =
            detect_and_parse(&pdfjs_fixture_or_skip!("issue19360.pdf"), Limits::default())
                .unwrap()
                .unwrap();
        let layout19360 = issue19360
            .objects
            .iter()
            .find_map(|object| text_layout(&object.visual))
            .unwrap();
        assert!(layout19360.text_matrix_scale_to_fit);
        assert!(matches!(
            layout19360.text_stroke_paint,
            Paint::LinearGradient { ref stops, .. } if !stops.is_empty()
        ));
        assert_eq!(layout19360.text_stroke_color, 0);

        let issue20513 =
            detect_and_parse(&pdfjs_fixture_or_skip!("issue20513.pdf"), Limits::default())
                .unwrap()
                .unwrap();
        assert!(issue20513.objects.iter().any(|object| {
            matches!(
                text_layout(&object.visual).map(|layout| &layout.text_stroke_paint),
                Some(Paint::LinearGradient { stops, .. })
                    if stops.iter().any(|stop| {
                        let red = stop.color >> 24;
                        let green = (stop.color >> 16) & 0xff;
                        let blue = (stop.color >> 8) & 0xff;
                        red > green.saturating_add(32) && red > blue.saturating_add(32)
                    })
            )
        }));
    }

