    #[test]
    #[cfg(feature = "pdf-formats")]
    fn predefined_gbk_cids_preserve_simple_font_and_to_unicode_boundaries() {
        let mut font = super::FontInfo {
            predefined_gbk: true,
            max_code_bytes: 2,
            ..super::FontInfo::default()
        };
        // Legacy simple TrueType GBK fonts keep source-code widths.
        assert_eq!(super::decode_pdf_glyphs(b"1", &font)[0].code, 0x31);
        font.predefined_cmap = super::CMap::parse(
            hayro_cmap::load_embedded(super::CMapName::from_bytes(b"GBK-EUC-H")).unwrap(),
            hayro_cmap::load_embedded,
        );
        let glyphs = super::decode_pdf_glyphs(b"1", &font);
        assert_eq!(glyphs[0].code, 830);
        assert_eq!(glyphs[0].text, "1");
        // ToUnicode changes extracted text, never the CID used for metrics.
        font.to_unicode.insert(b"1".to_vec(), "one".to_owned());
        let glyphs = super::decode_pdf_glyphs(b"1", &font);
        assert_eq!(glyphs[0].code, 830);
        assert_eq!(glyphs[0].text, "one");
    }

