    #[test]
    fn converts_binary_pfb_type1_fonts_for_browser_rendering() {
        let bytes = pdfjs_fixture_or_skip!("issue14462_reduced.pdf");
        let prepared = prepare(&bytes, Limits::default(), None).unwrap().unwrap();
        let type1 = super::decode_stream(
            &prepared.store.objects[&(32, 0)].value,
            &prepared.store,
            Limits::default(),
        )
        .unwrap();
        let font = prepared
            .store
            .dict(&prepared.store.objects[&(44, 0)].value)
            .unwrap();
        let encoding = super::simple_font_encoding(&prepared.store, font);
        assert!(
            super::pdf_type1::convert_type1_to_cff(&type1, &encoding).is_some(),
            "the PFB payload must convert to CFF"
        );
        let document = prepared
            .materialize(Some(0), true, &BTreeSet::new(), 0)
            .unwrap()
            .0;
        assert_eq!(
            document
                .objects
                .iter()
                .filter_map(|object| object.text.as_deref())
                .collect::<String>(),
            "Issue 14462"
        );
        let font = document
            .embedded_fonts
            .first()
            .expect("the embedded PFB font must be converted to OpenType");
        assert_eq!(&font.bytes[..4], b"OTTO");
        for code in [0x3c_u32, 0x2e, 0x43, 0x33, 0x20, 0x22, 0x25, 0x27, 0x23] {
            assert!(
                embedded_cmap_gid(&font.bytes, super::PDF_SIMPLE_GLYPH_PUA_START + code).is_some(),
                "missing browser glyph for source code {code:#x}"
            );
        }
        assert_eq!(sfnt_checksum(&font.bytes), 0xb1b0_afba);
    }

