    #[cfg(feature = "pdf-formats")]
    #[test]
    fn preserves_short_integer_type1_subset_outlines() {
        use skrifa::MetadataProvider;

        fn glyph_has_outline(font: &[u8], codepoint: u32) -> bool {
            let Ok(font) = super::FontRef::new(font) else {
                return false;
            };
            let Some(character) = char::from_u32(codepoint) else {
                return false;
            };
            let Some(glyph_id) = font.charmap().map(character) else {
                return false;
            };
            let Some(glyph) = font.outline_glyphs().get(glyph_id) else {
                return false;
            };
            let mut pen = super::PdfGlyphOutlinePen::default();
            glyph
                .draw(
                    super::DrawSettings::unhinted(
                        super::Size::unscaled(),
                        super::LocationRef::default(),
                    ),
                    &mut pen,
                )
                .is_ok()
                && !pen.commands.is_empty()
        }

        let open_sans =
            detect_and_parse(&pdfjs_fixture_or_skip!("issue10640.pdf"), Limits::default())
                .unwrap()
                .unwrap();
        assert_eq!(open_sans.embedded_fonts.len(), 6);
        let regular = open_sans
            .embedded_fonts
            .iter()
            .find(|font| font.family == "KUEKMM+OpenSans PDF 6 0")
            .unwrap();
        for code in [0x21, 0x45] {
            assert!(glyph_has_outline(
                &regular.bytes,
                super::PDF_SIMPLE_GLYPH_PUA_START + code,
            ));
        }

        let donation =
            detect_and_parse(&pdfjs_fixture_or_skip!("issue7769.pdf"), Limits::default())
                .unwrap()
                .unwrap();
        assert_eq!(
            donation
                .objects
                .iter()
                .filter_map(|object| object.text.as_deref())
                .take(4)
                .collect::<String>(),
            "Scan here to make a donation!"
        );
        let font = donation
            .embedded_fonts
            .iter()
            .find(|font| font.family == "TT3Do00 PDF 18 0")
            .unwrap();
        for code in [1, 6, 9, 11, 12, 14] {
            assert!(glyph_has_outline(
                &font.bytes,
                super::PDF_SIMPLE_GLYPH_PUA_START + code,
            ));
        }
    }

