    #[cfg(feature = "pdf-formats")]
    #[test]
    fn maps_all_authored_mac_roman_glyphs_in_embedded_cff_fonts() {
        use skrifa::MetadataProvider;

        let bytes = pdfjs_fixture_or_skip!("freeculture.pdf");
        let prepared = prepare(&bytes, Limits::default(), None).unwrap().unwrap();
        let document = prepared
            .materialize(Some(254), true, &BTreeSet::new(), 0)
            .unwrap()
            .0;
        let footer = document
            .objects
            .iter()
            .filter_map(|object| object.text.as_deref())
            .take(2)
            .collect::<String>();
        assert_eq!(footer, "BALANCES247");
        let font = document
            .embedded_fonts
            .iter()
            .find(|font| font.family.starts_with("MMPHDH+Monospace821BT-Roman"))
            .expect("the footer font must be embedded");
        for character in "BALANCES247".chars() {
            let font_ref = super::FontRef::new(&font.bytes).unwrap();
            let gid = font_ref
                .charmap()
                .map(character)
                .unwrap_or_else(|| panic!("missing browser glyph for {character:?}"));
            let glyph = font_ref.outline_glyphs().get(gid);
            let mut pen = super::PdfGlyphOutlinePen::default();
            let valid = glyph.is_some_and(|glyph| {
                glyph
                    .draw(
                        super::DrawSettings::unhinted(
                            super::Size::unscaled(),
                            super::LocationRef::default(),
                        ),
                        &mut pen,
                    )
                    .is_ok()
                    && !pen.commands.is_empty()
            });
            assert!(valid, "missing browser outline for {character:?}");
        }
    }

