    #[test]
    fn omits_unrenderable_standard_font_glyphs_from_paint() {
        fn text_runs(visual: &Visual) -> Option<&[TextRun]> {
            match visual {
                Visual::RichText { runs, .. } => Some(runs),
                Visual::Layer { visual, .. }
                | Visual::Effect { visual, .. }
                | Visual::TextLayout { visual, .. }
                | Visual::StrokeStyle { visual, .. }
                | Visual::AdvancedEffect { visual, .. }
                | Visual::ImageColorChange { visual, .. } => text_runs(visual),
                Visual::Media { poster, .. } => text_runs(poster),
                _ => None,
            }
        }

        let bytes = pdfjs_fixture_or_skip!("standard_fonts.pdf");
        let document = detect_and_parse(&bytes, Limits::default())
            .unwrap()
            .unwrap();
        let text = document
            .objects
            .iter()
            .filter_map(|object| text_runs(&object.visual))
            .flatten()
            .map(|run| run.text.as_str())
            .collect::<String>();
        assert!(
            !text
                .chars()
                .any(|character| matches!(character, '\u{e000}'..='\u{f8ff}'))
        );
        let controls = text
            .chars()
            .filter(|character| character.is_control())
            .collect::<Vec<_>>();
        assert!(
            controls.is_empty(),
            "unexpected control characters: {controls:?}"
        );
    }

