    #[test]
    fn aligns_mac_roman_parentheses_with_name_keyed_cff_glyphs() {
        let bytes = pdfjs_fixture_or_skip!("issue14048.pdf");
        let document = detect_and_parse(&bytes, Limits::default())
            .unwrap()
            .unwrap();
        let font = document
            .embedded_fonts
            .first()
            .expect("embedded MacRoman CFF font");
        let prepared = prepare(&bytes, Limits::default(), None).unwrap().unwrap();
        let descriptor = prepared
            .store
            .objects
            .iter()
            .find_map(|(_, object)| {
                let dict = prepared.store.dict(&object.value)?;
                (super::dict_name(dict, "Type") == Some("FontDescriptor")).then_some(dict)
            })
            .expect("MacRoman font descriptor");
        let stream = descriptor
            .get("FontFile3")
            .and_then(|value| prepared.store.resolve(value))
            .expect("MacRoman CFF stream");
        let cff = super::decode_stream(stream, &prepared.store, Limits::default()).unwrap();
        let (_, names, _) = super::cff_name_keyed_glyphs(&cff).unwrap();
        let left = names.get("parenleft").copied().unwrap();
        let right = names.get("parenright").copied().unwrap();
        assert_eq!(embedded_cmap_gid(&font.bytes, '(' as u32), Some(left));
        assert_eq!(embedded_cmap_gid(&font.bytes, ')' as u32), Some(right));
        let hmtx = super::sfnt_table(&font.bytes, b"hmtx").unwrap();
        assert_eq!(super::read_u16(hmtx, usize::from(left) * 4), Some(333));
        assert_eq!(super::read_u16(hmtx, usize::from(right) * 4), Some(333));
    }

