    #[test]
    fn preserves_accented_type1c_endchar_glyphs() {
        let bytes = pdfjs_fixture_or_skip!("endchar.pdf");
        let document = detect_and_parse(&bytes, Limits::default())
            .unwrap()
            .unwrap();
        let object = document
            .objects
            .iter()
            .find(|object| {
                object
                    .text
                    .as_deref()
                    .is_some_and(|text| text.contains('É'))
            })
            .unwrap();
        let runs = all_text_runs(&object.visual);
        assert!(
            !runs.is_empty(),
            "accented CFF text must retain its font run"
        );
        let font = document
            .embedded_fonts
            .iter()
            .find(|font| {
                embedded_cmap_gid(&font.bytes, super::PDF_SIMPLE_GLYPH_PUA_START + 131)
                    .is_some_and(|gid| gid != 0)
            })
            .expect("accented glyph must remain mapped to the embedded font");
        assert!(
            embedded_cmap_gid(&font.bytes, super::PDF_SIMPLE_GLYPH_PUA_START + 131)
                .is_some_and(|gid| gid != 0),
            "run_family={}, embedded={:?}, diagnostics={:?}",
            runs[0].font_family,
            document
                .embedded_fonts
                .iter()
                .map(|font| font.family.as_str())
                .collect::<Vec<_>>(),
            document.diagnostics
        );
        let cff = super::sfnt_table(&font.bytes, b"CFF ").unwrap();
        let header_size = usize::from(cff[2]);
        let (_, after_names) = super::cff_index(cff, header_size).unwrap();
        let (top_dicts, _) = super::cff_index(cff, after_names).unwrap();
        let char_strings_offset =
            usize::try_from(super::cff_dict_integer_operands(top_dicts[0], 17).unwrap()[0])
                .unwrap();
        let (char_strings, _) = super::cff_index(cff, char_strings_offset).unwrap();
        assert!(char_strings[102].ends_with(&[26, 14, 14]));
    }

