    #[test]
    fn neutralizes_invalid_cff_private_dict_values() {
        let bytes = pdfjs_fixture_or_skip!("bug1308536.pdf");
        let document = detect_and_parse(&bytes, Limits::default())
            .unwrap()
            .unwrap();
        let cff = super::sfnt_table(&document.embedded_fonts[0].bytes, b"CFF ").unwrap();
        let header_size = usize::from(cff[2]);
        let (_, after_names) = super::cff_index(cff, header_size).unwrap();
        let (top_dicts, _) = super::cff_index(cff, after_names).unwrap();
        let private = super::cff_dict_integer_operands(top_dicts[0], 18).unwrap();
        let [length, offset] = private.as_slice() else {
            panic!("CFF Private DICT must have a length and offset");
        };
        let start = usize::try_from(*offset).unwrap();
        let private = &cff[start..start + usize::try_from(*length).unwrap()];
        assert!(super::cff_dict_number_operands(private, 6).is_none());
        assert!(super::cff_dict_number_operands(private, (12_u16 << 8) | 9).is_none());
    }

