    #[test]
    fn keeps_large_zapf_widget_glyphs_within_their_appearance_box() {
        fn run_font_size(visual: &Visual) -> Option<f32> {
            match visual {
                Visual::RichText { runs, .. } => runs.first().map(|run| run.font_size),
                Visual::Effect { visual, .. }
                | Visual::Layer { visual, .. }
                | Visual::StrokeStyle { visual, .. }
                | Visual::AdvancedEffect { visual, .. }
                | Visual::TextLayout { visual, .. } => run_font_size(visual),
                _ => None,
            }
        }

        let bytes = pdfjs_fixture_or_skip!("bug1802506.pdf");
        let document = detect_and_parse(&bytes, Limits::default())
            .unwrap()
            .unwrap();
        let checkmark = document
            .objects
            .iter()
            .find(|object| object.kind == ObjectKind::TextBox)
            .expect("the checked widget appearance must retain its glyph");
        if let Some(font_size) = run_font_size(&checkmark.visual) {
            assert!(font_size <= checkmark.bounds.height * 1.01);
        } else {
            let SourceLocator::Pdf {
                object_number,
                byte_offset,
                ..
            } = &checkmark.source.locator
            else {
                panic!("checked widget text must retain its PDF source");
            };
            let outline = document
                .objects
                .iter()
                .find(|object| {
                    object.kind == ObjectKind::Shape
                        && matches!(
                            object.source.locator,
                            SourceLocator::Pdf {
                                object_number: candidate_object,
                                byte_offset: candidate_offset,
                                ..
                            } if &candidate_object == object_number && &candidate_offset == byte_offset
                        )
                })
                .expect("the checked widget must retain its vector outline");
            assert!(outline.bounds.height <= checkmark.bounds.height * 1.01);
        }
    }

