    #[test]
    fn positions_vertical_cid_glyphs_from_pdf_advances() {
        fn line_height(visual: &Visual) -> Option<f32> {
            match visual {
                Visual::RichText { line_height, .. } => Some(*line_height),
                Visual::Effect { visual, .. }
                | Visual::Layer { visual, .. }
                | Visual::StrokeStyle { visual, .. }
                | Visual::AdvancedEffect { visual, .. }
                | Visual::TextLayout { visual, .. } => line_height(visual),
                _ => None,
            }
        }

        let bytes = pdfjs_fixture_or_skip!("issue6387.pdf");
        let document = detect_and_parse(&bytes, Limits::default())
            .unwrap()
            .unwrap();
        assert!(document.objects.iter().any(|object| {
            matches!(
                object.visual,
                Visual::TextLayout { ref layout, .. }
                    if layout.orientation == crate::model::TextOrientation::VerticalRl
            )
        }));
        let starts = document
            .objects
            .iter()
            .filter(|object| object.text.as_deref() == Some("あ"))
            .take(3)
            .collect::<Vec<_>>();
        assert!(starts.iter().all(|object| {
            line_height(&object.visual)
                .is_some_and(|value| (value - object.bounds.width).abs() < 0.01)
        }));
        let advances = starts
            .iter()
            .map(|start| {
                document
                    .objects
                    .iter()
                    .find(|object| {
                        object.text.as_deref() == Some("の")
                            && (object.bounds.x - start.bounds.x).abs() < 0.01
                    })
                    .unwrap()
                    .bounds
                    .y
                    - start.bounds.y
            })
            .collect::<Vec<_>>();
        assert_eq!(advances, [40.0, 38.0, 36.0]);
    }

    #[test]
    fn normalizes_reversed_pdf_crop_box_coordinates() {
        let bytes = b"%PDF-1.7
1 0 obj << /Type /Catalog /Pages 2 0 R >> endobj
2 0 obj << /Type /Pages /Kids [3 0 R] /Count 1 >> endobj
3 0 obj << /Type /Page /Parent 2 0 R /MediaBox [0 0 200 100] /CropBox [0 100 200 0] >> endobj
trailer << /Root 1 0 R >>
%%EOF";
        let document = detect_and_parse(bytes, Limits::default()).unwrap().unwrap();
        assert!((document.units[0].width - 266.666_66).abs() < 0.01);
        assert!((document.units[0].height - 133.333_33).abs() < 0.01);
        assert!(document.diagnostics.iter().any(|diagnostic| {
            diagnostic.code == DiagnosticCode::ApproximateLayout
                && diagnostic.message.contains("PDF_PAGE_BOX_NORMALIZED")
        }));
    }

