    #[test]
    fn clips_overdeclared_cid_cff_charset_to_available_charstrings() {
        let cff = [
            1, 0, 4, 1, // header
            0, 1, 1, 1, 2, b'A', // Name INDEX
            0, 1, 1, 1, 13, // Top DICT INDEX header
            29, 0, 0, 0, 31, 15, // charset offset
            29, 0, 0, 0, 36, 17, // CharStrings offset
            0, 0, // String INDEX
            0, 0, // Global Subr INDEX
            2, 0, 65, 0, 1, // charset declares CIDs 65-66 for one available glyph
            0, 2, 1, 1, 2, 3, 14, 14, // two empty Type 2 charstrings
        ];

        assert_eq!(
            super::cff_cid_glyphs(&cff),
            Some((2, BTreeMap::from([(0, 0), (65, 1)])))
        );
    }

    #[test]
    fn wraps_a_cid_cff_subset_in_a_checksummed_opentype_container() {
        let cff = [
            1, 0, 4, 1, // header
            0, 1, 1, 1, 2, b'A', // Name INDEX
            0, 1, 1, 1, 13, // Top DICT INDEX header
            29, 0, 0, 0, 31, 15, // charset offset
            29, 0, 0, 0, 34, 17, // CharStrings offset
            0, 0, // String INDEX
            0, 0, // Global Subr INDEX
            0, 0, 65, // charset: GID 1 is CID 65
            0, 2, 1, 1, 2, 3, 14, 14, // two empty Type 2 charstrings
        ];
        let info = FontInfo {
            family: "Subset Sans".to_owned(),
            to_unicode: BTreeMap::from([(vec![0, 65], "A".to_owned())]),
            widths: BTreeMap::from([(65, 600.0)]),
            default_width: 1_000.0,
            ascent: 800.0,
            descent: -200.0,
            ..FontInfo::default()
        };
        let font =
            wrap_cid_cff_as_opentype(&cff, "Subset Sans", &info, [0.0, -200.0, 1_000.0, 800.0])
                .unwrap();
        assert_eq!(&font[..4], b"OTTO");
        assert_eq!(sfnt_checksum(&font), 0xb1b0_afba);
        assert!(font.windows(4).any(|window| window == b"CFF "));
        assert!(font.windows(4).any(|window| window == b"cmap"));
        assert_eq!(embedded_cmap_gid(&font, 'A' as u32), Some(1));
        assert_eq!(
            embedded_cmap_gid(&font, super::pdf_cid_glyph_codepoint(65).unwrap()),
            Some(1),
        );
    }

    #[test]
    fn maps_name_keyed_cff_glyphs_inside_cidfonttype0() {
        let cff = [
            1, 0, 4, 1, // header
            0, 1, 1, 1, 2, b'A', // Name INDEX
            0, 1, 1, 1, 13, // Top DICT INDEX header
            29, 0, 0, 0, 31, 15, // charset offset
            29, 0, 0, 0, 34, 17, // CharStrings offset
            0, 0, // String INDEX
            0, 0, // Global Subr INDEX
            0, 0, 19, // name-keyed charset: GID 1 is standard SID 19 (`two`)
            0, 2, 1, 1, 2, 3, 14, 14, // two empty Type 2 charstrings
        ];
        let mut bytes = format!(
            "%PDF-1.7
1 0 obj << /Type /Catalog /Pages 2 0 R >> endobj
2 0 obj << /Type /Pages /Kids [3 0 R] /Count 1 /MediaBox [0 0 100 100] >> endobj
3 0 obj << /Type /Page /Parent 2 0 R /Resources << /Font << /F1 5 0 R >> >> /Contents 4 0 R >> endobj
4 0 obj << >> stream
BT /F1 10 Tf 10 20 Td <001d> Tj ET
endstream endobj
5 0 obj << /Type /Font /Subtype /Type0 /BaseFont /Subset /Encoding /Identity-H /DescendantFonts [6 0 R] /ToUnicode 9 0 R >> endobj
6 0 obj << /Type /Font /Subtype /CIDFontType0 /BaseFont /Subset /DW 600 /W [29 [500]] /CIDSystemInfo << /Registry (Adobe) /Ordering (Identity) /Supplement 0 >> /FontDescriptor 7 0 R >> endobj
7 0 obj << /Type /FontDescriptor /FontName /Subset /Ascent 800 /Descent -200 /FontBBox [0 -200 1000 800] /FontFile3 8 0 R >> endobj
8 0 obj << /Subtype /CIDFontType0C /Length {} >> stream
",
            cff.len(),
        )
        .into_bytes();
        bytes.extend_from_slice(&cff);
        bytes.extend_from_slice(
            b"
endstream endobj
9 0 obj << >> stream
begincmap
1 begincodespacerange
<0000> <ffff>
endcodespacerange
1 beginbfchar
<001d> <0032>
endbfchar
endcmap
endstream endobj
trailer << /Root 1 0 R >>
%%EOF",
        );

        let document = detect_and_parse(&bytes, Limits::default())
            .unwrap()
            .unwrap();
        let font = &document.embedded_fonts[0].bytes;
        assert_eq!(
            embedded_cmap_gid(font, super::pdf_cid_glyph_codepoint(0x1d).unwrap()),
            Some(1)
        );
        assert_eq!(embedded_cmap_gid(font, u32::from('2')), Some(1));
    }

    #[test]
    fn sanitizes_cff_name_index_for_browser_validation() {
        let cff = [
            1, 0, 4, 1, // header
            0, 1, 1, 1, 4, b'A', b' ', b'B', // invalid PostScript whitespace in Name INDEX
            0, 1, 1, 1, 13, // Top DICT INDEX header
            29, 0, 0, 0, 33, 15, // charset offset
            29, 0, 0, 0, 36, 17, // CharStrings offset
            0, 0, // String INDEX
            0, 0, // Global Subr INDEX
            0, 0, 65, // charset: GID 1 is CID 65
            0, 2, 1, 1, 2, 3, 14, 14, // two empty Type 2 charstrings
        ];
        let info = FontInfo {
            family: "Subset Sans".to_owned(),
            to_unicode: BTreeMap::from([(vec![0, 65], "A".to_owned())]),
            widths: BTreeMap::from([(65, 600.0)]),
            default_width: 1_000.0,
            ascent: 800.0,
            descent: -200.0,
            ..FontInfo::default()
        };
        let font =
            wrap_cid_cff_as_opentype(&cff, "Subset Sans", &info, [0.0, -200.0, 1_000.0, 800.0])
                .unwrap();
        assert!(font.windows(3).any(|window| window == b"A-B"));
        assert!(!font.windows(3).any(|window| window == b"A B"));
    }

