    #[test]
    fn uses_the_embedded_cff_program_for_mislabeled_cid_font_visual_text() {
        let cff = [
            1, 0, 4, 1, // header
            0, 1, 1, 1, 2, b'A', // Name INDEX
            0, 1, 1, 1, 13, // Top DICT INDEX header
            29, 0, 0, 0, 31, 15, // charset offset
            29, 0, 0, 0, 34, 17, // CharStrings offset
            0, 0, // String INDEX
            0, 0, // Global Subr INDEX
            0, 1, 135, // name-keyed charset: GID 1 is SID 391
            0, 2, 1, 1, 2, 3, 14, 14, // two empty Type 2 charstrings
        ];
        let mut bytes = format!(
            "%PDF-1.7
1 0 obj << /Type /Catalog /Pages 2 0 R >> endobj
2 0 obj << /Type /Pages /Kids [3 0 R] /Count 1 /MediaBox [0 0 100 100] >> endobj
3 0 obj << /Type /Page /Parent 2 0 R /Resources << /Font << /F1 5 0 R >> >> /Contents 4 0 R >> endobj
4 0 obj << >> stream
BT /F1 10 Tf 1 0 0 1 10 80 Tm <0001> Tj ET
endstream endobj
5 0 obj << /Type /Font /Subtype /Type0 /BaseFont /Subset /Encoding /Identity-H /DescendantFonts [6 0 R] /ToUnicode 9 0 R >> endobj
6 0 obj << /Type /Font /Subtype /CIDFontType2 /BaseFont /Subset /DW 600 /CIDSystemInfo << /Registry (Adobe) /Ordering (Identity) /Supplement 0 >> /CIDToGIDMap /Identity /FontDescriptor 7 0 R >> endobj
7 0 obj << /Type /FontDescriptor /FontName /Subset /Ascent 800 /Descent -200 /FontBBox [0 -200 1000 800] /FontFile3 8 0 R >> endobj
8 0 obj << /Subtype /CIDFontType0C /Length {} >> stream
",
            cff.len(),
        )
        .into_bytes();
        bytes.extend_from_slice(&cff);
        bytes.extend_from_slice(
            b"
endstream endobj
9 0 obj << >> stream
begincmap
1 begincodespacerange
<0000> <ffff>
endcodespacerange
1 beginbfchar
<0001> <0041>
endbfchar
endcmap
endstream endobj
trailer << /Root 1 0 R >>
%%EOF",
        );

        let document = detect_and_parse(&bytes, Limits::default())
            .unwrap()
            .unwrap();
        let text = document
            .objects
            .iter()
            .find(|object| object.text.as_deref() == Some("A"))
            .unwrap();
        let Visual::TextLayout { visual, .. } = &text.visual else {
            panic!("PDF text must carry explicit layout semantics");
        };
        let Visual::RichText { runs, .. } = visual.as_ref() else {
            panic!("PDF text layout must contain rich text");
        };
        assert_eq!(
            runs[0].text,
            char::from_u32(super::pdf_cid_glyph_codepoint(1).unwrap())
                .unwrap()
                .to_string()
        );
        assert_eq!(
            embedded_cmap_gid(
                &document.embedded_fonts[0].bytes,
                super::pdf_cid_glyph_codepoint(1).unwrap()
            ),
            Some(1)
        );
    }

