    #[test]
    fn preserves_non_default_cff_font_matrix_in_opentype_metrics() {
        let cff = [
            1, 0, 4, 1, // header
            0, 1, 1, 1, 2, b'A', // Name INDEX
            0, 1, 1, 1, 23, // Top DICT INDEX header
            189, 15, // charset offset 50
            186, 16, // encoding offset 47
            192, 17, // CharStrings offset 53
            30, 0x0a, 0x00, 0x05, 0xff, // FontMatrix a = 0.0005
            139, 139, // b = 0, c = 0
            30, 0x0a, 0x00, 0x05, 0xff, // d = 0.0005
            139, 139, 12, 7, // e = 0, f = 0, FontMatrix
            0, 1, 1, 1, 4, b'G', b'2', b'1', // String INDEX: SID 391 = G21
            0, 0, // Global Subr INDEX
            0, 1, 33, // format 0 encoding: character code 33 -> GID 1
            0, 1, 135, // format 0 charset: GID 1 -> SID 391
            0, 2, 1, 1, 2, 3, 14, 14, // two empty Type 2 charstrings
        ];
        assert_eq!(super::cff_units_per_em(&cff), Some(2_000));
        let info = FontInfo {
            family: "Subset Marks".to_owned(),
            to_unicode: BTreeMap::from([(vec![33], "\u{230d}".to_owned())]),
            widths: BTreeMap::from([(33, 600.0)]),
            default_width: 1_000.0,
            ascent: 800.0,
            descent: -200.0,
            ..FontInfo::default()
        };
        let font = wrap_name_keyed_cff_as_opentype(
            &cff,
            "Subset Marks",
            &info,
            [0.0, -200.0, 1_000.0, 800.0],
            &BTreeMap::new(),
        )
        .unwrap();
        let table_offset = |tag: &[u8; 4]| {
            let table_count = usize::from(u16::from_be_bytes([font[4], font[5]]));
            (0..table_count).find_map(|index| {
                let record = 12 + index * 16;
                (&font[record..record + 4] == tag).then(|| {
                    usize::try_from(u32::from_be_bytes([
                        font[record + 8],
                        font[record + 9],
                        font[record + 10],
                        font[record + 11],
                    ]))
                    .unwrap()
                })
            })
        };
        let head = table_offset(b"head").unwrap();
        assert_eq!(
            u16::from_be_bytes([font[head + 18], font[head + 19]]),
            2_000
        );
        let hmtx = table_offset(b"hmtx").unwrap();
        assert_eq!(u16::from_be_bytes([font[hmtx + 4], font[hmtx + 5]]), 1_200);
    }

