    #[test]
    fn clips_shading_patterns_to_their_bbox() {
        let bytes = pdfjs_fixture_or_skip!("issue8092.pdf");
        let document = detect_and_parse(&bytes, Limits::default())
            .unwrap()
            .unwrap();
        let shape = document
            .objects
            .iter()
            .find(|object| object.kind == ObjectKind::Shape)
            .unwrap();
        let Visual::Effect {
            clip: Some(Geometry::Path { commands, .. }),
            ..
        } = &shape.visual
        else {
            panic!("the shading pattern must retain its BBox clip");
        };
        let points = commands
            .iter()
            .filter_map(|command| match command {
                PathCommand::MoveTo { x, y } | PathCommand::LineTo { x, y } => Some((*x, *y)),
                _ => None,
            })
            .collect::<Vec<_>>();
        let clip = super::bounds(&points).unwrap();
        assert!(clip.width < shape.bounds.width);
        assert!(clip.height < shape.bounds.height);
        assert!(clip.x > 0.0 && clip.y > 0.0);
    }

