    #[test]
    fn repeats_multicolor_stroked_curve_pattern_cells() {
        fn stroke_colors(visual: &Visual, colors: &mut BTreeSet<u32>) {
            match visual {
                Visual::PaintedShape {
                    stroke: Paint::Solid(color),
                    ..
                } => {
                    colors.insert(*color);
                }
                Visual::Effect { visual, .. }
                | Visual::Layer { visual, .. }
                | Visual::StrokeStyle { visual, .. }
                | Visual::TextLayout { visual, .. }
                | Visual::AdvancedEffect { visual, .. }
                | Visual::ImageColorChange { visual, .. } => stroke_colors(visual, colors),
                _ => {}
            }
        }

        let Some(bytes) = pdfjs_fixture("issue2177.pdf") else {
            return;
        };
        let document = detect_and_parse(&bytes, Limits::default())
            .unwrap()
            .unwrap();
        let mut colors = BTreeSet::new();
        for object in &document.objects {
            stroke_colors(&object.visual, &mut colors);
        }
        assert!(colors.contains(&rgba(255, 0, 0)));
        assert!(colors.contains(&rgba(0, 255, 0)));
        assert!(colors.contains(&rgba(0, 0, 255)));
        assert!(document.objects.len() > 20);
    }

    #[test]
    fn renders_filled_rectangle_tiling_cells_with_full_pattern_geometry() {
        fn fill_colors(visual: &Visual, colors: &mut BTreeSet<u32>) {
            match visual {
                Visual::PaintedShape {
                    fill: Paint::Solid(color),
                    ..
                } => {
                    colors.insert(*color);
                }
                Visual::Effect { visual, .. }
                | Visual::Layer { visual, .. }
                | Visual::StrokeStyle { visual, .. }
                | Visual::TextLayout { visual, .. }
                | Visual::AdvancedEffect { visual, .. }
                | Visual::ImageColorChange { visual, .. } => fill_colors(visual, colors),
                _ => {}
            }
        }

        let Some(bytes) = pdfjs_fixture("tiling_patterns_variations.pdf") else {
            return;
        };
        let document = detect_and_parse(&bytes, Limits::default())
            .unwrap()
            .unwrap();
        let mut colors = BTreeSet::new();
        for object in &document.objects {
            fill_colors(&object.visual, &mut colors);
        }
        assert!(colors.contains(&rgba(51, 102, 204)));
        assert!(colors.contains(&rgba(230, 128, 26)));
        assert!(colors.contains(&rgba(26, 179, 51)));
        assert!(colors.contains(&rgba(179, 26, 179)));
        assert!(colors.contains(&rgba(204, 51, 51)));
        assert!(document.objects.len() > 40);
    }

