    #[test]
    fn recovers_bare_pdf_dictionaries_and_nested_page_resources() {
        fn encoded_image(visual: &Visual) -> Option<(&str, &[u8])> {
            match visual {
                Visual::Image {
                    media_type, bytes, ..
                } => Some((media_type, bytes)),
                Visual::Layer { visual, .. } | Visual::Effect { visual, .. } => {
                    encoded_image(visual)
                }
                _ => None,
            }
        }
        let Some(bytes) = pdfjs_fixture("issue12841_reduced.pdf") else {
            return;
        };
        let document = detect_and_parse(&bytes, Limits::default())
            .unwrap()
            .unwrap();
        let image = document
            .objects
            .iter()
            .find(|object| object.kind == ObjectKind::Image)
            .expect("the image referenced through bare page resources must be retained");
        let (media_type, bytes) =
            encoded_image(&image.visual).expect("the recovered resource must remain encoded");
        assert!(image.bounds.x < 100.0 && image.bounds.y < 100.0);
        assert!(image.bounds.width > 500.0 && image.bounds.height > 700.0);
        assert_eq!(media_type, "image/jpeg;interpolate=false");
        assert!(bytes.starts_with(&[0xff, 0xd8]));
        assert!(bytes.len() > 5_000_000);
        assert!(bytes.ends_with(&[0xff, 0xd9]));
    }

