    #[cfg(feature = "pdf-formats")]
    fn decodes_ccitt_streams_with_explicit_end_of_block_semantics() {
        fn bitmap(visual: &Visual) -> Option<(&str, &[u8])> {
            match visual {
                Visual::Image {
                    media_type, bytes, ..
                } => Some((media_type, bytes)),
                Visual::Effect { visual, .. }
                | Visual::Layer { visual, .. }
                | Visual::StrokeStyle { visual, .. }
                | Visual::AdvancedEffect { visual, .. } => bitmap(visual),
                _ => None,
            }
        }

        let bytes = pdfjs_fixture_or_skip!("ccitt_EndOfBlock_false.pdf");
        let document = detect_and_parse(&bytes, Limits::default())
            .unwrap()
            .unwrap();
        let images = document
            .objects
            .iter()
            .filter_map(|object| bitmap(&object.visual))
            .collect::<Vec<_>>();
        assert_eq!(images.len(), 6);
        for (media_type, bytes) in images {
            assert_eq!(media_type, "image/bmp;interpolate=false");
            assert_eq!(&bytes[..2], b"BM");
            assert!(bytes[62..].iter().any(|byte| *byte != 0));
        }
    }

    #[test]
    fn renders_type3_inline_ccitt_stencil_glyphs_without_failing_the_document() {
        let fax = [
            0x26, 0xa0, 0xbf, 0xcc, 0x39, 0x14, 0x7c, 0x47, 0x23, 0x1f, 0xff, 0xf1, 0xcc, 0x39,
            0x18, 0xfe, 0xbb, 0x58, 0xfc, 0x00, 0x40, 0x04,
        ];
        let mut bytes = b"%PDF-1.7
1 0 obj << /Type /Catalog /Pages 2 0 R >> endobj
2 0 obj << /Type /Pages /Kids [3 0 R] /Count 1 /MediaBox [0 0 100 100] >> endobj
3 0 obj << /Type /Page /Parent 2 0 R /Resources << /Font << /F1 5 0 R >> >> /Contents 4 0 R >> endobj
4 0 obj << >> stream
1 0 0 rg BT /F1 20 Tf 1 0 0 1 10 20 Tm (A) Tj ET
endstream endobj
5 0 obj << /Type /Font /Subtype /Type3 /FontBBox [0 0 1000 1000] /FontMatrix [.001 0 0 .001 0 0] /CharProcs << /A 6 0 R >> /Encoding << /Differences [65 /A] >> /FirstChar 65 /LastChar 65 /Widths [1000] >> endobj
6 0 obj << >> stream
1000 0 0 0 1000 1000 d1 q 1000 0 0 1000 0 0 cm
BI /IM true /W 16 /H 16 /BPC 1 /D [1 0] /F /CCF /DP << /K -1 /Columns 16 >> ID "
            .to_vec();
        bytes.extend_from_slice(&fax);
        bytes.extend_from_slice(
            b"
EI Q
endstream endobj
trailer << /Root 1 0 R >>
%%EOF",
        );

        let document = detect_and_parse(&bytes, Limits::default())
            .unwrap()
            .unwrap();
        let image = document
            .objects
            .iter()
            .find(|object| object.kind == ObjectKind::Image)
            .expect("the Type 3 CCITT stencil glyph must be painted");
        let visual = match &image.visual {
            Visual::Layer { visual, .. } => visual.as_ref(),
            visual => visual,
        };
        let Visual::ImageColorChange {
            from,
            to,
            use_alpha,
            visual,
        } = visual
        else {
            panic!("the CCITT stencil background must become transparent");
        };
        assert_eq!((*from, *to, *use_alpha), (0x0000_00ff, 0x0000_0000, false));
        let Visual::ImageColorChange {
            from,
            to,
            use_alpha,
            visual,
        } = visual.as_ref()
        else {
            panic!("the CCITT stencil foreground must use the current fill");
        };
        assert_eq!((*from, *to, *use_alpha), (0xffff_ffff, 0xff00_00ff, false));
        assert!(matches!(
            visual.as_ref(),
            Visual::Image { media_type, .. } if media_type == "image/tiff;interpolate=false"
        ));
        assert!(
            document
                .diagnostics
                .iter()
                .all(|diagnostic| !diagnostic.message.contains("PDF_STREAM_FILTER_UNSUPPORTED"))
        );
    }

    #[test]
    fn preserves_a_dct_image_soft_mask_for_browser_compositing() {
        let mut bytes = b"%PDF-1.7
1 0 obj << /Type /Catalog /Pages 2 0 R >> endobj
2 0 obj << /Type /Pages /Kids [3 0 R] /Count 1 /MediaBox [0 0 10 10] >> endobj
3 0 obj << /Type /Page /Parent 2 0 R /Resources << /XObject << /Im0 5 0 R >> >> /Contents 4 0 R >> endobj
4 0 obj << >> stream
q 10 0 0 10 0 0 cm /Im0 Do Q
q 10 0 0 10 0 0 cm /Im0 Do Q
endstream endobj
5 0 obj << /Type /XObject /Subtype /Image /Width 2 /Height 1 /BitsPerComponent 8 /ColorSpace /DeviceRGB /Filter /DCTDecode /SMask 6 0 R >> stream
"
        .to_vec();
        bytes.extend_from_slice(&[0xff, 0xd8, 0xff, 0xd9]);
        bytes.extend_from_slice(
            b"
endstream endobj
6 0 obj << /Type /XObject /Subtype /Image /Width 2 /Height 1 /BitsPerComponent 8 /ColorSpace /DeviceGray /Filter /DCTDecode >> stream
",
        );
        bytes.extend_from_slice(&[64, 192]);
        bytes.extend_from_slice(
            b"
endstream endobj
trailer << /Root 1 0 R >>
%%EOF",
        );
        let document = detect_and_parse(&bytes, Limits::default())
            .unwrap()
            .unwrap();
        let Visual::MaskedImage {
            media_type,
            bytes,
            resource_id,
            mask_resource_id,
            mask_width,
            mask_height,
            mask_media_type,
            alpha_mask,
            ..
        } = &document.objects[0].visual
        else {
            panic!("DCT images with an SMask must retain the alpha plane");
        };
        assert_eq!(media_type, "image/jpeg;interpolate=false");
        assert_eq!(bytes, &[0xff, 0xd8, 0xff, 0xd9]);
        assert_eq!(*resource_id, 5);
        assert_eq!(*mask_resource_id, 6);
        assert_eq!((*mask_width, *mask_height), (2, 1));
        assert_eq!(mask_media_type, "image/jpeg");
        assert_eq!(alpha_mask, &[64, 192]);
        let Visual::MaskedImage {
            media_type,
            bytes,
            resource_id,
            mask_resource_id,
            alpha_mask,
            ..
        } = &document.objects[1].visual
        else {
            panic!("reused DCT image must retain its resource references");
        };
        assert_eq!(media_type, "image/jpeg;interpolate=false");
        assert!(bytes.is_empty());
        assert_eq!(*resource_id, 5);
        assert_eq!(*mask_resource_id, 6);
        assert!(alpha_mask.is_empty());
    }

