    #[test]
    fn renders_free_text_normal_appearance_streams() {
        let bytes = b"%PDF-1.7
1 0 obj << /Type /Catalog /Pages 2 0 R >> endobj
2 0 obj << /Type /Pages /Kids [3 0 R] /Count 1 /MediaBox [0 0 100 100] >> endobj
3 0 obj << /Type /Page /Parent 2 0 R /Annots [6 0 R] >> endobj
6 0 obj << /Type /Annot /Subtype /FreeText /Rect [10 70 90 90] /AP << /N 7 0 R >> >> endobj
7 0 obj << /Type /XObject /Subtype /Form /BBox [10 70 90 90] /Matrix [1 0 0 1 -10 -70] /Resources << /Font << /F1 << /Type /Font /Subtype /Type1 /BaseFont /Helvetica >> >> >> >> stream
BT /F1 10 Tf 1 0 0 rg 10 75 Td (red note) Tj ET
endstream endobj
trailer << /Root 1 0 R >>
%%EOF";

        let document = detect_and_parse(bytes, Limits::default()).unwrap().unwrap();
        let text = document
            .objects
            .iter()
            .find(|object| object.text.as_deref() == Some("red note"))
            .expect("FreeText normal appearance text must be materialized");
        fn text_runs(visual: &Visual) -> Option<&[TextRun]> {
            match visual {
                Visual::RichText { runs, .. } => Some(runs),
                Visual::Effect { visual, .. }
                | Visual::Layer { visual, .. }
                | Visual::TextLayout { visual, .. }
                | Visual::StrokeStyle { visual, .. }
                | Visual::AdvancedEffect { visual, .. } => text_runs(visual),
                _ => None,
            }
        }
        let runs =
            text_runs(&text.visual).expect("FreeText appearance text must retain its styled run");
        assert_eq!(runs[0].color, 0xff00_00ff);
    }

