    fn materializes_internal_pdf_link_annotations() {
        let bytes = b"%PDF-1.7
1 0 obj << /Type /Catalog /Pages 2 0 R /Names << /Dests 5 0 R >> >> endobj
2 0 obj << /Type /Pages /Kids [3 0 R 4 0 R] /Count 2 /MediaBox [0 0 100 100] >> endobj
3 0 obj << /Type /Page /Parent 2 0 R /Annots [
<< /Type /Annot /Subtype /Link /Rect [10 70 60 80] /A << /S /GoTo /D (section.1) >> >>
] >> endobj
4 0 obj << /Type /Page /Parent 2 0 R >> endobj
5 0 obj << /Names [(section.1) [4 0 R /Fit]] >> endobj
trailer << /Root 1 0 R >>
%%EOF";
        let document = detect_and_parse(bytes, Limits::default()).unwrap().unwrap();
        let link = document
            .objects
            .iter()
            .find(|object| {
                matches!(
                    object.source.locator,
                    SourceLocator::Pdf {
                        kind: "annotation",
                        action: Some(_),
                        ..
                    }
                )
            })
            .expect("PDF link annotation must be materialized");
        let SourceLocator::Pdf {
            action: Some(action),
            ..
        } = &link.source.locator
        else {
            unreachable!()
        };
        assert_eq!(action.kind, "command");
        assert_eq!(action.action.as_deref(), Some("navigate"));
        assert_eq!(action.target.as_deref(), Some("1"));
        assert!(link.bounds.width > 0.0 && link.bounds.height > 0.0);
    }

